    ["d-react"] = {
      { "Bringing someone back alive is a different sort of victory, and I liked it better than most.", tags = { "rescue" } },
      { "There are worse ways to spend a day than making sure someone gets home.", tags = { "rescue" } },
      { "Of everything the stretch asked of me, that was the part I would do again without being asked.", tags = { "rescue" } },
      { "Some foes I fight because I am asked to; that one I fought gladly.", tags = { "villain" } },
      { "The quiet afterwards was the best part of it.", tags = { "villain" } },
      { "I had heard enough of what that one had done to feel no regret at all.", tags = { "villain" } },
      { "The dead never fall quite the way the living do, and I was glad when it was over.", tags = { "undead" } },
      { "The dead had no business walking, and I had no doubts about sending them back.", tags = { "undead" } },
      { "A fight with demons leaves a taste behind it that no amount of walking quite clears.", tags = { "demon" } },
      { "Whatever the demons wanted there, they would not have it now.", tags = { "demon" } },
      { "Hunting something that size was its own kind of respect.", tags = { "beast" } },
      { "I was sorry for the beast, a little, and not sorry at all that it was done.", tags = { "beast" } },
