      { "I summoned my first voidwalker, {pet}, and found the bulk of that blue shadow unexpectedly reassuring.", tags = { "voidwalker" } },
      { "I called {pet}, my first voidwalker, glad to have something so substantial to send ahead of me.", tags = { "voidwalker" } },
      { "I bound my first voidwalker, {pet}; calling something out of the void was easier than feeling entirely safe beside it.", tags = { "voidwalker" } },
