      { "I bound my first felguard, {pet}, and felt the danger of having a soldier of the Legion within reach.", tags = { "felguard" } },
      { "I summoned {pet}, my first felguard; that much demonic strength was a formidable thing to claim as mine.", tags = { "felguard" } },
      { "I summoned {demon} for the first time, bound under the name {pet}, and felt less alone without feeling much safer." },
      { "I first summoned {pet}, {demon} bound to my service, with every intention of keeping the leash short." },
