      { "The voidwalker I had learned to call came at last, and answered to {pet}.", tags = { "known", "voidwalker" } },
      { "I called on what I had been taught, and {pet} came, a succubus with a name of her own.", tags = { "known", "succubus" } },
      { "The felhunter I had learned to summon came at last, and answered to {pet}.", tags = { "known", "felhunter" } },
