    ["kin"] = {
      { "We were of the same people, and it did me good to find one of my own so far from home." },
      { "It was good to work for one of my own people, so far from home." },
      { "That was one of my own people, and for a moment the land felt less foreign." },
      { "Meeting one of my own people out here, I was surprised how much the familiar face was worth." },
      { "It was easier to work for someone of my own people; less needed saying." },
    },
    ["lesson"] = {
      { "Life Tap taught me to pay for magic with my own health.", tags = { "spell:Life_Tap", "!diary" } },
      { "Fear was a new way to put the terror on the other side of a fight.", tags = { "spell:Fear", "!diary" } },
      { "Drain Life entered my repertoire, a hungry spell that could keep me alive at someone else's expense.", tags = { "spell:Drain_Life", "!diary" } },
      { "Corruption was mine to use, slow enough to make a quick death seem generous.", tags = { "spell:Corruption", "!diary" } },
      { "With Health Funnel learned, keeping a demon alive could now cost me my own health.", tags = { "spell:Health_Funnel", "!diary" } },
      { "Polymorph could turn a foe into a sheep, which is more of an answer than it sounds.", tags = { "spell:Polymorph", "!diary" } },
      { "Blink gave me a sudden affection for the distance a single spell could put between me and danger.", tags = { "spell:Blink", "!diary" } },
      { "Frost Nova offered a way to let ice hold an enemy while I found somewhere safer to stand.", tags = { "spell:Frost_Nova", "!diary" } },
      { "I learned to conjure water, and liked having one less ordinary need to carry along the road.", tags = { "spell:Conjure_Water", "!diary" } },
      { "Power Word: Shield was a ward I could now set between myself and an enemy's blow.", tags = { "spell:Power_Word:_Shield", "!diary" } },
      { "I took instruction in Renew, comforted by healing that could keep working after the prayer ended.", tags = { "spell:Renew", "!race:Scourge", "!diary" } },
      { "With Resurrection, I could call the dead back to life, which is not a thing to learn lightly.", tags = { "spell:Resurrection", "!race:Scourge", "!diary" } },
      { "Psychic Scream was mine to use, a way to make my fear someone else's problem.", tags = { "spell:Psychic_Scream", "!diary" } },
      { "Lay on Hands gave me a fierce comfort in having something left to offer when an ordinary blessing would not be enough.", tags = { "spell:Lay_on_Hands", "!diary" } },
      { "Divine Protection gave me a moment in which nothing could touch me.", tags = { "spell:Divine_Protection", "!diary" } },
      { "Hammer of Justice offered a firm interruption to an enemy's intentions.", tags = { "spell:Hammer_of_Justice", "!diary" } },
      { "With Charge learned, I could close the distance before my courage had time to argue about it.", tags = { "spell:Charge", "!diary" } },
      { "I took instruction in Execute, with the ugly comfort of knowing how to finish a fight that had already cost enough.", tags = { "spell:Execute", "!diary" } },
      { "Learning to pick pockets gave me a new sympathy for anyone who kept a hand on their purse.", tags = { "spell:Pick_Pocket", "!diary" } },
      { "With Sap, I could put a foe to sleep before it knew I was there.", tags = { "spell:Sap", "!diary" } },
      { "Vanish was a new way to let an enemy wonder where its troubles had gone.", tags = { "spell:Vanish", "!diary" } },
      { "I learned Sprint, and saw an excellent use for it in leaving trouble behind.", tags = { "spell:Sprint", "!diary" } },
      { "Aspect of the Cheetah gave me a hunter's answer to a long road.", tags = { "spell:Aspect_of_the_Cheetah", "!diary" } },
      { "Feign Death was a lie I could now tell with my whole body, so that I need not become the truth of it.", tags = { "spell:Feign_Death", "!diary" } },
      { "Hunter's Mark offered a way to keep my quarry from becoming merely another movement I could not place.", tags = { "spell:Hunter's_Mark", "!diary" } },
      { "I learned Ghost Wolf, and could borrow a swifter shape from the spirits without leaving my life behind.", tags = { "spell:Ghost_Wolf", "!diary" } },
      { "With Ancestral Spirit, I could call a fallen friend's spirit back into their body.", tags = { "spell:Ancestral_Spirit", "!diary" } },
      { "Lightning Shield was mine to call on, thunder waiting for the hand that reached for me.", tags = { "spell:Lightning_Shield", "!diary" } },
      { "Entangling Roots offered a way to hold an enemy without keeping it within my own reach.", tags = { "spell:Entangling_Roots", "!diary" } },
      { "Rebirth was the wild's answer to a death that came before the fighting was done, and I learned to call on it.", tags = { "spell:Rebirth", "!diary" } },
      { "Immolate kept a foe burning while I stayed out of its reach, which suited me.", tags = { "spell:Immolate", "!diary" } },
      { "I learned Immolate, a fire I would never welcome at my own hearth.", tags = { "spell:Immolate", "!diary" } },
      { "With Life Tap learned, I could feed my magic at the cost of my own blood.", tags = { "spell:Life_Tap", "!diary" } },
      { "I learned Renew, a healing that went on working after the prayer ended, and went on burning in my hands as long as it did.", tags = { "spell:Renew", "race:Scourge", "!diary" } },
      { "Resurrection was mine now; of all people, I knew what it was to be called back.", tags = { "spell:Resurrection", "race:Scourge", "!diary" } },
      { "I can pay for my magic with my own health now, and I have not yet decided whether that is a bargain.", tags = { "diary", "spell:Life_Tap" } },
      { "Fear is mine to cast now, and I like having the terror on the other side of a fight for a change.", tags = { "diary", "spell:Fear" } },
      { "Drain Life is mine now, a spell that keeps me standing on someone else's account.", tags = { "diary", "spell:Drain_Life" } },
      { "I added Corruption to what I can do, a slow and patient kind of harm.", tags = { "diary", "spell:Corruption" } },
      { "I can pour my own health into a demon now, which says something about the arrangement between us.", tags = { "diary", "spell:Health_Funnel" } },
      { "I can turn a foe into a sheep now, and I suspect I will never tire of it.", tags = { "diary", "spell:Polymorph" } },
      { "Blink is mine now, a single step that puts danger some distance behind me.", tags = { "diary", "spell:Blink" } },
      { "Frost Nova lets me pin an enemy in ice while I find a better place to stand.", tags = { "diary", "spell:Frost_Nova" } },
      { "I can conjure my own water now, one less thing to carry and one less thing to ask for.", tags = { "diary", "spell:Conjure_Water" } },
      { "I can set a ward between myself and a blow now, and I feel steadier for it.", tags = { "diary", "spell:Power_Word:_Shield" } },
      { "Renew is mine, a healing that keeps working long after the prayer is done.", tags = { "diary", "spell:Renew", "!race:Scourge" } },
      { "I can call the dead back now, and I mean to treat that gift with care.", tags = { "diary", "spell:Resurrection", "!race:Scourge" } },
      { "Psychic Scream is mine now, and my fear has somewhere to go besides my own stomach.", tags = { "diary", "spell:Psychic_Scream" } },
      { "Lay on Hands is mine now, something left to give when nothing else will do.", tags = { "diary", "spell:Lay_on_Hands" } },
      { "Divine Protection can give me a moment nothing can touch, and I am learning to wait for the right one.", tags = { "diary", "spell:Divine_Protection" } },
      { "Hammer of Justice is mine now, a way to stop a foe in the middle of its intentions.", tags = { "diary", "spell:Hammer_of_Justice" } },
      { "I can close the distance in a single rush now, before my fear has time to catch up.", tags = { "diary", "spell:Charge" } },
      { "Execute is mine now, for finishing a fight that has gone on long enough.", tags = { "diary", "spell:Execute" } },
      { "I can lift a purse now without its owner noticing, and I find I keep a closer hand on my own.", tags = { "diary", "spell:Pick_Pocket" } },
      { "Sap is mine, and a foe can now sleep through the start of its own bad luck.", tags = { "diary", "spell:Sap" } },
      { "I can vanish from a fight now, and leave an enemy wondering where I went.", tags = { "diary", "spell:Vanish" } },
      { "Sprint is mine now, and leaving trouble behind has never been easier.", tags = { "diary", "spell:Sprint" } },
      { "I can run with a cheetah's speed now, and the long roads have shrunk to fit.", tags = { "diary", "spell:Aspect_of_the_Cheetah" } },
      { "I can play dead now, convincingly enough that I hope never to need the real thing.", tags = { "diary", "spell:Feign_Death" } },
      { "Hunter's Mark is mine now, and no quarry of mine will vanish into the crowd.", tags = { "diary", "spell:Hunter's_Mark" } },
      { "I can borrow a ghost wolf's shape from the spirits now, and the roads feel shorter for it.", tags = { "diary", "spell:Ghost_Wolf" } },
      { "I can call a fallen friend's spirit back to their body now, a gift I hope to need rarely.", tags = { "diary", "spell:Ancestral_Spirit" } },
      { "Lightning Shield is mine now, thunder waiting for anyone who reaches for me.", tags = { "diary", "spell:Lightning_Shield" } },
      { "Entangling Roots is mine, and the earth will hold an enemy for me when I ask.", tags = { "diary", "spell:Entangling_Roots" } },
      { "Rebirth is mine now, the wild's way of refusing a death that came too soon.", tags = { "diary", "spell:Rebirth" } },
      { "Immolate is mine now, a fire that keeps burning after I have stepped away.", tags = { "diary", "spell:Immolate" } },
      { "I can call on Renew now, though its healing burns in my hands for as long as it works.", tags = { "diary", "spell:Renew", "race:Scourge" } },
      { "I can call the dead back now; of all people, I know what that means.", tags = { "diary", "spell:Resurrection", "race:Scourge" } },
    },
