        { "I am still on my feet, though only just, and I intend to find the flaw that nearly cost me everything before something else finds it for me.", tags = { "near" } },
        { "Close quarters have never unsettled me the way they unsettle some folk, and that dungeon put the boast to a fair test.", tags = { "delve" } },
        { "I died out there, and nothing stings quite like watching something give way under load, even when the something is me.", tags = { "hard" } },
        { "I came within a hair's breadth of the end, and I keep turning that moment over like a doubtful casting, hunting for the air bubble that nearly split it.", tags = { "near" } },
        { "The first rule of any dig is to come back out of it, and that place leaned on the rule harder than I would have liked.", tags = { "delve" } },
      },
      ["d-foes"] = {
        { "I took the measure of {foes} and found my own was enough, which is the kind of sum I like.", tags = { "one", "!hard" } },
        { "When the fighting was done, {foes} lay at my feet, and I allowed myself a moment's pride in clean work.", tags = { "one", "!hard" } },
        { "The fight with {foes} took everything I had to give, and a good deal I had not known was there.", tags = { "one", "hard" } },
        { "I got the better of {foes} in the end, though only by the thickness of my own hide.", tags = { "one", "hard" } },
        { "Both {foes} fell to me, and I came away from each with the sound of it still ringing in my ears.", tags = { "two", "!hard" } },
        { "I fought {foes} and came out the other side of both, though one of them left me a good deal less sound than it found me.", tags = { "two", "hard" } },
        { "I dealt with {foes} in turn, and all of them finished on the ground and I on my feet, which is the proper order of things.", tags = { "!one", "!two", "!hard" } },
        { "I fought my way through {foes}, and by the last of them there was very little of me left that had not been knocked loose.", tags = { "!one", "!two", "hard" } },
      },
      ["d-land"] = {
        { "I stepped into {lands} for the first time, a newcomer with a strong back and a great many questions.", tags = { "one", "!home", "!hosts" } },
        { "I had my first sight of {lands}, with all the quiet greed of a prospector looking over untried ground.", tags = { "one", "!home", "!hosts", "!town" } },
        { "I reached {lands} for the first time, and gave it the long, slow look my people give anything they might one day have to build on.", tags = { "one", "!home", "!hosts" } },
        { "I added {lands} to the places I have seen for myself, and to my mind nothing short of that counts as knowing a place.", tags = { "!one", "!home", "!hosts" } },
        { "I walked into {lands}, one new country after another, until my boots knew more of the world than my head did.", tags = { "!one", "!home", "!hosts" } },
        { "I came into {lands} for the first time, and the stonework there knew my people's hands even if the roads did not yet know my feet.", tags = { "one", "home" } },
      },
      ["d-react"] = {
        { "That was one less name for the mountain to worry about, and I did not mourn it.", tags = { "villain" } },
        { "It was a fight worth the walk, and I came away from it with nothing to regret.", tags = { "villain" } },
        { "Getting someone home in one piece is work I would do again without asking the wage.", tags = { "rescue" } },
        { "I have dug a good many things out of the ground, but none I was gladder to bring back.", tags = { "rescue" } },
      },
      ["died"] = {
        { "{foe} killed me {at}. I had been as stubborn as stone, and about as quick to get out of the way.", tags = { "foe" } },
        { "I fell to {foe} {at}; I had thought myself harder to break than that.", tags = { "foe" } },
        { "I fell to my death {at}; a dwarf's fondness for mountains was no protection against the drop.", tags = { "fall" } },
        { "I drowned {at}, longing for a stretch of good, dry stone under my feet.", tags = { "drowning" } },
        { "I died {at}, without having learned half of what the mountain kept from us." },
        { "Fire killed me {at}; I was flesh, for all my people's fondness for the forge.", tags = { "lava" } },
        { "I died {at}, and the ground that usually steadied me had offered no refuge.", tags = { "nature" } },
        { "{foe} killed me {at}. I hated the thought of leaving my kin to hear the name without me.", tags = { "foe" } },
        { "I died {at}, with more country left to see and a great deal of ale I would never taste." },
      },
      ["flight"] = {
        { "My first flight from {from} to {to} gave me a splendid view, though I would have enjoyed it more from a mountain.", tags = { "first" } },
        { "I flew from {from} to {to}, with the ground below looking reassuringly solid and inconveniently distant.", tags = { "!first" } },
        { "I flew from {from} to {to}, grateful not to have to prove my endurance over every mile.", tags = { "!first" } },
        { "I flew from {from} to {to}, feeling rather too substantial to be held up by anything but stone." },
        { "My first flight from {from} to {to} was worth the view, once my stomach agreed to come along.", tags = { "first", "aside" } },
      },
      ["kills-two"] = {
        { "I counted {n1} {foes1} and {n2} {foes2}, enough fighting to blunt a good axe.", tags = { "melee" } },
        { "The tally was {n1} {foes1} and {n2} {foes2}. I had had a bellyful of both." },
        { "I had brought down {n1} {foes1} and {n2} {foes2}, and felt rather older than I had at the start." },
      },
      ["kills"] = {
        { "I had brought down {n} {foes}, though I would sooner have spent the strength in the Hall of Explorers among older and quieter things." },
        { "I counted {n} {foes} among the fighting, with a proper thirst for a quiet evening afterwards." },
        { "{n} {foes} had fallen to me; I had held up, though not without feeling the hammering." },
        { "I had fought {n} {foes}, enough to make the din of the Great Forge sound restful.", tags = { "lots" } },
      },
      ["kin"] = {
        { "Another dwarf was working far from Ironforge, and the name made the mountain feel nearer." },
        { "We were both dwarves beyond the snows of Dun Morogh, and the distance was easier to bear shared between two." },
        { "That was another of the mountain's people, and I felt a little less far from home." },
        { "Finding another of King Magni's people out here made the road home seem shorter." },
        { "Here was another dwarf beyond the mountain, and I hoped we would both have something good to bring back." },
      },
      ["night"] = {
        { "I slept rough {at}; the earth had little of a dwarven mason's care for comfort.", tags = { "!last" } },
        { "I settled outside {at}, and missed the honest weight of stone overhead.", tags = { "!last" } },
        { "I lay down {at}, wondering how stone could feel so friendly at home and so hard beneath a back.", tags = { "!last" } },
        { "I bedded down {at}, with all the grace of a sack of ore being unloaded.", tags = { "!last" } },
        { "I slept outside {at}, and would have given a good deal for four thick walls and a door that shut.", tags = { "!last" } },
        { "I settled on the ground {at}; I had a newly tender feeling for innkeepers.", tags = { "!last" } },
        { "I lay down outside {at}, feeling less like a traveller than a stone someone had finally dropped.", tags = { "last" } },
        { "I settled beneath the sky {at}, with my bones rather less hard than the ground seemed to expect.", tags = { "last" } },
        { "I bedded down {at}, making a private promise to appreciate the next proper bed.", tags = { "last" } },
      },
      ["opening"] = {
        { "I got under way {at}, trusting my legs to hold out longer than the day's troubles." },
        { "I began again {at}, feeling sturdy enough to make the road earn my complaints." },
        { "I set out {at}, with more of the world to see than the inside of a mountain." },
        { "I set off {at}, with the Explorers' League's taste for old stone and unanswered questions." },
        { "I continued {at}, convinced that most trouble gives way if it is leaned on long enough." },
        { "I began this stretch {at}, with a job half done and no intention of leaving it that way." },
        { "The stone beneath a road could have a longer history than the road itself, and I set out {at} to see what I could." },
        { "I set off {at}, in a cheerful mood I doubted even the road could wear through." },
        { "I took up the road {at}, with the mountain's safety already precious in my mind." },
        { "Rams are sure of their footing on any ice, and I took up the road {at} hoping to be half as sure of my own." },
        { "I went on {at}, in no great hurry and in no doubt that I would get where I was going." },
        { "I began again {at}, spending my strength as carefully as I would spend good coin." },
        { "I made a start {at} after dark, giving every shadow the suspicion I would give a cracked beam overhead.", tags = { "night" } },
        { "Brann Bronzebeard never waited for a road to be safe before taking it, and I started out {at} in something of the same spirit." },
        { "The gnomes of Tinker Town knew better than anyone what a lost home costs, and I set out {at} with my own all the dearer for it." },
        { "I made ready {at}, sizing up the day's work by its weight rather than by my worries." },
        { "I set off {at} feeling properly tempered, hard enough for the day's knocks without being brittle about them." },
        { "I began {at} with my scales empty, ready to weigh the day as a fair assayer weighs ore, by what it turned out to hold." },
        { "I started off {at} after dark, which bothered me less than it might; the greatest city I know lies where no sunlight reaches.", tags = { "night" } },
        { "I set out {at} on ground my own people have held and worked for generations, which is as good a start as I know of.", tags = { "home" } },
        { "Good boots and a sound pack will carry anyone further than good intentions, and I took to the road {at} with the first two in decent order." },
        { "Somewhere an old sealed door is always waiting for the right hands, and I went looking {at}, quietly hoping they might be mine." },
        { "I began again {at}, steady on my feet and hard to knock over, which has always struck me as the right way to meet trouble." },
        { "I set out {at} among other people's roads and other people's walls, judging both by how squarely they had been built.", tags = { "!home" } },
        { "With daylight still to spend, I headed off {at} meaning to get good wear out of every hour of it.", tags = { "!night" } },
        { "My people are slow to start and slower to stop, and I got moving {at} meaning to live up to the second half at least." },
      },
      ["quests-many"] = {
        { "I had completed {n} jobs, and my legs were of the opinion that a few of them could have been done closer together." },
        { "By the end, {n} tasks were behind me, and a quiet evening had a great deal to recommend it." },
        { "I had finished {n} jobs for folk along the road; their names would give me something to talk of back in Ironforge." },
        { "The {n} tasks behind me were honest work, the kind the Bronzebeards respect." },
        { "I counted {n} jobs done, and began to understand the attraction of an evening at the inn." },
        { "I had brought {n} errands to an end, without finding a way to make the distance weigh any less." },
        { "Not one of the {n} tasks had been skimped, and I was prouder of that than of the number." },
        { "By my reckoning the {n} jobs came to a fair day's work, and I saw no reason to argue with my own sums." },
        { "I had lived through {n} tasks, and took more satisfaction in the living than in the tally.", tags = { "hc" } },
      },
      ["r-company"] = {
        { "someone to grumble at besides myself" },
        { "a companion worth having on the far side of the mountain", tags = { "one" } },
        { "the country no longer mine to face alone" },
        { "company I would gladly have bought a round for" },
        { "as heartening as the roofs of Kharanos after a cold walk" },
        { "two of us to hold the ground", tags = { "one" } },
        { "a second pair of eyes welcome after dark", tags = { "night", "one" } },
        { "more determined to see us both back alive", tags = { "hc", "one" } },
      },
      ["r-first"] = {
        { "more rattled than a mine cart on a bad rail" },
        { "my stomach as unsettled as loose scree" },
        { "close enough to make me miss the thick walls of Ironforge" },
        { "less tempted to mistake solid footing for safety" },
        { "already shaping it into a tale for the tables at the Thunderbrew" },
        { "those teeth giving me a new affection for distance", tags = { "teeth" } },
        { "my eyes no keener than anyone else's in that dark", tags = { "night" } },
        { "the little I had learned at Anvilmar looking very thin indeed", tags = { "low" } },
        { "the beginning of a grudge I meant to nurse for years" },
        { "my boots planted a good deal wider from then on" },
        { "the craftsmanship catching my eye even as they came at me", tags = { "mechanical" } },
        { "keener than ever to live long enough to grumble about it", tags = { "hc" } },
      },
      ["r-foe"] = {
