        { "I sat by the fire {at}, and let it be the only thing still working.", tags = { "last", "fire" } },
        { "I knocked off {at}, with the day's work stacked neatly behind me and no wish to add a single piece to the pile.", tags = { "last", "!fire" } },
        { "I set my burdens down {at}, and only then felt how much they had weighed.", tags = { "last" } },
        { "I drew up to the fire {at}, close enough to warm my toes and far enough to keep them, about the last fine judgement I had left in me.", tags = { "fire" } },
