      },
      ["close-light"] = {
        { "{foe} nearly finished me {at}, and my hands shook like a recruit's after the danger had passed." },
        { "I survived {foe} {at}, wanting the comfort of a door I could shut behind me." },
        { "{foe} nearly ended me {at}. I had been wishing for a less ordinary life; I was not wishing for that now." },
        { "I nearly fell {at}, with a sudden longing for the harmless noise of a crowded inn.", tags = { "!foe" } },
        { "I came through a close call {at}, feeling terribly soft beneath all the courage I had brought.", tags = { "!foe" } },
      },
      ["closing"] = {
        { "The work had kept me busy for {time}, and a quiet supper seemed an excellent use for what remained." },
        { "I had earned {gold} in {time}, and found myself already planning what not to spend the money on." },
        { "After {time}, an evening too dull for a town crier seemed a luxury." },
        { "I had spent {time} travelling; the road seemed to have followed me into every muscle." },
        { "The stretch had taken {time}, with no shortage of people needing more than I could offer." },
        { "I had spent {time} on the road and earned {gold}; a little money made the wish for a settled life less foolish." },
        { "All told it had taken {time}, enough to leave me as stiff as a sentry at the end of a double watch.", tags = { "slow" } },
        { "Only {time} had gone by, leaving me some leisure, which I meant to waste thoroughly.", tags = { "quick" } },
        { "I was still alive after {time} on the road, and as wary of the next stretch as Redridge was of the Blackrock orcs.", tags = { "hc" } },
      },
      ["d-close"] = {
        { "Dying has shown me how much I still want from the years ahead, and I mean to be careful enough to have them.", tags = { "hard", "!hc" } },
        { "It would have taken very little more to kill me, and I have stopped telling myself that such things only happen to other people.", tags = { "near" } },
        { "After that dungeon, I could happily spend a week on nothing more dangerous than the lane between two farms.", tags = { "delve" } },
        { "Death was an interruption rather than an ending this time, and I would rather not find out how many interruptions I am allowed.", tags = { "hard", "!hc" } },
        { "I keep turning that narrow escape over in my mind, the way one keeps checking a candle already snuffed, knowing it is out and looking all the same.", tags = { "near" } },
        { "I have only the one life, and from now on I mean to carry it the way a sensible traveller carries a full purse, close and well out of reach.", tags = { "hc", "near" } },
        { "In a place like that, I found out how much of my courage depends on knowing the way out, which is less courage than I had hoped and about as much as most people have.", tags = { "delve" } },
      },
      ["d-foes"] = {
        { "I put an end to {foes}, which is one less thing for honest folk to lie awake over.", tags = { "one", "!hard" } },
        { "I went up against {foes} with my heart in my mouth, and came away with nothing worse than a story.", tags = { "one", "!hard" } },
        { "{foes} came uncomfortably close to being the end of me, and I left that fight trusting my luck a good deal less than I had going in.", tags = { "one", "hard" } },
        { "I settled matters with both {foes}, and neither left me wishing I had stayed at home.", tags = { "two", "!hard" } },
        { "I got the better of both {foes}, though one of those fights very nearly went the other way.", tags = { "two", "hard" } },
        { "{foes} all went down while I stayed on my feet, which is the only way I care for a fight to end.", tags = { "!one", "!two", "!hard" } },
        { "I faced {foes} in turn, and each fight taught me something I would rather have learned from a book.", tags = { "!one", "!two", "!hard" } },
        { "I took on {foes}, all of them, and at least one of those fights was a nearer thing than anyone should have to live through twice.", tags = { "!one", "!two", "hard" } },
      },
      ["d-land"] = {
        { "I made my way into {lands} for the first time with a newcomer's manners, looking at everything and touching nothing.", tags = { "one", "!home", "!hosts" } },
