        { "I took my first steps in {lands}, each with its own roads to learn and its own dangers to respect.", tags = { "!one", "!home", "!hosts" } },
        { "I finally laid eyes on {lands}, a part of my own kingdom I had known only as a name until then.", tags = { "one", "home" } },
