        { "I defeated {boss} in {dungeon}, grateful that my own strength had held where no vanished patron could help me.", tags = { "faction:alliance" } },
        { "With {boss} down in {dungeon}, I wanted plenty of room around me and a long view, as anyone raised on Zephras would." },
