        { "fought {foe} the way I would cross a narrow bridge in Valanaar, without looking down until it was over", tags = { "!many" } },
        { "took on {foe} with my one life guarded as carefully as a harvested windstone", tags = { "hc" } },
      },
      ["campfire"] = {
        { "I rested beside a fire {at}, an element that at least answered when I came close, as the wind spirits had not for centuries.", tags = { "faction:horde" } },
        { "I sat by a fire {at}, with a comfort that required no recovered secret from Eldre'Thalas.", tags = { "faction:alliance" } },
        { "I stopped by a fire {at}, and warmed my hands like any traveller, Highborne blood or no." },
