        { "I sat by a fire {at}, enjoying a warmth that came without a pact and promised nothing it could not keep." },
        { "I rested by a fire {at}, and watched it the way my people had learned to watch anything that might go out." },
      },
      ["close-deep"] = {
        { "{foe} nearly killed me {at}. Our mentors were still missing, and I could not bear for the Windshapers to lose one more of their own before we found them.", tags = { "faction:horde" } },
        { "I barely survived {foe} {at}; the High Order's resolve felt terribly frail inside one frightened body.", tags = { "faction:alliance" } },
        { "{foe} brought me close to death {at}, and for a moment Zephras felt as lost to me as the islands we no longer heard from." },
        { "I barely survived {foe} {at}; every scrap of my composure had deserted me, and I was too glad to be alive to mind." },
        { "{foe} nearly finished me {at}; I thought of the refugees from Ban'aethal, who had lost their homes in a single night, and held on." },
      },
      ["close-light"] = {
        { "{foe} nearly killed me {at}, and the silence of our missing wind spirits hurt afresh.", tags = { "faction:horde" } },
        { "I survived {foe} {at}, with a new tenderness for the body the High Order expected to stand on its own.", tags = { "faction:alliance" } },
        { "{foe} brought me close to death {at}, and I thought, absurdly, of Windfield Orchard and whether I would ever see it again." },
        { "I barely survived {foe} {at}, with my balance slow to return even once I was standing safely." },
        { "{foe} nearly ended me {at}, and afterwards I kept very still, as one learns to on a narrow ledge, until the shaking passed." },
      },
      ["closing"] = {
        { "I had been at it for {time}, no nearer to the wind spirits, but perhaps a little nearer to the allies we would need to find them.", tags = { "faction:horde" } },
        { "The stretch had taken {time}, enough to make the High Order's appetite for self-reliance feel rather tiring.", tags = { "faction:alliance" } },
        { "After {time}, even my curiosity about so large a world was ready to rest." },
        { "I had earned {gold} in {time}, a sum I would gladly have traded for one evening's news from Anvilas or Siroccas." },
        { "I had spent {time} travelling, and company without an errand attached would have suited me." },
        { "The work had taken {time}, and I had walked more of it than I would once have believed one pair of feet could manage.", tags = { "slow" } },
        { "After {time}, I could not pass a pylon without looking to see whether it still held.", tags = { "home" } },
        { "I had survived {time}, and meant my ashes to wait a long while yet before anyone gave them to the winds.", tags = { "hc" } },
        { "I had been at work for {time}, and my courtesy had held up rather better than my feet." },
      },
      ["d-close"] = {
        { "Death was a long way to fall for a lesson in caution, and I would sooner take the next one from a lower height.", tags = { "hard", "!hc" } },
        { "My worst moment felt like the ground giving way beneath me, and it will be a while before I trust it to stay put.", tags = { "near" } },
        { "The dangers I was used to all lay out in the open, and that dungeon showed me how much worse they can be when there is no horizon to see them coming.", tags = { "delve" } },
        { "I died, and the world went on without so much as a pause, which is a humbling discovery for someone whose people feel every single loss.", tags = { "hard", "!hc" } },
        { "I came within a breath of the end, and since then I have carried my life the way we carry our old relics, as something only lent to me for a while.", tags = { "near" } },
        { "My people survived by slipping away from danger, not by walking into the heart of it, and that dungeon left me wondering which of the two I take after.", tags = { "delve" } },
      },
      ["d-foes"] = {
        { "I faced {foes} and came away the winner, and found the skysight my people prize as useful in a fight as on a far horizon.", tags = { "faction:horde", "one", "!hard" } },
        { "I brought down {foes}, and so learned one more of the names this world gives its dangers.", tags = { "one", "!hard", "!home" } },
        { "{foes} pushed me as near to the end as I ever want to go, and I came away with a new respect for anything that comes close to falling and keeps going, my island included.", tags = { "one", "hard" } },
        { "I defeated both {foes}, and would happily give the tale of either for a quiet hour on a skycutter's deck.", tags = { "two", "!hard" } },
        { "I fought {foes}, and neither fight went easily; by the end I was grateful for the plainest things, a next breath and solid ground under me.", tags = { "two", "hard" } },
        { "I dealt with {foes}, all of them, with hands that would have been just as content picking stormapples.", tags = { "!one", "!two", "!hard" } },
        { "{foes} all fell to me in turn, and I learned something from each, as one comes to know a strange wind, gust by gust.", tags = { "!one", "!two", "!hard" } },
        { "I got the better of {foes}, all of them, though one of those fights came closer to ending me than I like to admit, even to myself.", tags = { "!one", "!two", "hard" } },
      },
      ["d-land"] = {
        { "I set foot in {lands} for the first time, very likely one of the first of my people to walk there in an age.", tags = { "one", "!home", "!hosts" } },
        { "I came into {lands} for the first time, and turned its name over until it no longer sounded foreign to me.", tags = { "one", "!home", "!hosts" } },
        { "I walked into {lands} for the first time, and kept glancing up for the next island, as if the sky there might hold one too.", tags = { "one", "!home", "!hosts", "!town" } },
        { "I saw {lands} for the first time, more new country in a single stretch than I had once expected to see in my whole life.", tags = { "!one", "!home", "!hosts" } },
        { "I crossed into {lands} for the first time, looking in each for friends the Windshapers might one day call on.", tags = { "faction:horde", "!one", "!home", "!hosts" } },
        { "I travelled through {lands} for the first time, half hoping one of them still hid some scrap of the knowledge our forebears lost.", tags = { "faction:alliance", "!one", "!home", "!hosts" } },
      },
      ["d-react"] = {
        { "Of all the things this world has asked of me, ending that one is the part I would most willingly do again.", tags = { "villain" } },
        { "My people are too few to spare anyone, and I could not help counting a life saved twice over.", tags = { "rescue" } },
        { "Bringing someone safely home was the kind of work my people have always understood best.", tags = { "rescue" } },
        { "They were Highborne, as my own forebears had been until the rebellion in Eldre'Thalas, and I could not fight them without wondering what we might have become.", tags = { "highborne" } },
        { "My people left the Highborne behind for good reason, and meeting their ghosts showed me plainly what that reason was.", tags = { "highborne" } },
      },
