        { "an enchantment taking care of the homeward journey" },
        { "a haven kept within the reach of a stone" },
        { "almost as inviting as the prospect of being expected" },
        { "a stone I could trust to work every time, unlike the pylons" },
      },
      ["r-item"] = {
        { "each one counted twice, an islander's habit", tags = { "!one" } },
        { "learning how heavy useful things can be" },
        { "my interest in the search thoroughly satisfied" },
        { "a count I had no wish to see grow larger", tags = { "!one", "!plural", "!set" } },
        { "each piece weighed in my hand like ballast", tags = { "!one", "!plural" } },
        { "a find I could not stop turning over in my hands", tags = { "one", "!plural" } },
        { "keen to let someone else call it a treasure", tags = { "one", "!plural" } },
        { "a promising addition to supper despite the carrying", tags = { "meat" } },
        { "the weave worth a closer look than I had time to give it", tags = { "cloth" } },
        { "a wide view of little help where the darkness hid the find", tags = { "night" } },
        { "a find the scholars of the High Order would have catalogued twice", tags = { "faction:alliance" } },
        { "finer stuff than the grey robes of the Al'Aketh, and put to better use", tags = { "cloth" } },
        { "my appetite quite impatient with the business of carrying", tags = { "meat" } },
        { "keener on finishing the search than on admiring the view" },
        { "one burden I hoped would not travel far with me" },
        { "the sort of kaldorei ingredient our dwindling home had long gone without", tags = { "plant" } },
        { "dull company after the windstones of home", tags = { "stone" } },
        { "a reminder of the hippogryph feathers my people wear in their hair", tags = { "feather" } },
        { "a fragile way to keep words, to someone used to the crystals of home", tags = { "paper" } },
      },
      ["r-lesson"] = {
        { "an unfamiliar knack demanding a beginner's care", tags = { "one" } },
        { "an apprentice's difficulty hidden behind an assured manner" },
        { "something to keep wherever the road went", tags = { "one" } },
        { "a new skill to keep when a mentor could not stay", tags = { "faction:alliance", "one" } },
        { "my balance in no danger, and my pride less fortunate" },
        { "a knack I hoped to give back to those who needed me", tags = { "faction:horde", "one" } },
        { "a skill the High Order could keep without a patron's favour", tags = { "faction:alliance", "one" } },
        { "a craft useful enough to make a stranger welcome", tags = { "new" } },
        { "a beginner again, which my pride took harder than my hands", tags = { "new" } },
        { "as clumsy as a fledgling in a first gust", tags = { "low" } },
        { "an apprentice with no blessing to make the difficult part easy", tags = { "high" } },
        { "new skills to keep when a mentor could not stay", tags = { "faction:alliance", "!one" } },
        { "my fingers learning the part no wide view could supply" },
        { "readier to ask for help than to let pride keep me helpless" },
        { "an unfamiliar knack beginning to feel useful", tags = { "one" } },
      },
      ["r-road"] = {
        { "the distance measured out step by step, the slow way" },
        { "each face a new one to learn", tags = { "!back" } },
        { "an uncertain welcome to make with nothing but good manners", tags = { "!back" } },
        { "a place my people had no account of, after so many centuries away", tags = { "!back", "!home" } },
        { "my eyes patient with a night that offered few directions", tags = { "!back", "night" } },
        { "my steps easier in a place that had once seemed foreign", tags = { "back" } },
        { "the familiar turns giving an easy welcome", tags = { "back" } },
        { "the return taking the uncertainty out of my arrival", tags = { "back" } },
        { "this world almost as familiar to me now as Zephras", tags = { "high", "!home" } },
        { "a Windshaper seeking company for the search still ahead", tags = { "faction:horde", "!back" } },
        { "wondering what use the High Order could make of a life lived here", tags = { "faction:alliance", "!back" } },
        { "with an islander's eye for a long view" },
        { "every step taken on trust in the dark", tags = { "night" } },
        { "the arrival costing some of the courage I had set out with" },
      },
      ["r-task"] = {
        { "help given freely, as the wind spirits once gave theirs" },
        { "an errand that asked more walking than an islander is used to" },
        { "my hands finding a use no blessing needed to supply" },
        { "the work as painstaking as anything done close to an edge" },
        { "as plain an errand as any I had known, and none the worse for it" },
        { "a Windshaper's care given to people instead of the spirits' old instruments", tags = { "faction:horde" } },
        { "a route I hoped another traveller could follow without a blessing", tags = { "explore" } },
        { "the route acquiring the familiarity of a path at home", tags = { "explore" } },
        { "a slower pace worth the trouble of keeping another life safe", tags = { "escort" } },
        { "the dark making a slow business of every step", tags = { "night" } },
        { "the people here a little less strange to me afterwards", tags = { "!home" } },
        { "help of a sort that asks nothing of any spirit" },
        { "as tired as a gull that has fought the wind all day" },
        { "something the High Order could count on my hands to finish", tags = { "faction:alliance" } },
        { "my courtesy lasting a little longer than my patience" },
        { "wondering whether a wind spirit would find our errands amusing" },
        { "the way fixed in my memory for the return", tags = { "explore" } },
      },
      ["rare"] = {
        { "I brought down {foe} {at}, and hoped the wind spirits would one day hear the tale from me instead of finding another silence.", tags = { "faction:horde" } },
        { "{foe} fell to me {at}, a trial I would rather have survived than offered as proof of the High Order's strength.", tags = { "faction:alliance" } },
        { "I overcame {foe} {at}, and wished someone from home had seen it, if only to believe me later." },
        { "I killed {foe} {at}, and left the thought of another fight well alone." },
      },
      ["rest"] = {
        { "I settled {at}, content that the High Order's future need not be built by one exhausted pair of hands.", tags = { "faction:alliance" } },
        { "With no vanished patron to ask permission of, I stopped {at}.", tags = { "faction:alliance" } },
        { "I rested {at}; the lore of Eldre'Thalas had been lost for thousands of years, and could stay lost until I had my strength back.", tags = { "faction:alliance" } },
        { "I rested {at}, and let the search for our lost mentors wait an hour without feeling I had abandoned it.", tags = { "faction:horde" } },
        { "I stopped {at}, a Windshaper off duty, if such a thing existed.", tags = { "faction:horde" } },
        { "I rested {at}, taking a private pleasure in being idle." },
        { "I settled {at}, grateful to stop finding my way through the dark.", tags = { "night" } },
        { "Shen'dorei means the hidden people, and for a while {at} I was happy to live up to the name." },
        { "I rested {at}, a long way from the skydocks of Valanaar, and not unhappy about it.", tags = { "!home" } },
        { "I stopped {at}, and let myself forget, for a little while, that the island was failing beneath me.", tags = { "home" } },
        { "I rested {at}, and for once did not listen for a voice in the stillness, as my people had done for centuries." },
        { "I rested {at}, and thought of the crystals at the Calmbreeze Inn and their long account of the rebellion in Eldre'Thalas.", tags = { "!home" } },
        { "I rested {at}, and let my thoughts wander back to Windfield Orchard and the unhurried work of its trees.", tags = { "!home" } },
        { "I paused {at}, my feet aching from more walking than a year on Zephras had ever asked of them.", tags = { "!home" } },
        { "I rested {at}, determined not to become one more thing Zephras had lost.", tags = { "hc" } },
        { "I stopped {at}, and allowed myself the rare courtesy of having nothing to do." },
        { "I sat by the fire {at}, where the smoke was the only thing in sight in any hurry to reach the sky.", tags = { "fire" } },
        { "I stopped {at} once the work was done, and for a while kept nothing aloft but my own spirits.", tags = { "last", "!fire" } },
        { "I paused {at}, and went back over what I had done the way my scholarly forebears might have gone over a difficult text, unhurried and with some pleasure.", tags = { "!last", "faction:alliance" } },
        { "I rested {at}, my skysight as idle as my feet for once.", tags = { "!last", "faction:horde" } },
      },
      ["revived"] = {
        { "I found my body as a ghost {at}, a spirit myself for a while, and no closer to the ones we were sworn to find.", tags = { "corpse", "faction:horde" } },
        { "I returned to my body {at}, with the High Order's future too dear to me to spend my life carelessly.", tags = { "corpse", "faction:alliance" } },
        { "A spirit healer restored me {at}; I could gladly bear the weakness for a place among the living.", tags = { "healer" } },
        { "{by} brought me back {at}, and I meant to remember the name for as long as I lived.", tags = { "ally" } },
        { "My own preparation returned me to life {at}, with my hands having kept what pride alone could not.", tags = { "self" } },
      },
      ["summit"] = {
        { "I reached level {level}, still sworn to find the wind spirits and bring them home, and far better able now to keep that oath.", tags = { "faction:horde" } },
        { "At level {level}, I had become what the High Order hoped for: strong enough to stand on my own, with no patron to thank for it.", tags = { "faction:alliance" } },
        { "I reached level {level}, with Zephras and the people of Azeroth both mine to care for now, and no wish to choose between them." },
      },
      ["wake"] = {
        { "I rose {at}, rested, and as sure as ever that the spirits could still be found.", tags = { "rest", "faction:horde" } },
        { "I took up the road {at}, clear-headed enough to be of use to the High Order, and to myself.", tags = { "rest", "faction:alliance" } },
        { "Stiff from the night outside and quite unwilling to show it, I rose {at}.", tags = { "!rest" } },
        { "I rose {at}, taking pleasure in the simple prospect of an unfamiliar day.", tags = { "!rest" } },
        { "The world was exactly where I had left it the night before, and I set out again {at} rather relieved.", tags = { "!rest" } },
        { "Rested at last, I greeted the day {at} with something like the grace my people are supposed to have.", tags = { "rest" } },
      },
      ["zone"] = {
        { "I came into {zone}, with the Grand Skyseer's words in mind: the path to our salvation lay below.", tags = { "faction:horde", "!home" } },
        { "I reached {zone}, holding to the Supreme Magister's belief that Azeroth was the key to our future.", tags = { "faction:alliance", "!home" } },
        { "I crossed into {zone}, and caught myself looking for the place where it would simply stop, as every road on Zephras eventually did.", tags = { "!home", "!back" } },
        { "I came back to {zone}, where the edges of the world were open sky again.", tags = { "home" } },
        { "I returned to {zone}, and counted the pylons still standing as I came in.", tags = { "home" } },
        { "I entered {zone}, a stranger with thousands of years of my people's absence to account for, if anyone asked.", tags = { "!home", "!back" } },
        { "I returned to {zone}, and walked its roads now without looking for a drop at every turn.", tags = { "back", "!home" } },
        { "I was home in {zone} again, ready to say \"Gale's greetings\" and mean every word of it.", tags = { "home" } },
        { "I came to {zone} and took its measure slowly; a single life is quickly spent in a place one does not know.", tags = { "hc", "!home", "!back" } },
      },
    },
    ["Tauren"] = {
      ["beginning"] = {
        { "I began {at}; the tribes had held Mulgore in peace only since the centaur were driven off, and I did not mean to take that peace for granted." },
        { "I set out {at}; the orcs had helped us find a settled home, and I wanted to know the neighbours beyond it." },
        { "I began {at}, asking the Earth Mother for a good road rather than a short one." },
        { "I set out {at}, hoping to be of use to Cairne's people first and to the wider world in time." },
      },
      ["boss-final"] = {
        { "{boss} fell, and my work in {dungeon} was finished. The prospect of open country had never been so dear to me." },
        { "I defeated {boss} in {dungeon}, and felt my breath settle into something gentler than a struggle." },
        { "With {boss} down in {dungeon}, I could think of Mulgore without fearing I would never return." },
      },
      ["c-elite"] = {
        { "faced {foe} and lived, though my legs took a long while to agree that we had", tags = { "!many" } },
        { "fought {foe} to the end, and found no boast in me when it was over, only a wish to sit down" },
        { "brought down {foe}, quarry worthy of a great hunt", tags = { "!people", "!many" } },
        { "stood my ground against {foe}, as firm as a totem and a good deal less sure of it" },
        { "overcame {foe}, with my one life suddenly worth more to me than any tale the fight might make", tags = { "hc" } },
        { "wore down {foe}, and took every breath that followed as a gift" },
      },
      ["campfire"] = {
        { "I sat beside a fire {at}, with its warmth recalling the ease of a shared camp." },
        { "I paused by the fire {at}, enjoying a gentle warmth that asked for nothing in return." },
        { "I rested by a fire {at}, a small piece of An'she's warmth beside me." },
        { "The fire {at} made a small bright room of the dark, and I wished it had more company around it.", tags = { "night" } },
        { "I stopped by the fire {at}, and thought it a waste of good flames to have nothing roasting over them." },
        { "Nothing hurried me {at}, so I settled by the fire and let it burn down at its own pace, which was much the same as mine." },
      },
      ["close-deep"] = {
        { "{foe} nearly killed me {at}. I thought of the Earth Mother, but I was not ready to leave the people who still walked here." },
        { "I barely survived {foe} {at}, and would have given anything to be on a wind rider's back and far away." },
        { "{foe} left me barely alive {at}. I wanted to hear a kodo across the plains and know I still belonged among living things." },
        { "I barely survived {at}, and longed for Thunder Bluff's shelter with a fear my size could not disguise.", tags = { "!foe" } },
        { "I came very near the end {at}, with the wish to stand beneath An'she again stronger than any pride in the fight.", tags = { "!foe" } },
      },
      ["close-light"] = {
        { "{foe} nearly ended me {at}; being difficult to move had not made me difficult to kill." },
        { "I survived {foe} {at}, with my heart heavy and my breath unwilling to quiet." },
        { "{foe} brought me close to death {at}. I was in no hurry to join the ancestors, however much my people honour them." },
        { "I nearly fell {at}, and wanted nothing so much as to sit on Spirit Rise with Mulgore spread out below me.", tags = { "!foe" } },
        { "I came through a close call {at}, and felt suddenly very tender towards the life in this great body.", tags = { "!foe" } },
      },
      ["closing"] = {
        { "The work had occupied {time}, and I thought of Mulgore's evening grass bending in the wind.", tags = { "!home" } },
        { "I had earned {gold} in {time}, a little more to bring back to Thunder Bluff." },
        { "After {time}, the simple peace of not being needed felt almost extravagant." },
        { "I had spent {time} travelling, with the distance lodged firmly in my hooves." },
        { "The stretch had taken {time}. I would have liked an evening of the elders' stories, and nothing asked of me." },
        { "I had spent {time} on the road and earned {gold}; I could leave both the distance and the money alone for a while." },
        { "It had taken {time}, and by the end even legs as unhurried as mine wanted to stop.", tags = { "slow" } },
        { "I had been at it for {time}, and liked ending the stretch within sight and sound of other people.", tags = { "rest" } },
        { "{time} had gone by, and I counted being alive at the end of it the best of the day's earnings.", tags = { "hc" } },
      },
      ["d-close"] = {
        { "I have walked more softly since dying, as if the land had reminded me whose it is.", tags = { "hard" } },
        { "Coming so near my own end has made me think more gently about the ends I bring to others.", tags = { "near" } },
        { "There are places in this world that feel like wounds in the land, and I went into one; I hope I left it a little nearer to healing.", tags = { "delve" } },
        { "Dying has shown me that the Earth Mother is patient with her children, and I would rather not learn where that patience ends.", tags = { "hard", "!hc" } },
        { "I came close enough to the end that the ancestors seemed only a step away, and I am not ready to take that step.", tags = { "near" } },
        { "I am made for long views, and a place where every turning hid an enemy has left me hungry for a horizon.", tags = { "delve" } },
      },
      ["d-foes"] = {
        { "I met {foes} without hurry and without hatred, which is how I would want to meet any foe.", tags = { "one", "!hard" } },
        { "I faced {foes} and won, and took no more pleasure in the winning than a good hunter takes in the kill.", tags = { "one", "!hard" } },
        { "The fight with {foes} came nearer to ending me than any other, and I left it a good deal humbler than I went in.", tags = { "one", "hard" } },
        { "I faced both {foes}, and neither fight left me wanting another.", tags = { "two", "!hard" } },
        { "Between {foes}, I came nearer the end than I wanted, and learned how much of the open land I still mean to walk.", tags = { "two", "hard" } },
        { "{foes} fell to me in turn, and I wish each of them more peace now than the fight allowed them.", tags = { "!one", "!two", "!hard" } },
        { "I faced {foes}, and carried no anger from one of those fights into the next.", tags = { "!one", "!two", "!hard" } },
        { "{foes} all stood against me, and one of those fights very nearly gave my bones to the earth.", tags = { "!one", "!two", "hard" } },
      },
      ["d-land"] = {
        { "I walked into {lands} for the first time, careful not to treat it as mine to use.", tags = { "one", "!home", "!hosts" } },
        { "I set hoof in {lands} for the first time, and its ground felt different under me in ways I could not yet name.", tags = { "one", "!home", "!hosts", "!town" } },
        { "I came into {lands} for the first time, and wondered who had walked that ground first, and whether they had walked it gently.", tags = { "one", "!home", "!hosts", "!town" } },
        { "I saw {lands} for the first time, and let each of them be what it was before I made up my mind about it.", tags = { "!one", "!home", "!hosts" } },
        { "I came into {lands} for the first time, mindful that others had loved that ground long before I set eyes on it.", tags = { "!one", "!home", "!hosts" } },
        { "I crossed into {lands} for the first time, and found the Earth Mother's hand in each, however strange the face it showed me.", tags = { "!one", "!home", "!hosts" } },
      },
      ["d-react"] = {
        { "I do not hunt for hatred, but that one had wronged the land and its people, and I did not grieve its end.", tags = { "villain" } },
        { "Some harm will not stop until it is stopped, and I was the one who stopped it.", tags = { "villain" } },
        { "Bringing someone home was the kind of strength the elders would have praised, and I was glad to have spent mine that way.", tags = { "rescue" } },
        { "A life carried safely home weighs more than any kill, and I felt the difference.", tags = { "rescue" } },
        { "I was raised to honour Cenarius's children, and raising a hand against them sat heavily on me, whatever had turned them.", tags = { "cenarion" } },
        { "I asked the beast's pardon afterwards, as my people do, and meant it.", tags = { "beast" } },
      },
      ["died"] = {
        { "{foe} killed me {at}, and I wanted the long view from the mesas of Thunder Bluff more than any revenge.", tags = { "foe" } },
        { "I fell to my death {at}, with no ground beneath my hooves until the ground could do me no kindness.", tags = { "fall" } },
        { "I drowned {at}; neither horns nor strength could bring the air within reach.", tags = { "drowning" } },
        { "Fire killed me {at}, and my last thought was of the cool water of Winterhoof Water Well.", tags = { "lava" } },
        { "I died {at}, with no enemy to meet and no path my hooves could hold.", tags = { "nature" } },
        { "I died {at}, far too willing to remain a child of the Earth Mother to welcome returning to her." },
      },
      ["flight"] = {
        { "My first flight from {from} to {to} made me wish I weighed less, though I would not have traded away the view.", tags = { "first" } },
        { "I flew from {from} to {to}, missing the honest certainty of earth beneath my hooves." },
        { "I left {from} by air for {to}, looking down with a new sympathy for those who thought Thunder Bluff too high." },
      },
      ["kills-two"] = {
        { "I counted {n1} {foes1} and {n2} {foes2} {at}; I would sooner have spent the strength bringing a hunt home." },
        { "The fighting {at} had accounted for {n1} {foes1} and {n2} {foes2}, and I wanted no more deaths to weigh against my own survival." },
        { "I had brought down {n1} {foes1} and {n2} {foes2} {at}, enough to make me wish for the gentler work of tending a herd." },
      },
      ["kills"] = {
        { "I counted {n} {foes} among the fighting {at}, with a word to the Earth Mother for each of them." },
        { "{n} {foes} had fallen to me {at}; I longed for the kind of road that asked nothing of my anger." },
        { "I had faced {n} {foes} {at}, enough to make me long for the drums of Thunder Bluff." },
      },
      ["kin"] = {
        { "Another shu'halo was working beyond Mulgore, and I felt less alone for knowing the name." },
        { "We both answered to Cairne Bloodhoof, and for a moment that was all the introduction either of us needed." },
        { "I was working with one of my own people again, and the name recalled the ease of Thunder Bluff." },
        { "Another of the plains' people was here; the country seemed less far from Mulgore for it." },
        { "We were both shu'halo away from home, still carrying something of our people's shared camps with us." },
      },
      ["night"] = {
        { "I lay down outside {at}, giving my weight to the earth without having to carry it another step.", tags = { "!last" } },
        { "I slept on the ground {at}, missing the ease of a camp shared with my people.", tags = { "!last", "!home" } },
        { "I bedded down {at}, leaving the watch to Mu'sha for the night.", tags = { "!last" } },
        { "I settled outside {at}, with new respect for the tribes, who had slept this way for generations before they had a land of their own.", tags = { "last" } },
        { "I lay down {at}, and listened for the drums of a plains camp many miles away.", tags = { "last", "!home" } },
        { "Under the open sky {at}, I stretched out and listened until the night's sounds became ordinary ones.", tags = { "!last" } },
        { "The day ended {at} with me on bare ground, too tired to mind it.", tags = { "last" } },
      },
      ["opening"] = {
        { "I took up the road {at} beneath An'she's watch, with a day's work ahead and no wish to hurry it.", tags = { "!night" } },
        { "I set out {at} beneath Mu'sha's watch, trusting her eye in the dark a good deal more than my own.", tags = { "night" } },
        { "I set out {at}, mindful of the trust our people had found in the orcs." },
        { "I began this stretch {at}, one of a people still learning the pleasures of a settled home." },
        { "I set off {at}, with my people's patience to draw on and my own unease to contend with." },
        { "I kept going {at}, at the unhurried pace of my people's old migrations." },
        { "I set out {at}, with Cairne's new home dear enough to make the wider world worth knowing." },
        { "I took up the road again {at}, in no more of a hurry than the lifts of Thunder Bluff, which nobody has ever managed to rush." },
        { "I began {at}, wanting to be useful without having to make a fight of it." },
        { "I made ready {at}, still wary of anyone who looked at a hillside the way the Venture Company had looked at ours." },
        { "As watchful as a tallstrider and, I hoped, rather harder to catch, I set out {at}." },
        { "The druids of Elder Rise would have had me leave each place no poorer than I found it, and I began again {at}, meaning to try." },
        { "I took to the road {at}, and the wind brought me nothing urgent, which I took as good counsel.", tags = { "!night" } },
        { "I began again {at}, wanting what any village wants of a day: the work done, and everyone back before dark.", tags = { "!night" } },
        { "The tribes had only lately joined the Horde, and I took up the road {at}, hoping to give the rest of it a good account of us." },
        { "Quick to help and slow to anger was how I hoped to meet strangers, and I continued {at} in that spirit.", tags = { "!home" } },
        { "Some of my people never leave sight of the mesas, and I took to the road {at} a little sorry for them and a little envious.", tags = { "!home" } },
        { "I went on {at}, with a good deal of strength and the sense to spend very little of it on anger." },
        { "I set out {at} while most sensible creatures slept, and tried to trouble the night no more than they did.", tags = { "night" } },
        { "Grass, stone or swamp, the ground has to carry me, and I started {at} meaning to tread on it kindly." },
        { "Slow to start and hard to stop, I began again {at}." },
        { "There was work to be shared {at}, and I rose to carry my part of it." },
        { "With every rise and hollow around me known by name, I made ready {at} in no doubt of my way.", tags = { "home" } },
        { "I kept on {at}, giving the land the courtesy I would ask of any stranger crossing ours.", tags = { "!home" } },
        { "I took up the work again {at}, as ready to listen as to fight, and rather hoping to do more of the first." },
        { "The ancestors walked further with less, and I set out {at} with that thought to keep my complaints in proportion." },
      },
      ["quests-many"] = {
        { "I had seen {n} tasks through, easing a little of the work for the people here." },
        { "The {n} tasks behind me had given me some of the pleasure of bringing a good hunt back to my people." },
        { "I counted {n} jobs finished, enough to welcome the quiet work of a settled camp." },
        { "By the end, {n} tasks were done, and I felt less a newcomer to the Horde and more a part of it." },
        { "I had completed {n} errands, and the people who asked for them felt a little more like a tribe." },
        { "I had brought {n} tasks to an end, enough to leave me content with my usefulness for the day." },
