        { "I bedded down {at}, missing the sound of the sea more than any bed.", tags = { "!last" } },
        { "I settled for the night {at}, with a private request to the loa for thoroughly dull dreams.", tags = { "!last" } },
        { "I lay down outside {at}, quite content to let the world get on without my interest for a while.", tags = { "last" } },
        { "I settled on the ground {at}, with the sea's rhythm dear to me in the quiet.", tags = { "last" } },
        { "Sleeping out was nothing new to a people who had lost more than one home, and I settled down {at} with little fuss.", tags = { "!last" } },
        { "Night found me {at} with nowhere better to be, and I slept as soundly as caution allowed.", tags = { "last" } },
      },
      ["opening"] = {
        { "I took up the road {at}, grinning, with an eye on whatever might be grinning back." },
        { "I began again {at}, thinking of the Echo Isles and the day we would take them back from Zalazane.", tags = { "!zalazane" } },
        { "I set out {at}, still fond of a world that had driven my people from too many shores." },
        { "I kept going {at}, cheerful in the way of a people who have had to laugh in some very poor places." },
        { "I set off {at}, with one of the old drumming songs going round in my head." },
        { "I began this stretch {at}, light on my feet and ready to change direction at the first sign of trouble." },
        { "I set out {at}, with a jungle-born wariness even where the jungle was only in my thoughts." },
        { "I returned to the road {at}, with the easy walk and the open eyes my people learned the hard way." },
        { "I set out {at}, thinking of Sen'jin Village and the people there who were counting on the rest of us." },
        { "Some of my own tribe still walked under Zalazane's hexes, and I set out {at} with that weighing on me more than any pack.", tags = { "!zalazane" } },
        { "Vol'jin had held our people together since his father's death, and I took up the road {at} meaning to be worth the trouble." },
        { "With what we owed Thrall in mind, I set out {at}, happy to pay a little of it back in ordinary work." },
        { "I made a start {at}, easy in my manner and careful with every step, which is how my people have outlived worse roads.", tags = { "hc" } },
        { "I took up the road {at} after dark, listening for the soft feet of anything that hunted at this hour.", tags = { "night" } },
        { "I took to the road {at}, and it looked friendly enough, which in my experience is the moment to look twice." },
        { "I began again {at}, my eyes going to the ground for scorpids out of plain Durotar habit.", tags = { "!home" } },
        { "Off I went again {at}, long legs first and good sense trailing somewhat behind." },
        { "Daylight {at} found me rested and ready to like whatever came next, which is all anyone back home ever asks of a morning.", tags = { "!night" } },
        { "I pushed off {at} the way fishers push off from the sand, all at once and without a backward look." },
        { "I headed off {at} already planning supper, the one kind of forethought nobody ever had to teach me." },
        { "I started out {at} in a generous mood, the kind that makes a long road feel more like a visit." },
        { "Nights at home belonged to the drums, so the dark {at} felt more like an invitation than a warning as I set out.", tags = { "night" } },
        { "I was up and about {at} with both tusks, all my limbs and most of my wits, which I counted a fine start." },
        { "Some part of me still expects every road to end at the water with something good on the coals, and I set out {at} as hopeful as ever." },
        { "I went on {at} among orcs who had been strangers to us once and were neighbours now, which still warms me.", tags = { "home" } },
        { "Nobody had asked me to fetch anything yet when I got going {at}, and I meant to enjoy that for as long as it lasted." },
      },
      ["quests-many"] = {
        { "I had finished {n} tasks, and was popular for all the most tiring reasons." },
        { "The {n} jobs behind me had left me more names to know than enemies to avoid, which I preferred." },
        { "I counted {n} errands done; Sen'jin Village never asked so much of me, and it was family." },
        { "By the end, {n} tasks were finished, and the Darkspear had one more pair of hands to show for them." },
        { "I had seen {n} jobs through, with the Darkspear's name travelling a little further than my own." },
        { "I had brought {n} errands to an end, and the thought of company without a favour attached delighted me." },
        { "{n} errands had been seen to, and I had long since stopped pretending each one would be the last." },
        { "By the time {n} tasks were done, I knew which requests to run towards and which to walk past slowly." },
        { "I had seen {n} tasks through and was still alive to count them, which pleased me rather more than the tasks did.", tags = { "hc" } },
      },
