      ["rest"] = {
        { "I rested {at}, with my back to something solid, as my people prefer." },
        { "I settled {at}, in no hurry at all, and let the day's wariness drain out of my shoulders." },
        { "I paused {at}, with the sound of the sea almost present in the quiet." },
        { "I rested {at}, and found the day's troubles funnier now that they were behind me." },
        { "I stopped {at}, glad of an hour whose only demand was sitting still." },
        { "I rested {at}, and missed the drums of Sen'jin Village more than I expected.", tags = { "!home" } },
        { "I paused {at}, and thought of drums by the water and food shared out around a fire at home.", tags = { "!home" } },
        { "I rested {at}, and gave my curiosity a rest along with my legs." },
        { "I rested {at}, with no useful task left for my patience except doing nothing." },
        { "Quick as my body was to mend, weariness kept its own pace, and I rested {at} until it had gone." },
        { "Few of the places we had called home had let us rest with both eyes closed, so I made the most of a safe place {at}.", tags = { "!fire" } },
        { "I rested {at}, as unbothered as a raptor stretched out after a good meal." },
        { "I rested by the fire {at}, and let the smoke carry the day's long vigilance away.", tags = { "last", "fire" } },
        { "I settled {at}, and for once keeping still felt like ease rather than lying low." },
        { "I rested {at}, still breathing, which is reason enough to celebrate where I come from.", tags = { "hc" } },
        { "Content to be of no use for a while, I rested {at} and listened to nothing in particular." },
        { "I sat by the fire {at}, and decided it lacked only a drum and a few friends from home to be perfect.", tags = { "fire" } },
        { "I rested {at}, treating myself to the thought of crabs cracked open on a warm rock by the sea.", tags = { "!fire" } },
        { "I settled {at}, and let tiredness come in like a slow tide without arguing with it.", tags = { "last" } },
        { "I rested {at}, privately amused at how much effort I had spent getting somewhere to sit down." },
