    },
    ["Booty Bay"] = { type = "town", faction = "neutral", home = {  },
      { "Booty Bay was built into the cliffs around a hidden harbour, all planks, rope and goblin bargaining, with a great shark's jaw for a gate. Everyone here was for sale, and nobody pretended otherwise." },
    },
    ["Brackenwall Village"] = { type = "town", faction = "horde", home = {  },
      { "Brackenwall Village squatted in the marsh, a Horde camp of huts on stilts above the mud and the insects.", tags = { "!foe" } },
      { "Brackenwall Village was a Horde camp in the marsh, its huts on stilts and its guards unfriendly.", tags = { "foe" } },
    },
    ["Brill"] = { type = "town", faction = "horde", home = { ["Scourge"] = true },
      { "After the tombs, the crooked roofs of Brill looked almost companionable. Around the Gallows' End Tavern my people went about their business, and the town kept going on stubbornness alone.", tags = { "home" } },
      { "In Brill, the dead kept shops and ran errands beneath crooked roofs. I had come ready for graves, and was less ready for that.", tags = { "!home" } },
    },
    ["Burning Steppes"] = { type = "zone", faction = "neutral", home = {  },
      { "Ash drifted like snow over the Burning Steppes, and the ground still smouldered. Blackrock Mountain stood over it all, and the orcs who held it had made the whole country theirs.", tags = { "!night" } },
      { "The Burning Steppes never went fully dark. Fires burned across the plain, and the red glow of Blackrock Mountain hung in the sky like a threat.", tags = { "night" } },
    },
    ["Camp Mojache"] = { type = "town", faction = "horde", home = {  },
      { "Camp Mojache was a tauren camp at the edge of the Feralas forest, its great tents spread out in the grass.", tags = { "!foe" } },
      { "Camp Mojache was a tauren camp on the edge of the forest, and its braves did not take kindly to strangers like me.", tags = { "foe" } },
    },
    ["Camp Taurajo"] = { type = "town", faction = "horde", home = {  },
      { "Camp Taurajo was a tauren camp in the southern Barrens, its tents and totems standing over the grass.", tags = { "!foe" } },
      { "Camp Taurajo was a tauren camp in the open grass, and nobody there was glad to see me.", tags = { "foe" } },
    },
    ["Cenarion Hold"] = { type = "town", faction = "neutral", home = {  },
      { "Cenarion Hold was a fortified camp in the Silithus sand, where the Cenarion Circle stood guard against the hives." },
    },
    ["Chillwind Camp"] = { type = "town", faction = "alliance", home = {  },
      { "Chillwind Camp was a handful of tents under the trees at the edge of the Plaguelands, where the Alliance kept a foothold against the Scourge.", tags = { "!foe" } },
      { "Chillwind Camp was an Alliance camp on the edge of the plague, and its soldiers had as little love for me as for the Scourge.", tags = { "foe" } },
    },
    ["City of Dalaran"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Dalaran was only half rebuilt, its new streets unfinished, and the magic in its air had gone wrong. Things made of nothing but mana drifted where the mages should have been, and I understood why the Kirin Tor had wanted no outsiders to see it." },
      { "Inside the dome the city of the mages was a building site gone strange: unfinished streets, and loose magic taking shapes of its own. Whatever had disturbed it, the Kirin Tor had not mastered it yet." },
    },
    ["Darkshire"] = { type = "town", faction = "alliance", home = {  },
      { "Darkshire huddled under its lamps at the edge of the dark wood, with the Night Watch on every corner. People spoke in low voices, as if the forest might hear.", tags = { "!foe" } },
      { "Darkshire was lit and guarded against the dark, and against my kind as well. Its lamps left very few shadows.", tags = { "foe" } },
    },
    ["Darkshore"] = { type = "zone", faction = "alliance", home = {  },
      { "Mist rolled in off the sea along Darkshore, and old stones lay half buried in the grey sand. Even the trees looked tired, and I caught myself searching the shore for a light.", tags = { "!night" } },
      { "On Darkshore at night, the mist made sea and sky one grey thing. I kept my bearings by the sound of the surf and the blurred moon above it.", tags = { "night" } },
    },
    ["Darnassus"] = { type = "zone", faction = "alliance", home = { ["NightElf"] = true },
      { "The white stone and still pools of Darnassus slowed me without my meaning to. Near the Temple of the Moon the old hush settled around me, and I was home.", tags = { "home" } },
      { "I lowered my voice in Darnassus without anyone asking me to. The pale stone and quiet water seemed a long way from the pace of the road below.", tags = { "ally" } },
      { "In Darnassus, pale stone held still water. I might have admired the quiet, if it had not made every one of my footsteps sound too loud.", tags = { "foe" } },
    },
    ["Deadwind Pass"] = { type = "zone", faction = "neutral", home = {  },
      { "Deadwind Pass was dead in every sense, grey trees on grey rock, with the tower of Karazhan standing alone in the gloom. Nobody I had met could say what still lived inside it." },
      { "Deadwind Pass was colder than it had any right to be at night. Karazhan's tower rose black over the ravine, and the wind through the dead trees sounded almost like voices.", tags = { "night" } },
    },
    ["Desolace"] = { type = "zone", faction = "neutral", home = {  },
      { "Desolace was grey from edge to edge: cracked earth, old bones and the camps of warring centaur. Something had drained the life from this land, and it had never come back.", tags = { "!night" } },
      { "Night in Desolace was cold, empty and very still. The centaur drums carried a long way, and so did the howling.", tags = { "night" } },
    },
    ["Dire Maul"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Dire Maul was the ruin of an elven city in the forest, its great halls overgrown, its old masters still haunting them and ogres living in the wreck." },
    },
    ["Dolanaar"] = { type = "town", faction = "alliance", home = { ["NightElf"] = true },
      { "Rain scented the houses around the moonwell in Dolanaar. The sentinels kept their patient watch on the road, and I let my guard down a little.", tags = { "home" } },
      { "The blue moonwell at Dolanaar caught my eye before the houses did. Under the trailing vines I found myself speaking softly, as if someone had asked me to.", tags = { "!home" } },
    },
    ["Dun Morogh"] = { type = "zone", faction = "alliance", home = { ["Dwarf"] = true, ["Gnome"] = true },
      { "The cold of Dun Morogh caught in my throat, and the pines bowed under their snow. Above the valleys rose the mountain that holds Ironforge, and the sight of it made the cold easier to bear.", tags = { "home", "!night" } },
      { "The snow of Dun Morogh glowed blue under the stars, and the cold felt cleaner for it. I knew the shapes of those mountains even in the dark.", tags = { "home", "night" } },
      { "The cold of Dun Morogh found my fingers before anything else did. Ahead, the gate of Ironforge sank into the mountain, as though the dwarves had talked the stone into making room.", tags = { "ally" } },
      { "Snow lay deep across Dun Morogh, and the mountain of Ironforge stood ahead. I wondered how many dwarves were waiting behind all that stone.", tags = { "foe" } },
    },
    ["Durotar"] = { type = "zone", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "Heat rose from the red dust of Durotar, as if the ground itself were breathing. This was the land we had claimed, and I meant to learn how to belong to it.", tags = { "home", "!night" } },
      { "The red earth of Durotar faded to grey as the heat left the stones. From beyond the hills came the drums of Orgrimmar, a sound I could have followed blind.", tags = { "home", "night" } },
      { "In Durotar the red hills closed around the road to Orgrimmar. Under that sun, I began to understand the people who had chosen to stay.", tags = { "ally" } },
      { "A hot wind drove the red dust of Durotar against my face. This was the Horde's own country, and I stopped trusting the ridges to be empty.", tags = { "foe" } },
    },
    ["Duskwood"] = { type = "zone", faction = "alliance", home = {  },
      { "Duskwood was dark even at midday, the trees grown so thick that the sun barely reached the road. Things moved in the graveyards, and the people of Darkshire had stopped pretending not to notice.", tags = { "!night" } },
      { "Night in Duskwood was a darker kind of night. Worgs howled out among the trees, and at Raven Hill the dead did not stay where they had been buried.", tags = { "night" } },
    },
    ["Dustwallow Marsh"] = { type = "zone", faction = "neutral", home = {  },
      { "Dustwallow Marsh was hot, wet and humming with insects, its mud full of crocolisks and its trees heavy with moss. Theramore's towers on the coast looked very far from the swamp.", tags = { "!night" } },
      { "At night Dustwallow came alive with croaks and splashes, and mist rose off the water in sheets. Somewhere to the south was Onyxia's lair, and I could not put it out of my mind.", tags = { "night" } },
    },
    ["Eastern Plaguelands"] = { type = "zone", faction = "neutral", home = {  },
      { "The Eastern Plaguelands were a land without colour, the trees grey, the rivers foul and the ground soft with plague. Stratholme's walls stood to the north, and nothing living went there willingly.", tags = { "!night" } },
      { "The Eastern Plaguelands were darker than any night should be. Things walked among the dead trees, and the only kind light came from the chapel at Light's Hope, small against the dark.", tags = { "night" } },
    },
    ["Elwynn Forest"] = { type = "zone", faction = "alliance", home = { ["Human"] = true },
      { "Elwynn's woods were green and orderly, with farms tucked between the oaks and Stormwind's guards riding the roads. In country like that, it was easy to forget how close the trouble had come.", tags = { "home", "!night" } },
      { "Elwynn was quiet at night, with lanterns along the road and the trees dark on either side. Somewhere in the woods a wolf called, and the next lamp post was a welcome sight.", tags = { "home", "night" } },
      { "Elwynn Forest was gentle country, all oak and meadow and well-kept fields, with the walls of Stormwind never far away. It looked like a place people had fought hard to keep ordinary.", tags = { "ally" } },
      { "Elwynn's forest ran right up to the walls of Stormwind, and every road had a patrol on it. It was pretty country, and the heart of the Alliance; I felt every one of those patrols.", tags = { "foe" } },
    },
    ["Everlook"] = { type = "town", faction = "neutral", home = {  },
      { "Everlook was a goblin town in the snow, its walls warm with lamps and its streets full of traders who had come a long way." },
    },
    ["Feathermoon Stronghold"] = { type = "town", faction = "alliance", home = {  },
      { "Feathermoon Stronghold rose from its island off the Feralas coast, a night elf fortress reached by boat or on hippogryph back.", tags = { "!foe" } },
      { "Feathermoon Stronghold stood on its island, and its sentinels did not care for visitors of my kind.", tags = { "foe" } },
    },
    ["Felwood"] = { type = "zone", faction = "neutral", home = {  },
      { "Felwood had been forest once, and in places it still was, but the trees were twisted and the water glowed green. The demons' corruption was in everything, even the air.", tags = { "!night" } },
      { "Felwood was worse at night, when the green glow of the tainted pools was the only light. The trees creaked as if they were in pain.", tags = { "night" } },
    },
    ["Feralas"] = { type = "zone", faction = "neutral", home = {  },
      { "Feralas was green and towering, with trees as tall as any in Ashenvale and the ruins of the old elves sunk among the ferns. Rain came often, and the air smelled of growth.", tags = { "!night" } },
      { "Feralas at night was deep and dripping, the canopy so thick the stars were lost. Somewhere in the dark were the walls of Dire Maul, and nearer, the calls of animals I could not name.", tags = { "night" } },
    },
    ["Freewind Post"] = { type = "town", faction = "horde", home = {  },
      { "Freewind Post sat on top of a stone needle, reached by a creaking lift, with the whole canyon spread out below.", tags = { "!foe" } },
      { "Freewind Post stood on top of a stone needle, reached only by its lift, and its guards had seen my kind before.", tags = { "foe" } },
    },
    ["Gadgetzan"] = { type = "town", faction = "neutral", home = {  },
      { "Gadgetzan was a goblin town in the middle of the desert, walled and noisy, with a bruiser on every corner keeping a very particular kind of peace." },
    },
    ["Gnomeregan"] = { type = "dungeon", faction = "alliance", home = { ["Gnome"] = true },
      { "I had pictured the halls of Gnomeregan so many times. Among the troggs and the poisoned glow, I still caught myself searching for faces I knew.", tags = { "home" } },
      { "The machines of Gnomeregan were still turning in halls their makers had lost. Under the sickly green light, I wondered who would ever stop the wheels.", tags = { "!home" } },
    },
    ["Goldshire"] = { type = "town", faction = "alliance", home = {  },
      { "Goldshire gathered around the Lion's Pride Inn, with the forge glowing at the smithy and children running in the street. It felt like the safest place in the world.", tags = { "!foe" } },
      { "Goldshire was a cosy little Alliance town around its inn, with guards at every corner, and not one of them would have been glad to see me.", tags = { "foe" } },
    },
    ["Grom'gol Base Camp"] = { type = "town", faction = "horde", home = {  },
      { "Grom'gol was a Horde camp hacked out of the jungle, with a zeppelin tower rising over the trees and the jungle pressing in on every side.", tags = { "!foe" } },
      { "Grom'gol was a Horde camp in the jungle, its zeppelin tower visible from far off, and every grunt in it an enemy of mine.", tags = { "foe" } },
    },
    ["Hammerfall"] = { type = "town", faction = "horde", home = {  },
      { "Hammerfall stood stern and red-bannered among the Arathi hills, an orc stronghold in country the humans still called their own.", tags = { "!foe" } },
      { "Hammerfall was an orc stronghold in the Arathi hills, all spiked walls and watchful eyes, and here I was the enemy.", tags = { "foe" } },
    },
    ["Hillsbrad Foothills"] = { type = "zone", faction = "neutral", home = {  },
      { "Hillsbrad's hills were green and its orchards heavy, but Southshore and Tarren Mill sat on either side of them, and both knew it. The old farms had become a front line.", tags = { "!night" } },
      { "The foothills of Hillsbrad were uneasy at night, with the watch fires of both sides burning across the valley. Whatever peace there was here was only a pause.", tags = { "night" } },
    },
    ["Ironclad Cove"] = { type = "town", faction = "neutral", home = {  },
      { "The tunnel opened onto a hidden cove, and in the water lay a full-sized ship, armoured and lined with cannons, built in secret beneath Westfall. I understood then how much VanCleef had been planning." },
      { "Sea air reached me before I saw the cove. A great ironclad ship sat in the hidden harbour, its decks crowded with pirates, and I could hardly believe it had been built underground." },
    },
    ["Ironforge"] = { type = "zone", faction = "alliance", home = { ["Dwarf"] = true },
      { "The heat of the Great Forge met me at the gate of Ironforge, and the hammering followed me in. I stood above the molten iron and let the noise of my people fill the space the road had left.", tags = { "home" } },
      { "After the mountain cold, the warmth of Ironforge was almost too much. The hammers rang through every hall, and I found the sound oddly comforting after the open country.", tags = { "ally" } },
      { "The mountain closed around me in Ironforge, with hammering from every hall. There were guards everywhere, and the warmth did little to put me at ease.", tags = { "foe" } },
    },
    ["Kargath"] = { type = "town", faction = "horde", home = {  },
      { "Kargath was cut into the canyon walls of the Badlands, a hard Horde outpost named for a hard warrior.", tags = { "!foe" } },
      { "Kargath was a Horde outpost cut into the canyon walls, all watchtowers, and every one of them looked my way.", tags = { "foe" } },
    },
    ["Kharanos"] = { type = "town", faction = "alliance", home = { ["Dwarf"] = true, ["Gnome"] = true },
      { "I smelled the Thunderbrew Distillery before I had properly reached Kharanos. Smoke rose above the houses, where dwarves and gnomes crowded together against the cold, and I felt my shoulders ease at the sight.", tags = { "home" } },
      { "The smell of brewing reached me on the road into Kharanos. Among the sturdy houses I saw gnomes as well as dwarves, and thought of how far a lost home could follow its people.", tags = { "ally" } },
      { "Smoke hung over Kharanos, and the smell of ale carried well beyond the houses. It might have promised a welcome to someone else; I found myself counting the dwarves instead.", tags = { "foe" } },
    },
    ["Lakeshire"] = { type = "town", faction = "alliance", home = {  },
      { "Lakeshire sat on the shore of Lake Everstill, its great bridge still unfinished and its people tired. The town had the look of a place holding on.", tags = { "!foe" } },
      { "Lakeshire's bridge was guarded, and the whole town watched the hills. It did not take long for it to watch me as well.", tags = { "foe" } },
    },
    ["Light's Hope Chapel"] = { type = "town", faction = "neutral", home = {  },
      { "Light's Hope Chapel stood alone in the Eastern Plaguelands, its stones still clean and the Argent Dawn keeping watch around it. Living people of every kind gathered at its walls, with nowhere else left to go." },
    },
    ["Loch Modan"] = { type = "zone", faction = "alliance", home = {  },
      { "The blue water of Loch Modan lay still behind the Stonewrought Dam. I knew dwarves built on a grand scale, but the weight of all that water made me stop and look.", tags = { "!night" } },
      { "At night the water of Loch Modan lay black beneath the hills, with the dam a darker line against the sky. Thelsamar was asleep along the shore, and I envied it.", tags = { "night" } },
      { "Across Loch Modan stood the great dam of the dwarves. I watched the guards along the water as closely as I watched the view.", tags = { "foe" } },
    },
    ["Maraudon"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Maraudon was a cavern of crystal and poisoned water, home of the centaur's sacred dead and of something much older underneath. The deeper it went, the greener it grew." },
    },
    ["Marshal's Refuge"] = { type = "town", faction = "neutral", home = {  },
      { "Marshal's Refuge was a camp tucked into a cave mouth on the crater's edge, where a few hardy souls lived among the dinosaurs." },
    },
    ["Menethil Harbor"] = { type = "town", faction = "alliance", home = {  },
      { "Menethil Harbor was a fortress on the edge of the marsh, its keep half sunk into the mud and its docks busy with ships bound for Kalimdor.", tags = { "!foe" } },
      { "Menethil Harbor's keep and docks were full of Alliance soldiers coming and going by sea, and every one of them was an enemy of mine.", tags = { "foe" } },
    },
    ["Molten Core"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Molten Core lay at the very bottom of Blackrock Mountain, a cavern of fire where Ragnaros himself waited. The heat was like walking into a forge." },
    },
    ["Moonbrook"] = { type = "town", faction = "neutral", home = {  },
      { "Moonbrook had been a town once. Now its houses stood burned and broken, and men in red bandanas watched the road from the ruins.", tags = { "!night" } },
      { "Moonbrook was a ruin after dark, its broken walls black against the sky. Somewhere among the burned houses the Defias were talking, and I kept to the shadows.", tags = { "night" } },
    },
    ["Moonglade"] = { type = "zone", faction = "neutral", home = {  },
      { "Moonglade was peaceful as nowhere else in the world was, a quiet lake in an endless twilight with druids walking slowly by the water. Even my thoughts went softer there." },
      { "Night in Moonglade hardly differed from day, the same soft light on the lake and the same stillness. It was the first place in a long time where I did not listen for footsteps behind me.", tags = { "night" } },
    },
    ["Morgan's Vigil"] = { type = "town", faction = "alliance", home = {  },
      { "Morgan's Vigil was a small Alliance camp at the edge of the Burning Steppes, holding on against the orcs of Blackrock.", tags = { "!foe" } },
      { "Morgan's Vigil was an Alliance camp at the edge of the Steppes, and my coming did not make their vigil any easier.", tags = { "foe" } },
    },
    ["Mulgore"] = { type = "zone", faction = "horde", home = { ["Tauren"] = true },
      { "The grass of Mulgore rolled on toward the mesas, with plainstriders running and the wind moving through it like water. The Earth Mother's land asked nothing of me but that I walk it gently.", tags = { "home", "!night" } },
      { "Night over Mulgore was wide and clear, the stars reaching down to the edge of the grass. The tents of the tribe glowed here and there, and the land felt as though it kept watch.", tags = { "home", "night" } },
      { "Mulgore's plains rolled green and gold beneath the mesas, with kodo grazing and windmills turning by the tents. It was the calmest country I had seen in a long while.", tags = { "ally" } },
      { "The plains of Mulgore were open in every direction, with nowhere to hide on them. This was the tauren's land, and I felt like a stranger walking through someone's home.", tags = { "foe" } },
    },
    ["Naxxramas"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Naxxramas floated over the Plaguelands, Kel'Thuzad's necropolis, and from its cold halls the dead marched out." },
    },
    ["Nethergarde Keep"] = { type = "town", faction = "alliance", home = {  },
      { "Nethergarde Keep stood guard over the Blasted Lands, its mages watching the Dark Portal as if it might open again at any moment.", tags = { "!foe" } },
      { "Nethergarde Keep was an Alliance fortress full of mages watching the Portal. They watched me just as closely.", tags = { "foe" } },
    },
    ["Nighthaven"] = { type = "town", faction = "neutral", home = {  },
      { "Nighthaven was a village of the druids by the lake, quiet and open, where anyone who came in peace was welcome." },
    },
    ["Nijel's Point"] = { type = "town", faction = "alliance", home = {  },
      { "Nijel's Point was a small Alliance camp in the hills above Desolace, with a little green still clinging to the slopes.", tags = { "!foe" } },
      { "Nijel's Point was an Alliance camp in the hills, and a dangerous place for one of my kind.", tags = { "foe" } },
    },
    ["Onyxia's Lair"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Onyxia's Lair was a cave in the marsh, littered with bones and full of whelps. Everyone fell quiet at its mouth." },
    },
    ["Orgrimmar"] = { type = "zone", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "The drums of Orgrimmar echoed off the spiked walls as I came in. At Grommash Hold I felt the weight of it: a city our people had built for themselves, with no one's chains on it.", tags = { "home" } },
      { "Smoke drifted over the red stone and iron spikes of Orgrimmar. The drums made the pride of the place something I could almost feel underfoot.", tags = { "ally" } },
      { "Under the walls of Orgrimmar, the drums rolled off the red stone. I had never felt so far from anyone who might call me a friend.", tags = { "foe" } },
    },
    ["Ragefire Chasm"] = { type = "dungeon", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "Fire ran through the rock of Ragefire Chasm, right beneath our city. That the Burning Blade could hide so close to home troubled me more than the dark.", tags = { "home" } },
      { "Magma lit Ragefire Chasm from below. I had to keep reminding myself to watch the ground rather than the fire.", tags = { "!home" } },
    },
    ["Ratchet"] = { type = "town", faction = "neutral", home = {  },
      { "Ratchet was a goblin port on the Barrens coast, all docks, cranes and haggling, with the boat to Booty Bay coming and going." },
    },
    ["Razor Hill"] = { type = "town", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "At Razor Hill I heard the forge before I saw the drilling. Beyond the barracks, Kul Tiras ships sat off the coast, and I understood why no one in the town ever quite stood at rest.", tags = { "home" } },
      { "The barracks and watchtowers of Razor Hill stood over the coast. With so many weapons in sight, it was plainly no town at peace.", tags = { "!home" } },
    },
    ["Razorfen Downs"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Razorfen Downs was a mound of thorns and bones, where the quilboar had made common cause with the Scourge. The dead walked there beside the living." },
    },
    ["Razorfen Kraul"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Razorfen Kraul was a maze of giant thorns, the quilboar's warrens dug deep beneath them. The brambles tore at everything that passed." },
    },
    ["Redridge Mountains"] = { type = "zone", faction = "alliance", home = {  },
      { "Red rock rose around Lake Everstill in the Redridge Mountains, and the bridge at Lakeshire carried more soldiers than travellers. Gnolls and Blackrock orcs had moved into the hills, and the valley had the look of a place under siege.", tags = { "!night" } },
      { "The lake at Redridge lay black under the red hills, with fires burning up on the ridges where nobody friendly had lit them. I began counting them, and stopped.", tags = { "night" } },
    },
    ["Refuge Pointe"] = { type = "town", faction = "alliance", home = {  },
      { "Refuge Pointe was a camp on a rocky height, where the last of Stromgarde's people kept their banners flying over the highlands.", tags = { "!foe" } },
      { "Refuge Pointe stood on its rock above the highlands, an Alliance camp with good eyes on every approach, mine included.", tags = { "foe" } },
    },
    ["Revantusk Village"] = { type = "town", faction = "horde", home = {  },
      { "Revantusk Village stood on the Hinterlands coast, a troll village of huts and totems where the Revantusk had taken the Horde's side.", tags = { "!foe" } },
      { "Revantusk Village was a troll village on the coast, sworn to the Horde, and no friend of mine.", tags = { "foe" } },
    },
    ["Ruins of Ahn'Qiraj"] = { type = "dungeon", faction = "neutral", home = {  },
      { "The Ruins of Ahn'Qiraj spread out in the sand beyond the scarab wall, broken towers and silithid everywhere." },
    },
    ["Scarlet Monastery"] = { type = "dungeon", faction = "neutral", home = {  },
      { "The Scarlet Monastery was beautiful and terrible, all red banners and polished floors, and the Crusaders there were sure of everything. Certainty like theirs was more frightening than anything I had met in the dark." },
    },
    ["Scholomance"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Scholomance had been the Barov family's keep before it became a school for necromancers. Its halls smelled of dust and death and old books." },
    },
    ["Searing Gorge"] = { type = "zone", faction = "neutral", home = {  },
      { "The Searing Gorge was a wound in the earth, black rock and glowing slag and the stink of sulphur. The Dark Iron dwarves had worked it until nothing was left but heat.", tags = { "!night" } },
      { "In the Searing Gorge, night hardly mattered. The lava lit the cliffs from below, and the great Cauldron at its heart glowed like a second sun.", tags = { "night" } },
    },
    ["Sentinel Hill"] = { type = "town", faction = "alliance", home = { ["Human"] = true },
      { "A stone tower stood on Sentinel Hill, and around it the People's Militia had pitched their tents. Farmers who had lost everything queued for soup, and it made me angrier than I expected.", tags = { "home" } },
      { "Sentinel Hill was a tower, a hill and a camp of farmers turned soldiers. Nobody there had much, but they had decided to hold the line together.", tags = { "!home" } },
    },
    ["Shadowfang Keep"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Cold stone and howling closed around me in Shadowfang Keep, high above Pyrewood. I knew of Arugal, but listened harder to the sounds behind the walls." },
    },
    ["Shadowprey Village"] = { type = "town", faction = "horde", home = {  },
      { "Shadowprey Village sat on the Desolace coast, a quiet Horde village among the reeds, far from everything.", tags = { "!foe" } },
      { "Shadowprey Village was a Horde village on the coast, and even in Desolace I was not welcome there.", tags = { "foe" } },
    },
    ["Silithus"] = { type = "zone", faction = "neutral", home = {  },
      { "Silithus was a desert of red sand and great hives, and the ground hummed with the silithid moving beneath it. The ruins of Ahn'Qiraj stood to the south, and the air felt heavy with whatever slept there.", tags = { "!night" } },
      { "Night in Silithus was full of clicking and scratching, the hives pale under the moon. I tried not to think about what was down there.", tags = { "night" } },
    },
    ["Silverpine Forest"] = { type = "zone", faction = "horde", home = {  },
      { "Rain blurred the grey lake in Silverpine, and beyond it the purple dome of Dalaran. Howls in the hills kept pulling my attention back to the trees around me.", tags = { "!night" } },
      { "Rain and howling followed me into Silverpine after dark. Behind the black wall of pines, I had no wish to find out what else was there.", tags = { "night" } },
    },
    ["Southshore"] = { type = "town", faction = "alliance", home = {  },
      { "Southshore's houses stood by the water, with a good inn and a long memory of the war. Tarren Mill was just over the hill, and nobody here forgot it.", tags = { "!foe" } },
      { "Southshore was a human town by the water, and Tarren Mill was just over the hill. Its guards knew at a glance which side I came from.", tags = { "foe" } },
    },
    ["Splintertree Post"] = { type = "town", faction = "horde", home = {  },
      { "Splintertree Post was a rough Horde camp at the edge of Ashenvale, all palisade and woodsmoke, where the axes never stopped.", tags = { "!foe" } },
      { "Splintertree Post was a Horde camp at Ashenvale's edge, the sound of axes carrying from it all day, and its guards had no welcome for me.", tags = { "foe" } },
    },
    ["Stonard"] = { type = "town", faction = "horde", home = {  },
      { "Stonard rose out of the swamp in heavy orcish stone, the one dry and certain place in the Swamp of Sorrows.", tags = { "!foe" } },
      { "Stonard was an orc fortress rising out of the swamp, and its walls were watched by people who wanted me dead.", tags = { "foe" } },
    },
    ["Stonetalon Mountains"] = { type = "zone", faction = "neutral", home = {  },
      { "The Stonetalon Mountains climbed in great grey ridges, and in places the forest had been cut back to stumps by the Venture Company's saws. The peak itself seemed to look down on all of it.", tags = { "!night" } },
      { "Stonetalon's ridges stood black against the stars, and the wind sang through the passes. Far below, the goblins' machines were still at work.", tags = { "night" } },
    },
    ["Stonetalon Peak"] = { type = "town", faction = "alliance", home = {  },
      { "Stonetalon Peak was a quiet camp high among the trees, where the druids watched over what remained of the forest.", tags = { "!foe" } },
      { "Stonetalon Peak was a night elf camp high in the mountains, quiet and watchful, and it watched me.", tags = { "foe" } },
    },
    ["Stormwind City"] = { type = "zone", faction = "alliance", home = { ["Human"] = true },
      { "The white walls of Stormwind rose over the canals, and the bells of the cathedral carried across the city. It was home, and I tried not to think about the masons who had rebuilt it and were never paid.", tags = { "home" } },
      { "Stormwind was all white stone, blue roofs and canals, with guards on every bridge. It looked like a city that had never known a war, though I knew better.", tags = { "ally" } },
      { "The white walls of Stormwind closed around me, and every guard seemed to be looking my way. I had never been so aware of my own face.", tags = { "foe" } },
    },
    ["Stranglethorn Vale"] = { type = "zone", faction = "neutral", home = {  },
      { "Stranglethorn was jungle from end to end, hot and loud with birds and full of things that wanted to eat me. Old troll ruins rose out of the green, and hunters came from all over the world to prove themselves.", tags = { "!night" } },
      { "In Stranglethorn the night was never quiet. Panthers moved through the dark, drums carried from the troll ruins, and the heat did not ease for a moment.", tags = { "night" } },
    },
    ["Stratholme"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Stratholme was a city that had burned and never stopped burning, the Scourge in its streets and the Scarlet Crusade dug in among the ruins." },
    },
    ["Sun Rock Retreat"] = { type = "town", faction = "horde", home = {  },
      { "Sun Rock Retreat sheltered under the cliffs of Stonetalon, a Horde camp where the mountain stood close on every side.", tags = { "!foe" } },
      { "Sun Rock Retreat was a Horde camp tucked under the cliffs, with nowhere to go but back the way I came.", tags = { "foe" } },
    },
    ["Sunken Temple"] = { type = "dungeon", faction = "neutral", home = {  },
      { "The Sunken Temple lay half drowned in the swamp, its halls dark and dripping, where the Atal'ai still called on their blood god. The air tasted of old magic." },
    },
    ["Swamp of Sorrows"] = { type = "zone", faction = "neutral", home = {  },
      { "The Swamp of Sorrows lived up to its name: grey water, hanging moss and a silence that felt like grief. Somewhere in its depths lay the sunken temple of the Atal'ai.", tags = { "!night" } },
      { "Night in the Swamp of Sorrows was close and heavy, the air thick enough to taste. Pale lights moved over the water, and I had no intention of following them.", tags = { "night" } },
    },
    ["Tanaris"] = { type = "zone", faction = "neutral", home = {  },
      { "Tanaris was sand and heat and more sand, dunes running to the horizon under a white sky. Gadgetzan's walls were the only shade for miles.", tags = { "!night" } },
      { "The desert of Tanaris turned cold at night, and the dunes went silver. I could hear the wind moving the sand, and now and then a scorpid's claws on stone.", tags = { "night" } },
    },
    ["Tarren Mill"] = { type = "town", faction = "horde", home = {  },
      { "Tarren Mill belonged to the Forsaken now, its old houses mended after their fashion and the apothecaries busy. Southshore was just over the hill, and the town never forgot it.", tags = { "!foe" } },
      { "Tarren Mill had been a human village once; now the Forsaken held it, and the deathguards watched every road. Every one of them knew what I was.", tags = { "foe" } },
    },
    ["Teldrassil"] = { type = "zone", faction = "alliance", home = { ["NightElf"] = true },
      { "The branches of Teldrassil held the whole forest up beneath my feet. Wisps drifted over the moss of our new home, and I envied them their ease.", tags = { "home", "!night" } },
      { "Moonlight silvered the leaves of Teldrassil while owls called overhead. I listened between my footfalls, unwilling to hurry through so much quiet.", tags = { "home", "night" } },
      { "In the violet light of Teldrassil, it was hard to forget that the whole forest stood on a single tree. The thought kept drawing my eyes from the sentinels to the ground.", tags = { "ally" } },
      { "The leaves of Teldrassil softened every sound. I admired the place, and was quite sure someone had already noticed me.", tags = { "foe" } },
    },
    ["The Barrens"] = { type = "zone", faction = "horde", home = {  },
      { "Yellow grass ran on past the thorn trees of the Barrens, with zhevra shifting in the heat. Distances were harder to judge than they had looked on any map.", tags = { "!night" } },
      { "The grass of the Barrens turned silver under an enormous night sky. Somewhere far off, centaur drums carried over the grass, and I kept my eyes on the horizon.", tags = { "night" } },
    },
    ["The Crossroads"] = { type = "town", faction = "horde", home = {  },
      { "The palisade of the Crossroads stood where the roads met the grassland. After so much empty distance, people gathered in one place were a relief.", tags = { "!foe" } },
      { "At the Crossroads, the Horde's palisade sheltered its own. For me it was a reason to look carefully before I moved on.", tags = { "foe" } },
    },
    ["The Deadmines"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Timber props held up the tunnels of the Deadmines, and the air tasted of dust and lamp oil. Somewhere ahead, machinery was hammering, as if the whole hill were being worked from the inside." },
      { "Mine carts stood abandoned on their rails, and the walls sweated in the lamplight. The deeper I went into the Deadmines, the louder the hammering grew." },
    },
    ["The Hall of Thanes"] = { type = "dungeon", faction = "alliance", home = { ["Dwarf"] = true },
      { "Below Old Ironforge the caverns opened into the Hall of Thanes. The dead of Anvilmar would not lie quiet there, and Dark Iron voices carried up from the lower vaults, under the very city my people call home.", tags = { "home" } },
      { "The tunnels beneath Old Ironforge ended in the Hall of Thanes, where the dwarves' restless dead walked and the Dark Irons had dug their way in from below. I kept close to my companions and spoke as little as the place seemed to want.", tags = { "!home" } },
    },
    ["The Hinterlands"] = { type = "zone", faction = "neutral", home = {  },
      { "The Hinterlands were high and wild, forested hills where gryphons flew and the Witherbark trolls watched from their ruins. It felt like country that had never quite been tamed.", tags = { "!night" } },
      { "The Hinterlands were full of sound at night: owls, wolves, and the drums of the trolls up in the hills. It was no country for sleeping out of doors.", tags = { "night" } },
    },
    ["The Sepulcher"] = { type = "town", faction = "horde", home = { ["Scourge"] = true },
      { "Bats wheeled over the tombs of the Sepulcher, and our guards stood at the gate. Making an outpost of a burial ground seemed a fair use of what was left.", tags = { "home" } },
      { "I came to the Sepulcher through a hillside of tombs. For a moment I watched the guards warily, before I remembered who lived here.", tags = { "!home" } },
    },
    ["The Stockade"] = { type = "dungeon", faction = "neutral", home = {  },
      { "The Stockade was Stormwind's prison, built under the city, and the prisoners had taken it over. Every cell door hung open." },
    },
    ["Thelsamar"] = { type = "town", faction = "alliance", home = {  },
      { "I found the Stoutlager Inn of Thelsamar beside the loch. After the open hills, its ale and blood sausages interested me more than the distance I had come.", tags = { "!foe" } },
      { "The inn at Thelsamar looked comfortable beside the loch. On an Alliance shore, though, its windows offered more chance of being seen than of rest.", tags = { "foe" } },
    },
    ["Theramore Isle"] = { type = "town", faction = "alliance", home = {  },
      { "Theramore stood on its island off the marsh coast, stone towers and busy docks, Lady Jaina's city and the Alliance's anchor in Kalimdor.", tags = { "!foe" } },
      { "Theramore's towers rose from their island off the coast, Lady Jaina's city and the Alliance's anchor in Kalimdor. Its walls were the last place I should have been.", tags = { "foe" } },
    },
    ["Thorium Point"] = { type = "town", faction = "neutral", home = {  },
      { "Thorium Point was the Thorium Brotherhood's camp on the rim of the gorge, a few tents and a forge above all that heat." },
    },
    ["Thousand Needles"] = { type = "zone", faction = "neutral", home = {  },
      { "Thousand Needles was well named: stone pillars rose from the canyon floor by the hundred, with rope bridges strung between their tops. To the east, the Shimmering Flats shone white.", tags = { "!night" } },
      { "At night the stone spires of Thousand Needles stood like a forest of black stone. The camps on the mesas were small and far apart, and the drop below them was a long one.", tags = { "night" } },
    },
    ["Thunder Bluff"] = { type = "town", faction = "horde", home = { ["Tauren"] = true },
      { "Thunder Bluff stood on its mesas high above Mulgore, with tents and totems on every top and rope bridges swinging between them. The wind never stopped, and nobody seemed to mind.", tags = { "!foe" } },
      { "Thunder Bluff rose on its mesas above the plains, reached only by its great lifts. From below, there was no hope of getting in unseen.", tags = { "foe" } },
    },
    ["Tirisfal Glades"] = { type = "zone", faction = "horde", home = { ["Scourge"] = true },
      { "Under the grey sky of Tirisfal, dead trees stood where the plague had left them. I recognised something of myself in a country that had been obliged to go on.", tags = { "home", "!night" } },
      { "Crows called over the crypts of Tirisfal, toward the broken walls of Lordaeron. Night changed little here, though it left me feeling less conspicuous.", tags = { "home", "night" } },
      { "The grey fields of Tirisfal led past dead trees to the broken walls of Lordaeron. I wondered what the people here still remembered of the country.", tags = { "ally" } },
      { "Dead trees stretched across Tirisfal toward the ruins of Lordaeron. Knowing the Forsaken walked here made the stillness harder to trust.", tags = { "foe" } },
    },
    ["Uldaman"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Uldaman was a vault of the titans, carved deep into the mountain, where troggs and Dark Iron dwarves fought over things neither understood. The stone itself seemed to watch." },
    },
    ["Undercity"] = { type = "zone", faction = "horde", home = { ["Scourge"] = true },
      { "Green canals ran through the Undercity, past the bubbling Apothecarium, deep beneath the ruins of Lordaeron. Out of so much that had survived badly, we had made a city, and it was ours.", tags = { "home" } },
      { "Green sludge filled the stone canals of the Undercity, deep under Lordaeron. The smell stayed with me the whole time I was trying to find my way.", tags = { "ally" } },
      { "Below the ruins of Lordaeron, the Forsaken had made the Undercity their home. Each turn I took made the way back to daylight less certain.", tags = { "foe" } },
    },
    ["Un'Goro Crater"] = { type = "zone", faction = "neutral", home = {  },
      { "Un'Goro Crater was another world, hot and steaming, full of giant ferns and creatures that should have died out long ago. Devilsaurs walked through the jungle, and the ground shook when they did.", tags = { "!night" } },
      { "Night in Un'Goro was thick with heat and noise: insects as big as my hand, and the far-off roar of something enormous. The crater felt older than anything I knew.", tags = { "night" } },
    },
    ["Valanaar"] = { type = "town", faction = "neutral", home = { ["Skyborne"] = true },
      { "Slender bridges joined the floating halls of Valanaar, and skycutters rode at the docks. Refugees from Ban'aethal, emptied in a single night when it began to fall into the sky, filled its walks, and I tried not to count how many of us had nowhere else left to go.", tags = { "home" } },
      { "The halls of Valanaar floated on nothing, joined by bridges no wider than a garden path, built in a powder blue that put me in mind of night elf stonework. The Skyborne crossed them without a glance down; I did not.", tags = { "!home" } },
    },
    ["Wailing Caverns"] = { type = "dungeon", faction = "neutral", home = {  },
      { "In the Wailing Caverns, the wind moaned over green water among the roots. Knowing what had become of the druids, I listened for a voice I could still reason with." },
    },
    ["Western Plaguelands"] = { type = "zone", faction = "neutral", home = {  },
      { "The Western Plaguelands had been farmland once, and the farms still stood, empty or worse. The grain was blighted, the dead walked in the fields, and Andorhal was a ruin.", tags = { "!night" } },
      { "Night in the Western Plaguelands was full of wrong sounds: shuffling feet, the creak of empty houses, the wind in dead wheat. Every shadow looked as if it might stand up.", tags = { "night" } },
    },
    ["Westfall"] = { type = "zone", faction = "alliance", home = { ["Human"] = true },
      { "Westfall's fields ran gold to the horizon, and half of them had gone to seed. Farmhouses stood empty with their doors open, and I thought of the families who had worked them before the Defias came.", tags = { "home", "!night" } },
      { "Westfall lay dark and quiet, its windmills turning over farms nobody tended any more. A light in a window was rare enough to make me wonder who still dared to keep one.", tags = { "home", "night" } },
      { "Golden fields ran across Westfall down toward the sea, with windmills turning above them. It was beautiful country, and a hungry one: too many farms stood empty, and too many people on the road had nowhere else to go.", tags = { "ally" } },
      { "The fields of Westfall ran on toward the sea, with empty farms and scarecrows that were not always scarecrows. In the heart of the Alliance's farmland, I kept well away from the road.", tags = { "foe" } },
    },
    ["Wetlands"] = { type = "zone", faction = "alliance", home = {  },
      { "The Wetlands were mud, reeds and rain, and half the road lay under water. Raptors stalked the marsh, and in the east the heights of Grim Batol were not something anyone mentioned lightly.", tags = { "!night" } },
      { "At night the Wetlands came alive with croaking and splashing, and the mist lay low over the water. The road was the only thing I trusted, and in a marsh that was not saying much.", tags = { "night" } },
    },
    ["Winterspring"] = { type = "zone", faction = "neutral", home = {  },
      { "Winterspring lay deep in snow, quiet and clean, with frostsabers in the hills and steaming springs among the drifts. After so many burned and blighted places, the cold felt honest.", tags = { "!night" } },
      { "Under the stars, Winterspring's snow was blue and silent. The cold bit hard, and Everlook's lights in the distance looked very warm.", tags = { "night" } },
    },
    ["Zephras Isle"] = { type = "zone", faction = "neutral", home = { ["Skyborne"] = true },
      { "Pink woods climbed toward the snow on the high peaks of Zephras Isle, and past every edge there was only the open sky of Skywall. Since the wind spirits had gone, the pylons held the island up alone, and I caught myself trusting the ground a little less.", tags = { "home", "!night" } },
      { "After dark the floating towers of Zephras Isle were only shapes against the stars. The quiet that had settled over the island since the wind spirits left sounded to me like a voice that had stopped mid-sentence.", tags = { "home", "night" } },
      { "Zephras Isle hung in the open sky of Skywall, its pink forests climbing to snowy peaks while towers drifted loose above the ground. I had never stood anywhere that felt so lightly held, and I kept well back from the edges.", tags = { "neutral", "!night" } },
      { "At night Zephras Isle was a dark shape among the stars, with towers floating free above its woods. Somewhere below the edge there was nothing at all, and I walked as though the island might notice my weight.", tags = { "neutral", "night" } },
    },
    ["Zul'Farrak"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Zul'Farrak was a troll city in the desert, its stairs and temples baking in the sun and the Sandfury watching from every wall." },
    },
    ["Zul'Gurub"] = { type = "dungeon", faction = "neutral", home = {  },
      { "Zul'Gurub was the old Gurubashi capital rising out of the jungle, its temples soaked in the blood god's worship." },
    },
  },
  why = {
    [2] = { 2, "brought Sharptalon's claw to Senani Thunderheart, proof that the hippogryph who had terrorized the lumber camps' peons was dead" },
    [6] = { 3, "hunted down Garrick Padfoot, a cutthroat who had plagued Elwynn's farmers and merchants, for Deputy Willem's bounty" },
    [9] = { 1, "cleared the Harvest Watchers from Farmer Saldean's fields and his neighbours', in the hope Westfall might prosper again" },
    [10] = { 2, "searched the Gaping Chasm for Fizzledowser's missing assistant, Junior Surveyor Scrimshank, and found only his surveying equipment" },
    [11] = { 1, "collected painted armbands from the Riverpaw gnolls infesting Elwynn's borders, for the Stormwind Army's bounty" },
    [12] = { 1, "hunted Defias Trappers and Smugglers across Westfall's farms to earn a place in Gryan Stoutmantle's People's Militia" },
    [13] = { 1, "drove Defias Pillagers and Looters from the Gold Coast Quarry and Moonbrook, the next step of training in the Militia" },
    [14] = { 2, "rooted out the Defias who had fled to the Dagger Hills, which earned me a place in the People's Militia" },
    [15] = { 1, "cleared kobold workers from their camp by the Echo Ridge Mine, to learn for Marshal McBride how far the infestation ran" },
    [17] = { 1, "gathered magenta fungus caps in Uldaman for Ghak Healtouch to study for alchemy, minding their poison spores" },
    [18] = { 1, "pulled red burlap bandanas from the Defias Brotherhood, a new band of thieves lurking across the river from Northshire" },
    [19] = { 3, "hunted down Tharil'zun, vicious leader of the Blackrock Outrunners ambushing the road to Stonewatch Keep" },
    [20] = { 2, "fought the Blackrock orcs of Stonewatch Keep, whose raids kept the people of Lakeshire penned in town like cattle" },
    [21] = { 2, "purged the Echo Ridge Mine of kobold laborers before they gained a deeper foothold in Northshire" },
    [22] = { 1, "fetched Goretusk livers for Salma Saldean's famous meat pie, a feast for her and Farmer Saldean" },
    [23] = { 2, "presented the paw of Ursangous, a great bear with many kills to his name, to Senani Thunderheart for the Ashenvale Hunt" },
    [24] = { 2, "claimed the head of Shadumbra, the nightsaber that made every trip west of Splintertree Post dangerous, for the Ashenvale Hunt" },
    [25] = { 2, "cleared the befouled elementals that had halted the transports past Mystral Lake, and scouted the Alliance outpost there" },
    [28] = { 2, "dived into Lake Elune'ara for a shrine bauble and raced it to the Shrine of Remulos, a first trial for the aquatic form" },
    [29] = { 2, "searched Lake Elune'ara for a shrine bauble and raced it to the Shrine of Remulos before it decayed, the Trial of the Lake" },
    [30] = { 3, "joined the halves of the Pendant of the Sea Lion, agility and endurance, to pass the trial for the aquatic form" },
    [32] = { 1, "carried Fizzledowser's report on the desert bugs to Zilzibin Drumlore in Orgrimmar, a troll scholar who might know how to stop them" },
    [33] = { 1, "hunted timber wolves for the tough meat Eagan Peltskinner wanted for his wolf steaks" },
    [34] = { 2, "put an end to Bellygrub, the boar that kept trampling Martie Jainrose's garden and her daffodils" },
    [36] = { 1, "carried Verna Furlbrow's recipe for Westfall stew to Salma Saldean before the Furlbrows left their overrun farm" },
    [37] = { 2, "searched the river for Guard Thomas's missing men, Rolf and Malakai, and found Malakai's medallion beside a stripped corpse" },
    [38] = { 1, "gathered vulture meat, goretusk snouts, murloc eyes and okra so Salma Saldean could cook Verna's Westfall stew" },
    [39] = { 1, "told Marshal Dughan that Rolf and Malakai were dead and the murlocs of eastern Elwynn more than his troops could contain" },
    [40] = { 1, "urged Marshal Dughan, for Remy, to send troops east against the murlocs scaring away fish and attacked gentle folk" },
    [45] = { 2, "followed webbed footprints to the murloc village at Stone Cairn Lake to learn what became of Rolf, and found his body" },
    [46] = { 1, "thinned the murlocs of Stone Cairn Lake for the Stormwind Army's bounty, to help bring eastern Elwynn under control" },
    [48] = { 1, "fetched Holy Spring Water from a hidden well in the south for Grimbooze Thunderbrew's rhyming recipe for sweet amber" },
    [49] = { 1, "gathered sacks of barley, rye and corn for the mash of Grimbooze Thunderbrew's sweet amber" },
    [50] = { 1, "supplied truesilver so Grimbooze Thunderbrew could fashion a still for his private stash" },
    [51] = { 1, "fetched a sycamore branch for the charcoal that would filter Grimbooze Thunderbrew's spirit" },
    [52] = { 1, "culled the prowlers and young bears that kept attacking the Eastvale Logging Camp, for Guard Thomas" },
    [53] = { 1, "hauled charred oak for the barrel that would age Grimbooze Thunderbrew's sweet amber, ending in a rhyming toast" },
    [54] = { 1, "carried Marshal McBride's papers to Marshal Dughan in Goldshire, a commission as Acting Deputy to help keep Elwynn safe" },
    [55] = { 3, "turned Morbent's Bane on Morbent Fel in his house above Raven Hill and slew him, the revenge Sven had long hoped for" },
    [56] = { 2, "cleared skeletons from Tranquil Gardens for the Night Watch, guarding Darkshire alone since Stormwind withdrew its soldiers" },
    [57] = { 2, "drove the skeletal fiends and horrors from the Raven Hill graveyard, where the undead were spreading through the forest around Darkshire" },
    [58] = { 2, "rid the eastern mausoleum of Raven Hill of its Plague Spreaders, with too few Watchers left to keep Darkshire safe" },
    [61] = { 1, "carried William Pestle's candles to his brother Morgan at Pestle's Apothecary in Stormwind" },
    [62] = { 1, "scouted the Fargodeep Mine for Marshal Dughan, who had word it had become a haven for kobolds" },
    [63] = { 3, "defeated the Corrupt Manifestation of Water at the plague-tainted shrine in Silverpine, to cleanse its pool and call up a pure spirit" },
    [64] = { 1, "retrieved Farmer Furlbrow's pocket watch, a wedding gift from Verna's father, from the farmhouse thieves had overrun" },
    [66] = { 1, "asked after the name Stalvan at the Town Hall, a clue from Madame Eva's trance as she feared for her granddaughter Alyssa" },
    [67] = { 1, "looked for word of Stalvan Mistmantle at the Moonbrook Schoolhouse, his last known address in Clerk Daltry's registry" },
    [68] = { 1, "brought Clerk Daltry a dusty unsent letter from a footlocker in Moonbrook, proof that Stalvan had lived there after all" },
    [69] = { 1, "followed a half scratched-out address in the town registry to the Lion's Pride Inn in Goldshire, in search of Stalvan" },
    [70] = { 2, "delivered a letter of Stalvan's, left behind by a messenger who fled the Lion's Pride Inn screaming one stormy night" },
    [71] = { 2, "brought the medallions of Rolf and Malakai back to Guard Thomas, so he would know the fate of his murdered guards" },
    [72] = { 1, "searched the Flintridge family's last possessions, bound for auction long after the massacre, for a clue to Stalvan" },
    [74] = { 1, "showed the torn journal page from the Flintridge crate to Marshal Haggard, whose failing eyes still knew the hand" },
    [75] = { 1, "fetched the faded journal page from the chest upstairs for Marshal Haggard, too nearly blind to read it himself" },
    [76] = { 1, "explored the distant Jasperlode Mine to confirm the kobolds there, more bad news for Marshal Dughan" },
    [77] = { 1, "recovered bottles of Hinterlands Honey Ripple from crates in the ooze-ridden ruins of Skulk Rock, the delicacy Dran Droffers wanted" },
    [78] = { 1, "took the faded journal page to Tavernkeep Smitts, an expert in local lore, who recognized the handwriting at once" },
    [79] = { 2, "brought Commander Ebonlocke the muddy pages found where visiting nobles were slaughtered, tying the evidence to Stalvan" },
    [80] = { 2, "had Clerk Daltry match the bloodstained journal page to the signatures in his registry, proving Stalvan's guilt" },
    [81] = { 1, "carried the barrel of packaged Hinterlands Honey Ripple back to Dran Droffers, who would sell it to a tavern for five times the fee" },
    [82] = { 2, "pried parts off the Centipaar in the Noxious Lair so Alchemist Pestlezugg could learn what was draining the desert's water pools" },
    [83] = { 1, "took red linen bandanas from the Defias of Elwynn so Sara Timberlain could make fine linen goods" },
    [84] = { 1, "carried Auntie Bernice's Pork Belly Pie to Billy Maclure, whose memory of the necklace came back with a full belly" },
    [86] = { 1, "brought boar meat to Auntie Bernice for a pork belly pie, the price of Billy Maclure's memory of her lost necklace" },
    [87] = { 2, "chased a big gold-toothed kobold into the Fargodeep Mine for Auntie Bernice's lost necklace, which she had blamed on Billy Maclure" },
    [88] = { 2, "killed Princess, the Brackwells' prize-winning sow, before she came back to eat the Stonefields' whole crop" },
    [89] = { 1, "recovered iron pikes and rivets from the gnolls who hijacked Lakeshire's supplies, so the Everstill Bridge could be rebuilt" },
    [90] = { 1, "gathered lean wolf flanks and Stormwind seasoning herbs for the Seasoned Wolf Kabobs Chef Grual called a house favorite" },
    [91] = { 2, "killed the Shadowhide gnolls who served the warlock Morganth and kept Lakeshire in fear, as the Law of Lakeshire demanded" },
    [92] = { 1, "gathered condor meat, goretusk snouts and spider meat to restock Chef Breanna's bare cupboard for a Redridge Goulash" },
    [93] = { 1, "collected gooey spider legs for Chef Grual's Dusky Crab Cakes, to feed Jitters after weeks of grubs and weeds" },
    [94] = { 1, "placed the Glyph of Azora by the Tower of Ilgalar so Theocritus could spy on his rival, the mage Morganth" },
    [95] = { 2, "dug up what a shadowy figure had buried behind the old stump at Sven's farm, where dark riders had slaughtered Sven's family" },
    [96] = { 2, "brought the Shard of Water to Islen Waterseer as proof the shrine was cleansed, and earned a water totem" },
    [98] = { 3, "executed Stalvan Mistmantle at his cottage north of Darkshire, the murderer Madame Eva's premonition had uncovered" },
    [99] = { 2, "claimed enchanted shackles from the cursed folk of Pyrewood, the last piece Dalar Dawnweaver needed to undo Arugal's magic" },
    [100] = { 1, "spoke with the pure water spirit at the cleansed shrine, which left the protection of life to the shaman" },
    [101] = { 1, "gathered fangs, fingers and venom so Madame Eva could enchant a Totem of Infliction against a danger she foresaw" },
    [102] = { 1, "patrolled the grasslands for the gnolls who worked with the Deadmines thieves, and brought their paws to Captain Danuvin" },
    [103] = { 1, "took flasks of oil from the Harvest Monsters so Captain Grayson could keep the lighthouse lit for sailors near the rocks" },
    [104] = { 3, "slew Old Murk-Eye, the murloc whose raids killed the lighthouse keeper's family, for the ghost of Captain Grayson" },
    [105] = { 3, "destroyed Araj the Summoner, the lich who held Andorhal, and took a shard of his phylactery to High Executor Derrington" },
    [106] = { 1, "carried Maybell Maclure's love letter to Tommy Joe Stonefield, whose family was the bitter enemy of hers" },
    [107] = { 1, "brought Gramma Stonefield's note to William Pestle in Goldshire, in hope of a potion to unite the young lovers" },
    [112] = { 1, "took crystal kelp from the murlocs of Crystal Lake for William Pestle's invisibility liquor" },
    [113] = { 1, "brought Fizzledowser the grim finding of Pestlezugg: the bugs were driven by some outside force, a threat to all of southern Kalimdor" },
    [114] = { 2, "delivered the invisibility liquor to Maybell, so she could slip away from the Maclure Vineyards to see Tommy Joe" },
    [115] = { 2, "took midnight orbs from Blackrock shadowcasters to be destroyed, dark devices that had struck hard at Redridge's defenders" },
    [116] = { 1, "fetched lager, merlot, moonshine and rum from four towns for Barkeep Daniels, his bottles near dry since the orc invasion" },
    [117] = { 1, "found hops for Grimbooze Thunderbrew so his lager would taste more like beer and less like stew" },
    [118] = { 1, "took Verner Osgood's note to Smith Argus in Goldshire, asking for horseshoes for the stable's horses" },
    [119] = { 1, "hauled the crate of horseshoes back to Verner Osgood, along with Argus's note asking to be paid" },
    [120] = { 2, "carried Magistrate Solomon's plea for reinforcements to General Marcus Jonathan, Lakeshire being under constant siege" },
    [121] = { 1, "returned General Marcus Jonathan's reply to Magistrate Solomon, who read in it that something was amiss in the kingdom" },
    [122] = { 1, "hunted black dragon whelps for underbelly scales, so Verner Osgood could pay Argus for his horseshoes" },
    [123] = { 2, "handed Marshal Dughan a schedule of gold shipments from Elwynn's mines to someone called the Collector" },
    [124] = { 2, "drove off the gnoll brutes and mystics on the ridge above Verner Osgood's stable, who took his horses when they strayed" },
    [125] = { 1, "dived to the bottom of Lake Everstill for Foreman Oslow's toolbox, sunk when orc catapults hit the boat carrying it" },
    [126] = { 3, "killed Yowler, leader of the gnolls whose baying filled the hills above Lakeshire, to send his pack scattering" },
    [127] = { 1, "sold Dockmaster Baren the spotted sunfish Lake Everstill is famous for, his stock running low" },
    [128] = { 2, "slew Blackrock Champions, leaders of the clan's units camped north of Lakeshire, as Magistrate Solomon wanted" },
    [129] = { 1, "took Guard Parker his lunch on his patrol of the Duskwood road, too dangerous a walk for the townsperson who made it" },
    [131] = { 1, "delivered Guard Parker's daffodils to Darcy, who feared jealous Martie might have poisoned them" },
    [132] = { 1, "brought Wiley's note to Gryan Stoutmantle, a warning that the Defias were working with gnolls, kobolds and even goblins" },
    [133] = { 1, "collected ghoul ribs for Abercrombie's effigy, a scarecrow for ghouls after Bone Chewers pounded on his walls" },
    [134] = { 1, "recovered Abercrombie's crate of tools and herbs from near the ogre mound, left behind when ogres chased him off" },
    [135] = { 1, "showed Wiley's note to Mathias Shaw of SI:7, to learn whether the Defias had ties to the Stonemasons" },
    [136] = { 1, "followed the first of Captain Sanders' clues to a footlocker half-buried by the one rusty anchor on the coast" },
    [138] = { 1, "followed the next clue to Captain Sanders' treasure east up the bluffs to an old barrel by a ruined chimney" },
    [139] = { 1, "chased Captain Sanders' trail of clues north to an empty jug beside a lone windmill on the sea bluffs" },
    [140] = { 1, "swam west to an island for Captain Sanders' treasure chest, the end of his trail of clues" },
    [141] = { 2, "carried Shaw's report to Stoutmantle: the Defias leader was likely Edwin VanCleef, the stonemason who had fallen out with the King" },
    [142] = { 2, "hunted down the Defias Messenger on Westfall's roads for the message that proved VanCleef led the Brotherhood" },
    [143] = { 1, "carried Magistrate Solomon's plea to Gryan Stoutmantle of the Westfall militia, since the Stormwind Army had not come" },
    [144] = { 1, "brought back Gryan Stoutmantle's heavy-hearted refusal, Westfall abandoned by Stormwind just as Lakeshire was" },
    [145] = { 1, "crossed into Duskwood with Magistrate Solomon's letter asking Lord Ebonlocke to send his Night Watch to Lakeshire" },
    [146] = { 2, "brought Lord Ebonlocke's refusal back to Lakeshire, news that left Magistrate Solomon sure of treachery in Stormwind" },
    [147] = { 3, "hunted down the Collector, who had been stealing gold from Elwynn's mines, and brought his ring to Marshal Dughan" },
    [149] = { 1, "took a spectral comb to the sad spirit Blind Mary, so Madame Eva could glean ghost hair from it for thread" },
    [150] = { 1, "hunted the murlocs fishing Lake Everstill bare for Dockmaster Baren, strangely far from the sea" },
    [152] = { 1, "cleared the murlocs from the Westfall coast for Captain Grayson, so shipwrecked sailors would be safe on its beaches" },
    [153] = { 1, "collected red leather bandanas from Defias gang members for Scout Galiaan, who tracked the shifting Defias front by them" },
    [154] = { 1, "brought the comb back to Madame Eva after Blind Mary cried that she was a monster no one would think lovely again" },
    [155] = { 3, "escorted the Defias Traitor to the Brotherhood's secret hideout, so Stoutmantle would know where VanCleef was hiding" },
    [156] = { 1, "plucked rot blossoms from the skulls of Raven Hill's skeletons for Tavernkeep Smitts's zombie juice, thinning their ranks" },
    [157] = { 1, "brought Abercrombie the ghost hair thread, good for binding evil spirits or sewed life into lifeless things" },
    [159] = { 1, "took Abercrombie the zombie juice he wanted against the cold nights, a brew strong enough to raise the dead" },
    [160] = { 1, "carried Abercrombie's letter to his old friend the Mayor of Darkshire, who found it written in a tongue he could not read" },
    [161] = { 1, "carried the strange powder from the dam to Ashlan Stonesmirk in Dun Modr, an explosives expert who could tell what it was" },
    [162] = { 1, "took Fizzledowser's report on the desert bugs to Gracina Spiritmight in Darnassus, a scholar who might know how to stop them" },
    [163] = { 1, "looked into what haunted Raven Hill, where Calor had seen shadows moving, and found only Jitters in hiding" },
    [164] = { 1, "delivered supplies to Sven's camp at the edge of Duskwood, his followers too few to spare a man to fetch them from town" },
    [165] = { 1, "checked on the old man in the shack above Raven Hill cemetery, who had long stopped coming into town for supplies" },
    [166] = { 3, "assassinated Edwin VanCleef in the Deadmines, the beginning of the end for the Defias Brotherhood that plagued Westfall" },
    [167] = { 2, "searched the collapsed Moonbrook mine for Wilder Thistlenettle's brother, and brought back only his Explorers' League badge" },
    [168] = { 1, "gathered the Miners' Union cards of those lost in the cave-in, so Wilder Thistlenettle could tell their families" },
    [169] = { 3, "killed Gath'Ilzogg, leader of the Blackrock attacks on Lakeshire, the first step to reclaim Stonewatch Keep for Stormwind" },
    [170] = { 2, "drove back the Rockjaw troggs for Balir Frosthammer, whose camp to the west they had overrun only nights before" },
    [171] = { 2, "brought Randis home to Orphan Matron Nightingale at the end of Children's Week, an orphan who now wanted to be a hero" },
    [172] = { 1, "took on Grunth, an orc orphan whose parents died with honour in battle, as a ward for Children's Week" },
    [173] = { 1, "took on the Nightbane Shadow Weaver worgen of Brightwood Grove, to prove worthy of Master Carevin's band" },
    [174] = { 1, "got a bronze tube for Viktori Prism'Antras, the first part of a device to read in the stars the truth of the forest's change" },
    [175] = { 1, "tracked down Mary, once known for always carrying a looking glass, to ask a mirror of her for Viktori's star device" },
    [176] = { 3, "slew Hogger, the huge gnoll who had overpowered every attempt at his capture, for the bounty in Goldshire" },
    [177] = { 1, "wrested Blind Mary's looking glass from the Insane Ghoul of Tranquil Gardens, the mirror Viktori's device lacked" },
    [178] = { 1, "brought a faded Shadowhide pendant to Theocritus the Mage, whose spell through it to Morganth's gnolls had seemed a failure" },
    [179] = { 1, "hunted wolves for Sten Stoutarm's Tough Wolf Meat, in trade for warm gloves against the frostbite" },
    [180] = { 3, "slew Lieutenant Fangore, leader of the Shadowhide gnolls in Morganth's service, wanted dead by Magistrate Solomon" },
    [181] = { 2, "took the ogre Zzarc'Vul's monocle for the lens of Viktori's stargazing device, the last piece it called for" },
    [182] = { 2, "thinned the Frostmane troll whelps in the southern cave for Grelin Whitebeard, sent to Coldridge Valley to judge the troll threat" },
    [183] = { 1, "culled the Small Crag Boars by the frozen lake, grown so many that Talin Keeneye's daily hunting had become dangerous" },
    [184] = { 1, "returned the Furlbrows' stolen deed, which the thieves meant to forge, so the family might one day reclaim their land" },
    [185] = { 1, "proved a hunter's mettle to Ajeck Rouack on the young tigers near Nesingwary's camp, the first of her trials" },
    [186] = { 1, "stalked the grown Stranglethorn Tigers, the next step of Ajeck Rouack's training in the tiger hunt" },
    [187] = { 1, "tracked down the elder tigers of Stranglethorn, the fiercest and hardest to find, to show Ajeck Rouack the training had taken" },
    [188] = { 3, "hunted down Sin'Dall, the elusive tiger Nesingwary's party had tracked for weeks, and earned the name of master tiger hunter" },
    [189] = { 1, "collected Bloodscalp ears for Kebok of Booty Bay, whose agents and guards the trolls had been killing in the jungle" },
    [190] = { 1, "started out on young panthers, the first proof Sir S. J. Erlgadin asked of anyone joining Hemet's hunt" },
    [191] = { 1, "moved up to full-grown panthers, tougher game, to be thought worthy of Nesingwary's big game hunters" },
    [192] = { 1, "dropped Shadowmaw Panthers, the deadliest cats in Stranglethorn, as Sir S. J. Erlgadin's hardest test of a panther hunter" },
    [193] = { 3, "slew the great panther Bhag'thera, who had eluded Nesingwary's party, and brought his fang to Sir S. J. Erlgadin" },
    [194] = { 1, "bagged Stranglethorn Raptors for Hemet Nesingwary, who left the finding of them to the hunter as half the challenge" },
    [195] = { 1, "took on the Lashtail Raptors, Hemet Nesingwary's next and stiffer test of a raptor hunter" },
    [196] = { 1, "tracked the cagey Jungle Stalkers, the hardest raptors to find and kill, to earn Hemet Nesingwary's tip on the best hunting yet" },
    [197] = { 3, "killed Tethis, a wily raptor even Hemet Nesingwary had failed to bring down, and brought back its talon" },
    [198] = { 1, "carried goblin supplies to Private Thorsen, land mines Lieutenant Doren's rebels needed against Kurzen and his men" },
    [200] = { 2, "searched Kurzen's Compound for Bookie Herod's records, to learn how Private Thorsen's secret had leaked to Kurzen" },
    [201] = { 1, "scouted the hunters' camp upriver for Krazek in Booty Bay, who wanted to know what Hemet Nesingwary was about" },
    [202] = { 3, "stormed the Stockpile to kill Colonel Kurzen and his leaders, saving Lieutenant Doren's band of rebels" },
    [203] = { 2, "raided Kurzen's camp to cut down his Jungle Fighters and ease the pressure on the outnumbered rebels" },
    [204] = { 2, "stripped Kurzen's Medicine Men of their Jungle Remedies and Venom Fern Extract, so the rebels could heal their own" },
    [205] = { 2, "took Skullsplitter Fetishes from their witchdoctors for Brother Nimetz, who sought the secret of Kurzen's fall into evil" },
    [206] = { 3, "killed the ogre mage Mai'Zoth, whose mind magic Brother Nimetz blamed for Kurzen's corruption, and took his Mind's Eye" },
    [207] = { 2, "copied four troll tablets in the ruins of Stranglethorn for Brother Nimetz, who suspected troll magic behind Kurzen's fall" },
    [208] = { 3, "hunted King Bangalash, the great white tiger Hemet Nesingwary had come to Stranglethorn for, a prize no other hunter had taken" },
    [209] = { 1, "pried tusks from Skullsplitter trolls for Kebok, who passed them off as tiger fangs to buyers in the South Seas" },
    [210] = { 1, "took the rebel cook's broken Crock Pot back to Krazek in Booty Bay, the goblin who had made it, to be mended" },
    [211] = { 3, "brought down Araj the Summoner, the lich ruling Andorhal, and carried his phylactery shard to Commander Ashlam Valorfist" },
    [212] = { 1, "rushed a Chilled Basilisk Haunch from Stranglethorn to Angus Stern, who needed the meat fresh for a noble's birthday banquet" },
    [213] = { 1, "stole Tumbled Crystals from the Venture Co. geologists for Kebok, as Baron Revilgaz pushed back against Gelriz's meddling" },
    [214] = { 2, "cut down the highest-ranking Defias in VanCleef's hideout and brought their red silk bandanas to Scout Riell as proof" },
    [215] = { 1, "learned from Lieutenant Doren that Private Thorsen had gone back among Kurzen's men as a spy for the rebels" },
    [216] = { 2, "thinned the Thistlefur furbolgs, whose village blocked the Horde's path between Zoram'gar and Splintertree Post" },
    [217] = { 3, "killed the trogg chieftain Grawmug and his guards Gnasher and Brawler, to push the troggs of Loch Modan back into the ground" },
    [218] = { 3, "killed Grik'nir the Cold in the troll cave to take back Grelin Whitebeard's stolen journal" },
    [219] = { 3, "escorted the wounded Corporal Keeshan, whose regiment the Blackrock orcs had overpowered, from his prison cave back to Redridge" },
    [220] = { 1, "carried Brine's blessed Vial of Purest Water to Islen Waterseer, the makings of a sapta and of the trial to come" },
    [221] = { 2, "culled the Nightbane Dark Runners that had overrun the Rotting Orchard, the bulk of the worgen in the woods, for Calor" },
    [222] = { 2, "faced the Nightbane Vile Fangs and Tainted Ones by their bonfires in the south, the most dangerous worgen in Duskwood" },
    [223] = { 1, "carried Calor's letter of recommendation to Master Jonathan Carevin, to join his fight against demons and the undead" },
    [224] = { 2, "fought the Stonesplinter troggs tunnelling across Loch Modan, the gravest threat Ironforge faced while its soldiers were at the front" },
    [225] = { 1, "asked Sirra Von'Indi about Morgan Ladimore, whose weathered grave had been freshly dug up" },
    [226] = { 1, "thinned the starving and rabid dire wolves that harried Lars on his way back to Sven's Camp with meat" },
    [228] = { 3, "killed Mor'Ladim, the risen body of Morgan Ladimore, who wandered Duskwood attacking Watchmen on patrol" },
    [229] = { 1, "brought Watcher Sarah Ladimore news of her father, whose death had always troubled her" },
    [230] = { 1, "brought Sven the book dug up at his farm, which told him the shadowy figure had witnessed his family's death" },
    [231] = { 3, "laid Sarah Ladimore's ring on her father's grave, so Morgan Ladimore would know she lived and his soul could rest" },
    [232] = { 1, "took Apothecary Zinge's order to Alessandro Luca for a testing kit, the start of her plan to profit from Keever's research" },
    [237] = { 2, "held off the trogg skullthumpers and seers in the southern hills, buying time until the dwarves returned from the Alliance front" },
    [240] = { 1, "brought the Dusky Crab Cakes back to Jitters, starving in his hiding place in the ghost town" },
    [244] = { 1, "warned Deputy Feldon of gnoll camps gathering near the road, a force that might advance into Elwynn" },
    [245] = { 1, "rooted out the pygmy venom web spiders overrunning Duskwood's western border, too many for the Night Watch" },
    [246] = { 2, "harried the gnoll camps along Redridge's southern road to judge their numbers for Deputy Feldon, who had no men to spare" },
    [247] = { 3, "completed the Ashenvale Hunt for Senani Thunderheart, with all three of its legendary beasts slain and proven" },
    [248] = { 1, "hid a Glyph of Azora atop the watch tower by Stonewatch Keep, so Theocritus could look into the minds within" },
    [249] = { 3, "entered the Tower of Ilgalar to defeat Morganth before he could find the Scythe of Elune and turn it on Stormwind" },
    [250] = { 2, "searched the eastern ramp of the Stonewrought Dam, where Dark Iron Sappers had been seen, for a clue to their next attack" },
    [251] = { 1, "had Abercrombie's strange letter to the mayor translated by Sirra Von'Indi, learned in languages and ancient arts" },
    [252] = { 2, "carried the translated letter to Lord Ello Ebonlocke, revealing that the help given Abercrombie had doomed Darkshire" },
    [253] = { 3, "took the Embalmer's still-beating heart from his wife Eliza's grave, to break his power and shield the town of Darkshire" },
    [255] = { 2, "fought the Mo'grosh ogres camped by the lake as hired arms for Magistrate Bluntnose, while Thelsamar waited months for soldiers" },
    [256] = { 3, "hunted down Chok'sul, the ogre behind the attacks on Thelsamar, the dam and the excavation" },
    [257] = { 1, "met Daryl the Youngling's boastful challenge to bring down a flock of mountain buzzards against the clock" },
    [258] = { 1, "raced the clock against elder mountain boars to prove Daryl the Youngling wrong a second time" },
    [261] = { 1, "destroyed the undead ravagers in the Valley of Bones to prove allegiance to Brother Anton and the Scarlet Crusade" },
    [262] = { 1, "showed the book from Sven's farm around Darkshire, to find the skulker Sven saw the night his family was killed" },
    [263] = { 2, "killed trogg shaman and bonesnappers for Mountaineer Wallbang, the reserves called to the front and the guards left alone" },
    [264] = { 1, "laid Clarice's pendant on Yuriv's tomb at the Sepulcher, since she wanted nothing more to do with the husband who left her for his crusade" },
    [265] = { 1, "asked around Darkshire after the book's owner, a nervous, jittery stranger who had bought it in town a month before" },
    [266] = { 1, "searched the inn for word of the book's owner, who had left in a hurry, muttering about being hunted, and gone west" },
    [267] = { 1, "took the fight to the troggs in the hills for Captain Rugelfuss, whose regiment could not leave its gate" },
    [268] = { 2, "took Jitters' finished journal to Sven, for what it told of the dark riders and Morbent Fel" },
    [269] = { 1, "brought Jitters' journal to Bishop Farthing in the Cathedral of Light, for counsel before facing Morbent Fel" },
    [270] = { 1, "asked Glorin Steelbrow in Menethil Harbor after the Lightforge Iron lost at sea, metal for a weapon against Morbent Fel" },
    [271] = { 2, "killed Ol' Sooty, the bear that gave Daryl the Youngling his scar, at Vyrin Swiftwind's urging" },
    [272] = { 3, "found and joined both halves of the Pendant of the Sea Lion, proof of the agility and endurance a water form needs" },
    [273] = { 2, "caught up with Huldar's powder shipment to the excavation just as the porter Saean turned out to be a Dark Iron sympathizer" },
    [274] = { 1, "rushed back to Hinderweir with word that the powder was Seaforium, enough once wet to blow Ironforge out of the mountain" },
    [275] = { 2, "put down the diseased Fen Creepers for Rethiel the Greenwarden, so the fever festering in the Wetlands could break" },
    [276] = { 2, "culled the Mosshide gnolls near the gate of Algaz for Rethiel the Greenwarden, their swelling numbers trampling the fen" },
    [277] = { 1, "took crude flints from the Mosshides so Rethiel the Greenwarden could cast them into the sea, ending their burning of living wood" },
    [278] = { 2, "gathered lurker venom, a Mo'grosh crystal and a crocolisk tear for the mixture that could defuse the Dark Irons' Seaforium" },
    [279] = { 2, "slew Gobbler and his Bluegill kin for the Merchant Marines, the murlocs harrying merchants along the coast road" },
    [280] = { 3, "swam down to the Dark Irons' keg at the base of the Stonewrought Dam to stir in the disarming mixture before it blew" },
    [281] = { 1, "searched the coastal murloc camps for cargo dragged from the Blind Princess, among it a valuable statuette of Terenas Menethil" },
    [284] = { 1, "combed more murloc hovels along the coast for the missing Menethil Statuette" },
    [285] = { 1, "dug through the last murloc hovels to the north, sure the Menethil Statuette was close" },
    [286] = { 2, "returned the Menethil Statuette to Karl Boran, precious cargo lost when murlocs raided the Blind Princess" },
    [287] = { 2, "scouted Frostmane Hold and killed its headhunters for Senir Whitebeard, who had seen too many trolls to dare go in" },
    [288] = { 1, "bought a flagon of mead for First Mate Fitzsimmons, sole survivor of the doomed Third Fleet, so he could finish his tale" },
    [289] = { 2, "put down the cursed crew of the Third Fleet, First Mate Snellig among them, to free the souls of Fitzsimmons' shipmates" },
    [290] = { 2, "took the strongbox key from Captain Halyndor, who still walked the doomed Intrepid, to reach the cursed thing binding his crew" },
    [291] = { 1, "carried Senir Whitebeard's report on the trolls to a sour Senator Barin Redstone in Ironforge" },
    [292] = { 1, "brought the Cursed Eye of Paleth from the Intrepid to the priest Glorin Steelbrow, hoping to learn how to lift its curse" },
    [293] = { 3, "took the Cursed Eye of Paleth to Archbishop Benedictus in Stormwind to be cleansed, the way to free the Third Fleet's cursed dead" },
    [294] = { 2, "killed Mottled Raptors and Screechers for Ormer Ironbraid, whose brethren the raptors had slain at the Whelgar Excavation Site" },
    [295] = { 2, "slew Mottled Scytheclaws and Razormaws below the bluff, to make the raptors pay for the dwarves of the dig" },
    [296] = { 3, "hunted Sarltooth, the great raptor Ormer Ironbraid blamed for leading the attack on the dig, and brought back a talon as proof" },
    [297] = { 1, "pried carved idols from the troggs at Ironband's Excavation, relics that drove them berserk, for Magmar Fellhew to study" },
    [298] = { 1, "brought Ironband's progress report and his plea for more blastpowder to Jern Hornhelm in Thelsamar" },
    [299] = { 2, "unearthed the four lost fragments of the Goaz Stone for Prospector Whelgar, a Titan tablet that spoke of a doomed prophecy" },
    [301] = { 1, "carried Ironband's report to Prospector Stormpike in Ironforge, who had sent blastpowder weeks before that never arrived" },
    [303] = { 2, "pushed back the Dark Iron dwarves at Dun Modr for Motley Garmason, so the reserve might arrive in time to finish the drive" },
    [304] = { 3, "killed Balgaras the Foul, the cowardly Dark Iron warlock leading the thugs who took Dun Modr, for Longbraid the Grim" },
    [305] = { 2, "sought Merrin Rockweaver at the excavation site for her worried husband Tarrel, two weeks without a letter from her" },
    [306] = { 1, "carried Merrin's note to Tarrel, telling him raptors had overrun the dig and only three of the team survived" },
    [307] = { 1, "rescued the Miners' League gear from the kobold-infested Silver Stream Mine before the warriors stormed in" },
    [309] = { 2, "escorted Miran and the blastpowder to Ironband's Excavation, with Dark Iron sympathizers about on the road" },
    [310] = { 1, "sneaked a barrel of Barleybrew Scalder into the Thunderbrew cellar, to teach the Thunderbrews theirs was not the only decent brew" },
    [311] = { 1, "brought a pilfered barrel of Thunder Ale back to Marleth Barleybrew as proof of the switch" },
    [312] = { 2, "slipped into Old Icebeard's cave for Tundra MacGrann's dried meats, a month of food he would starve without" },
    [313] = { 1, "took wendigo manes from the Grizzled Den for Pilot Stonegear, a rug for the deck of his siege engine Trollplow" },
    [314] = { 3, "slew Vagash, the beast preying on the Amberstill rams while most of Magni's army was away at war" },
    [315] = { 1, "swiped shimmerweed from the Frostmane trolls for Rejold Barleybrew, who meant to brew the perfect stout" },
    [317] = { 1, "hunted boar meat and bear furs to stock Pilot Bellowfiz's tank Jetsteam for a month-long Siege Brigade mission" },
    [318] = { 1, "fetched a cask of Evershine for Pilot Bellowfiz, a brew to warm him on the cold road and burn in Jetsteam's furnace" },
    [319] = { 1, "cleared bears, boars and snow leopards from around Brewnall Village so its dwarves could get on with their brewing" },
    [320] = { 1, "brought Pilot Bellowfiz his cask of Evershine, fire for Jetsteam's furnace on the long mission ahead" },
    [321] = { 1, "searched the wreck of the Flying Osprey for its Lightforge Iron, only to find the chest clawed open by murlocs" },
    [322] = { 1, "took the lightforge ingots to Grimand Elmore in Stormwind, to forge a weapon to give even Morbent Fel worry" },
    [323] = { 2, "fought Morbent Fel's skeletal minions, so Sven would know the strength needed to face the necromancer" },
    [324] = { 1, "hunted the murloc raiders near the wreck of the Flying Osprey for the lightforge ingots they had stolen" },
    [325] = { 1, "brought Morbent's Bane, forged of the lightforge iron, to Sven as proof against the fiend Morbent Fel" },
    [328] = { 2, "opened Bookie Herod's strongbox in the Stockpile with a key hidden in his ledger, hoping to learn how Thorsen was found out" },
    [329] = { 2, "brought a muddy note from Herod's strongbox to Lieutenant Doren, the clue to a traitor within the rebel camp" },
    [330] = { 2, "checked Corporal Sethman's patrol schedules to learn who had shared Thorsen's routes, and so who had betrayed him" },
    [331] = { 3, "unmasked Private Merle as the spy among Lieutenant Doren's rebels, a traitor they could not have survived for long" },
    [333] = { 1, "took Harlan Bagley's request for more knitted clothing to the Canal Tailor, his stock run low with everyone buying armour" },
    [334] = { 1, "brought young Thurman Schneider the sewing kit he had forgotten, without which he could not do his apprentice work" },
    [335] = { 1, "gathered a Tear of Tilloa and a Musquash Root for Zardeth the Black Claw, who meant to keep Lord Wishock from exposing the warlocks" },
    [336] = { 2, "served Lord Wishock a bottle of Zardeth's Black Claw stout, so the warlocks of Stormwind could practice their ways undisturbed" },
    [338] = { 1, "gathered the scattered pages of Hemet Nesingwary's novel for Barnil Stonepot, who had let the wind blow them across the jungle" },
    [339] = { 1, "pieced together the first chapter of The Green Hills of Stranglethorn, where Nesingwary names his hunting companions" },
    [340] = { 1, "found the lost pages of Chapter II of Nesingwary's novel, its tales of panther and tiger hunts, for Barnil Stonepot" },
    [341] = { 1, "restored Chapter III of Nesingwary's manuscript, with Erlgadin and Rouack's first kill with a dwarven rifle" },
    [342] = { 1, "recovered the last pages of Chapter IV, the finale of The Green Hills of Stranglethorn, for Barnil Stonepot" },
    [346] = { 1, "returned The Stresses of Iron to Brother Kristoff at last, for his speech on the Fortitude of the Spirit" },
    [347] = { 1, "dug Rethban Ore out of the gnoll-held Rethban Caverns so Brother Paxton could mix the ink to finish copying his book" },
    [348] = { 3, "fetched the heart of Mokk the Savage, summoned by Witch Doctor Unbagwa, the only cure for Fin Fizracket's deadly fever" },
    [351] = { 1, "followed a distress beacon to Oglethorpe's homing robot, crashed near the Gaping Chasm" },
    [353] = { 1, "carried Grimand Elmore's new axe all the way to Mountaineer Stormpike in Loch Modan, eager to try it on troggs and kobolds" },
    [354] = { 2, "destroyed the risen Agamands for their remains, revenge for Coleman Farthing, whom their pride had doomed to undeath" },
    [356] = { 2, "patrolled behind the Bulwark to slay the Scourge that slipped past, so its defenders faced no attack from the rear" },
    [357] = { 2, "stole the spellbook of the lich on Brightwater Lake's island, which told Bethor Iceshard he was Gunther Arcanus" },
    [358] = { 2, "slew the Rot Hide gnolls robbing the Mass Graves for the Scourge's armies, and took their ichor for the apothecaries" },
    [361] = { 1, "delivered Thurman Agamand's last letter to Yvette Farthing, who had begged him to leave Agamand Mills with her" },
    [362] = { 2, "destroyed Devlin Agamand, whose mad chattering still carried from the mills, so Coleman Farthing could have his bones" },
    [364] = { 2, "destroyed the Mindless Ones overrunning the north of Deathknell, brothers and sisters once, now slaves of the Lich King" },
    [365] = { 1, "stole pumpkins from a farm under the Scarlet Crusade's nose for Apothecary Johaan, a first lesson in the Forsaken's ways" },
    [366] = { 1, "returned Gunther's spellbook with Bethor's enchantment upon it, in hope the freed lich would join the Forsaken" },
    [367] = { 1, "collected darkhound blood for Apothecary Johaan, a first test toward a new plague to bring the Scourge to ruin" },
    [368] = { 1, "gathered Vile Fin scales for Johaan's plague, since plaguing a whole world took more than poisoning one victim" },
    [369] = { 1, "drew venom from vicious night web spiders, the agent of an ancient plague, to complete Johaan's deadly new concoction" },
    [370] = { 2, "killed Captain Perrine and his brigade at the tower southwest of Brill, found through the Crusade's captured documents" },
    [371] = { 2, "cut down Captain Vachon and his friars, raiders from the ruined tower near the Balnir Farmstead, to slow the Crusade" },
    [372] = { 3, "assassinated Captain Melrache, ruthless commander of the Crusaders raiding past Faol's Rest, and his two bodyguards" },
    [373] = { 2, "brought Edwin VanCleef's unsent letter to Baros Alexston, the City Architect who had once been his fellow Stonemason" },
    [374] = { 1, "took Scarlet Insignia Rings from slain crusaders as proof of loyalty to Varimathras and the Dark Lady" },
    [375] = { 1, "brought duskbat pelts and thread to Gretchen Dedmar, so hands shaking with the Plague's chill could sew a blanket" },
    [376] = { 1, "gathered scavenger paws and duskbat wings for Novice Elreth, who tended the wounded and tailored their armour" },
    [377] = { 3, "assassinated Dextren Ward in the Stockade for Councilman Millstipe, the body seller Stormwind had spared from beheading" },
    [378] = { 3, "killed Kam Deepfury in the Stockade, the Dark Iron whose plan to bring down the Thandol Span cost Longbraid his kin" },
    [379] = { 1, "wrested water pouches from the Wastewander nomads so Chief Engineer Bilgewhizzle would part with a power source" },
    [380] = { 2, "cleared the spiders from the gold mine near Deathknell, gold the Forsaken needed to survive" },
    [381] = { 2, "struck first at the Scarlet Crusade camp southeast of Deathknell, zealots sworn to destroy every undead, and took their armbands" },
    [382] = { 3, "killed Meven Korgal, the Scarlet messenger sent from the Monastery, for the orders he carried to the Crusaders outside Deathknell" },
    [383] = { 1, "carried the captured Scarlet Crusade documents, with the names of their officers in Tirisfal, to Executor Zygand in Brill" },
    [384] = { 1, "gathered crag boar ribs and a Rhapsody Malt for Ragnar Thunderbrew, whose trapper had gone off to war, for his family recipe" },
    [385] = { 1, "wrestled the crocolisks of the Loch's islands for meat and skins, the Farstrider Lodge's trade" },
    [386] = { 3, "beheaded Targorr the Dread, Gath'Ilzogg's ruthless executioner, whose sentence some noble had mysteriously put on hold" },
    [387] = { 2, "put down the Defias inmates rioting in the Stockade for Warden Thelwater, for the safety of Stormwind" },
    [388] = { 2, "took the red wool bandanas of the Defias for Nikova Raskol, whose grandson Mac was stabbed for scolding the prisoners who made them" },
    [391] = { 3, "killed Bazil Thredd, the Defias leader behind the Stockade riots, as proof of loyalty to a distrustful Warden Thelwater" },
    [392] = { 2, "carried a description of Bazil Thredd's mysterious visitor, Maelik, to Baros Alexston in hope he knew the man" },
    [393] = { 2, "took the description to Mathias Shaw of SI:7, who knew the visitor as an assassin in the pay of Lord Gregor Lescovar" },
    [396] = { 2, "delivered Baros Alexston's report on the Defias to Stormwind Keep, and being commended for thwarting VanCleef's machinations" },
    [398] = { 3, "executed Maggot Eye, the gnoll who stole corpses near Garren's Haunt for the Lich King's army, for Brill's reward" },
    [399] = { 1, "searched the burned Alexston Farmstead in Westfall for the first compass of Baros Alexston, a keepsake of his boyhood" },
    [400] = { 1, "delivered a fresh order of tools to Beldin Steelgrill, who had broken his last fang-ratchet mid-repair on a siege engine" },
    [404] = { 1, "beat back the Scourge that had crept in by the old bridge west of Brill, for the Deathguards" },
    [407] = { 1, "fed a pumpkin laced with Johaan's latest formula to the captured Scarlet Zealot in the Gallow's End Tavern cellar" },
    [408] = { 3, "put down the Agamand ancestors in the family crypt and took the skull of Captain Dargol, the Scourge's leader there" },
    [409] = { 2, "summoned and destroyed Lillith Nefara at her bloody altar, proof for Gunther of being the Lich King's foe" },
    [411] = { 2, "brought Gunther's Nether Gem to Bethor Iceshard so the old comrades could speak, the wayward lich won over" },
    [412] = { 2, "took cogs and gears from the leper gnomes outside Gnomeregan for Razzle Sprysprocket's Recombobulator, meant to reverse their plight" },
    [413] = { 1, "carried a barrel of Rejold's new Shimmer Stout to his brother Wellart at the guard tower on the Loch Modan border" },
    [414] = { 1, "took a cask of Shimmer Stout to Mountaineer Kadrell in Thelsamar, so a fellow Mountaineer could taste the Barleybrews' latest" },
    [416] = { 1, "rooted tunnel rat kobolds out of the foothills west of Thelsamar for the bounty on their ears" },
    [417] = { 3, "killed Mangeclaw, the Ice Claw Bear that mauled Pilot Hildelve, as the dead pilot's journal asked" },
    [418] = { 1, "gathered bear meat, boar intestines and spider ichor for Vidra Hearthstove's famous blood sausages" },
    [419] = { 1, "found Pilot Mori Hildelve in the hills, frozen and dead, after he went looking for a rare ore for blastpowder" },
    [420] = { 1, "carried Grelin Whitebeard's report through the trogg-infested tunnel to his brother Senir in Kharanos" },
    [421] = { 1, "killed Moonrage Whitescalps to prove worthy of Dalar Dawnweaver, who meant to rid Silverpine of Arugal's curse" },
    [422] = { 1, "retrieved the Remedy of Arugal from the spellbooks at the wheat farm, so Dalar Dawnweaver could learn the magic behind it" },
    [423] = { 1, "collected enchanted shackles from Moonrage worgen for Dalar Dawnweaver, the items Arugal used to prop up his weak magic" },
    [424] = { 2, "beheaded Grimson the Pale, the tainted foreman of the Deep Elem Mine, to win the mine for Varimathras's advance" },
    [425] = { 3, "killed Ivar the Foul, the ghoul who had mauled Quinn Yorick, so the wounded Deathstalker would have time to heal" },
    [426] = { 2, "broke the Scourge at the Agamand Mills before they could make it a base for attacks across Tirisfal" },
    [427] = { 1, "slew Scarlet Warriors at the tower past the Solliden Farmstead, to prove worthy of serving the Dark Lady" },
    [428] = { 1, "found the Deathstalkers Rane and Quinn Yorick, missing for weeks on a scouting mission through northern Silverpine" },
    [429] = { 1, "gathered discolored worg hearts so Apothecary Renferrel could brew a healing potion for the badly mauled Quinn Yorick" },
    [430] = { 1, "delivered Apothecary Renferrel's potion to Quinn Yorick at the Ivar Patch, so he could travel again" },
    [432] = { 2, "killed Rockjaw Skullthumpers in the Gol'Bolar quarry for a furious Foreman Stonebrow, whose work site they had wrecked" },
    [433] = { 2, "cleared Rockjaw Bonesnappers out of the Gol'Bolar quarry for Senator Mehr Stonehallow, so the miners could get back to work" },
    [434] = { 3, "killed Lord Gregor Lescovar and the assassin Marzon in the castle garden as they met to plot with the Defias" },
    [435] = { 2, "escorted Erland past the hungry wolves to the Deathstalker Rane Yorick, who had feared him lost" },
    [437] = { 3, "assaulted the Rot Hide gnolls at the Dead Fields until the banshee Nightlash appeared, and destroyed her for the Forsaken" },
    [438] = { 2, "investigated the Decrepit Ferry, where the Scourge gathered, and found a heap of wrapped corpses bound for Fenris Isle" },
    [439] = { 2, "brought High Executor Hadrec a ring from a fresh corpse at the ferry, proof the Rot Hide gnolls were robbing Tirisfal's graves" },
    [440] = { 1, "showed Deliah's ring to Magistrate Sevren in Brill, who confirmed the rot hide gnolls had stolen her body" },
    [441] = { 1, "returned Deliah's ring to her husband Raleigh in the Undercity, who felt nothing for her death but burned for revenge" },
    [442] = { 3, "stormed Fenris Isle to destroy Thule Ravenclaw, the traitor mage who led the Rot Hide gnolls for the Scourge" },
    [443] = { 2, "drained ichor from the rot hide gnolls on Fenris Isle so Apothecary Renferrel could learn who was behind them" },
    [444] = { 1, "carried rot hide ichor to Bethor Iceshard in the Undercity, whose knowledge of magic might unravel the gnolls' origin" },
    [445] = { 1, "carried Apothecary Johaan's findings to Apothecary Renferrel at the Sepulcher, toward the New Plague the Dark Lady desired" },
    [446] = { 1, "delivered Bethor Iceshard's scroll to Apothecary Renferrel, the makings of a potion against Thule Ravenclaw's spells" },
    [447] = { 1, "gathered bear hearts and spider blood for Master Apothecary Faranell, ingredients of a New Plague for Scourge and humans alike" },
    [449] = { 1, "carried the Deathstalkers' report to High Executor Hadrec, word of a Scourge presence no one had accounted for" },
    [450] = { 1, "slipped into the Pyrewood inn for the journal of Apothecary Berard, cursed by Arugal, who had studied an ancient plague" },
    [451] = { 1, "gathered lake moss and a rare murloc tumor for Master Apothecary Faranell's New Plague, as Berard's journal advised" },
    [452] = { 2, "helped Deathstalker Faerleia ambush the Pyrewood Council, the puppets through which Arugal ruled the cursed village" },
    [453] = { 2, "tracked the nervous stranger who had left Darkshire heading west, and found him hiding from whatever hunted him" },
    [455] = { 2, "fought through Dun Algaz against the Dragonmaw orcs, whose foothold threatened to cut Loch Modan off from Menethil Harbor" },
    [456] = { 1, "thinned the young nightsabers and thistle boars, too many after heavy spring rains, to keep the balance of nature in Shadowglen" },
    [457] = { 1, "culled mangy nightsabers and thistle boars before they ate through the forest's food, for Conservator Ilthalaine" },
    [459] = { 2, "took Fel Moss from the grells that threatened Shadowglen, confirming Tarindrella's fear that its corruption was spreading through Teldrassil" },
    [460] = { 2, "reunited the head of Alaric, Thule Ravenclaw's bodyguard, with the body the gnolls had buried in an unmarked grave at Fenris Keep" },
    [461] = { 1, "carried Alaric's body to a hidden alcove in Fenris Keep, where he wished to rest within the walls he had loved" },
    [464] = { 2, "attacked the Dragonmaw encampment northeast of Menethil and took their war banners as proof for Captain Stoutfist" },
    [465] = { 2, "burned the catapults Nek'rosh had built to lay siege to Menethil Harbor, cut off from reinforcements" },
    [466] = { 1, "mined volatile incendicite ore in the Wetlands for Pilot Stonegear, hoping it would make cannon shells with a mighty punch" },
    [469] = { 1, "carried Einar's bundle of crocolisk skins to James Halloran, so Einar could put off facing his wife" },
    [470] = { 1, "recovered Sida's bag from the oozes of Ironbeard's Tomb, where she had thrown it to escape them" },
    [471] = { 1, "skinned giant crocolisks for James Halloran, whose apprentice the brutes had left barely alive" },
    [472] = { 2, "sought Longbraid near fallen Dun Modr for a wounded soldier in Menethil, who hoped his leader still lived" },
    [474] = { 3, "killed Chieftain Nek'rosh of the Dragonmaw, a telling blow to the clan that had meant to besiege Menethil Harbor" },
    [476] = { 1, "brought Athridas Bearmantle grave news from the wounded Gaerolas: the Gnarlpine furbolgs had been driven mad by Fel Moss" },
    [477] = { 1, "pried open a Dalaran wizards' crate near Pyrewood, to learn why they were shipping supplies to backwater Ambermill" },
    [478] = { 1, "handed the strange pendant from the wizards' crate to Shadow Priest Allister, a clue to Dalaran's aims at Ambermill" },
    [479] = { 2, "stripped Dalaran pendants from the wizards at Ambermill to slow their work on the dormant ley energy node" },
    [480] = { 3, "killed the Dalaran archmage reawakening Ambermill's ley energy node, and took his staff to Shadow Priest Allister" },
    [481] = { 1, "showed the rune-inscribed pendant to Dalar Dawnweaver, who knew it as a Kirin Tor tool for channeling magic" },
    [483] = { 2, "recovered the Relics of Wakening from the ravaged Ban'ethil Barrow Den, lest the sleeping Druids of the Talon be lost in the Dream" },
    [484] = { 1, "skinned young crocolisks for James Halloran, the tanner whose cured skins sail to ports around the world" },
    [485] = { 1, "brought a distress beacon to Oglethorpe Obnoticus's homing robot, crashed at the head of the river near Skulk Rock" },
    [486] = { 3, "slew Ursal the Mauler, the Gnarlpine chieftain who drove his tribe mad, so the Druids of the Talon could be woken" },
    [487] = { 2, "cleared Gnarlpine ambushers off the road to Darnassus, where travellers bringing news and trade had come under attack" },
    [488] = { 1, "fetched fangs, feathers and spider silk for Zenn Foulhoof, a satyr who laughed at the gullible for doing his bidding" },
    [489] = { 1, "slipped Zenn Foulhoof fel cones as a harmless-looking snack, the lesson the Council of the Forest demanded for having served the satyr" },
    [491] = { 1, "handed the Woven Wand, token of a friendship Thule had betrayed, to his old colleague Bethor Iceshard" },
    [492] = { 2, "served a captured dwarven mountaineer Johaan's special drink, a hint of what the Dark Lady had planned for the rest of Azeroth" },
    [493] = { 1, "carried Apothecary Renferrel's findings on the New Plague to Apothecary Lydon in Tarren Mill, to speed the work" },
    [494] = { 1, "ran Deathstalker Lesh's coded word to Tarren Mill, the signal that Hillsbrad was ripe for attack" },
    [496] = { 1, "gathered grey bear tongues and creeper ichor for Apothecary Lydon, who sought killing agents to plague the humans" },
    [498] = { 3, "freed Drull and Tog'thar from Durnholde Keep, two orc scouts the humans had caught spying on the Syndicate" },
    [499] = { 1, "gave Lydon's assistant Umpi a taste of the Elixir of Suffering, a trial of what the Dark Lady planned for humans and Scourge" },
    [500] = { 1, "hunted Crushridge ogres for their knucklebones, so they would not settle in the ruins of Alterac and move down on Southshore" },
    [501] = { 1, "collected mountain lion blood for Apothecary Lydon's death-brew, in the service of the New Plague" },
    [502] = { 1, "fed Farmer Ray's dog Stanley the Elixir of Pain, Apothecary Lydon's test of a brew he hoped would please Lady Sylvanas" },
    [503] = { 3, "freed Gol'dir, leader of the Warchief's expedition, from the Syndicate in the Alterac Mountains, who made him haul burdens and dig" },
    [504] = { 2, "cut down Crushridge Warmongers in the Ruins of Alterac, to teach the ogres to keep their distance from Southshore" },
    [505] = { 2, "slew Syndicate thieves and footpads near Tarren Mill, the gang believed behind the murder of Southshore's last magistrate" },
    [506] = { 2, "carried back Gol'dir's word that Aliden Perenolde meant to enslave orcs like Blackmoore, and his mistress wore the Warchief's pendant" },
    [507] = { 3, "killed Lord Aliden Perenolde, who would have made slaves of the orcs, and asked his mistress Elysa for Taretha's pendant" },
    [508] = { 3, "brought Taretha's pendant, given up by a frightened Elysa, back to Krusk, the small thing the Warchief had spent so much to recover" },
    [509] = { 1, "picked Mudsnout Blossoms at Nethander Stead for Apothecary Lydon's next elixir, to spread death and disease across the land" },
    [510] = { 2, "turned over the Syndicate's foreboding plans to Magistrate Maleb, an urgent supply list for a mission against Southshore" },
    [511] = { 1, "took an encrypted letter found among the Syndicate to Loremaster Dibbs in Southshore, in the hope he could read it" },
    [512] = { 2, "killed the Alterac nobles hiding in the Syndicate at Strahnbrad for their signet rings, to strip the gang of its leaders" },
    [513] = { 1, "rushed Lydon's Mudsnout Composite to Master Apothecary Faranell in the Undercity, to be treated with his colloid of decay" },
    [514] = { 1, "carried the cleverly encrypted letter to Prospector Stormpike in Ironforge, the one scholar likely to read it" },
    [515] = { 1, "gathered a troll's blood potion, daggerspine scales and torn fin eyes to activate the contagion in Lydon's mudsnout mixture" },
    [516] = { 2, "found Beren's Peril, where undead were massing for an attack, and struck them first for Shadow Priest Allister" },
    [517] = { 1, "stole a keg of Shindigger Stout from the dwarves of Dun Garok, so Lydon's plague would not be wasted on a mere frog or dog" },
    [518] = { 1, "thinned the Crushridge ogres who had overrun the ruins of Alterac, so Melisara could strike at their leader Mug'Thol" },
    [519] = { 2, "took the heads of Targ, Muckrake and Glommus, Mug'Thol's loyal lieutenants, for Melisara in Tarren Mill" },
    [520] = { 3, "killed Mug'Thol and took the Crown of Will from him, to end the Crushridge resistance to the Dark Lady" },
    [521] = { 2, "carried the Crown of Will, the relic Mug'Thol used to defy the Dark Lady, to Sharlindra in the Undercity" },
    [522] = { 2, "brought Magistrate Maleb the contract for his own assassination, sealed in red wax with a distinctive signet ring" },
    [523] = { 3, "hunted down Baron Vardus, the cold-hearted Alterac noble who signed the contract on Magistrate Maleb's life" },
    [525] = { 2, "brought Magistrate Maleb the decrypted letter, which showed the Syndicate had ties to another, darker power" },
    [526] = { 1, "took back from the murlocs the lightforge ingots they had carried off, since one alone would craft nothing decent" },
    [530] = { 3, "killed Valdred Moray at the Greymane Wall and brought his hands to Raleigh Andrean, whose wife he had strangled" },
    [531] = { 1, "presented Ol' Sooty's head to Vyrin Swiftwind, who had itched for months to get back at that stuck-up Daryl" },
    [533] = { 2, "searched the Syndicate camp north of Tarren Mill for any word of where the humans were holding Gol'dir, for Krusk" },
    [535] = { 1, "fetched a mug of Southshore Stout for Valik, a dying Syndicate man, in exchange for what he knew" },
    [536] = { 1, "fought the Torn Fin murlocs down the Western Strand in place of Lieutenant Farren Orinelle, who could barely rouse himself to obey Redpath" },
    [537] = { 3, "killed Nagaz and the Argus Shadow Mages in the Alterac Uplands, envoys of the Argus Wake allied with the Syndicate" },
    [539] = { 2, "killed Foreman Bonds and his miners at the Azureload Mine, so its iron would arm the Dark Lady's soldiers instead" },
    [540] = { 2, "rescued books from the ogres in the Ruins of Alterac for Loremaster Dibbs, the troll lore of The Arm of Gri'lek among them" },
    [541] = { 3, "laid siege to Dun Garok and killed Captain Ironhill, to show the dwarves what aiding the humans would cost them" },
    [542] = { 1, "returned the recovered tomes of Alterac to Milton Sheaf, saving their knowledge for the Royal Library of Stormwind" },
    [543] = { 2, "recovered the Perenolde Tiara, heirloom of Alterac's fallen rulers, from the ogre mage Grel'borg the Miser" },
    [544] = { 2, "hunted down the Forsaken traitors held at the Lordamere Internment Camp and recovered the artifacts they stole from the Dark Lady" },
    [545] = { 1, "thinned Dalaran's summoners and their elemental slaves, so Magus Voidglare could search the ruins outside the dome for treasures" },
    [546] = { 1, "collected human skulls for Deathguard Samsa, who envied the fighting in Hillsbrad from his post in Tarren Mill" },
    [547] = { 1, "got Deathguard Humbert's sword back from the dwarven scouts of Dun Garok, who stole his gear while he gathered firewood" },
    [549] = { 1, "cut down Syndicate rogues and watchmen at Durnholde Keep, all of them wanted dead by order of Lady Sylvanas" },
    [550] = { 2, "carried Darthalia's sealed commendation for the Battle of Hillsbrad to Varimathras, word of a decisive blow against the Alliance" },
    [551] = { 1, "took the ensorcelled parchment bearing the name Nagaz to Loremaster Dibbs, hoping he could break its spell" },
    [552] = { 1, "recovered Helcular's Rod from the yeti in his old ritual lair, for an apprentice bent on vengeance against Southshore" },
    [553] = { 3, "carried out the vengeance Helcular's apprentice wanted on Southshore, charging the rod at three flames and drove it into Helcular's grave" },
    [554] = { 1, "brought the ensorcelled parchment to Prospector Stormpike in Ironforge, a master of deciphering, to make sense of it" },
    [555] = { 1, "hunted snapjaw turtles near Lake Lordamere so Chef Jessen could serve Southshore's famous Soothing Turtle Bisque again" },
    [556] = { 1, "gathered worn stone tokens, the means Dalaran's wizards used to control elementals, for Magus Voidglare to study" },
    [557] = { 1, "took bracers of earth binding from Dalaran's elementals, the bonds that held them in a mage's service, for Magus Voidglare" },
    [558] = { 1, "got Lady Jaina Proudmoore's autograph in Theramore for a young ward who dreamed of being a hero of the Alliance" },
    [559] = { 1, "collected murloc heads on the Western Strand for Lieutenant Farren Orinelle, proof for Redpath that the murlocs were dealt with" },
    [560] = { 1, "carried the dripping sack of murloc heads to Marshall Redpath for Farren Orinelle, who could not stand to touch them" },
    [562] = { 1, "put down the Daggerspine naga for Lieutenant Farren Orinelle, who hoped the deed would win him a transfer back to Stormwind" },
    [563] = { 1, "carried Farren Orinelle's report on the naga to Major Samuelson in Stormwind Keep, his hope of being reassigned to the city" },
    [564] = { 2, "culled the mountain lions that came down from Alterac to prey on Darren Malvew's horses" },
    [565] = { 1, "gathered wool, fine thread, yeti fur and a Hillman's Cloak so the great Bartolo Ginsetti could sew his famous Yeti Fur Cloak" },
    [566] = { 3, "killed Baron Vardus, a Syndicate leader wanted for crimes against the Forsaken, and brought his head to Darthalia" },
    [567] = { 2, "hunted the four Hillsbrad humans wanted for murdering Forsaken and ambushed supplies from the Undercity" },
    [568] = { 1, "culled the Lashtail Raptors outside Grom'gol, which threatened the Horde's supply line to Stonard" },
    [569] = { 2, "struck at the ogres of the Mizjah Ruins, who kept ambushing the caravans meant to supply Stonard" },
    [570] = { 1, "collected Shadowmaw claws and a flawless tigress fang, the first reagents of an enchantment Far Seer Mok'thardin meant to make" },
    [571] = { 1, "hunted Elder Mistvale Gorillas for a perfect aged sinew, the magical tether to hold Mok'thardin's charm together" },
    [572] = { 1, "plucked Jungle Stalker feathers from the raptors south of Grom'gol for Far Seer Mok'thardin's enchantment" },
    [573] = { 2, "fetched Holy Spring Water past the naga explorers who had advanced on the spring, the last reagent of Mok'thardin's choker" },
    [574] = { 2, "broke Kurzen's Commandoes and Headshrinkers in the Stockpile, his best troops, and gave the rebels hope of surviving" },
    [575] = { 1, "skinned river crocolisks for Drizzlik, the Booty Bay leathercrafter, who had a dozen Excelsior boots to make" },
    [576] = { 2, "got Dizzy One-Eye's enchanted glass eye back from the Bloodsail Buccaneers who had jumped him, so the old sea dog could see" },
    [577] = { 1, "took cheaper Snapjaw Crocolisk skins at Lake Nazferiti to fill out the inner layers of Drizzlik's boots" },
    [578] = { 2, "found the haunted island off the coast for Baron Revilgaz, who hoped the Stone of the Tides might soon be his" },
    [580] = { 1, "fished Whiskey Slim's lost bottles of Pupellyverbos Port out of the sea, before his captain gave him a taste of the cat" },
    [581] = { 2, "hunted Bloodscalps for their tusks, to prove fit to help Nimboya search for Yenniku, his chief's lost son" },
    [582] = { 2, "took shrunken heads from Bloodscalp Headhunters so Nimboya could make sure Yenniku's was not among them" },
    [584] = { 3, "killed the Bloodscalp chief Gan'zulah and Nezzliok the Dire, their heads for Nimboya's cauldron to force the truth of Yenniku" },
    [585] = { 2, "stole Skullsplitter trophy skulls from three ruins to appease the spirit of Nezzliok, who knew where Yenniku had been taken" },
    [586] = { 3, "cut into the heart of the Skullsplitters to defeat their chief, Ana'thek the Cruel, as Gan'zulah's raging spirit demanded" },
    [587] = { 1, "won back the snuff the Bloodsail Raiders had hijacked, for Deeg, a pirate who could find none in Booty Bay" },
    [588] = { 1, "brought word to Kin'weelay that Zanzil the Outcast held Yenniku body and soul, leaving only the faintest hope" },
    [589] = { 2, "gathered Pulsing Blue Shards from Ironjaw Basilisks in the Crystalvein Mine, magic Kin'weelay needed to bend the Mind's Eye" },
    [590] = { 1, "beat Calvin Montague when he denied owing the coin he had promised for carrying his letter to Brill" },
    [591] = { 3, "wrested the Mind's Eye from the ogre mage Mai'Zoth in the Mosh'Ogg mound, the only hope of saving Yenniku" },
    [592] = { 3, "trapped Yenniku's soul in a gem at the Ruins of Aboraz and carried it to Nimboya, freeing him from Zanzil the Outcast" },
    [594] = { 2, "searched for the writer of a message in a bottle, a captive held by a great Skymane on an island in the South Seas" },
    [595] = { 1, "scouted the cove north of Booty Bay for First Mate Crazz, after word of Bloodsail Buccaneers all over southern Stranglethorn" },
    [596] = { 1, "took bloody bone necklaces from Bloodscalp trolls for Kin'weelay, whose rites would weaken the Darkspears' enemies" },
    [597] = { 1, "brought First Mate Crazz a Bloodsail map, proof their men were camped by Booty Bay waiting for a signal to attack" },
    [598] = { 1, "hunted Skullsplitters for their split bone necklaces, carrying on the Darkspears' old war with the tribe for Kin'weelay" },
    [599] = { 1, "warned Fleet Master Seahorn of the attack the Bloodsail Buccaneers were planning on Booty Bay" },
    [600] = { 1, "seized Singing Blue Crystals from the Venture Company miners near the Crystalvein Mine for Crank Fizzlebub" },
    [601] = { 1, "took bracers from the water elementals of the haunted island, so a Dalaran mage could study the curse of the Stone of the Tides" },
    [602] = { 1, "carried the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran, who knew the legends of the Stone of the Tides" },
    [604] = { 2, "raided the Bloodsail command post on the Wild Shore for their charts and orders, to learn their plan against Booty Bay" },
    [605] = { 1, "harvested Singing Crystal shards from basilisk hides for Crank Fizzlebub, kept from the crystals by the Venture Company" },
    [606] = { 1, "frightened Shaky Phillipe with gorilla giblets into paying the gambling debt he owed Sea Wolf MacKinley" },
    [607] = { 1, "collected Shaky Phillipe's overdue payment for Sea Wolf MacKinley, along with his promise he had meant to pay" },
    [608] = { 3, "killed Captain Stillwater, Captain Keelhaul and Fleet Master Firallon to break the Bloodsail attack on Booty Bay" },
    [609] = { 1, "collected from three cursed gamblers in the jungle ruins a foot, a spyglass and a ring they owed Sea Wolf MacKinley" },
    [610] = { 2, "took Catelyn's dagger back from Pretty Boy Duncan of the Bloodsail, the blade needed to break the altar of the Stone" },
    [611] = { 3, "broke the Altar of the Tides with Catelyn's Blade and killed Gazban, to bring the Stone of the Tides to Baron Revilgaz" },
    [613] = { 1, "searched the Mosh'Ogg ogres for Maury's key, to open the locked foot that held what he owed Sea Wolf MacKinley" },
    [614] = { 2, "recovered Captain Smotts' chest from Gorlash, one of the sea giants who had smashed his ship and killed his crew" },
    [617] = { 1, "gathered akiris reed from the naga along the beach for Privateer Bloads, whose friend Groy paid well for it" },
    [618] = { 3, "lured the giant Negolash with buzzard wings and wine, then killed him to win back Captain Smotts' cutlass" },
    [621] = { 1, "took samples of Zanzil's mind-bending mixture from his followers for Crank Fizzlebub, who meant to find a use for it" },
    [622] = { 1, "brought the mended Crock Pot back to Corporal Kaleb, so the rebel camp could get its dinner started" },
    [623] = { 1, "shipped a bundle of akiris reed to Privateer Groy in Theramore, for a client who wanted more right away" },
    [624] = { 1, "followed Cortello's riddle to a clue hidden under a bridge in the Swamp of Sorrows" },
    [625] = { 1, "chased the riddle's next clue to a cave in the southwest of Dustwallow Marsh" },
    [626] = { 2, "solved the last of Cortello's riddles under the great falls of the Hinterlands, where a treasure chest waited" },
    [627] = { 1, "mined bloodstone ore in Drywhisker Gorge for Krazek, the favour he asked while he mended the Crock Pot" },
    [628] = { 1, "drew out an elder saltwater crocolisk for its prized skin, the outer layer of Drizzlik's Excelsior boots" },
    [629] = { 1, "braved the murlocs of the Vile Reef for a shard of the tablet of Gri'lek, for the Darkspears to enshrine in Orgrimmar" },
    [630] = { 3, "slew King Mukla, the great Skymane, to free Princess Poobah from the chain that held her on his island" },
    [631] = { 2, "searched for Ol' Rustlocke, the scout Longbraid sent days before to see if the eastern bridge of the Thandol Span could be held" },
    [632] = { 1, "brought Rhag Garmason the grim news of Ol' Rustlocke's death and the parchment found by his clenched fist" },
    [633] = { 3, "destroyed Kam Deepfury's cache of explosives across the Thandol Span before it could sever the last bridge to the north" },
    [634] = { 1, "carried the plea of Dun Modr's survivors to Captain Nials at Refuge Pointe, for soldiers to help retake the Thandol Span" },
    [635] = { 1, "followed a vision from a pulsing shard to a crystal in the northern mountains of Arathi, where someone seemed to plead for help" },
    [636] = { 1, "sought the Shards of Myzrael, which an old book called a window into the prison of an elemental princess beneath Arathi" },
    [637] = { 1, "carried Sully Balloo's waterlogged letter to his wife Sara in Ironforge, with word that he lay pinned beneath the icy waters" },
    [639] = { 2, "took the Sigil of Strom from the Syndicate for Zengu, the first of the seals on the tomb of Trollbane and his troll-slaying sword" },
    [640] = { 2, "pried the five fragments of the Sigil of Thoradin from the Stromgarde defenders so Tor'gan could bind them whole again" },
    [641] = { 1, "brought the restored Sigil of Thoradin back to Zengu, halfway to opening Trollbane's tomb" },
    [642] = { 2, "gathered Motes of Myzrael from the Drywhisker Kobolds to power a shard for Myzrael, a princess of the earth trapped by giants" },
    [643] = { 2, "took the Sigil of Arathor from Lieutenant Valorcall, leader of the Stromgarde cavalry, for Zengu" },
    [644] = { 3, "killed Prince Galen Trollbane in his Stromgarde chapel for the last sigil sealing his father's tomb" },
    [645] = { 3, "broke the wards on Trollbane's tomb in Stromgarde to take Trol'kalar, the troll-slaying sword the Darkspear wanted" },
    [646] = { 2, "delivered Trol'kalar to Zengu in Hammerfall, the greatest weapon of Strom and Arathor turned to the Darkspear's fight in Zul'Gurub" },
    [647] = { 1, "rushed a batch of MacKreel's Moonshine to Brewmeister Bilger in Southshore to repay Foggy MacKreel's debt before it fell overdue" },
    [648] = { 2, "escorted the battered OOX-17/TN to Steamwheedle Port so Oglethorpe Obnoticus could get his homing robot back in the air" },
    [651] = { 2, "won keys from the guarded Stones of Binding across Arathi to loosen the bonds holding Myzrael beneath the earth" },
    [652] = { 3, "killed the stone watcher Fozruk for the Rod of Order and opened the Keystone that held Myzrael chained" },
    [654] = { 1, "raced a two-hour power source to test the tissue of the basilisks, hyenas and scorpids of Tanaris with a field kit" },
    [656] = { 3, "summoned Myzrael and defeated her before she grew strong enough to challenge the giants, then bound her again in her own shackles" },
    [658] = { 2, "tracked down a Forsaken courier near the Go'Shek Farm for her sealed folder, which might shed light on what was happening in Hillsbrad" },
    [659] = { 1, "looked for Quae and Kinelory, Phin Odelic's friends gone quiet at the Go'Shek Farm while seeking proof the undead were at work" },
    [660] = { 2, "protected Kinelory as she stole Apothecary Jorell's research from the farm before it could reach Tarren Mill" },
    [661] = { 1, "brought Phin Odelic word that Quae and Kinelory were alive, and the research Kinelory took from the Go'Shek Farm" },
    [662] = { 1, "dived to the sunken Maiden's Folly and Spirit of Silverpine for their charts and logs, so no prying eyes would find them" },
    [664] = { 2, "slaughtered the Daggerspine naga who killed the survivors of the Maiden's Folly, some solace for Captain Steelgut" },
    [665] = { 2, "guarded Professor Phizzlethorpe at the cursed cave while he charged the goggles meant to find the lost elven treasure" },
    [666] = { 1, "searched the sea floor with the Goggles of Gem Hunting for Elven Gems of the lost treasure, calcified into stone" },
    [667] = { 3, "manned the cannon to defend Shakes O'Breen from the Daggerspine attack, since his crew could not reach Booty Bay without him" },
    [668] = { 1, "handed the recovered Elven Gems to Captain O'Breen, the treasure his ships had come to Faldir's Cove for" },
    [669] = { 1, "carried a sample Elven Gem to Fleet Master Seahorn in Booty Bay, proof O'Breen's stranded crew had found the treasure" },
    [670] = { 1, "carried Fleet Master Seahorn's secret letter back to Shakes O'Breen, tied up off the Arathi coast" },
    [671] = { 2, "gathered Bloodstone Amulets for Tor'gan, who had found traces of demonic summoning at Northfold Manor" },
    [672] = { 1, "collected raptor eyes so Tor'gan could craft an amulet to lift the despair of Gor'mul, broken since Doomhammer's death" },
    [673] = { 3, "killed the warlock Marez Cowl in Stromgarde for the Bloodstone Orb that summoned demons there, so Tor'gan could destroy it" },
    [674] = { 1, "gave Gor'mul the Raptor Talon Amulet from Tor'gan, hoping the raptors' strength would rekindle the warrior in him" },
    [676] = { 1, "proved strength against the Boulderfist ogres before going to the aid of Hammerfall, under attack and close to falling" },
    [677] = { 2, "slew Witherbark trolls in their camps for Drum Fel, to show trolls and ogres alike that the Horde had a home in Arathi too" },
    [678] = { 2, "fought the Boulderfist brutes and magi in their lair near the dwarven bridge, the harder test Drum Fel set" },
    [679] = { 3, "struck down the Boulderfist lords and their shaman in the ruins of Stromgarde, the leaders of the attacks on Hammerfall" },
    [680] = { 3, "killed Or'Kalar for Korin Fel, who kept the ogre's trap hidden from her husband so he would not rush off foolishly into it" },
    [682] = { 2, "took back the badges of fallen Stromgarde militiamen from the Syndicate, who paid bounties for them, so their families could be told" },
    [683] = { 1, "laid the grieving Sara Balloo's plea before King Magni Bronzebeard, since she could not face him in her grief" },
    [684] = { 3, "hunted Marez Cowl, a demon-trafficking Syndicate warlock in Stromgarde, for the bounty at Refuge Pointe" },
    [685] = { 3, "brought down Lord Falconcrest, head of the Syndicate in Arathi, and Otto, the bodyguard who had killed dozens of defenders" },
    [687] = { 2, "searched the Badlands for Theldurin the Lost, a mad deserter of the Twilight's Hammer who had stolen the scroll of Myzrael" },
    [689] = { 2, "fetched Alterac Granite from Darrow Hill for the memorial King Magni commissioned to Sully Balloo, lost in the Thandol Span tragedy" },
    [691] = { 1, "gathered Witherbark tusks, medicine pouches and a shadow hunter knife as reagents for Archmage Malin's apprentice Kryten" },
    [692] = { 2, "gathered the torn fragments of the Scroll of Myzrael from the elementals fighting over them, perhaps the only chance against Myzrael" },
    [693] = { 2, "wrested Trelane's Wand of Invocation from Kor'gresh in Boulderfist Hall before the ogre mastered its icy power" },
    [694] = { 1, "took an Azure Agate from the Boulderfist shaman so Kryten could enchant it into a key to the Tower of Arathor's defenses" },
    [696] = { 2, "raided the ogre-held Tower of Arathor for Trelane's phylactery, orb and ember agate" },
    [698] = { 1, "hunted grown sawtooth crocolisks for flanks to feed Tok'Kar's soldiers at the beach outpost, who had no time to hunt" },
    [699] = { 1, "supplied Tok'Kar sawtooth snapper claws to make weapons for the outpost watching the coast for murlocs" },
    [701] = { 1, "cut raptor hearts from Highland Fleshstalkers so Tor'gan could imbue Gor'mul with the guile of the raptor" },
    [702] = { 2, "brought Gor'mul the orb Tor'gan had filled with raptor spirit, another try at waking the warrior dormant in him" },
    [703] = { 1, "fetched buzzard wings for Rigglefuzz's barbecue, a favorite whose recipe he promised to share" },
    [704] = { 2, "recovered the stone urns found by dead Agmond's diggers at Uldaman, which Prospector Ironband feared had stirred the troggs" },
    [705] = { 1, "dived for blue pearls at the Vile Reef in Stranglethorn, the powder Rigglefuzz needed for flash bombs to scare off the Badlands' scavengers" },
    [706] = { 1, "cut a still-beating heart from a black drake whelp in Lethlor Ravine, so Sigrun Ironhew could show his fiery weapon enchantment" },
    [708] = { 1, "carried a corroded black box from a giant condor's stomach to the Hall of Arms in Ironforge, stamped Engine #19 - Ironforge Siege Brigade" },
    [709] = { 2, "found the Tablet of Ryun'eh in an ancient chest deep in Uldaman for Theldurin the Lost, who feared a doom he dared not name" },
    [710] = { 1, "collected small stone shards from the lesser rock elementals, for Lotwil Veriatus to test his shackles of elemental binding" },
    [711] = { 1, "pried large stone slabs off the rock elementals for Lotwil Veriatus's tests, a load he thought would take half a dozen tauren" },
    [712] = { 1, "stripped the bracers of rock binding from the greater rock elementals, to gauge the strength of Lotwil Veriatus's own shackles" },
    [713] = { 1, "learned to make frost oil from Bro'kin in Alterac, so Lotwil's shackles could keep his summoned elemental from killing everyone" },
    [714] = { 1, "found a gyrochronatom, the small but crucial part Lotwil Veriatus needed to finish his shackles" },
    [715] = { 1, "brought healing and invisibility potions to Lucien Tosselwrench, who expected to need them if Lotwil's experiment worked" },
    [716] = { 1, "supplied patterned bronze bracers so Lucien Tosselwrench could enchant them with the spare stones, thanks Lotwil was too cheap to give" },
    [717] = { 3, "broke the Seal of the Earth to free and slay Blacklash and Hematus, Deathwing's lieutenants, for Garek of the Kirin Tor" },
    [718] = { 1, "recovered the supply crate the ogres of Camp Kosh took, without which Sigrun Ironhew's party could not get food" },
    [719] = { 1, "retrieved Prospector Ryedol's lucky pick from the Shadowforge Dark Irons who had attacked his dig site" },
    [720] = { 2, "told Prospector Ryedol that Hammertoe Grez was alive and taken to Uldaman, as his chalk scrawl on a map said" },
    [721] = { 2, "sought Hammertoe Grez in Uldaman, held by the Shadowforge for what he knew of the titan excavations" },
    [722] = { 2, "took Hammertoe Grez's amulet back from Magregan Deepshadow, before it led the Dark Irons to scrolls for stronger golems" },
    [723] = { 2, "carried the wounded Hammertoe's amulet, his life's work, to Prospector Ryedol, with his plea to stop the Shadowforge clan" },
    [724] = { 1, "took Hammertoe's amulet on to Historian Karnik in Ironforge, who had sought Uldaman's lost artifacts with him" },
    [725] = { 1, "ran Historian Karnik's note to Advisor Belgrum, warning of the Shadowforge's activities in the Badlands" },
    [727] = { 1, "showed the Sigil of the Hammer to Gerrig Bonegrip, posing as one of his order, to obtain Yagyin's Digest for Theldurin" },
    [728] = { 1, "passed as one of Keeper Bel'dugur's order with the Sigil of the Hammer, to obtain Yagyin's Digest for Theldurin" },
    [729] = { 1, "went south to see whether Prospector Remtravel was all right, his dig overrun by golems he never seemed to notice" },
    [730] = { 1, "looked in Darkshore for signs of the dwarven excavation team, unheard from in weeks" },
    [731] = { 2, "guarded the absent-minded Prospector Remtravel among the creatures of his dig while he hunted for his fossil" },
    [732] = { 2, "wrested the Sign of the Earth from the ogres near Camp Boff for Garek, sent by Krasus of the Kirin Tor to end the trouble in Lethlor Ravine" },
    [733] = { 1, "scrounged scrap metal from the ogres of Dustbelch Grotto, so Sigrun could build defenses for the worried prospector's camp" },
    [735] = { 1, "gathered three items of power, named only in writing, for Gerrig Bonegrip, his price for a copy of Yagyin's Digest" },
    [736] = { 1, "gathered three relics of power for Keeper Bel'dugur, the price of Yagyin's Digest and of opening a chapter of the order" },
    [737] = { 2, "brought Yagyin's Digest to Theldurin the Lost, who hoped its knowledge would protect all from what might rise to the surface" },
    [738] = { 2, "searched the southernmost dig site past Angor Fortress for Prospector Agmond, unheard from in weeks, and found only his bones" },
    [739] = { 3, "avenged Prospector Agmond on Murdaloc, the trogg whose name he scrawled in the sand as he died, and on the Stonevault Bonesnappers" },
    [741] = { 1, "carried Remtravel's mysterious fossil to Chief Archaeologist Greywhisker in Darnassus, as promised to the League" },
    [743] = { 1, "tested strength against the Windfury harpies, one of Mulgore's natural enemies, before travelling on, as Ruul Eagletalon advised" },
    [744] = { 1, "gathered azure and bronze harpy feathers for the headdress Eyahn Eagletalon was making for a brother soon to stand before Chief Bloodhoof" },
    [745] = { 2, "drove the Palemane gnolls out of Mulgore for Baine Bloodhoof, since they killed its game without restraint and would not parley" },
    [746] = { 1, "smashed the dwarves' digging picks for Baine Bloodhoof, to teach them that hollowing the land is no path to knowledge" },
    [747] = { 1, "hunted plainstriders for the meat and feathers Camp Narache had run short of, to prove worthy in Chief Hawkwind's eyes" },
    [748] = { 1, "hunted prairie wolves and plainstriders for a totem to cleanse the Winterhoof Water Well, tainted by goblins" },
    [749] = { 1, "examined the burned Venture Co. caravan by Stonebull Lake for Morin Cloudstalker, after salvagers were seen at the wreck" },
    [750] = { 1, "skinned mountain cougars in the hills for Camp Narache, whose children needed clothing and whose tents needed mending" },
    [751] = { 2, "brought Morin Cloudstalker the Venture Co. papers from the caravan, proof the goblins were robbing Mulgore of its ore" },
    [752] = { 1, "looked in on Chief Hawkwind's mother, gone a long while fetching water from the well" },
    [753] = { 1, "carried a water pitcher back from the well for the Greatmother, whose old legs lacked their vigor" },
    [754] = { 2, "carried the cleansing totem past the goblins to the Winterhoof Water Well, so its waters could be used again" },
    [756] = { 1, "took claws from prairie stalkers and flatland cougars, whose purity in the hunt Mull Thunderhorn needed for the next cleansing totem" },
    [757] = { 3, "passed the Rite of Strength, first of the Rites of the Earthmother, against the Bristlebacks who raided Camp Narache" },
    [758] = { 2, "performed the cleansing ritual at the Thunderhorn Water Well, a deed its clan's ancestors praised in Mull Thunderhorn's dream" },
    [759] = { 1, "hunted prairie wolf alphas for their teeth, the land's offering for the totem to cleanse the last well" },
    [760] = { 3, "cleansed the Wildmane Water Well, the last of the wells the goblins poisoned, so clean water would flow in Mulgore again" },
    [761] = { 1, "stalked the elusive swoop for its quills, a badge of cleverness and determination for Harken Windtotem" },
    [762] = { 3, "killed Ambassador Infernus in Angor Fortress, sent by Ragnaros to oversee the Shadowforge's hunt for Uldaman's artifacts" },
    [764] = { 2, "sent the Venture Co. a message at their Mulgore mine, so the goblins would not plunder the tauren's land unopposed" },
    [765] = { 3, "took Supervisor Fizsprocket's clipboard, the plans by which the Venture Co. meant to drive the tauren from their land" },
    [766] = { 2, "gathered a wolf heart, cougar femur, plainstrider scale and swoop gizzard to cure the infected bite Mazzranache gave Maur Raincaller" },
    [768] = { 1, "traded light leather from the hunt to Veren Tallstrider, who fashions clothes and armour for the people of Thunder Bluff" },
    [769] = { 1, "supplied Veren Tallstrider with leather and thread to learn the making of a Kodo Hide Bag" },
    [770] = { 2, "showed Ghost Howl's demon-scarred hide in Bloodhoof Village, where an old hunter could hardly believe the great wolf had fallen" },
    [771] = { 1, "gathered well stones and ambercorn for Zarlman Two-Moons to brew the Water of the Seers, a step of the Rite of Vision" },
    [772] = { 2, "drank the Water of the Seers before the tribal fire and followed the vision, to pass the Rite of Vision" },
    [773] = { 2, "sought the Ancestral Spirit at Red Rocks for the blessing of the Rite of Wisdom, and with it the duty of protecting Thunder Bluff" },
    [776] = { 3, "tracked the mighty kodo Arra'chea for its horn, to prove a hunter's skill to Cairne Bloodhoof after the Rites of the Earthmother" },
    [777] = { 1, "fetched cog #5 for Lotwil Veriatus from Lucien Tosselwrench, who handed it over and took cover" },
    [778] = { 3, "defeated the Fam'retor Guardian, the elemental Lotwil Veriatus summoned to test his shackles, when his experiment went wrong" },
    [780] = { 1, "killed the Battleboars the Bristlebacks had trained to be malicious, for snouts and flanks to stew for the young of the camp" },
    [781] = { 2, "brought Chief Hawkwind the Bristleback warchief's plans for a siege of Camp Narache, in time to call Bloodhoof Village to help" },
    [782] = { 2, "killed Boss Tho'grun, the ogre mercenary who betrayed Kargath, to take back the Sign of the Earth for Gorn" },
    [784] = { 3, "drove Lieutenant Benedict and his Kul Tiras men out of Tiragarde Keep, which they had retaken in defiance of the Warchief's pact" },
    [786] = { 2, "destroyed the Kolkar centaurs' attack plans, held by three leaders in Kolkar Crag, before they could strike Durotar" },
    [788] = { 1, "killed mottled boars to put some strength in a new recruit's backbone, Gornek's first trial" },
    [789] = { 1, "took scorpid worker tails to Gornek as proof of prowess, and learned that the smallest foe can still be deadly" },
    [790] = { 2, "slew Sarkoth, the vicious scorpid that left Hana'zua bleeding on the plateau, to uphold the wounded orc's honour" },
    [791] = { 1, "brought canvas to Furl Scornbrow, too old for battle, who now made bags for younger warriors from his watchtower" },
    [792] = { 1, "drove back the Vile Familiars spilling from the Burning Blade coven, the first blow against the cult in the valley" },
    [793] = { 3, "freed the black drakes Blacklash and Hematus from the Seal of the Earth only to slay them, silencing the Horde's depraved allies of old" },
    [794] = { 2, "wrested the Burning Blade Medallion from deep in the cult's coven, to root it out of the Valley of Trials" },
    [804] = { 1, "brought Gornek word that Hana'zua lay wounded on the plateau, so help could be sent" },
    [805] = { 1, "warned Master Gadrin in Sen'jin Village that the Burning Blade had reached the Valley of Trials" },
    [806] = { 3, "defeated Fizzle Darkstorm, goblin warlock of the Burning Blade in Thunder Ridge, to deny the cult a foothold in Durotar" },
    [808] = { 3, "took Minshina's skull from Zalazane's circle of power, freeing the trapped spirit of Master Gadrin's brother" },
    [812] = { 3, "hurried to Kor'ghan in Orgrimmar for the antidote that saved Rhinag, stung by a venomtail with an hour left to live" },
    [813] = { 2, "gathered venomtail poison sacs so Kor'ghan could make an antidote for the stung Rhinag" },
    [815] = { 1, "stole taillasher eggs on the Echo Isles for Cook Torka's next breakfast" },
    [816] = { 2, "searched the crocolisks of the Southfury for a sign of Kron's fate, so his mother Misha Tor'kren could at last mourn" },
    [817] = { 1, "hunted Durotar tigers on the southern islands for furs, so Vel'rin Fang could keep the people from going cold" },
    [818] = { 1, "gathered makrura eyes and crawler mucus for Master Vornal, a half-blind alchemist who never found anyone worthy to teach" },
    [819] = { 1, "carried an empty keg to someone who knew its maker, Chen Stormstout, who once travelled with Rexxar" },
    [821] = { 1, "gathered tusks, kidneys and a thunder lizard horn so Brewmaster Drohn could brew Chen's stormstout once more" },
    [822] = { 1, "collected lightning glands, a saliva gland and a kodo liver for Brewmaster Drohn's trogg ale, another of Chen's recipes" },
    [824] = { 1, "took a befouled water globe to Je'neu Sancrea of the Earthen Ring, who feared it fed a corruption of the elements" },
    [825] = { 1, "swam through the wreckage of Proudmoore's fleet for gnomish tools, so the Horde could learn the Alliance's mechanics" },
    [826] = { 3, "defeated Zalazane and his hexed trolls on the Echo Isles, so the Darkspear tribe could sleep in peace again" },
    [827] = { 2, "took Searing Collars from the Burning Blade in Skull Rock, so Margoz could learn how the cultists drew on demonic power" },
    [829] = { 1, "showed a searing collar to Neeru Fireblade, a warlock who claims to hunt demons, its origin being beyond Margoz's skill" },
    [830] = { 1, "brought a found copy of Admiral Proudmoore's orders to Gar'Thok, commander of Razor Hill" },
    [831] = { 1, "rushed Admiral Proudmoore's orders to Nazgrel in Thrall's chamber, proof the humans' plans outlived the admiral" },
    [832] = { 1, "handed Neeru Fireblade the Eye of Burning Shadow, a cultist's pendant whose voice had spoken his name" },
    [833] = { 2, "drove the Bristleback Interlopers from Red Rocks, the sacred burial ground of the tauren, for Lorekeeper Raintotem" },
    [834] = { 1, "took back the supplies Dustwind harpies snatched from Rezlak's caravan into Razorwind Canyon" },
    [835] = { 2, "cleared the harpies of Drygulch Ravine so Rezlak's supply caravans could pass safely" },
    [836] = { 2, "guarded the robot OOX-09/HL to the shore beyond Overlook Cliff, where it could begin its long take-off home" },
    [837] = { 2, "drove the Razormane quilboars from their camps west of Razor Hill, to secure the borders of the orcs' new homeland" },
    [843] = { 2, "drove the dwarves from Bael Modan, whose blasts tore up Gann Stonespire's tribal lands, and took Khazgorm's journal" },
    [844] = { 1, "put down the plainstriders that raided the Crossroads' food supplies, Sergra Darkthorn's first and easiest prey" },
    [845] = { 1, "hunted zhevra for their hooves, a shade tougher than plainstriders, as Sergra Darkthorn's next lesson" },
    [846] = { 2, "looted nitroglycerin, wood pulp and sodium nitrate so Gann Stonespire could give the dwarves a taste of their own medicine" },
    [848] = { 1, "picked fungal spores by the oases for Apothecary Helbrim, whose fellow Forsaken prized their strange properties" },
    [849] = { 3, "blew up the flying machine at Bael Modan, a dwarven weapon of war and an insult to Gann Stonespire's lost tribe" },
    [850] = { 3, "hunted down Barak Kodobane, one of the new leaders rallying the Kolkar centaurs, for Regthar Deathgate" },
    [851] = { 3, "stirred up the centaurs at the Stagnant Oasis until Verog the Dervish came, the next of the Kolkar leaders after Barak Kodobane" },
    [852] = { 3, "killed Hezrul Bloodmark, leader of the Kolkar, to fracture the centaurs and blunt their threat to the Horde" },
    [853] = { 1, "rushed Apothecary Helbrim's rendered spores to Apothecary Zamah in Thunder Bluff before the emulsion lost its potency" },
    [855] = { 1, "stripped bracers from Kolkar warriors for Regthar Deathgate's bounty, to thin the centaur troops" },
    [857] = { 2, "stole the Tear of the Moons from General Twinbraid's keep for Feegly the Exiled, who raved that its power was his" },
    [858] = { 1, "fetched the ignition key for Wizzlecrank, a goblin stuck inside a Venture Company shredder he meant to steal" },
    [861] = { 1, "brought flatland prowler claws to Melor Stonehoof on the Hunter's Rise, proof of the skill to walk the hunter's path" },
    [862] = { 1, "caught dig rats at Bael Modan for Grub's stew, since to him no adventurer was seasoned without some rat killing" },
    [863] = { 2, "guarded Wizzlecrank as he drove a stolen Venture Company shredder out of the Sludge Fen toward Sputtervalve in Ratchet" },
    [864] = { 1, "brought the sealed field testing kit back to Apothecary Zinge, its data preserved for her study of Keever's research" },
    [865] = { 1, "pried horns from sunscale scytheclaws for Mebok Mizzyrix, who meant to grind them into smart drinks and get rich" },
    [866] = { 1, "gathered root samples from the herbs of the Barrens for Mebok Mizzyrix, who hoped the oasis water had given them valuable properties" },
    [867] = { 1, "cut talons from the Witchwing harpies that had ravaged the Horde's caravans, a first blow for Darsok Swiftdagger" },
    [868] = { 2, "dug silithid eggs from their mounds in the Field of Giants so Korran could study the strange insects for Orgrimmar" },
    [869] = { 1, "hunted the raptors that had somehow stolen the Crossroads guards' silver, so they would never steal again" },
    [870] = { 2, "searched the Forgotten Pools for the power seeping up beneath the Barrens, and found a fissure for Tonga Runetotem" },
    [871] = { 2, "thinned the Razormane quilboars that had been attacking the supply lines from Durotar, for Thork at the Crossroads" },
    [872] = { 3, "killed Kreenig Snarlsnout, the Razormane behind the raids on the Durotar caravans, and brought his tusk to Thork" },
    [873] = { 3, "swam out to slay Isha Awak, the Deep Doom of the coast, the worthy prey Mahren Skyseer had set me" },
    [875] = { 2, "picked off the Witchwing Slayers, the harpy lieutenants of the Dry Hills, in a decisive strike at their matriarchy" },
    [876] = { 3, "slew Serena Bloodfeather, whose harpies raided Horde caravans to avenge the sister Rexxar had killed" },
    [877] = { 2, "planted dead seeds in a fissure at the Stagnant Oasis for Tonga Runetotem, and watched them spring to life" },
    [878] = { 1, "struck down the spiritual leaders of the Bristleback quilboars so the caged Mangletooth's Razormane could defeat them" },
    [879] = { 3, "killed Nak, Kuz and Lok Orcbane, the Razormane who raided the Horde and left Mangletooth to rot in a cage" },
    [880] = { 1, "gathered snapjaw shells so Tonga Runetotem could learn how the fissures changed the beasts that drank there" },
    [881] = { 2, "called Echeyakee, white mist king of the savannah cats, from his lair with a horn and took his hide to Sergra Darkthorn" },
    [882] = { 2, "baited Ishamuhale, the fiercest sunscale raptor, with a zhevra carcass and took his fang to Jorn Skyseer" },
    [883] = { 2, "brought the hoof of Lakota'mani, the great kodo the tauren call Earthshaker, to Jorn at Camp Taurajo" },
    [884] = { 2, "presented the sparking tailspike of Owatanka, the thunder lizard the tauren call Bluebolt, to Jorn at Camp Taurajo" },
    [885] = { 2, "hunted Washte Pawne, the rare thunderhawk called Spirit Biter, and brought its stinging feather to Jorn Skyseer" },
    [887] = { 2, "cleared the Southsea Freebooters' camp south of Ratchet, pirates who kept raiding Gazlowe's ships" },
    [888] = { 1, "searched the pirate camp for Gazlowe's shipment of boots and the telescopic lens his new observatory still lacked" },
    [890] = { 1, "carried Gazlowe's ledger to Wharfmaster Dizzywig, to check whether his missing shipment had ever arrived" },
    [891] = { 3, "laid siege to Northwatch Hold, whose guns kept sinking Captain Brightsun's ships, and slew Captain Fairmount" },
    [893] = { 1, "seized a dagger, a wand and a shield from the Razormane so Tatternack Steelforge could study their sturdier weapons" },
    [894] = { 1, "reached the control console of a Venture Company research site, to work out how to free the mysterious samophlange" },
    [895] = { 3, "hunted down Baron Longshore of Gilneas, captain of the Heedless and wanted by Gazlowe for piracy" },
    [896] = { 1, "lifted a fist-sized emerald from the Venture Co. at Boulder Lode for Wharfmaster Dizzywig, who promised half its sale" },
    [897] = { 2, "showed Jorn Skyseer the head of the Harvester, an insect-like thing that did not belong in the Barrens" },
    [898] = { 3, "escorted Gilthares Firebough, sole survivor of a ship Theramore had sunk, out of Northwatch Hold to Ratchet" },
    [899] = { 1, "collected Bristleback tusks for Mankrik, whose thirst for revenge on the pig men was far from quenched" },
    [900] = { 1, "shut three valves on the Venture Company console so the samophlange's apparatus could be switched off" },
    [901] = { 1, "wrested the console key from Tinkerer Sniggles to unlock the Venture Company apparatus and reach the samophlange inside" },
    [902] = { 2, "pulled the samophlange from its console for Sputtervalve in Ratchet, to be sent on to the Tinkers' Union" },
    [903] = { 1, "stalked savannah prowlers in the tall grass for their claws, prey that could turn the hunter into the hunted" },
    [905] = { 1, "laid sunscale raptor feathers on the Scytheclaw nests to show their brethren no fear, as Sergra Darkthorn asked" },
    [906] = { 1, "brought Lok's skull to Thork at the Crossroads, proof that the leader of the raids on his supply lines was dead" },
    [907] = { 1, "faced the great thunder lizards of the southern Barrens and brought their blood to Jorn Skyseer as proof" },
    [908] = { 2, "dived into Blackfathom Deeps for the fathom core, so Je'neu Sancrea and the Earthen Ring might stop the Twilight's Hammer there" },
    [910] = { 1, "showed a young ward the docks of Ratchet and the ships that sail to Booty Bay, for an orphan who dreamed of being a Horde sailor" },
    [911] = { 1, "took a young ward to the Mor'shan Rampart to see the frontier of Ashenvale, where Horde and Alliance clash" },
    [913] = { 2, "slew a thunderhawk for its wings, the hunt that brought Jorn Skyseer's teaching near its end" },
    [914] = { 3, "slew the four leaders of the Druids of the Fang for their dream gems, to save the Barrens from a cursed future" },
    [915] = { 1, "fetched Tigule and Foror's Strawberry Ice Cream for a young ward, his favourite treat in the whole wide world" },
    [916] = { 1, "gathered webwood venom sacs for Gilshalan Windwalker, who believed the new world tree had changed the spiders" },
    [917] = { 1, "fetched an unhatched egg from the webwood spiders' nest in the Shadowthread Cave for Gilshalan's studies in Darnassus" },
    [918] = { 1, "gathered timberling seeds around Lake Al'Ameth for Denalan, who hoped to grow gentler timberlings in his special soil" },
    [919] = { 1, "pulled up the timberling sprouts spreading around Lake Al'Ameth before they grew large enough to cause trouble" },
    [921] = { 1, "filled a phial at the moonwell for Tenaron Stormgrip while learning what became of Nordrassil after the Battle of Mount Hyjal" },
    [922] = { 1, "took a timberling seed to Rellian Greenspyre in Darnassus, who found it carried its parent's taint" },
    [923] = { 2, "cut down the tainted timberlings of Wellspring Lake for Rellian Greenspyre, their mossy tumors to be burned" },
    [924] = { 3, "carried a flawed power stone up Dreadmist Peak before it consumed itself, and so destroying the Burning Blade's Demon Seed" },
    [925] = { 1, "asked Cairne Bloodhoof in Thunder Bluff for his hoofprint, a keepsake for a young ward who wanted to be a hero of the Horde" },
    [927] = { 1, "handed Denalan the still-beating heart of Blackmoss the Fetid, wrapped in a dark, oily moss" },
    [929] = { 1, "filled a phial at the moonwell near Starbreeze for Corithras Moonrage, as he began the tale of how Teldrassil came to be" },
    [930] = { 1, "showed Denalan a strange glowing fruit, a plant from far off that reacted oddly with the soil of Teldrassil" },
    [931] = { 1, "brought Denalan a shimmering frond, a plant he had last seen in the Swamp of Sorrows decades before" },
    [932] = { 3, "hunted down the satyr Lord Melenas, who was plotting something foul in Fel Rock, much too close to Dolanaar" },
    [933] = { 1, "braved the ill-tempered Gnarlpine to fill a phial at the moonwell by the Pools of Arlithrien for Corithras Moonrage" },
    [934] = { 1, "drew water from the moonwell beneath the Oracle Tree, and heard why the dragons refused to bless Teldrassil" },
    [935] = { 1, "carried the moonwell waters to Arch Druid Fandral Staghelm, on whose shoulders the troubles of Teldrassil fell" },
    [937] = { 2, "drove the harpies from their nests around the Oracle Tree, after they killed its messenger to Darnassus" },
    [938] = { 3, "led Mist, a badly wounded sabercat, back to Sentinel Arynia Cloudsbreak, who had given her faithful companion up for dead" },
    [939] = { 2, "brought Xavaric's strange flute and Jadefire Felbind samples to Eridan Bluewind, who sensed ancient ones suffering in them" },
    [940] = { 1, "carried the Oracle Tree's report to Fandral Staghelm, its last messenger having been killed by the harpies" },
    [941] = { 1, "planted the tainted heart of Blackmoss in Denalan's nutritive soil, which cleansed it" },
    [942] = { 1, "took the fossil over the sea to Archaeologist Flagongut in Menethil Harbor, who believed such fossils held a hidden power" },
    [943] = { 2, "pried the Stone of Relu from a raptor that swallowed it and got Whelgar's fossil, so Flagongut could try to unlock them" },
    [944] = { 2, "scouted the Master's Glaive, where an old lord of the earth fell, and told Onu of its cultists through a scrying bowl" },
    [945] = { 2, "helped Therylune slip away from the cultists at the Master's Glaive, and told her sister Therysil she was safe" },
    [947] = { 1, "picked rare mushrooms behind Cliffspring Falls for Barithras Moonshade's potion, and scouted the cave the Ancients feared" },
    [949] = { 2, "searched the Twilight's Hammer camp at the Master's Glaive for some clue to what the cult intended there" },
    [950] = { 1, "tore a page of insane scribbles from the maddening Twilight Tome, in hope it would reveal the cult's purpose to Onu" },
    [951] = { 2, "sifted the ruins of Mathystra for elven relics, to learn how the cult would use elven magic to bring back its masters" },
    [953] = { 1, "deciphered the tablets of Ameth'Aran among its restless spirits, so Sentinel Tysha Moonblade could report its fall" },
    [954] = { 1, "investigated the strange blue aura at a shrine in Bashal'Aran that its satyrs and sprites would not go near" },
    [955] = { 2, "took earrings from the grells of Bashal'Aran, where the spirit Asterion hoped to find a trace of the seal binding him" },
    [956] = { 2, "wrested the Ancient Moonstone Seal, the bond of Asterion's long imprisonment, from the satyrs who led the grells" },
    [957] = { 3, "destroyed the Ancient Moonstone Seal in the blue flame of Ameth'Aran, setting Asterion free after ages" },
    [958] = { 1, "pried Highborne relics from the spirits of Ameth'Aran, so Thundris Windweaver could destroy their dormant evil" },
    [959] = { 1, "chased Mad Magglish into the Wailing Caverns for the stolen 99-year-old port, before Crane Operator Bigglefuzz lost his job" },
    [962] = { 1, "picked serpentbloom in the darkest recesses of the Wailing Caverns for Apothecary Zamah of the Royal Apothecary Society" },
    [963] = { 2, "released the haunted spirit of Anaya Dawnrunner for Cerellean Whiteclaw, who loved her and had not the heart to do it" },
    [964] = { 2, "gathered skeletal fragments in Andorhal for Apothecary Dithers, the first step toward a key to Scholomance's barred door" },
    [965] = { 1, "looked for Balthule Shadowstrike, overdue from his watch on the Tower of Althalaxx, for a worried Elissa Starbreeze" },
    [966] = { 2, "took worn parchments from the warlocks at the Tower of Althalaxx, papers that named them the Cult of the Dark Strand" },
    [967] = { 1, "rushed Balthule's warning about the Cult of the Dark Strand to his master, Delgren the Purifier, at Maestra's Post" },
    [968] = { 1, "returned a battered copy of The Powers Below, a book of dark worship, to Gerrig Bonegrip's shop in Ironforge" },
    [969] = { 1, "fetched Frostmaul Shards from the ice giants' canyon for Witch Doctor Mau'ari, who would make a lucky charm from them" },
    [970] = { 2, "seized the Glowing Soul Gem at Ordil'Aran for Delgren, who believed it held the secret of the Dark Strand's power" },
    [971] = { 2, "recovered the Lorgalis Manuscript from Blackfathom for Gerrig Bonegrip, who collected lore that could awaken Those Who Sleep" },
    [973] = { 3, "faced down Ilkrud Magthrull, a powerful orc warlock at the Fire Scar Shrine, and took his tome to Delgren" },
    [974] = { 1, "took the temperature of hot spots on Fire Plume Ridge for Krakle, to learn whether the volcano warmed the crater's springs" },
    [976] = { 2, "guarded Feero through Ashenvale Forest with supplies and messages Auberdine needed against the forest's dark threats" },
    [977] = { 1, "collected two unbroken horns from the ice thistle patriarchs and matriarchs to finish Umi Rumplesnicker's mechanical yeti" },
    [978] = { 1, "picked up fallen moontouched feathers in Winterspring for Erelas Ambersky, to see if its wildkin held the same magic as the Hinterlands'" },
    [982] = { 1, "dived to the wrecks of the Silver Dawning and the Mist Veil, sunk by murlocs, for their dead captains' lockboxes" },
    [983] = { 1, "mended Buzzbox 827 with crawler legs for Wizbang, an inventor whose talking boxes needed constant repair" },
    [984] = { 2, "scouted a Blackwood furbolg camp for signs of corruption, for Terenthis, who had vowed no more night elves would be hurt" },
    [985] = { 2, "fought the Blackwood furbolgs in their camp south of Auberdine, the biggest threat to its people" },
    [986] = { 1, "skinned moonstalker sires and matriarchs for fine pelts, so Terenthis could make a cloak to reach Volcor unhindered" },
    [991] = { 2, "searched the shrine in Lake Falathim for Raene Wolfrunner's friend Teronis, and found him dead among the murlocs" },
    [992] = { 1, "tapped a pool near Sandsorrow Watch for the Gadgetzan Water Company, its wells lost to the nomads, and met a strange bug there" },
    [993] = { 2, "sought out Volcor, Grimclaw's wounded master, in a furbolg cave and brought him an enchanted moonstalker cloak" },
    [994] = { 3, "fought a way out of the furbolg cave at Volcor's side, down to the road where Grimclaw waited" },
    [995] = { 3, "sneaked out of the furbolg cave with the wounded Volcor, then met Terenthis back in Auberdine" },
    [996] = { 1, "spent two Cenarion plant salves on a corrupted windblossom, which shed its twisted form and blossomed healthy" },
    [997] = { 1, "delivered a long-delayed package of rare earth to Denalan for his experiments on the plants of Teldrassil" },
    [998] = { 1, "cleansed a windblossom of Felwood's corruption with two doses of Cenarion plant salve" },
    [1001] = { 1, "fished thresher eyes out of the deep sea to fix Buzzbox 411, while Wizbang hiccupped through the box" },
    [1002] = { 1, "fed moonstalker fangs into Buzzbox 323 for a Wizbang who sounded drunker at every box" },
    [1003] = { 1, "fixed Buzzbox 525 with grizzled scalps, and learned the boxes also distilled liquor for a trade the night elves frowned on" },
    [1007] = { 1, "searched the site of a naga ambush on the Zoram Strand for Talen's ancient statuette, the reason he had braved that coast" },
    [1008] = { 2, "drove the Wrathtail naga from the Zoram Strand, where the drowned city of Zoram lies, for Shindrell Swiftfire" },
    [1009] = { 3, "took the Ring of Zoram from Ruuzel, leader of the naga, the key Talen needed to unlock the secrets of his statuette" },
    [1010] = { 2, "searched Bathran's Haunt for Bathran's Hair, a plant Orendil Broadleaf needed to treat a sick child in the village" },
    [1011] = { 2, "stole a bottle of disease from the Forsaken camp near Dor'Danil, so Kayneth Stillwind could learn what they meant to spread" },
    [1012] = { 2, "destroyed the maddened ghosts of Dor'danil's druids, murdered by the Forsaken, so their spirits might at last find peace" },
    [1013] = { 1, "took the Book of Ur, a Dalaran mage's studies of other worlds, from Shadowfang Keep for Keeper Bel'dugur's collection" },
    [1014] = { 3, "killed Arugal in Shadowfang Keep and brought his head to Dalar Dawnweaver, to free Silverpine from his foul spells" },
    [1016] = { 2, "divined from the elementals' bracers who had been filling the pools with corruption, for Sentinel Velene Starstrike" },
    [1017] = { 3, "killed Sarilus Foulborne, the undead mage fouling the waters with corrupted elementals, for Sentinel Velene Starstrike" },
    [1020] = { 1, "carried Orendil's cure to Pelturas Whitemoon in Astranaar, the parent of the sick child" },
    [1021] = { 2, "searched Xavian for the dryads who had gone to take back the Branch of Cenarius, and found Anilia dying" },
    [1022] = { 2, "studied the Tome of Mel'Thandris at the Howling Vale, to learn why wolf-men had overrun the shrine" },
    [1023] = { 2, "found the glowing gem Teronis had died seeking and brought his journal back to Raene Wolfrunner" },
    [1025] = { 2, "fought the Foulweald furbolgs who had been attacking travellers on the road east, to help the Sentinels protect the land" },
    [1026] = { 1, "took a wooden key from the corrupted treants to open a hidden chest holding the next piece of Dartol's Rod" },
    [1027] = { 2, "recovered the last piece of Dartol's Rod, hidden by the druids of Dor'danil before they were killed" },
    [1028] = { 2, "found a hidden shrine in the mountains and re-enchanting Dartol's Rod there, the work Teronis had died to begin" },
    [1030] = { 2, "took furbolg form with Dartol's Rod to speak with an uncorrupted furbolg, who blamed the night elves for the corruption of his kin" },
    [1031] = { 3, "killed Geltharis and returned the Branch of Cenarius to the dryads, Anilia's dying wish" },
    [1032] = { 1, "slew the satyrs who had taken Anilia, for her grieving sister Illiyana" },
    [1033] = { 2, "brought Elune's Tear from the isle on Iris Lake to Pelturas, to wash away the corruption sickening Relara" },
    [1034] = { 2, "gathered frosted dust in the Ruins of Stardust for a poultice to bring down Relara's fever" },
    [1035] = { 3, "slew the Shadethicket Oracle for a fallen moonstone, the power Pelturas believed would give Relara back her strength" },
    [1037] = { 1, "asked Thyn'tel Bladeweaver in Darnassus about Velinde Starsong, the priestess who had vanished from Ashenvale" },
    [1038] = { 2, "searched Velinde Starsong's chest in the Sentinels' bunkhouse for her journal, which made her disappearance look more troubling" },
    [1039] = { 1, "traced Velinde Starsong through the wharfmaster's ledgers in Ratchet, where she had booked passage to Booty Bay" },
    [1040] = { 1, "trailed Velinde to Booty Bay and the caravaneer Ruzzgot, of whom she had asked about travel overland" },
    [1041] = { 1, "followed the caravan road to Darkshire, where Velinde had parted from Ruzzgot's caravan" },
    [1042] = { 1, "sought out the Carevin family of Darkshire, hunters of the worgen that Velinde's trail had led to" },
    [1043] = { 2, "searched the worgen-infested mine south of Darkshire, where the wolf-men were first found, for signs of the Scythe of Elune" },
    [1044] = { 2, "brought Thyn'tel Bladeweaver word of Velinde Starsong's fate, the end of a long search from Ashenvale to Duskwood" },
    [1045] = { 3, "killed Ran Bloodtooth and his guards for Krolg, an uncorrupted furbolg determined that his people police their own" },
    [1046] = { 2, "brought Ran Bloodtooth's skull and Dartol's Rod to Raene Wolfrunner, finishing what Teronis had died to begin" },
    [1048] = { 3, "laid waste to High Inquisitor Whitemane and her lieutenants in the Scarlet Monastery, the sharpest thorn in the Forsaken's side" },
    [1049] = { 2, "retrieved the Compendium of the Fallen from the Scarlet zealots for Sage Truthseeker, who doubted the Forsaken and wanted their research" },
    [1050] = { 2, "rescued Mythology of the Titans from the Monastery's library for Librarian Mae Paledust, to unlock the secrets of the past" },
    [1051] = { 2, "avenged Vorrel Sengutz on the wife of the interrogator who tortured him, and brought his wedding ring home to Monika in Tarren Mill" },
    [1052] = { 1, "carried Brother Anton's commendation to Raleigh the Devout in Southshore, for a place of honour in the Scarlet Monastery" },
    [1053] = { 3, "crushed the deranged regime of the Scarlet Monastery for Raleigh the Devout, to spare the innocents it tortured as plagued" },
    [1054] = { 3, "killed Dal Bloodclaw, chieftain of the Thistlefur furbolgs, whose growing numbers might soon dare to attack Astranaar" },
    [1057] = { 2, "drove the Bloodfury harpies out of the Charred Vale for Keeper Albagorm, so the burnt land could begin to grow back" },
    [1058] = { 1, "gathered sap, whiskers, courser eyes and a fey dragon scale for Witch Doctor Jin'Zil's forest magic, brewed for his caged elves" },
    [1059] = { 1, "carried Keeper Albagorm's plea to Falfindel Waywarder, a druid who could call forest spirits to help reclaim the Charred Vale" },
    [1060] = { 1, "carried Darsok Swiftdagger's letter to the witch doctor Jin'Zil in Stonetalon, word that Serena Bloodfeather was dead" },
    [1062] = { 2, "killed Venture Co. loggers in Windshear Crag for Seereth Stonebreak, to stop the goblins burning and felled the forest" },
    [1065] = { 1, "carried Apothecary Zamah's note to Apothecary Lydon in Tarren Mill, a plan to rid Stonetalon of the Venture Company without bloodshed" },
    [1066] = { 1, "obtained vials of innocent blood from the Syndicate shadow mages of Durnholde Keep for Lydon's toxin to make the Venture Company docile" },
    [1067] = { 1, "brought Lydon's Toxin back to Apothecary Zamah in Thunder Bluff, who would find a way to deliver it" },
    [1068] = { 2, "wrecked the shredders XT:4 and XT:9, the machines of Seereth's vision that felled trees with impossible speed" },
    [1069] = { 1, "gathered deepmoss spider eggs in Stonetalon for Mebok Mizzyrix, to sell to Booty Bay's craze for spider egg omelettes" },
    [1070] = { 1, "looked for Kaela Shadowspear in Stonetalon, sent to investigate the land and not heard from since" },
    [1071] = { 2, "kept the Venture Co. at bay in Windshear Crag so Gaxim Rustfizzle could plan the inventions he hoped would save the forest" },
    [1073] = { 1, "proved some skill at alchemy to Lomac Gearstrip in Ironforge with a few potions, the price of his Nitromirglyceronium" },
    [1074] = { 1, "carried the volatile Nitromirglyceronium back to Gaxim Rustfizzle, the spark for his wagons of dynamite" },
    [1076] = { 1, "took debris from a Westfall dust devil to Collin Mauren, for a scroll to set off Gaxim's explosives from afar" },
    [1077] = { 1, "brought the Scroll of Messaging to Gaxim, the last piece of the remote explosive meant to cover a raid on the Venture Co. site" },
    [1078] = { 1, "collected crystalized basilisk scales in the Charred Vale for Collin Mauren, ground into a reagent for his spells" },
    [1079] = { 2, "set off a distraction at the lumber mill in Windshear Crag and stole the Venture Co.'s engineering plans for Gaxim" },
    [1080] = { 2, "stole the Venture Co. letters from Windshear Mine under cover of Gaxim's explosives" },
    [1082] = { 1, "brought Sentinel Thenysil word that Kaela and Gaxim were alive, and well on their way to stopping the Venture Co. goblins" },
    [1083] = { 1, "thinned the burning spirits loosed on the Charred Vale when the Venture Co. set it aflame, for Kaela Shadowspear" },
    [1084] = { 2, "took corroded shrapnel from a wounded treant so Gaxim could learn whether the goblins' weapons had corrupted it" },
    [1086] = { 3, "found the Venture Co. sky port in Stonetalon and planted the Toxic Fogger there, in the hope it would reach their headquarters" },
    [1087] = { 1, "killed the Sons and Daughters of Cenarius for Braelyn Firehand, who hated how the druids stifled the flow of magic" },
    [1088] = { 3, "took the head of Ordanus, one of the eldest sons of Cenarius, from the top of Raynewood for Braelyn Firehand" },
    [1089] = { 2, "unlocked the druids' hoard in the Talon Den on Stonetalon Peak with secrets Braelyn had wrung from one of them" },
    [1090] = { 2, "guarded Piznik while he mined a sample of Gerenzo's mysterious gold-green ore, to learn what the gnome was planning" },
    [1091] = { 1, "brought the stolen Venture Co. letters to Kaela Shadowspear, with word of how well the raid had gone" },
    [1092] = { 1, "carried the unidentified ore to Ziz Fizziks, whose new boss would pay well to learn Gerenzo's plans" },
    [1093] = { 1, "took the Super Reaper 6000 blueprints from one of its operators for Ziz Fizziks, whom Gerenzo wanted dead on sight" },
    [1094] = { 1, "delivered a sealed envelope of stolen Venture Company documents from Ziz Fizziks to Sputtervalve in Ratchet" },
    [1095] = { 1, "carried Sputtervalve's new orders to Ziz Fizziks: Gerenzo, whom the trade princes did not approve of, was to be removed" },
    [1096] = { 3, "killed Gerenzo Wrenchwhistle, the half-mechanical gnome running the Venture Co. site, and brought his metal arm to Ziz Fizziks" },
    [1098] = { 2, "searched Shadowfang Keep for the deathstalkers Adamant and Vincent, sent to scout it before the assault, and found Vincent dead" },
    [1101] = { 3, "slew Charlga Razorflank, crone of the Kraul, so the valour of Heralath and the dwarf Lonebrow would not go for naught" },
    [1102] = { 3, "avenged the tauren driven from their holy lands in the Barrens, taking Charlga Razorflank's heart for Auld Stonespire" },
    [1103] = { 1, "brought a water sapta to Tiev Mordune, a troll shaman at the shrine who offered a second chance to see the pure water spirit" },
    [1104] = { 1, "gathered salty scorpid venom for Fizzle Brassbolts, the base of a fuel to make the gnomes' rocket car burn hotter" },
    [1105] = { 1, "collected tortoise shells for Wizzle Brassbolts to build fuel tanks strong enough to hold his brother's fierce new fuel" },
    [1106] = { 1, "carried Fizzle's letter to Martek the Exiled in the Badlands, a great smith who might know how to make harder pistons" },
    [1107] = { 1, "cut tail fins from the Saltscale murlocs of the Vile Reef for a composite to keep the rocket car from tearing itself apart" },
    [1108] = { 1, "took indurium flakes from the Stonevault troggs for Martek to test, a metal that might stand the heat of Fizzle's engine" },
    [1109] = { 1, "scraped up the guano of the Kraul bats for Master Apothecary Faranell's ambitious experiments" },
    [1110] = { 1, "scavenged crashed rocket car parts across the Shimmering Flats for Kravel Koalbeard to sell to the racers" },
    [1111] = { 1, "fetched the gnomes' long-delayed car parts from Wharfmaster Dizzywig in Ratchet for Kravel Koalbeard" },
    [1113] = { 1, "cut Hearts of Zeal from the Scarlet Crusade's disciples for Master Apothecary Faranell's most ghastly experiment" },
    [1114] = { 1, "delivered the car parts Fizzle Brassbolts had long waited for, short one small piece Kravel had kept back" },
    [1116] = { 1, "gathered dream dust from the dragon whelps of the swamp for Krazek's snuff pouch, his price for news of Nazz" },
    [1117] = { 1, "brought Kravel the rumors Krazek had dug up on Nazz Steamboil, a secret the goblin pilot would pay a fortune to keep" },
    [1118] = { 1, "took Kravel's new scheme to Crank Fizzlebub in Booty Bay, who would need something to addle the racers' wits" },
    [1119] = { 1, "brought back a Fool's Stout, brewed by Crank Fizzlebub from Zanzil's mixture, for Kravel's scheme against the racers" },
    [1120] = { 1, "plied the gnome pit crew with Fool's Stout before the race, as Kravel's scheme demanded" },
    [1121] = { 1, "slipped Fool's Stout to the goblin pit crew before the race, so Kravel's bet would pay" },
    [1125] = { 2, "freed the tortured spirits of druids and sentinels in the ruins of Southwind Village, where Layo Starstrike's work began" },
    [1126] = { 2, "scaled the tower of Southwind Village to stir its silithid hive, and found an encrusted box that seemed to hold a book" },
    [1127] = { 1, "brought Crank Fizzlebub more of Zanzil's mixture to brew Fool's Stout, a drink wanted back at the races" },
    [1131] = { 2, "defeated Steelsnap, a tyrant hyena of Thousand Needles who spread fear and bloodshed among more peaceful beasts" },
    [1134] = { 2, "killed pridewings near Mirkfallon Lake to deny their venom to the orc assassins said to use it on the Alliance" },
    [1135] = { 1, "hunted Highperch wyverns in Thousand Needles for their venom sacs, worth more to Fiora Longears than the beasts themselves" },
    [1136] = { 3, "lured the elusive yeti Frostmaw out of the snows of the Alterac Mountains with Melor Stonehoof's scroll and defeated him for his mane" },
    [1138] = { 1, "picked fine crab chunks out of reef crawlers for Gubber Blump, who loved crab more than anything" },
    [1139] = { 3, "recovered the Tablet of Will before the Shadowforge clan could find it, so Hammertoe's death would not be in vain" },
    [1140] = { 2, "freed the Highborne souls whose soulgems, in Night Run and Satyrnaar, still fed Athrikus's power" },
    [1141] = { 1, "caught Darkshore grouper for Gubber Blump, no boats having gone out since the murlocs moved in" },
    [1142] = { 2, "returned Treshala Fallowbrook's pendant of bonding to her in Darnassus, with word of her husband Heralath's lonely death" },
    [1143] = { 3, "killed Athrikus Narassin atop the Tower of Althalaxx amid his warlocks, so the demonic forces there might be driven back" },
    [1144] = { 2, "escorted Willix the Importer out of Razorfen Kraul, held prisoner there after a tuber hunt went wrong" },
    [1145] = { 1, "carried Korran's sealed note to Orgrimmar, warning that the insects of the Field of Giants were deadlier than thought" },
    [1146] = { 1, "took Belgrom's sealed note to Moktar Krin, whose war party had lost over half its number to insects erupting from a Shimmering Flats cave" },
    [1147] = { 2, "pushed the silithid back from the dig site for Moktar Krin's half-dead war party, who could not fight them alone" },
    [1148] = { 2, "brought silithid hearts, talons and carapaces to Korran at the Crossroads, to learn what the creatures were" },
    [1153] = { 1, "pried an ore sample from the Gravelsnout kobolds for Tatternack Steelforge, who hoped to forge a weapon for the warchief" },
    [1164] = { 2, "killed Kenata Dabyrie and her sons at their Arathi farmstead for Genavie Callow, who wanted their heads for robbing her" },
    [1166] = { 1, "recovered Overlord Mok'Morokk's grog, snuff and strongbox from the old Stonemaul home he had fled when the dragons came" },
    [1168] = { 2, "fought the black dragon army for Tharg, whose wife the dragons had killed and who wanted revenge and his home back" },
    [1169] = { 2, "took tongues and hearts from the black whelps and hatchlings so Draz'Zilb could trace the evil that had descended on the old Stonemaul home" },
    [1172] = { 2, "destroyed Onyxia's eggs in the Wyrmbog so no more whelps would hatch and the Stonemaul could one day reclaim their village" },
    [1173] = { 3, "challenged Overlord Mok'Morokk and beat him until he fled, so the Stonemaul could choose a leader to win back their home" },
    [1175] = { 1, "cleared basilisks away from the racetrack for Trackmaster Zherin, after one had caused a big crash with the Red Thunder" },
    [1176] = { 1, "collected hollow vulture bones for Pozzik, light and strong for tweaking the goblins' racers" },
    [1177] = { 1, "fed Mudcrush Durtfeet a pile of Mirefin heads, since the hungry ogre promised to eat whoever failed to" },
    [1179] = { 1, "carried a crate of crash helmets to Wizzle Brassbolts, whose rocket car pilots kept crashing and gave themselves concussions" },
    [1182] = { 2, "stole the fuel regulator blueprints from Cozzle's locked house at Lake Nazferiti, for the goblin racer Pozzik" },
    [1183] = { 1, "delivered the fuel regulator blueprints to Pozzik, who could now build a better one for his racer from the ground up" },
    [1187] = { 1, "recovered Razzeric's seaforium booster from a zeppelin crashed in Dustwallow Marsh, the extra power he wanted for his racer" },
    [1188] = { 1, "took the seaforium booster to Shreev in Gadgetzan to have its safety removed, at Razzeric's reckless insistence" },
    [1189] = { 1, "returned the modified booster to Razzeric, with Shreev's warning that one mistake would leave him a burnt spot on the track" },
    [1190] = { 2, "stole Rizzle Brassbolts' plans under cover of Zamek's diversion, to learn why the gnomes' cars had grown faster" },
    [1193] = { 1, "mended a broken trap with a thorium widget and frost oil, a nasty surprise for any ogre that wandered by" },
    [1194] = { 1, "brought Pozzik a sample of indurium ore found with Rizzle's plans, the secret of the gnomes' faster cars" },
    [1195] = { 1, "took an etched phial from the dryads of Ashenvale and filled it at a moonwell, to help breach the flame guarding a Galak relic" },
    [1196] = { 1, "carried the moonwell water to Rau Cliffrunner at Freewind Post, since the dryads' kinship with the centaurs would let it breach the eternal flame" },
    [1197] = { 2, "doused the eternal flame in Splithoof Hold and took the Cloven Hoof from under the Galak centaurs' guard for Rau Cliffrunner" },
    [1198] = { 1, "sought out Argent Guard Thaelrid in Blackfathom Deeps, a scout of the Argent Dawn who had not reported back in weeks" },
    [1199] = { 2, "tore pendants from the Twilight's Hammer cultists massing with the naga in Blackfathom, to thwart their evil plan" },
    [1200] = { 3, "slew Twilight Lord Kelris, who sacrificed innocents to Aku'Mai in a ruined temple of Elune, for Dawnwatcher Selgorm" },
    [1201] = { 2, "hunted down the Theramore infiltrators spying on Brackenwall Village, a clear message that the Horde would not tolerate spies" },
    [1202] = { 2, "dived for the footlocker beneath the Theramore docks to recover the Captain's Documents two Horde spies had thrown into the sea" },
    [1203] = { 1, "found a Moonsteel Broadsword for Jarl, who had some cutting to do and would not say what" },
    [1204] = { 1, "hunted Mudrock turtles for their forked tongues, whose flavour Morgan Stern wanted in his Mudrock Soup and Bugs" },
    [1205] = { 2, "ended the life of Deadmire, an ancient crocolisk living in maddening pain, to lead the noble beast to peace for Melor" },
    [1206] = { 1, "collected unpopped Darkmist spider eyes for Jarl, who liked their juice and, it seemed, their company" },
    [1218] = { 1, "gathered Soothing Spices for Jarl's swamp cooking, and a stew he promised to share" },
    [1219] = { 1, "carried an orcish spy's report, found clutched in a severed orc hand, to a Theramore lieutenant" },
    [1220] = { 1, "brought the orc spy's report to Captain Garran Vimes, who read orcish and needed to know of Horde spies near Theramore" },
    [1221] = { 1, "set a snufflenose gopher to sniff out blueleaf tubers in Razorfen Kraul, a rare delicacy for Mebok Mizzyrix to sell" },
    [1222] = { 2, "escorted 'Stinky' Ignatz out of a swamp full of critters while he searched for bogbean leaves for Morgan Stern" },
    [1238] = { 1, "carried the last report of a Horde spy, found in a severed hand in the mud, to the spymaster Nazeer Bloodpike in Brackenwall" },
    [1239] = { 2, "brought Nazeer Bloodpike the severed head of his agent Marg Nighteye, to learn whether the Alliance had killed him" },
    [1240] = { 2, "travelled with Marg Nighteye's head to Kin'weelay, the Darkspear witchdoctor at Grom'gol, so the angry spirit could tell of his death" },
    [1244] = { 2, "searched Addle's Stead in Duskwood for the Defias Docket, a clue to the diplomat who never reached Theramore" },
    [1245] = { 1, "carried the Defias Docket to Elling Trias, a plan Watcher Backus said was bigger than him" },
    [1249] = { 2, "subdued Tapoke Jahn, the eavesdropper in Menethil's tavern, before he could slip away with what he knew of the missing diplomat" },
    [1251] = { 2, "removed a blackened iron shield from the chimney of the burned Shady Rest Inn for Krog, who wondered if it had been left as a warning" },
    [1252] = { 2, "brought the badge of Lieutenant Paval Reethe, found in the Shady Rest's rubble, to Captain Garran Vimes, who knew a guard's badge meant bad news" },
    [1253] = { 2, "took the blackened iron shield from the ruins of the Shady Rest Inn to Captain Garran Vimes, a clue to whoever burned it" },
    [1258] = { 1, "gathered pristine crawler legs in the Swamp of Sorrows for Morgan Stern's new dish, the only crabs whose shells would do" },
    [1261] = { 2, "tracked down the muckshell that killed Marg Nighteye to recover the Jeweled Pendant he stole from an Alliance camp, finishing his mission" },
    [1262] = { 1, "carried the Jeweled Pendant to Zor Lonetree in Orgrimmar, who knew Alliance politics and might find its noble owner" },
    [1265] = { 1, "searched Sentry Point for Private Hendel, said to be the Defias' man aboard the king's ship" },
    [1268] = { 1, "told Krog of the hoofprints leading away from the burned Shady Rest Inn, where the owner's wife and child had been killed" },
    [1269] = { 1, "showed Krog the badge of Paval Reethe, a human deserter suspected of stealing from Brackenwall's supplies" },
    [1270] = { 2, "got 'Stinky' Ignatz out of a ring of critters and guarded him while he looked for bogbean for Mebok Mizzyrix" },
    [1273] = { 2, "went with Ogron to question the deserter Reethe, hoping for answers about the burning of the Shady Rest Inn" },
    [1275] = { 1, "harvested satyr and naga brain stems in Blackfathom for Gershala Nightwhisper, who feared the blood elves would be deformed too" },
    [1276] = { 1, "showed the blackened shield to Mosarn, the Thunder Bluff smith whose name was on its rim, though he had made too many to remember this one" },
    [1282] = { 1, "asked Captain Garran Vimes about Smiling Jim, James Hyal, whose Shady Rest Inn had been burnt to the ground" },
    [1284] = { 1, "reported the hoofprints leading from the burned Shady Rest Inn to Captain Vimes, who sent a tracker after them" },
    [1285] = { 1, "passed Captain Vimes the record of Paval Reethe, a Kul Tiras marine listed as missing, which he took to mean traitor" },
    [1286] = { 2, "sought out Balos Jacken and the deserters squatting at Lost Point to learn what they knew of Reethe" },
    [1287] = { 1, "told Captain Vimes the deserters had thrown Reethe out for raiding the ogres of Brackenwall Village" },
    [1302] = { 1, "sought word in Theramore of James Hyal, an innkeeper whose brother had not heard from him in some time" },
    [1318] = { 2, "sought the Gauntlet of Gordok Might, stolen long ago by the elf Tortheldrin, which only the true Gordok king could win back" },
    [1319] = { 1, "showed the blackened shield to Caz Twosprocket, who judged it was not made by any smith on this side of the sea" },
    [1320] = { 1, "reported to Captain Vimes that the shield's burnt strap had been made for someone large, likely a tauren" },
    [1322] = { 1, "collected acidic venom sacs from the Darkmist spiders so Do'gol could clean the writing on the shield's rim" },
    [1324] = { 3, "beat Private Hendel, the Defias' man aboard the king's ship, so Theramore could question him about the missing King" },
    [1338] = { 1, "carried Mountaineer Stormpike's request for a shield to Furen Longbeard, the dwarven armorsmith he admired in Stormwind" },
    [1358] = { 1, "carried wolf heart samples to Apothecary Helbrim in the Barrens, who studied Lordaeron toxins in Kalimdor's beasts" },
    [1359] = { 1, "delivered samples of the strangely toxic wolf hearts to Apothecary Zinge, a new poison for the Society to study" },
    [1360] = { 1, "fetched Krom Stoutarm's treasured stein from his chest in the trogg-filled North Common Hall of Uldaman" },
    [1364] = { 1, "recovered Khadgar's essays from the swamp creatures that frightened Dellis, and brought them to Watcher Mahar Ba at Nethergarde" },
    [1365] = { 3, "killed Khan Dez'hepah, leader of the Kolkar of Desolace, to break the clan before the centaurs could unite" },
    [1366] = { 1, "collected ears from centaurs of every clan for Felgur Twocuts, to weaken their numbers and stamp out thoughts of expansion" },
    [1367] = { 1, "slew Gelkis centaurs to win the trust of their rivals the Magram, so the Horde could learn to beat all the clans" },
    [1368] = { 1, "slew Magram centaurs to earn the respect of the Gelkis, so the Horde could learn to beat all the clans" },
    [1369] = { 1, "smashed the Gelkis' hoarded tears of Theradras for Warug, to show them their centaur mother would not protect them" },
    [1370] = { 1, "raided the Magram's stores of dried meat for Uthek the Wise, so the Gelkis could fight on while their rivals went hungry" },
    [1371] = { 1, "found Warug a new Advanced Target Dummy, like the waving wooden man he had taken from the cart of a gnome he killed" },
    [1373] = { 1, "won a draenethyst shard from Ongeku in the Swamp of Sorrows, a crystal from a land of demons to strengthen Uthek's magic" },
    [1374] = { 3, "beheaded Khan Jehn of the Magram for Uthek the Wise, so the clan would fall without its leader" },
    [1375] = { 3, "beheaded Khan Shaka of the Gelkis for Warug, who wanted to stare at the head and laugh" },
    [1380] = { 3, "sounded the Maraudine War Horn to draw out Khan Hratha, and took his key fragment to Uthek the Wise" },
    [1381] = { 3, "killed Khan Hratha of the Maraudine for Warug, after winning a mouthpiece and blew the war horn that called him out" },
    [1382] = { 1, "killed Magram centaurs to win the Gelkis' trust, so the Alliance might strike a pact with one warring clan" },
    [1383] = { 1, "gathered panther hearts, Mire Lord fungus and a Deep Strider tumor for Apothecary Faustin's so-called truth serum" },
    [1384] = { 1, "snatched crude charms from the Kolkar for Uthek the Wise, who meant to burn them and laugh at their weak magic" },
    [1385] = { 1, "fought the Gelkis to earn the Magram's favour, so the Alliance could learn how to beat the warring centaur clans" },
    [1386] = { 1, "slaughtered Kolkar centaurs to the north to show Warug they could be killed the Magram way" },
    [1387] = { 1, "cut ears from centaurs for Corporal Melkins at Nijel's Point, thinning the cruel clans in the hope of peace" },
    [1389] = { 2, "reclaimed the sacred draenethyst crystals the lost ones of the Fallow Sanctuary stole, lest Magtoor's people lose their way" },
    [1391] = { 2, "brought the captive Infiltrator Marksen in Stonard an ale laced with Faustin's truth serum, a quiet Forsaken errand" },
    [1392] = { 3, "brought Noboru's cudgel to the leader of the Harborage, proof the brute who killed any Draenei in his path was dead" },
    [1393] = { 2, "escorted Galen away from the creatures about to eat him, for the treasure in his strongbox and the trick to open it" },
    [1394] = { 2, "returned to Dorn Plainstalker at the end of his trials, to be rewarded for a mind, body and spirit proven strong" },
    [1395] = { 1, "rushed a crate of powerstones to Nethergarde Keep before they lost their power, too urgent to wait for a caravan" },
    [1396] = { 1, "drove off the beasts skulking around Watcher Biggs's camp, all that was left of his caravan after the Lost Ones struck" },
    [1398] = { 1, "found sun-dried driftwood on the coast so Watcher Biggs could mend his wagon and reach Nethergarde" },
    [1419] = { 1, "hunted the crag coyotes that crept into Kargath to raid its food supplies, for Neeka Bloodscar" },
    [1420] = { 1, "carried Neeka Bloodscar's report to Helgrum the Swift in Stonard, news that the Alliance had troubles of its own" },
    [1421] = { 2, "recovered wizards' reagents from a wagon dragged into the Fallow Sanctuary, vital to Nethergarde's work on the Dark Portal" },
    [1423] = { 1, "returned a barrel of lost supplies to Quartermaster Lungertz at Nethergarde Keep, so many being lost on the road" },
    [1424] = { 2, "gathered Atal'ai artifacts around the Pool of Tears for Fel'zerul, to learn how the Temple of Atal'Hakkar came to be sunk" },
    [1425] = { 1, "carried the vital supplies saved from Watcher Biggs's caravan to Nethergarde Keep, where they were thought lost" },
    [1426] = { 1, "thinned the murlocs of the beach for Katar, guarding Stonard's coast, who hated the sea and all its spawn" },
    [1428] = { 1, "killed still more of the marsh murlocs, oracles among them, for Katar, who called for all the fish men to perish" },
    [1429] = { 2, "took Atal'ai artifacts to an exiled Atal'ai priest among the Witherbark of the Hinterlands, to learn their true use" },
    [1430] = { 1, "brought Dar monstrous crawler legs from the coast, a meat much prized by his customers in Orgrimmar" },
    [1434] = { 2, "drove back the Hatefury satyrs of Desolace for Takata Steelblade, since Thrall would have the Burning Blade's allies slain" },
    [1435] = { 2, "drew the corrupted spirits out of dying Burning Blade cultists into a gem, so Maurin Bonesplitter could put them somewhere safe" },
    [1436] = { 1, "reported the Desolace campaign to Keldran, who wanted the Alliance never to think the Horde in league with the Burning Legion" },
    [1437] = { 2, "searched for the wagon of Tyranis and Dalinda Malem, missing Darnassian nobles, and found it ambushed and empty" },
    [1438] = { 2, "found Dalinda Malem in Thunder Axe Fortress, where the Burning Blade meant to sacrifice her to their demon masters" },
    [1439] = { 2, "settled the fate of Tyranis Malem, whose craving for the arcane had led his sister into the Burning Blade's hands" },
    [1440] = { 3, "escorted Dalinda Malem out of Thunder Axe Fortress and back to Vahlarriel Demonslayer at Nijel's Point" },
    [1442] = { 2, "ventured into Blackfathom Deeps for a Kor gem from the naga, to be purified for the smith Stilwell's ritual" },
    [1445] = { 2, "seized Fetishes of Hakkar in the Sunken Temple for Fel'Zerul, who feared they were the key to the Atal'ai ritual behind it all" },
    [1446] = { 3, "killed Jammal'an the Prophet, whose false visions of Hakkar doomed the Atal'ai, for the exile who had urged caution" },
    [1447] = { 2, "brawled with Dashel Stonefist and his friends in Old Town until he talked about the Defias' plot" },
    [1448] = { 2, "found the Temple of Atal'Hakkar sunk beneath the Pool of Tears, the mystery that had eluded old Brohann Caskbelly" },
    [1452] = { 1, "gathered roc gizzards and groddoc and ironfur livers for Rhapsody Shindigger's Kalimdor Kocktail, the price of his tale" },
    [1454] = { 1, "searched for the chest the mage Karnitol abandoned to the sea giants, and found it forced open and empty" },
    [1456] = { 1, "wrested Karnitol's satchel from the Slitherblade naga, who had looted his chest from the shipwreck" },
    [1457] = { 1, "returned Karnitol's satchel to Roetten Stonehammer in Ironforge, so the mage would have his belongings back" },
    [1458] = { 1, "collected Hatefury satyr claws and horns for Kreldig Ungor, the first reagents on Leftwitch's list" },
    [1459] = { 1, "gathered scorpashi venom and aged kodo hides for Leftwitch's list, to help Kreldig Ungor get home to Ironforge sooner" },
    [1465] = { 2, "handed the Malem pendant to Vahlarriel Demonslayer, with word of tracks leading south to a Burning Blade fort" },
    [1466] = { 1, "harvested felhound brains, nether wings and doomwarder blood from demons, the last and worst of Leftwitch's reagents" },
    [1467] = { 1, "carried Leftwitch's package back to Roetten Stonehammer in Ironforge to collect the Reclaimers' pay" },
    [1468] = { 1, "took on Randis, an orphan whose parents were adventurers, as a ward for Children's Week" },
    [1469] = { 2, "carried Rhapsody Shindigger's Atal'ai tablet fragment to Brohann Caskbelly, proof the sunken temple lay under the swamp" },
    [1470] = { 2, "collected skulls from the rattlecage skeletons near the abandoned smithy, the test Venya Marthand set before teaching the binding of an imp" },
    [1471] = { 3, "drew an unbound voidwalker out of the circle of summoning with Carendin Halgar's runes and dominated it, to earn its summoning" },
    [1473] = { 2, "reclaimed Egalin's Grimoire, which held the first voidwalker's summoning, from Perrine, a Scarlet Crusade agent in a tower to the west" },
    [1474] = { 3, "baited a succubus through the summoning circle with the Pure Hearts and overcame it, so Carendin Halgar would teach the spell to call it" },
    [1475] = { 2, "gathered intact Atal'ai Tablets from the Sunken Temple for Brohann Caskbelly, an old dwarf's final obligation in life" },
    [1476] = { 2, "claimed the hearts of Dalin Forgewright, who cared for refugees, and Comar Villard, faithful to his lost wife, as bait for a succubus" },
    [1479] = { 1, "took a young orphan to Darnassus to see the Bough of the Eternals, the bank hollowed out of a tree" },
    [1480] = { 2, "showed a flayed demon skin to Maurin Bonesplitter, who read in its runes a contract signed by the demon Lord Azrethoc" },
    [1481] = { 1, "scalped a Hatefury shadowstalker so Maurin Bonesplitter could break the demon lord's wards against scrying" },
    [1482] = { 1, "pried an oracle crystal from the Slitherblade oracles, the focus Maurin Bonesplitter needed to find Lord Azrethoc" },
    [1485] = { 2, "slew the vile familiars in the cave to the northeast for their heads, the proof Ruzan asked for before teaching the art of summoning" },
    [1486] = { 1, "skinned the deviate creatures of the Wailing Caverns for Nalpak, who believed some good could come of their hides" },
    [1487] = { 2, "purged the deviate beasts from the Wailing Caverns, a first step for the Disciples of Naralex toward a restored Barrens" },
    [1488] = { 3, "slew Lord Azrethoc and his warlock servant Jugkar Grim'rod before the demon could bend the Burning Blade to his goals" },
    [1491] = { 1, "gathered wailing essence from the caverns' ectoplasmic creatures for Mebok Mizzyrix's smart drinks, his hope of a fortune" },
    [1492] = { 1, "took a crate of potions and reagents to Wharfmaster Dizzywig in Ratchet, to sail on the next boat to Blackwater Cove" },
    [1498] = { 3, "hunted the thunder lizards of Thunder Ridge for singed scales, proof to Uzzek of a warrior fit to be the Horde's shield" },
    [1501] = { 2, "recovered the Tablet of Verga from the Burning Blade at Skull Rock, so Gan'rul Bloodeye could teach the runes for a voidwalker" },
    [1503] = { 1, "recovered the steel bars the Razormanes stole from Thun'grim Firegaze, a half-blind smith who promised a weapon in return" },
    [1504] = { 3, "defeated a voidwalker called forth with the Glyphs of Summoning in Neeru Fireblade's tent, so Gan'rul Bloodeye would teach its binding" },
    [1509] = { 1, "asked at the Crossroads for news of Dogran, Zankaja's mate, a week overdue home from his new post and not heard from" },
    [1510] = { 1, "followed word of the wounded Dogran, held by the quilboar, to the Malaka'jin, where a healing draught had been sought for him" },
    [1511] = { 2, "carried Ken'zigla's draught to Camp Taurajo for the dying Dogran, after goblins killed the first one sent to fetch it" },
    [1512] = { 2, "handed Gan'rul Bloodeye the pendant Dogran parted with, rather than chain Zankaja to an invalid, as bait for a succubus" },
    [1513] = { 3, "lured a succubus with Dogran's Pendant and subdued it, then returned the pendant so Gan'rul could bring Zankaja the news" },
    [1514] = { 1, "nursed a corrupted windblossom back to health with a pair of Cenarion plant salves" },
    [1515] = { 3, "reached Dogran in a heavily guarded quilboar camp north of Camp Taurajo with the draught that gave him the strength to hobble away" },
    [1516] = { 1, "took two hooves from the Felstalkers for Canaga Earthcaller, the first test on the shaman's path toward the earth" },
    [1517] = { 3, "drank the Earth Sapta at Spirit Rock, at the end of the Hidden Path, to stand humbly before the earth and pass its rite" },
    [1518] = { 2, "carried the rough quartz from the earth spirit to Canaga Earthcaller as proof of the meeting, the heart of a first totem" },
    [1519] = { 1, "took ritual salve from the Bristleback shamans for Seer Ravenfeather, enough to make an earth sapta" },
    [1520] = { 3, "drank the Earth Sapta at the shaman shrine of Kodo Rock, binding the spirit to the earth in a young shaman's rite" },
    [1521] = { 2, "brought the rough quartz to Seer Ravenfeather as proof of meeting the earth spirit, the heart of the totem she would craft" },
    [1524] = { 1, "climbed the hidden trail above the Southfury River to the Shrine of the Dormant Flame with a torch that marked an attempt to tame fire" },
    [1525] = { 1, "won fire tar from the Razormane spellcasters and a reagent pouch from the Burning Blade cultists for Telf Joolam's fire sapta" },
    [1526] = { 3, "struck down the Minor Manifestation of Fire atop the Shrine of Eternal Flame and lit the torch from its glowing ember" },
    [1527] = { 2, "bore the Torch of Eternal Flame back to Kranal Fiss in the Barrens to receive a totem of fire" },
    [1531] = { 1, "sought out Prate Cloudseer in Thousand Needles, who gave a totem to call upon the spirits of air" },
    [1532] = { 1, "found Prate Cloudseer far to the east of Thousand Needles to receive a totem of air" },
    [1534] = { 1, "filled a waterskin at the fountain in the Ruins of Stardust in Ashenvale, the last sample Brine needed for the purest water" },
    [1535] = { 1, "filled a waterskin at the pond below Brine's hut, in quilboar country, the first sample of pure water for her sapta" },
    [1536] = { 1, "fetched water from the fresh spring well in Forsaken Tarren Mill, a holy vestige Brine remembered, for the sapta" },
    [1558] = { 1, "led a young orphan to the middle of the Stonewrought Dam in Loch Modan to look out over the great waterfall" },
    [1560] = { 2, "led Tooga, lost while fetching dinner, back to his wife Torta south of Steamwheedle Port" },
    [1578] = { 1, "forged copper axes and chain belts for Thorvald, to keep the mountaineers of Loch Modan in good gear against the troggs" },
    [1579] = { 1, "fished up the box of gaffer jacks Wizbang Cranktoggle dropped overboard on a tipsy voyage to Auberdine" },
    [1580] = { 1, "fished Wizbang Cranktoggle's lost electropellers out of the waters of Darkshore, dropped the night he passed out" },
    [1581] = { 1, "mixed elixirs for Syral Bladeleaf, whose husband spent so long brewing for their shop that they never had time for each other" },
    [1582] = { 1, "filled Lotherias's orders of embossed leather for the young adventurers of Darnassus, to learn the Moonglow Vest" },
    [1598] = { 2, "stole the Powers of the Void for Drusilla La Salle from the Defias tent in the Vineyards, a book a runaway novice took from the Abbey" },
    [1599] = { 2, "fought the Frostmane novices in their cave to the southwest for feather charms, the proof Alamar Grimm wanted before teaching the imp" },
    [1618] = { 1, "made runed copper belts and heavy copper mauls for Verner Osgood, always short of gear with Redridge under Blackrock attack" },
    [1640] = { 2, "brawled with Bartleby the drunk at the Pig and Whistle for his mug, the test Harry Burlguard set before teaching any moves" },
    [1643] = { 1, "searched Stormwind's Trade District for someone of noble intent in need of help, and found Stephanie Turner" },
    [1644] = { 2, "brought linen to Stephanie Turner so she could sew clothes for the orphans the Scourge had left in her care" },
    [1647] = { 1, "searched the outer ring of Ironforge for someone in need of a paladin's kindness, and found John Turner" },
    [1648] = { 2, "gave John Turner the linen he needed to send clothes home at last to the orphanage he and his wife run in Stormwind" },
    [1650] = { 1, "rode out to Westfall's Longshore to stand by Daphne Stilwell, left alone against the Defias while her husband was away" },
    [1651] = { 3, "defended Daphne Stilwell's home against wave after wave of Defias, a paladin's test of valour against overwhelming odds" },
    [1655] = { 1, "wrested Jordan Stilwell's ore shipment from the Mo'grosh ogres who ambushed its caravan, for Bailor Stonehand" },
    [1656] = { 1, "took a bundle of furs to Innkeeper Kauth in Bloodhoof Village for a young tauren too worn out by the Rite of Strength" },
    [1657] = { 1, "tossed Forsaken stink bombs into the heart of Southshore for Darkcaller Yanka, a Hallow's End tribute to Forsaken liberation" },
    [1658] = { 1, "scouted the Forsaken's Wickerman Festival in Tirisfal Glade for Sergeant Hartman, who feared the trouble it would bring Southshore" },
    [1667] = { 2, "recovered Marshal Haggard's badge from Dead-tooth Jack's camp, so the Defias who tricked him could not pose as an official" },
    [1678] = { 3, "took the head of Vejrek, the toughest troll near Frostmane Hold, to prove a warrior's mettle to Muren Stormpike" },
    [1681] = { 2, "avenged Tormus Deepforge's mentor on the Dark Irons of Ironband's compound and recovered the umbral ore that drew them" },
    [1683] = { 3, "destroyed the satyr Vorlus Vilehoof, who was defiling a hidden moonwell of Teldrassil, and brought his horn to Elanaria" },
    [1686] = { 2, "defeated the Shade of Elura, a captain cursed to guard her sunken cargo off Auberdine, and raised its elunite for a weapon" },
    [1687] = { 1, "took a young orphan to the haunted lighthouse off Westfall, where the ghost of Captain Grayson appeared" },
    [1688] = { 2, "hunted down Surena Caledon, the student who ran off with the Defias, for the bloodstone choker Gakin the Darkbinder wanted back" },
    [1689] = { 3, "called up a voidwalker with Gakin's bloodstone choker at the circle below the Slaughtered Lamb and bested it, to learn to command one" },
    [1690] = { 2, "drove back the Wastewander Bandits and Thieves who had seized nearly every water well around Gadgetzan" },
    [1691] = { 2, "thinned out the nomads' shadow mages, rogues and assassins so the Gadgetzan Water Company could win back its wells" },
    [1699] = { 3, "ran the Rethban Gauntlet for Yorus Barleybrew, past the gnolls to the caverns' first fork and back within the hour" },
    [1700] = { 1, "took Furen Longbeard's notes to Grimand Elmore, a proud smith who hated the idea of learning anything from his old pupil" },
    [1701] = { 2, "gathered rare materials for Furen Longbeard's fire hardened mail, braving chimaeras for some of them" },
    [1702] = { 1, "carried a cask of Barleybrew Scalder to the shieldsmith Furen Longbeard in Stormwind, to claim the shield Yorus promised" },
    [1703] = { 1, "brought Furen's notes on his new armour techniques all the way to the blacksmith Mathiel in Darnassus" },
    [1704] = { 1, "carried Furen's notes to Klockmort Spannerspan in Ironforge, who was nearly beside himself at Furen's breakthrough" },
    [1705] = { 2, "took burning blood from the Nightbane worgen of Roland's Doom and a burning rock from Gutspill, for Grimand Elmore's armour" },
    [1708] = { 1, "gathered searing coral on the coast south of Menethil Harbor for Klockmort Spannerspan, eager to try Furen's techniques" },
    [1710] = { 1, "searched below the Highperch wyvern nests for sunscorched egg shells, for armour Mathiel would make by Furen's new techniques" },
    [1712] = { 2, "gathered the items Bath'rah the Windwatcher needed to summon the wind lord Cyclonian, a test of strength and cunning" },
    [1713] = { 3, "defeated Cyclonian, the wind lord Bath'rah the Windwatcher had waited ages to see fall, and took his whirlwind heart" },
    [1719] = { 3, "passed The Affray on Fray Island, beating every challenger and then Big Will to earn Klannoc Macleod's teaching" },
    [1738] = { 2, "sought the Heartswood in the ruins of Ordil'Aran, a tree grown where two lovers fell in the War of the Ancients, to tempt a succubus" },
    [1739] = { 3, "opened a portal with the Heartswood Core in the crypt beneath the Slaughtered Lamb, and bested the succubus that came through it" },
    [1740] = { 2, "hunted the fragments of the Orb of Soran'ruk through Blackfathom Deeps and Shadowfang Keep, so Doan Karhan could make it whole again" },
    [1783] = { 3, "raised Narm Faulk with the Symbol of Life where he had fallen to the Dark Iron dwarves south of Helm's Bed Lake" },
    [1784] = { 2, "took a Dark Iron script near Helm's Bed, proof for Ironforge's doubting council that the Dark Iron were in Dun Morogh" },
    [1786] = { 3, "raised Henze Faulk with the Symbol of Life on Heroes' Vigil, where he fell holding off Defias mages so Gazin could escape" },
    [1787] = { 2, "seized the Defias rogue wizards' papers on Heroes' Vigil, proof for the king's advisors that the Defias were in Elwynn" },
    [1795] = { 3, "read the incantation from the Tome of the Cabal in Strahad Farsan's greater circle to pull forth a felhunter, then subdued it" },
    [1799] = { 2, "seized an Infernal Orb from the Mannoroc Coven's warlocks in Desolace, for Tabetha to cleanse in Dustwallow Marsh at Menara's bidding" },
    [1800] = { 1, "showed a young ward the old Lordaeron Throne Room, where Arthas took his own father's life" },
    [1802] = { 2, "pieced together the Tome of the Cabal for Krom Stoutarm, half held by the centaur of Thousand Needles, half lost off Southshore" },
    [1803] = { 2, "recovered the vandalized Tome of the Cabal for Jorah Annison, from the centaur of Thousand Needles and the coast west of Southshore" },
    [1804] = { 2, "wrested rods of channeling from the Dragonmaw spellcasters of the Wetlands, for the greater circle Strahad Farsan's acolytes would raise" },
    [1805] = { 2, "wrested rods of channeling from the Dragonmaw spellcasters of the Wetlands, for the greater circle Strahad Farsan's acolytes would raise" },
    [1819] = { 3, "unsealed Ulag the Cleaver and killed him, a Scourge captive the Deathguards had failed to free from the Lich King" },
    [1821] = { 2, "robbed the Agamand family crypt of its heirloom weapons for Coleman Farthing, whose employers in life had caused his death" },
    [1824] = { 3, "raced back from the Field of Giants with still-twitching antennae for Ruga Ragetotem, a timed trial on the warrior's path" },
    [1838] = { 1, "gathered smoky iron, azurite, iron bars and phlogiston for Thun'grim Firegaze to forge the first piece of a warrior's armour" },
    [1842] = { 1, "took the swollen hooves of satyrs leeching Ashenvale's magic, so Ula'elek could work their power into brutal gauntlets" },
    [1844] = { 2, "slew a chimaera matriarch in the ashen Charred Vale to end her misery, and brought her galvanized horn to Orm Stonehoof" },
    [1846] = { 1, "collected sturdy Dragonmaw shinbones in the Wetlands for brutal legguards by Velora Nitely, a fine armorsmith even in death" },
    [1858] = { 3, "lifted Tazan's key from Gamon, his drunken assistant, to open the satchel for Therzok, the last proof needed to join the Shattered Hand" },
    [1861] = { 1, "drew water from Mirror Lake for Jennea Cannon to test for magical taint, lest those who drank there be harmed" },
    [1880] = { 1, "recovered Bink's Mage-tastic Gizmonitor, left in a hut outside Gnomeregan when the gnomes fled, from among the leper gnomes" },
    [1882] = { 1, "picked snapdragons at the Balnir Farmstead so the Forsaken mages could measure how far the plague had crept into Tirisfal" },
    [1884] = { 2, "smashed the ju-ju heaps the warlock Zalazane had planted on the Echo Isles to twist the flow of magic in Durotar" },
    [1886] = { 2, "procured the personal effects of Astor Hadren, a messenger between Silverpine and the Undercity, as the first test of the Deathstalkers" },
    [1898] = { 1, "posed as the messenger Andron Gant expected, to learn which group he had been secretly aiding" },
    [1899] = { 2, "carried Andron's ledger to Mennet Carkad, the proof Lord Varimathras wanted of the group Andron Gant had been secretly aiding" },
    [1918] = { 1, "brought a befouled water globe from Mystral Lake to Mastok Wrilehiss, in case it held what had fouled the lake" },
    [1920] = { 2, "caught the invisible creatures loose in the Blue Recluse for Jennea Cannon, who feared a mana rift had opened there" },
    [1921] = { 1, "gathered linen and charged rift gems from the Silver Stream Mine so Wynne Larson could weave a robe fit for a mage" },
    [1938] = { 2, "retrieved Ur's Treatise on Shadow Magic from the tower of Ilgalar, where the fallen mage Morganth had taken it" },
    [1940] = { 1, "stripped pristine silk from the carrion recluses of Duskwood for a finer robe, one suited to an adept mage" },
    [1944] = { 1, "filled a flask at the highest falls of satyr-held Xavian for Deino, who sought the fabled magic of its waters" },
    [1945] = { 1, "took locks of hair from the laughing sisters of Ashenvale, dryads who would never have given it willingly, for robes from Kil'hala" },
    [1948] = { 1, "found jade and charged a bramble with lightning for Tabetha, the first materials of a mage's wand" },
    [1950] = { 1, "looked for Magus Tirth's missing apprentice around the Shimmering Flats races, for the phrase that opened his strongbox" },
    [1951] = { 2, "recovered Tirth's Rituals of Power from the Scarlet Monastery, sold off to pay his gambling debts, for Tabetha's wand ritual" },
    [1954] = { 1, "snatched an infernal orb from a Burning Blade summoner in Desolace, the vessel Tabetha needed for a staff or orb" },
    [1955] = { 2, "killed the demon Tabetha drove out of the infernal orb before it could leap back in" },
    [1956] = { 2, "defeated the obsidian sentinel in Uldaman for its ancient power source, to strengthen Tabetha's orb" },
    [1957] = { 2, "destroyed the mana surges pouring from a rift Tabetha opened, so their energy could fill the empty orb" },
    [1960] = { 2, "captured the invisible creatures of magic loose in Algernon's shop, so the Undercity's mages could learn why they had come" },
    [1961] = { 1, "took mana gems from the Dalaran mages of Silverpine for Josef Gregorian to sew into spellfire robes" },
    [1963] = { 2, "killed Tazan, the troll who traded with the pirates near Ratchet, for the satchel of information Therzok wanted" },
    [1978] = { 3, "delivered Andron's ledger, which exposed the Syndicate, to Lord Varimathras, and being welcomed into the Deathstalkers for it" },
    [1998] = { 3, "killed Fenwick Thatros, a leader of the undead that had taken root in Silverpine, at the decrepit dock on Lordamere for Lord Varimathras" },
    [1999] = { 2, "picked the locks of the Kirin Tor at Ambermill for the Dalaran Status Report, documents the Deathstalkers were charged to recover" },
    [2038] = { 2, "recovered the tools and Blastencapper explosives the troggs stole from Bingles, whose air assault on Gnomeregan depended on them" },
    [2039] = { 1, "searched Loch Modan for Bingles Blastenheimer, missing a week after a reconnaissance flight over Gnomeregan" },
    [2040] = { 2, "salvaged a goblin shredder's power supply from the Deadmines for Shoni the Shilent, to drill a way back into Gnomeregan" },
    [2078] = { 1, "led Gelkak's mechanical first mate, the Threshwackonator 4100, back to its sunken captain to deal with the murlocs" },
    [2098] = { 1, "recovered the pieces of Gelkak Gyromast's broken key from the beasts of the shore, so his first mate could work again" },
    [2118] = { 2, "trapped a rabid thistle bear alive for Tharnariun Treetender, who hoped to cure the sickness driving the bears mad" },
    [2138] = { 2, "put down rabid thistle bears for Tharnariun, his cure having failed, to slow the damage the plague did to the forest" },
    [2139] = { 3, "slew the Den Mother in her cave near Bashal'Aran, the last killing Tharnariun asked to ease the forest's pain" },
    [2160] = { 1, "brought a crate of inn supplies through the trogg-held pass to Tannok Frosthammer in Kharanos" },
    [2161] = { 1, "carried the peon Ukor's load of food to Innkeeper Grosk in Razor Hill, the peon too afraid of the beasts on the road" },
    [2178] = { 1, "hunted striders near Auberdine for their meat, to earn Alanndarian Nightsong's secret recipe for fresh strider stew" },
    [2198] = { 1, "traced a shattered, magical necklace stamped with the Ironforge seal and the letters TdK back to the jeweler who made it" },
    [2199] = { 1, "fetched silver bars for Talvash del Kissel, a jeweler ruined by a rival's rumors, for what he knew of the necklace" },
    [2200] = { 2, "searched Uldaman for the remains of the paladin who last had Talvash's necklace, to clear the jeweler of a rumored curse" },
    [2201] = { 2, "took the necklace's gems from a Shadowforge barricade, a trogg urn and the trogg leader Grimlok, as the paladin had written" },
    [2202] = { 1, "collected magenta fungus caps from the Uldaman dig site for Jarkal Mossmeld, curious about their use in alchemy" },
    [2203] = { 1, "drained blood from scorched guardian dragons into thaumaturgy vessels, a dangerous task for Jarkal Mossmeld's own recipe" },
    [2204] = { 3, "brought down Uldaman's mightiest construct for the power source Talvash del Kissel needed to restore his necklace's magic" },
    [2206] = { 2, "infiltrated the dock house at Jerod's Landing for the Defias Dockmaster's shipping schedule, proof of their smuggling to Westfall" },
    [2239] = { 1, "carried Onin's report on the long route of the king's ore tanks back to Hulfdan, so the Hidden Circle could plan its next step" },
    [2240] = { 2, "explored the hidden Chamber of Khaz'mul by Baelog's journal, a find that might move Ironforge's leaders to retake Uldaman" },
    [2241] = { 1, "delivered lovestruck Jannok's rose to Syurna, who would speak to no one but a rogue" },
    [2242] = { 2, "rifled the packs of Sethir the Ancient, a satyr who had doomed all who approached, for clues to what ailed the forests of Teldrassil" },
    [2258] = { 1, "gathered buzzard gizzards, coyote fangs and rock elemental shards to restock Jarkal Mossmeld's alchemy supplies" },
    [2278] = { 2, "learned from the stone watcher of the Discs of Norgannon the history of the Earthen, the troggs and the dwarves" },
    [2279] = { 2, "carried a miniature of the Discs of Norgannon to the Explorers' League in Ironforge, perhaps the find of the century" },
    [2280] = { 2, "presented a miniature of the Discs of Norgannon to the sages of Thunder Bluff, who sensed secrets the earth had long kept" },
    [2282] = { 2, "cracked Lucius's lockbox at Alther's Mill for the Token of Thievery, to earn a Certificate of Thievery" },
    [2283] = { 1, "searched the Uldaman dig site for a dead paladin's valuable necklace, for the salvagers Dran Droffers and son" },
    [2284] = { 1, "delved back into Uldaman for the necklace's missing gems, and found the dead paladin's bloodstained journal" },
    [2338] = { 1, "lent Jarkal Mossmeld the necklace to study in secret, in exchange for a translation of the paladin's journal" },
    [2339] = { 3, "recovered the three gems and the strongest construct's power source from Uldaman, for Jarkal Mossmeld's secret deal" },
    [2340] = { 1, "handed the necklace and gems to Dran Droffers in Orgrimmar, keeping quiet about Jarkal Mossmeld's side of the deal" },
    [2342] = { 1, "reclaimed the Garrett family weapon of choice from Uldaman for Patrick Garrett, which turned out to be a broom" },
    [2358] = { 2, "cut through Blackrock orcs until the Horns of Nez'ra, stolen from Ravenholdt manor years ago, were recovered for Arantir's Shadow" },
    [2359] = { 2, "broke into the Defias tower past its inhuman guards to learn what the chest shipped from Duskwood held, for Mathias Shaw" },
    [2381] = { 2, "boarded the Tide Razor to steal the Southsea treasure for Wrenix the Wretched, whose last five thieves came back in pieces" },
    [2398] = { 2, "searched deep in Uldaman for Baelog and his band, dwarves trapped behind trogg lines when the dig site was overrun" },
    [2418] = { 1, "gathered power stones in Uldaman for Rigglefuzz, thrown out by the Shadowforge once he had told them the stones' secret" },
    [2438] = { 1, "recovered Tallonkai Swiftroot's emerald dreamcatcher, a rare gift from the warden Gaerolas, from furbolg-held Starbreeze" },
    [2458] = { 1, "signalled Taskmaster Fizzule, the Shattered Hand's agent planted inside the Venture Co., with two flares and the Shattered Salute" },
    [2459] = { 2, "took back the emerald Ferocitas the Dream Eater had stolen from Tallonkai's dreamcatcher, and thinned his Gnarlpine mystics" },
    [2478] = { 3, "assassinated Grand Foreman Gallywix in the Venture Co. tower and stole his cache of Zanzil's altered mixture for Shenthul" },
    [2479] = { 2, "brought a sample of Zanzil's mixture to Serge Hinott in Tarren Mill, the one apothecary likely to cure its poison" },
    [2499] = { 3, "hunted down Oakenscowl, once a grand leader of the timberlings, whose gargantuan tumor spread corruption around Lake Al'Ameth" },
    [2500] = { 1, "collected gizzards, coyote fangs and elemental shards in the Badlands to restock the alchemist Ghak Healtouch" },
    [2501] = { 1, "drained blood from scorched guardian dragons in the Badlands for Ghak Healtouch, in exchange for the recipe of his brew" },
    [2518] = { 3, "ended the suffering of Lady Sathrah, a spider once beloved of Elune now gone mad, and took her silvery spinnerets" },
    [2520] = { 2, "offered Lady Sathrah's spinnerets at the temple fountain, so the holy waters could cleanse her corruption and she might be reborn" },
    [2521] = { 1, "found a flawless draenethyst sphere, among the rarest of crystals, for Kum'isha, who hoped it could open a rift home" },
    [2522] = { 1, "recovered another flawless draenethyst sphere for Kum'isha the Collector, still hopeful after the first portal home failed" },
    [2523] = { 1, "cleansed a corrupted songflower with Cenarion plant salve until it shed its tainted form and bloomed vibrant again" },
    [2541] = { 2, "took a voodoo charm from the Gnarlpine shaman for Oben Rageclaw, whose spirit they had torn from his sleeping body" },
    [2561] = { 3, "killed the soulless body of Oben Rageclaw, turned by the Gnarlpine against the Den, so his spirit could rest in the Emerald Dream" },
    [2581] = { 1, "gathered jowls, lungs and a pincer for Bloodmage Drazial, who had seen a hyena's jaws snap through thorium steel" },
    [2582] = { 1, "fetched more parts for another dose of Bloodmage Drazial's snickerfang assay, despite his warning of its lasting harm" },
    [2583] = { 1, "served as first test subject for Bloodmage Drazial's elixir of the hardy boars, after bringing him the lungs and pincers" },
    [2584] = { 1, "went back into the wasteland for more of Bloodmage Drazial's lung juice cocktail, addictive even to the strong-willed" },
    [2585] = { 1, "hunted scorpoks, vultures and a boar for Bloodmage Drazial's attempt to bottle the scorpok's grace and quickness" },
    [2586] = { 1, "traded more pincers and gizzards to Bloodmage Drazial for one sample of the scorpok assay, the other nine kept for his research" },
    [2601] = { 1, "harvested redstone basilisk brains for Bloodmage Lynnore, who had seen the beasts think more cleverly than some humanoids" },
    [2602] = { 1, "brought Bloodmage Lynnore more basilisk brains and gizzards for another dose of her compound, its focus worn off" },
    [2603] = { 1, "collected vulture gizzards for Bloodmage Lynnore, curious how carrion birds withstood the pestilence, in hope of a cure" },
    [2604] = { 1, "gathered more gizzards and jowls for Bloodmage Lynnore's gizzard gum, after its spiritual euphoria had worn off" },
    [2605] = { 1, "fetched a Laden Dew Gland from the cactus garden for Marin Noggenfogger, who hoped to brew a drink for his terrible thirst" },
    [2609] = { 2, "rounded up the makings of Doc Mixilpixil's cure for the 'itis' left by the touch of Zanzil" },
    [2621] = { 1, "asked Dispatch Commander Ruag in Stonard what became of the orders the Fallen Hero never waited for" },
    [2623] = { 2, "recovered the Warchief's orders from the Swamp Talker's cave, seized when murlocs ambushed the soldiers carrying them" },
    [2641] = { 1, "dived in a lake of the Hinterlands for a Violet Tragan, Sprinkle's secret ingredient for making Marin's foul dew drinkable" },
    [2662] = { 1, "saw Marin Noggenfogger mix dew and violet powder into the elixir he swore would make him millions" },
    [2681] = { 2, "shattered the stones that bound the Fallen Hero's men to Razelikh's service, so their tortured souls could rest" },
    [2721] = { 2, "found out what became of Lieutenant Kirith, last heard screaming under Archmage Allistarj's experiments" },
    [2742] = { 2, "escorted Rin'ji, a captured troll, out of the Quel'Danil Lodge, for the secret he swore he had hidden at the Overlook Cliffs" },
    [2744] = { 1, "sought the demon hunter Loramus Thalipedes in Azshara, since Razelikh's triad could not die within the Blasted Lands" },
    [2746] = { 1, "brought Tyrion silk and Clara's apples for the disguise that would slip Spybot past Lescovar's guards" },
    [2751] = { 2, "forged bronze bracers, greatswords and claws for Orokk Omosh, last of his line, so the Omosh recipes would not die with him" },
    [2752] = { 1, "hammered out bronze battleaxes and warhammers at Orokk Omosh's anvil, the next of his lessons in the way of the Omosh" },
    [2753] = { 1, "made green iron helms, bracers and leggings for Orokk Omosh, his second-to-last lesson in carrying on the Omosh legacy" },
    [2754] = { 1, "brought Orokk Omosh solid iron mauls and silvered bronze boots and gauntlets, the final lesson of the Omosh family forge" },
    [2755] = { 1, "watched Orokk Omosh perform the Omosh dance of joy, the last family secret of a smith who said he would now die happy" },
    [2758] = { 1, "made golden scale bracers for Hank the Hammer, who promised his old master Galvan to train every determined smith" },
    [2761] = { 1, "smelted iron and mithril bars for Galvan the Ancient, who held that an accomplished smith must be a miner too" },
    [2762] = { 1, "brought Galvan the Ancient mithril and truesilver, to learn ornate mithril gloves and that truesilver is a liar" },
    [2763] = { 1, "fortified mithril with citrines under Galvan the Ancient, a lesson in how gems amplify the magic a smith imbues" },
    [2765] = { 2, "claimed an expert blacksmith's reward from Galvan the Ancient, a trinket of greater power than the one given up to reach him" },
    [2766] = { 1, "carried Oglethorpe Obnoticus's distress beacon to his crashed homing robot near Feral Scar Vale, so it could be recovered" },
    [2767] = { 2, "escorted the robot OOX-22/FE to the dock on the Forgotten Coast, where it could start its long take-off home" },
    [2768] = { 2, "recovered the divino-matic rod Chief Engineer Bilgewhizzle needed to find new water holes, stolen by Sergeant Bly" },
    [2770] = { 3, "summoned the great beast Gahz'rilla from the trolls' sacred pool and took his electrified scale for Wizzle Brassbolts' car" },
    [2771] = { 1, "traded lessons with Trenton Lighthammer, mithril coifs and an ornate shoulder for his secret of the ornate mithril helm" },
    [2772] = { 1, "taught Trenton Lighthammer ornate mithril pants for his tournament against a Venture Co. shredder, for his ornate boots" },
    [2773] = { 1, "showed the Mithril Kid, Trenton Lighthammer, the ornate gloves he secretly could not make, for his ornate breastplate" },
    [2781] = { 3, "hunted down Caliph Scorpidsting, leader of the Wastewander outlaws, wanted for murdering Gadgetzan Water Co. employees" },
    [2782] = { 1, "showed Rin'ji's tablet of Witherbark markings to the scholar Oran Snakewrithe in the Undercity, to learn its worth" },
    [2783] = { 1, "put aside the war with the orcs to join the Fallen Hero of the Horde against the Burning Legion" },
    [2821] = { 1, "collected thick yeti hides for Pratt McGrubben, a leatherworker sure that properly treated they could be stronger than iron" },
    [2822] = { 1, "hunted yetis in Feral Scar Vale for the thick hides Jangdor Swiftstrider wanted to raise his leatherwork's mark of quality" },
    [2841] = { 2, "got Mekgineer Thermaplugg's safe combination and the rig blueprints inside the safe, so Nogg could make gnomish innovations goblin ones" },
    [2844] = { 1, "looked for Shay Leafrunner, the night elf girl who wandered off in the ruins while Rockbiter was meant to be watching her" },
    [2845] = { 2, "escorted Shay Leafrunner back to Rockbiter's camp, ringing her precious bell whenever she wandered off" },
    [2846] = { 3, "wrenched the Tiara of the Deep from the Hydromancer Velratha, who had sent thieves to steal it from Tabetha" },
    [2847] = { 1, "paid Pratt McGrubben ten thick leather to begin learning Wild Leather armour at Feathermoon Stronghold" },
    [2848] = { 1, "crafted thick armour kits and found a wildvine for Pratt McGrubben, the price of the Wild Leather shoulders pattern" },
    [2849] = { 1, "made Turtle Scale breastplates and gloves for Pratt McGrubben's orders, to earn the Wild Leather vest" },
    [2850] = { 1, "filled Pratt McGrubben's order of Nightscape tunics and headbands for the Wild Leather helmet pattern" },
    [2851] = { 1, "stitched Nightscape pants and boots and found two wildvines, to learn Pratt McGrubben's Wild Leather boots" },
    [2852] = { 1, "crafted Turtle Scale helms and bracers for Pratt McGrubben, earning the pattern for Wild Leather leggings" },
    [2853] = { 2, "took Pratt McGrubben's letter to his own teacher Telonis, to be named an equal and taught the last Wild Leather pattern" },
    [2854] = { 1, "paid Jangdor Swiftstrider ten thick leather to become his apprentice in Wild Leather armour at Camp Mojache" },
    [2855] = { 1, "crafted thick armour kits and found a wildvine for Jangdor Swiftstrider, the price of the Wild Leather shoulders pattern" },
    [2856] = { 1, "made Turtle Scale breastplates and gloves for Jangdor Swiftstrider, to earn the Wild Leather vest" },
    [2857] = { 1, "stitched Nightscape tunics and headbands for Jangdor Swiftstrider's lesson in the Wild Leather helmet" },
    [2858] = { 1, "made Nightscape pants and boots and found two wildvines, to learn Jangdor Swiftstrider's Wild Leather boots" },
    [2859] = { 1, "crafted Turtle Scale helms and bracers for Jangdor Swiftstrider, earning the pattern for Wild Leather leggings" },
    [2860] = { 2, "took Jangdor Swiftstrider's letter to his teacher Una in Thunder Bluff, to be named an equal and taught the last pattern" },
    [2862] = { 2, "took the manes of Woodpaw gnolls for Hadoken Swiftstrider, whose attacks threatened to drive Camp Mojache out of Feralas" },
    [2863] = { 2, "killed Woodpaw Alphas in quick succession, so the sudden loss of their leaders would throw the gnolls into chaos" },
    [2865] = { 1, "gathered uncracked scarab shells in Zul'Farrak for Tran'rek, the beetles having been hunted near to extinction elsewhere" },
    [2866] = { 2, "explored the Ruins of Solarsal, newly overrun by Hatecrest naga, and found the strange glyphed gazebo at their heart" },
    [2869] = { 1, "took scales from the Hatecrest naga to weaken their hold on Sardor Isle before they could claim it for their own" },
    [2870] = { 3, "slew Lord Shalzaru, a cruel naga royal, and seized the strange relic his diggers had uncovered on the Isle of Dread" },
    [2871] = { 1, "delivered the mysterious relic to Vestia Moonspear, a priestess and scholar who might work out what it was" },
    [2873] = { 1, "took back Stoley's rum from Captain Cuergo's pirate town so Stoley could settle a wager with MacKinley of Booty Bay" },
    [2874] = { 1, "settled MacKinley's bet with a bottle of Steamwheedle bilge rum, carried all the way to Booty Bay" },
    [2875] = { 3, "ended the pirate Andre Firebeard, wanted for crimes against Steamwheedle and Gadgetzan, his head standing in at his trial" },
    [2876] = { 1, "handed Steamwheedle Port a pirate's copy of its ship schedules, the sailings to Booty Bay marked with notes of loot and hard fights" },
    [2877] = { 1, "cleared sludges and oozes out of the abandoned Horde base at Skulk Rock, so the Wildhammers could extend their reach" },
    [2878] = { 1, "healed a corrupted songflower, a little Cenarion salve and it shook off its corruption and blossomed" },
    [2879] = { 3, "energized Troyas' stave with the four flames of Ravenwind to open the Equinex Monolith and the artifact sealed in it" },
    [2880] = { 1, "took tribal necklaces from the trolls choking the Hinterlands' hills, to prove some worth to the independent Wildhammers" },
    [2882] = { 2, "followed a treasure map to a beach south of Wheedle, with a mast, a flag and bones, to dig up Cuergo's gold" },
    [2902] = { 2, "searched the Woodpaw camps for the gnolls' battle plans, to learn why their attacks on Camp Mojache had grown so coordinated" },
    [2903] = { 1, "brought the Woodpaw battle plans to Hadoken Swiftstrider, which showed the gnolls fighting a war on two fronts" },
    [2904] = { 2, "led Kernobee, captured and beaten by Dark Iron dwarves, out of Gnomeregan so he could warn Tinkerwiz of their part in the new rig" },
    [2922] = { 2, "recovered Techbot's memory core in Gnomeregan for Tinkmaster Overspark, who hoped to fix his maddened creation" },
    [2924] = { 1, "collected the essential artificials left behind in the flight from Gnomeregan, which Klockmort Spannerspan needed for his experiments" },
    [2926] = { 1, "filled a phial with fallout from the irradiated troggs for Ozzie Togglevolt's cure for the sickness of Gnomeregan" },
    [2928] = { 1, "tore the guts out of Gnomeregan's robots for spare parts to fix Shoni's fleet of gyrodrillmatic excavationators" },
    [2929] = { 3, "killed Mekgineer Thermaplugg, who betrayed the gnomish people and made himself king of nothing, so Gnomeregan could be retaken" },
    [2930] = { 2, "worked through Gnomeregan's security terminals to the prismatic punch card, the vital data the gnomes left behind when they fled" },
    [2932] = { 2, "drove Nimboya's pike, laden with Witherbark skulls, into one of their villages to punish the trolls who betrayed Thrall" },
    [2933] = { 1, "carried a bottle of the vile green venom the Witherbarks hoarded to an apothecary in Tarren Mill, who might want a sample" },
    [2934] = { 1, "hunted the spiders near Shadra'Alor for an undamaged venom sac, a fresh sample for Apothecary Lydon" },
    [2936] = { 2, "defeated Theka the Martyr for the tablet bearing the Witherbark spider god's true name, so Master Gadrin could summon her" },
    [2937] = { 3, "summoned Shadra, the Witherbark spider god, at her altar in Shadra'Alor and defeated her for Apothecary Lydon's venom" },
    [2938] = { 1, "carried Shadra's venom, the most potent poison Apothecary Lydon had known, to Master Apothecary Faranell in the Undercity" },
    [2942] = { 1, "returned the Stave of Equinex and the sparkling stone from the Monolith to Troyas Moonbreeze, who named it the Morrow Stone" },
    [2943] = { 1, "brought Daryn Lightwind's old book, Feralas: A History, to Troyas Moonbreeze, who hoped it would tell what his stave was" },
    [2944] = { 1, "took a snapshot of the giant snapjaw Gammerita with the Super Snapper FX, the price of borrowing Daryn Lightwind's book" },
    [2945] = { 1, "fed a grime-caked ring from a slain Dark Iron dwarf to the Sparklematic 5200, to see what precious thing lay under the residue" },
    [2946] = { 2, "bore the miniature platinum discs to the sealed gates of Uldum for the Explorers' League, with no idea what they would wake there" },
    [2947] = { 1, "traced the initials TdK in the ring's band to its maker, who had kept a shop in Gnomeregan and wondered how the Dark Irons came by it" },
    [2948] = { 1, "brought Talvash del Kissel a silver bar, a moss agate and his fee to rework the Brilliant Gold Ring with a silver and agate lattice" },
    [2949] = { 1, "followed the NOG engraved in the ring to Nogg in Orgrimmar, who found it very interesting that the Dark Iron dwarves had it" },
    [2950] = { 1, "brought Nogg a silver bar and a moss agate to set a lattice into the Brilliant Gold Ring and strengthen its magic" },
    [2954] = { 2, "learned from the Stone Watcher of Norgannon that only the Plates of Uldum would open the way into Uldum" },
    [2962] = { 1, "collected high potency fallout from the irradiated slimes, lurkers and horrors of Gnomeregan, since Ozzie's first sample was too weak" },
    [2966] = { 2, "took the platinum discs from Uldaman to the sealed gates of Uldum, unsure what would happen, to learn the link between them" },
    [2967] = { 1, "told Nara Wildmane that the gates of Uldum wanted the Plates of Uldum, missing from the discs" },
    [2969] = { 3, "freed the sprite darters caged in the Grimtotem camp with Kindal Moonweaver, and saw the faerie dragons get away alive" },
    [2970] = { 2, "took the fight to the Grimtotem camps with Kindal and Jer'kai Moonweaver, retribution for the faerie dragons they caged" },
    [2972] = { 1, "carried Jer'kai Moonweaver's signet ring to Tyrande Whisperwind in Darnassus, as word that her priestess was well" },
    [2973] = { 1, "collected sprite darter wings so Krueg Skullsplitter could make a new cloak for Korrin, a life-mate fond of fine clothes" },
    [2974] = { 1, "took horns from the Grimtotem for Krueg Skullsplitter, since Belgrom in Orgrimmar had put a bounty on their kind" },
    [2975] = { 2, "drove back the Gordunni ogres at their outpost up the river, before they could spread any further into Feralas" },
    [2976] = { 1, "carried a crate of Grimtotem horns to Belgrom Rockmaul in Orgrimmar, with the news that the Grimtotem were in Feralas" },
    [2978] = { 1, "brought a soiled Gordunni scroll to Rok Orhan, its pictures of some meeting or ceremony found at the ogres' outpost" },
    [2979] = { 2, "took an orb from a Gordunni mage-lord so Rok Orhan could learn about the dark ceremony the ogres were planning" },
    [2980] = { 2, "pushed the stronger Gordunni out of the old night elf ruins of the High Wilderness, where the land had withered around them" },
    [2982] = { 2, "cleared ogres out of the High Wilderness ruins for Angelas Moonbreeze, to keep her Troyas safer there without his knowing" },
    [2987] = { 1, "dug up the cobalt the Gordunni bury near their outpost for Orwin Gizzmick, who meant to sell it for a pretty penny" },
    [2988] = { 2, "searched the Witherbark villages' cages for Sharpbeak, heir of Aerie Peak's mightiest gryphon, thought taken by trolls" },
    [2989] = { 2, "climbed the Altar of Zul, where the Vilebranch trolls made sacrifices, in search of the missing gryphon Sharpbeak" },
    [2990] = { 1, "delivered a feather from Sharpbeak's nest to the diviner Thadius Grimshade, whose magic might trace it to the gryphon" },
    [2991] = { 2, "took Nekrum Gutchewer's medallion for Thadius Grimshade, the price of his help in finding the gryphon Sharpbeak" },
    [2994] = { 3, "fought up Jintha'Alor and killed Vile Priestess Hexx for the key to Sharpbeak's cage, so the young gryphon could go home" },
    [2995] = { 2, "burned the Highvale records at the Quel'Danil Lodge to cut the high elves' lines of communication with would-be allies" },
    [3002] = { 1, "carried the Gordunni orb to Uthel'nay in Orgrimmar, a mage who could tell what its dangerous power was" },
    [3022] = { 1, "carried a crate of hippogryph eggs to the druid Erelas Ambersky in Rut'theran, who hatched them and trained the young" },
    [3042] = { 1, "collected troll temper from the Sandfury trolls for Trenton Lighthammer, a prized agent for tempering his wares" },
    [3062] = { 3, "summoned the harpy queen Edana Hatetalon at the Hatetalon stones and took her dark heart for Talo Thornhoof" },
    [3063] = { 2, "avenged old Talo Thornhoof on the Northspring harpies, whose ambush had haunted the hunter for years" },
    [3121] = { 1, "carried Witch Doctor Uzer'i's shrunken dwarf head to Neeru Fireblade in Orgrimmar, in trade for the herbs he needed" },
    [3122] = { 1, "brought Neeru's herb pouch back to Witch Doctor Uzer'i, the last thing he needed to prepare his muisek vessel" },
    [3124] = { 1, "killed frayfeather hippogryphs and trapped their loyal spirits in Witch Doctor Uzer'i's muisek vessel" },
    [3125] = { 1, "captured the muisek of sprite darters for Witch Doctor Uzer'i, so the Horde might share their strength of spirit" },
    [3126] = { 1, "felled wandering forest walkers and shrank their protective spirits into Witch Doctor Uzer'i's muisek vessel" },
    [3127] = { 2, "brought down mountain giants and sealed their mighty muisek in the vessel, the last spirit Witch Doctor Uzer'i needed" },
    [3128] = { 1, "gathered splintered logs, minerals, sinew and metal fragments so Witch Doctor Uzer'i could bind the muisek into weapons" },
    [3161] = { 1, "dug up Gahz'ridian ornaments, relics of the trolls' hydra god Gahz'rilla, for Marvon Rivetseeker to study" },
    [3181] = { 1, "brought Mountaineer Pebblebitty the great horn lodged with his own broken axe head, only to have him call it a fake" },
    [3182] = { 2, "proved to Curator Thorius in Ironforge that the horn was truly Margol the Rager's, the price of a key to the Searing Gorge" },
    [3201] = { 1, "carried the curator's proof of deed to Mountaineer Pebblebitty, who doubted Margol's horn was real, for the key she had promised" },
    [3281] = { 2, "recovered the Crossroads guards' stolen silver from the raptors' nests at the Raptor Grounds, their next month's pay" },
    [3301] = { 1, "delivered a glowing snapjaw shell to Mura Runetotem, who hoped its secret could heal the dying forest of Silverpine" },
    [3321] = { 1, "being welcomed into the Mithril Order by Trenton Lighthammer, who gave back the trinket sacrificed to reach Galvan" },
    [3341] = { 3, "killed the lich Amnennar the Coldbringer, who ruled the quilboar of Razorfen Downs for the Scourge, to sever his link to Ner'zhul" },
    [3361] = { 1, "recovered Felix Whindlebolt's chest, box and bucket of bolts from the trolls, lost when he fled irradiated Gnomeregan" },
    [3362] = { 1, "cleared the thistleshrubs out of Thistleshrub Valley so Tran'rek would dare go back in" },
    [3363] = { 1, "purified a songflower that Felwood's corruption had twisted, watching it blossom healthy under the Cenarion salve" },
    [3364] = { 1, "raced a scalding mornbrew to Durnan Furcutter in Anvilmar before it went cold" },
    [3367] = { 2, "tried to help the badly injured Dorius back toward Ironforge, bleeding inside and light headed" },
    [3368] = { 2, "carried Dorius' singed letter to his brother Thorius in Ironforge, a plea to free the excavation team enslaved by Lathoric the Black" },
    [3369] = { 2, "carried a shard of the Emerald Dream to Hamuul Runetotem in Thunder Bluff, a nightmare Falla would not speak of" },
    [3370] = { 2, "carried a shard of the Emerald Dream to Mathrengyl Bearwalker in Darnassus, a nightmare Falla would not speak of" },
    [3371] = { 2, "searched the Slag Pits of the Searing Gorge for Dorius's men, enslaved by the Dark Irons, to fulfil the murdered Dorius's last wish" },
    [3372] = { 2, "took a relic from the Twilight's Hammer to the Altar of Suntara, to release the archaeologists forced to work even after death" },
    [3373] = { 2, "placed the Essence of Eranikus in the font of his lair, trying to purge the trolls' taint from the green dragon's mind" },
    [3374] = { 2, "pledged to aid Ysera's Dragonflight by giving Itharius the chained essence of Eranikus, to redeem the dragon's soul" },
    [3375] = { 1, "gathered a mana potion, coal and sweet nectar so a grumbling Talvash del Kissel would make a replacement Phial of Scrying" },
    [3376] = { 3, "brought Brave Windfeather the head of Chief Sharptusk Thornmantle, whose Bristlebacks waged war on the Mesa's tauren" },
    [3378] = { 2, "recovered Zamael's golden prayer to Elune from the idol worshippers for Astarii Starseeker, so a caged soul's prayer would be heard" },
    [3379] = { 2, "hunted down the poachers slaughtering the spiders of the Searing Gorge, the source of shadow silk, for Nilith" },
    [3382] = { 3, "defended Captain Vanessa Beltis, her crew and passengers through a naga attack by night, a fight not all her crew survived" },
    [3385] = { 3, "killed Trade Master Kovic and his minion Clunk, whose cutthroat Undermarket had close ties with the Dark Iron dwarves" },
    [3442] = { 1, "collected hearts of flame and golem oil for Kalaran Windblade's torch, meant to set the Dark Iron sentry towers ablaze" },
    [3443] = { 1, "took thorium plated daggers from the Dark Iron taskmasters and slavers, to be reforged into the shaft of Kalaran Windblade's torch" },
    [3444] = { 1, "fetched a serpent-marked stone from Marvon Rivetseeker's workshop in Ratchet, to stir his memories of the Sunken Temple" },
    [3446] = { 1, "sought the Altar of Hakkar in the Sunken Temple, the secret Marvon Rivetseeker glimpsed after nearly dying in a trap" },
    [3447] = { 2, "unlocked the secret of the circle of statues in the Sunken Temple, which Marvon believed hid a greater treasure" },
    [3449] = { 1, "made rubbings of four elven runes in the Ruins of Eldarath for Tymor, then signalled Pilot Xiggs Fuselighter to fly them out of Azshara" },
    [3452] = { 1, "seized a Symbol of Ragnaros from the Twilight's Hammer camp, its foul magic meant for the casing of the torch" },
    [3463] = { 3, "set the four Dark Iron sentry towers ablaze with the Torch of Retribution, leaving their first line of defence empty" },
    [3504] = { 1, "carried Belgrom Rockmaul's sealed letter to Ag'tor Bloodfist in Azshara, after the blood elf he trusted killed the warriors he lent her" },
    [3505] = { 2, "cut down Magus Rimtori's blood elf workers in Azshara and scouted her camp for something that would draw her into a fight" },
    [3506] = { 3, "destroyed Magus Rimtori's focusing crystal and killed the blood elf, so the spirits of the orcs she betrayed could be at peace" },
    [3507] = { 1, "brought Magus Rimtori's head home to Belgrom Rockmaul in Orgrimmar, who had trusted her and wanted to see it for himself" },
    [3510] = { 3, "slew Hetaera, the false sea queen killing Lord Arkkoroc's children, for her three heads and a demon lord's true name" },
    [3511] = { 1, "carried Lord Arkkoroc's blood temper and the demon lord's true name to Loramus Thalipedes, to forge weapons against him" },
    [3513] = { 1, "took an official-looking runed scroll to the guard tower by the Ashenvale border, in case it concerned the night elves" },
    [3514] = { 3, "killed Rynthariel the Keymaster and raised a Horde flag in the Talon Den, so the Alliance would send no more runners" },
    [3517] = { 1, "found four Highborne tablets in the Ruins of Eldarath for Jediga, an orc making the most of her punishment in Azshara" },
    [3518] = { 1, "delivered the Tablet of Beth'Amara to Magatha in Thunder Bluff, who hoped it could help the Forsaken back to being human" },
    [3519] = { 1, "hurried to tell Dirania Silvershine that Iverron had been badly poisoned by a spider called Githyiss the Vile" },
    [3520] = { 2, "captured the spirits of the vale screechers of Feralas for Yeh'kinya, who said they were linked to an old, old god" },
    [3521] = { 2, "gathered hyacinth mushrooms, moonpetal lilies and webwood ichor for Dirania's antidote to the poison in Iverron" },
    [3522] = { 2, "raced Dirania's antidote to the poisoned Iverron by the spider cave before its five minutes ran out" },
    [3524] = { 1, "took bones from a beached sea creature ringed by Greymist murlocs, to learn why such beasts wash ashore" },
    [3525] = { 3, "guarded Belnistrasz as he shut down the quilboar's idol, the oven in which they consumed their captives from the Barrens" },
    [3527] = { 2, "pried the two Mosh'aru tablets from Theka the Martyr and Hydromancer Velratha, a prophecy of how to contain Hakkar's essence" },
    [3528] = { 3, "summoned the avatar of Hakkar in the Sunken Temple and captured its essence in the Egg of Hakkar for Yeh'kinya" },
    [3541] = { 1, "handed the Tablet of Jin'yael to Jes'rimon, Jediga's fence in the Drag, who had been excited to hear where it was" },
    [3542] = { 1, "took the Tablet of Markri to Andron Gant in the Undercity, for mages wishing to study Highborne summoning" },
    [3561] = { 1, "carried the Tablet of Sael'hai to Archmage Xylem in his tower above Azshara, the buyer Jediga trusted least of all" },
    [3566] = { 3, "slew Lathoric the Black and Obsidion for Thorius, only to learn the trap had been his own brother's doing" },
    [3568] = { 2, "filled vials at the tide pools of the Ruins of Eldarath so Chemist Cuely could learn what had sickened Thersa Windsong" },
    [3569] = { 2, "gave Cuely's elixir to the ailing Thersa Windsong, who had found no other cure, in the hope it would save her" },
    [3601] = { 1, "raided the Thalassian Base Camp for the equipment the blood elves kept after turning on Kim'jael, stuffed chicken and all" },
    [3602] = { 2, "recovered Azsharite crystal from the violent cliff giants' lands in southern Azshara, the body of Loramus's weapons" },
    [3621] = { 1, "took the tempered azsharite to Galvan the Ancient in Stranglethorn Vale, a smith able to harness fel energy into weapons" },
    [3627] = { 2, "slew Grol the Destroyer, Lady Sevine and Archmage Allistarj for the pieces of the amulet that summons Razelikh" },
    [3628] = { 3, "destroyed Razelikh the Defiler atop the highest mountain of the Blasted Lands, his horn a symbol of hope" },
    [3636] = { 3, "slew Amnennar the Coldbringer, the lich ruling the quilboar of Razorfen Downs, to end their unholy pact with the Scourge" },
    [3638] = { 2, "pledged life-long secrecy to the goblin engineers, giving up gnome engineering for good" },
    [3639] = { 2, "built big iron bombs, solid dynamite and explosive sheep for Nixx Sprocketspring, to earn a Goblin Engineer Membership Card" },
    [3640] = { 2, "signed the gnome engineers' pledge of secrecy for Tinkmaster Overspark, closing the door on goblin engineering for good" },
    [3641] = { 2, "made mithril tubes, a scope and target dummies for Tinkmaster Overspark, to earn a Gnome Engineer Membership Card" },
    [3642] = { 2, "swore the gnome engineers' oath of secrecy before Oglethorpe Obnoticus in Booty Bay, forsaking goblin engineering" },
    [3643] = { 2, "showed Oglethorpe Obnoticus samples of work, mithril tubes, a scope and target dummies, for a Gnome Engineer Membership Card" },
    [3661] = { 1, "collected wildkin feathers in the Hinterlands for Erelas Ambersky, who wondered whether the owlbeasts were truly made by Elune" },
    [3701] = { 2, "studied the relics in the smoldering Ruins of Thaurissan, past the assassins who guard them, for the history of the Dark Iron dwarves" },
    [3741] = { 1, "found Hilary's necklace in the lake at Lakeshire, where the children had been told not to swim" },
    [3761] = { 1, "collected Un'Goro soil, rich in magic, for the Cenarion Circle's research in Thunder Bluff" },
    [3764] = { 1, "dug up Un'Goro soil for the Cenarion Circle in Darnassus, to sort fact from falsehood about its magical qualities" },
    [3783] = { 1, "gathered thick fur from the ice thistle yetis for Umi Rumplesnicker's secret mechanical yeti, meant to impress her friends" },
    [3785] = { 1, "grew morrowgrain from Tharlendis seeds in Un'Goro soil, a mysterious herb the Arch Druid meant to unravel" },
    [3786] = { 1, "grew morrowgrain from Tharlendris seeds and Un'Goro soil for the Arch Druid, who hoped to unravel the mysterious herb" },
    [3791] = { 2, "brought morrowgrain to Quintis Jonespyre, troubled that the Arch Druid was gathering so much of it in the Circle's name" },
    [3802] = { 3, "killed Fineous Darkvire for the hammer Ironfel and set it in the hands of Franclorn Forgewright's statue, for the key to his city" },
    [3821] = { 2, "searched the Burning Steppes for Sha'ni Proudtusk, missing three weeks while watching the Firegut ogres' rituals, for her husband Thal'trak" },
    [3822] = { 3, "took Sha'ni's wedding nose-ring back from her killer Krom'Grul and carried it, with her last words, to the grieving Thal'trak" },
    [3823] = { 2, "crippled the Firegut ogres who guarded Dreadmaul Rock and the Blackrock orcs' supply lines, at the raving Oralius's orders" },
    [3824] = { 3, "chopped off the head of Gor'tesh the Brute Lord, master of the Firegut ogres, for the decisive strike Oralius planned" },
    [3825] = { 2, "planted Gor'tesh's head on a pike atop Dreadmaul Rock, to send the remaining Firegut ogres running in terror" },
    [3841] = { 1, "took a sprite darter egg, saved from a nest whose mother had died, to Quentin in Thousand Needles to see it hatched" },
    [3842] = { 1, "brought Quentin elixirs of fortitude for a small spell to protect the sprite darter egg before it hatched" },
    [3843] = { 2, "hurried the fragile sprite darter egg to Agnar Beastamer at Aerie Peak within the hour, before the hatchling could die" },
    [3844] = { 1, "searched the pond beside a wrecked raft for a clue to its owner, and pulled a water-logged pack from the bottom" },
    [3845] = { 1, "returned a lost pack to Linken at Marshal's Refuge, who only half recognized his own belongings" },
    [3861] = { 1, "found Special Chicken Feed for a befriended chicken that seemed to be spelling out a word in the dirt" },
    [3881] = { 2, "recovered food and research equipment from the overrun camps of Williden Marshal's stranded expedition, saving their lives" },
    [3882] = { 1, "dug up dinosaur bones for Spark Nilminer of Marshal Expeditions, who preferred not to know if they came from live beasts" },
    [3883] = { 2, "scraped a Gorishi hive wall for Hol'anyee Marshal, who wanted to know why the alien insects had come to Un'Goro" },
    [3884] = { 1, "returned a mangled journal to Williden Marshal, whose expedition had fled to higher ground from the crater's beasts" },
    [3901] = { 1, "thinned the rattlecage skeletons, tougher minions of the Lich King, to prove worthy of the freedom given to the Forsaken" },
    [3902] = { 1, "scavenged the crates of Deathknell for equipment, so the recruits still rising would not stumble about naked" },
    [3904] = { 2, "saved Milly Osworth's grape harvest from the overrun vineyards, before Defias thieves or trampled guards ruined it" },
    [3905] = { 1, "delivered Milly's grape manifest to Brother Neals in the abbey's bell tower, glad news of fresh grapes for more wine" },
    [3906] = { 2, "slew Overmaster Pyron, the fire lord the Dark Iron dwarves summoned, before he could plague the land with drought" },
    [3907] = { 3, "slew Lord Incendius and brought Thunderheart the tablet that named his master, Ragnaros, a general of the Old Gods" },
    [3908] = { 1, "bore Linken's sword to Donova Snowden in Winterspring to be tempered, though Linken could not remember why" },
    [3909] = { 1, "tracked down Gregan Brewspewer in the wilds of Feralas for the Videre Elixir, so Linken's sword could be finished" },
    [3912] = { 2, "drank the Videre Elixir in the graveyard outside Gadgetzan to speak with Gaeriyan, who could finish Linken's sword" },
    [3913] = { 1, "laid Linken's sword in the hollow beneath the gravestone Gaeriyan spoke of, where a flash of light transformed it" },
    [3914] = { 1, "returned the transformed sword to Linken, who still could not remember why he needed it" },
    [3921] = { 1, "took the broken samophlange to the clever Wenikee Boltbucket near Mor'shan Rampart, in the hope she could fix it" },
    [3922] = { 1, "raided Venture Company tool buckets in the Sludge Fen for nugget slugs, so Wenikee Boltbucket could start on the samophlange" },
    [3923] = { 1, "brought the battered samophlange to Rilli Greasygob in Orgrimmar, an old Venture Company hand who might mend it" },
    [3924] = { 2, "recovered the samophlange manual and its pages from Boss Copperplug, so Rilli Greasygob might learn to mend the device" },
    [3961] = { 1, "brought the Silver Totem of Aquementas to Linken, in the hope it would remind him he had come to fight Blazerunner" },
    [3962] = { 3, "broke Blazerunner's aura and defeated him on Fire Plume Ridge for the Golden Flame, a power too dangerous for an evil heart" },
    [3981] = { 2, "found Commander Gor'shak in the prisons of Blackrock Depths, after a note on an arrow showed him behind bars" },
    [3982] = { 2, "held off the Dark Iron guards come for Gor'shak, who had let himself be captured to gather intelligence for Thrall" },
    [4001] = { 2, "questioned Kharan Mighthammer about the kidnapping of Princess Moira Bronzebeard and carried all he knew to Thrall" },
    [4003] = { 3, "slew Emperor Dagran Thaurissan to break his spell on Princess Moira Bronzebeard, without harming her, for Thrall" },
    [4004] = { 2, "brought Thrall the news that Moira carried Thaurissan's child, an unborn Dark Iron who might one day rule Ironforge" },
    [4005] = { 2, "summoned Aquementas at Lost Rigger Cove with the Book of Aquor to forge a totem that could break Blazerunner's aura" },
    [4021] = { 3, "fought the vengeful Kolkar from Desolace until Warlord Krom'zar appeared, and took a piece of his banner" },
    [4024] = { 2, "slew the fire giant Bael'Gar and captured his inner flame in a dragonflight molt, for Cyrus Therepentous, who craved its heat" },
    [4061] = { 2, "pried shards from the rock automatons of the Burning Steppes so Theodora Mulvadania could trace where the golems were coming from" },
    [4062] = { 2, "brought Lotwil Veriatus a shard marked G.L.A. from the machines destroyed in the Burning Steppes, to learn who had made them" },
    [4063] = { 3, "destroyed Golem Lord Argelmach for Lotwil, who had killed him once before, only to find the head was another machine" },
    [4081] = { 2, "cut down General Angerforge's first line in Blackrock Depths, the killers of the K.E.F.'s 109th division, for Warlord Goretooth" },
    [4082] = { 2, "struck at the high-ranking Dark Iron officials training their forces to snuff out the Kargath Expeditionary Force" },
    [4084] = { 1, "collected silvery claws and an irontree heart in Felwood for Eridan Bluewind, toward a power to dispel Blazerunner's aura" },
    [4101] = { 1, "gathered blood amber from the Warpwood elementals of Irontree Caverns, for Arathandris Silversky to study in hope of saving the rest of Felwood" },
    [4102] = { 1, "cut blood amber from Warpwood elementals beyond hope of cleansing, so Maybess Riverbreeze could seek a way past Felwood's corruption" },
    [4113] = { 1, "restored another corrupted songflower with Cenarion plant salve, one more plant of Felwood blooming clean" },
    [4114] = { 1, "salved a sick songflower back to health, its corrupted form falling away into a vibrant bloom" },
    [4115] = { 1, "purified a corrupted windblossom, two salves from the Cenarion Circle and it bloomed vibrant again" },
    [4116] = { 1, "treated a corrupted songflower with Cenarion plant salve and saw it blossom into a healthy plant" },
    [4117] = { 1, "worked three Cenarion plant salves into a corrupted whipper root until it shed its corruption and grew healthy" },
    [4118] = { 1, "revived a songflower from its corruption with a dose of Cenarion plant salve" },
    [4119] = { 1, "poured four Cenarion plant salves on a corrupted Night Dragon plant until it shed its corruption and bloomed healthy" },
    [4120] = { 1, "faced the fel-maddened bears and wolves of Felwood for Talo Thornhoof, to learn whether the corruption made them stronger" },
    [4121] = { 2, "marched the traitor Grark Lorkrub in shackles through Blackrock Mountain to Lexlort's men waiting in the Searing Gorge" },
    [4122] = { 2, "bound Grark Lorkrub, caught selling the K.E.F.'s secrets to the Blackrock orcs, in their fortress in the Burning Steppes" },
    [4123] = { 2, "breached the Lower Vault and defeated Watchman Doomgrip for the Heart of the Mountain, the gem Maxwort Uberglint had sought for years" },
    [4125] = { 2, "searched the Feralas coast for the boat of Raschal, a Feathermoon courier missing for a week" },
    [4126] = { 2, "smashed Dark Iron kegs and took back the Thunderbrew Lager recipe Hurley Blackbreath stole, for Ragnar Thunderbrew" },
    [4127] = { 1, "brought Ginro Hearthkindle a knife found in the mud by Raschal's wrecked boat, the first clue to the courier's fate" },
    [4129] = { 1, "took Raschal's knife to the druid Quintis Jonespyre, whose psychometry might show what had befallen the courier" },
    [4131] = { 2, "tore into the Woodpaw gnoll camps in search of Raschal's backpacks, the next trace of the missing courier" },
    [4132] = { 3, "slew General Angerforge, who ordered the slaughter of the K.E.F.'s 109th division, to bring him to justice for Warlord Goretooth" },
    [4134] = { 2, "took the stolen Thunderbrew Lager recipe from Hurley Blackbreath for Vivian Lagrave, who wanted its virtues turned to Forsaken ends" },
    [4135] = { 2, "followed Raschal's hasty note into the Writhing Deep, where he had gone after insects he feared threatened all of Feralas" },
    [4136] = { 2, "tracked Ribbly Screwspigot into Blackrock Depths for his sister Yuka, who wanted him or his head for Baron Revilgaz's bounty" },
    [4141] = { 1, "picked bloodpetals for Muigin, who hoped to train the crater's plant creatures to pester Larion, whom he blamed for it all" },
    [4142] = { 1, "showed a bloodpetal to Gregan Brewspewer in Feralas, an expert who might explain the plants' strange intelligence" },
    [4143] = { 1, "gathered Atal'ai haze in the temple of Atal'Hakkar for Muigin, the horrid stuff that would let him control the bloodpetals" },
    [4145] = { 1, "cut down the bloodpetal pests Muigin kept sending to annoy Larion, who blamed him for getting them lost" },
    [4146] = { 1, "collected Atal'ai haze from the temple's oozes and lurkers to fuel a bug zapper against the Bloodpetal pests" },
    [4161] = { 1, "collected only the spider legs Zarrin asked for, a lesson in the kaldorei balance of taking from nature no more than needed" },
    [4182] = { 2, "pushed back the black dragonkin gathered below Helendis Riverhorn's ridge in the Burning Steppes" },
    [4183] = { 1, "carried Helendis Riverhorn's warning to Magistrate Solomon: the black dragonflight was the true master of the Blackrock orcs" },
    [4184] = { 2, "pleaded Lakeshire's case before Highlord Bolvar Fordragon, for the town could not survive both the Blackrock orcs and the black dragons" },
    [4186] = { 1, "returned to Lakeshire with Bolvar's decree, a deputy of Stormwind on whose shoulders the town's fate now rested" },
    [4201] = { 1, "fetched gromsblood, giant silver veins and Golakka spring water for Mistress Nagmara's love potion, aimed at Private Rocknot" },
    [4221] = { 1, "healed a windblossom gone foul in Felwood, two Cenarion salves bringing back a vibrant bloom" },
    [4222] = { 1, "restored a corrupted windblossom with two Cenarion plant salves, one more plant taken back from the corruption" },
    [4224] = { 1, "found Ragged John in his cave to learn what became of Marshal Windsor and the intelligence on the Blackrock lost with him" },
    [4241] = { 2, "searched Blackrock Depths for Marshal Windsor, to bring him back alive or proof he was dead, for Marshal Maxwell" },
    [4242] = { 1, "broke the news to Marshal Maxwell that Windsor had lost his proof and, it seemed, his mind" },
    [4243] = { 1, "searched the apes' lair at Fungal Rock for A-Me 01, Karna Remtravel's mechanical ape, and found her dented and powerless" },
    [4244] = { 1, "fitted a new mithril casing into A-Me 01 so Karna Remtravel's mechanical ape might run again" },
    [4245] = { 2, "escorted the battered A-Me 01 back to Karna Remtravel past the gorillas of Un'Goro" },
    [4261] = { 3, "led the ancient spirit Arei out of Felwood, trapped in the land's suffering since the Legion came, so it might finally rest" },
    [4262] = { 2, "killed Overmaster Pyron at the Blackrock Quarry so Jalinda Sprig's expedition could get into Blackrock Depths" },
    [4263] = { 3, "destroyed Lord Incendius, the minion of Ragnaros who kept raising Pyron from the ashes, for Jalinda" },
    [4264] = { 2, "showed Marshal Windsor a crumpled note of Thaurissan's, a sign his stolen notes were not lost but being decrypted" },
    [4265] = { 3, "freed Raschal, the missing Feathermoon courier, alive from a pod in the Zukk'ash hive" },
    [4267] = { 1, "carried Raschal's report on the infestation to Gracina Spiritmight in Darnassus, a priestess who knew such creatures" },
    [4281] = { 1, "delivered the parcel the missing courier never brought to Falfindel Waywarder at the Thalanaar way-station" },
    [4282] = { 3, "killed General Angerforge and Golem Lord Argelmach to take back the lost information Marshal Windsor needed as proof" },
    [4283] = { 1, "stripped Blackrock medallions off the orcs for Oralius, who wanted badges to go with his ogre ear collection" },
    [4284] = { 1, "collected power crystals of four colors for J.D. Collie, who sensed a power in them her experiments had yet to find" },
    [4285] = { 1, "found the northern crystal pylon for J.D. Collie, who could not stop wondering what the pylons were for" },
    [4286] = { 1, "stripped Dark Iron fanny packs from the dwarves of Blackrock Depths for Oralius, who wanted the good stuff inside" },
    [4287] = { 1, "located the eastern crystal pylon to put J.D. Collie's curiosity about the rumored pylons to rest" },
    [4288] = { 1, "sought out the western crystal pylon, in the hope it held the key to J.D. Collie's fruitless crystal experiments" },
    [4289] = { 1, "skinned the great apes of northern Un'Goro for Torwa Pathfinder, pelts to clothe the tribe and proof of strength" },
    [4290] = { 2, "stole meat from Lar'korwi's freshest kill to provoke the beast that had once hunted down Torwa Pathfinder's brother" },
    [4291] = { 1, "provoked Lar'korwi's ravasaur mates for their pheromone glands, the bait Torwa Pathfinder needed to draw him out" },
    [4292] = { 3, "baited Lar'korwi with stolen meat and his mates' scent, and brought the monster's head to Torwa Pathfinder" },
    [4293] = { 1, "tested slime samples from Felwood for the most corrupt, so Chemist Fuely could study the creatures of its Fel-touched pools" },
    [4294] = { 1, "collected the purest slimes of Un'Goro Crater for Chemist Fuely, who wondered how creatures untouched by corruption evolved" },
    [4296] = { 1, "copied the Tablet of the Seven in the ruins of Thaurissan for Maxwort Uberglint, who hoped its dwarven lore would make them rich" },
    [4297] = { 1, "hunted Silvermane stalkers for raw flanks so the sprite darter hatchling would have something to eat" },
    [4298] = { 1, "took the newly hatched sprite darter from Agnar Beastamer, so it would bond to its new parent" },
    [4300] = { 1, "sought out the rare white-clawed ravasaurs of Un'Goro Crater for Jes'rimon of the Hand, whose clients liked weapons crafted from those claws" },
    [4301] = { 2, "bested U'cha, the huge ape Torwa Pathfinder called one of the Earth Mother's greatest sons, and brought back his pelt" },
    [4322] = { 3, "helped Marshal Windsor recover his gear and free his friends from Blackrock Depths before he set off to confront Bolvar" },
    [4341] = { 2, "found Kharan Mighthammer in the prisons of Blackrock Depths for King Magni, who wanted answers about his missing daughter" },
    [4343] = { 1, "anointed a corrupted windblossom with two Cenarion salves and watched it shed the corruption" },
    [4361] = { 1, "bore Kharan's tale back to King Magni Bronzebeard in Ironforge, bad news of his daughter Moira" },
    [4362] = { 3, "killed Emperor Dagran Thaurissan to break his spell on Princess Moira, the only way King Magni saw to save his daughter" },
    [4363] = { 2, "told King Magni, as Moira demanded, that the heir to Ironforge would be a Dark Iron, her child by Thaurissan" },
    [4401] = { 1, "tended a corrupted songflower with Cenarion salve until it bloomed bright and whole" },
    [4402] = { 1, "picked cactus apples for Galgar's famous cactus apple surprise, a treat against the heat of the valley" },
    [4403] = { 1, "treated a twisted windblossom with Cenarion plant salves until it blossomed whole and healthy" },
    [4421] = { 3, "killed Xavathras and his Jadefire satyrs at the Ruins of Constellas, who spread the corruption to every creature, for Eridan Bluewind" },
    [4441] = { 2, "fetched blessed water from the Temple of the Moon so Eridan Bluewind could try to free the ancient bound in Xavaric's flute" },
    [4443] = { 1, "cleansed a corrupted whipper root with three doses of Cenarion salve, leaving a vibrant, healthy plant" },
    [4444] = { 1, "healed a whipper root sick with Felwood's corruption, three Cenarion salves to bring it back" },
    [4445] = { 1, "purified a corrupted whipper root, three Cenarion plant salves and it blossomed anew" },
    [4446] = { 1, "saved a corrupted whipper root with three Cenarion plant salves, the taint falling away from it at once" },
    [4447] = { 1, "cleansed a corrupted Night Dragon plant with four Cenarion salves, one more of Felwood's plants won back" },
    [4448] = { 1, "revived a Night Dragon plant from Felwood's corruption, four doses of Cenarion salve to make it vibrant again" },
    [4449] = { 1, "taught the Dark Iron Geologists a lesson for the dwarf they locked in an outhouse, who also wanted silk cloth for reasons unsaid" },
    [4450] = { 1, "rounded up the goods on Krinkle Goodsteel's ledger and took them to him in Gadgetzan, a job the outhouse prisoner had left unfinished" },
    [4451] = { 1, "found the Grimesilt Outhouse Key and turned it to let ol' Locheed out of the outhouse the Dark Irons had locked" },
    [4461] = { 1, "restored a whipper root twisted by corruption, three Cenarion salves turning it vibrant and healthy" },
    [4462] = { 1, "healed a corrupted Night Dragon plant with four Cenarion plant salves, the plant blossoming healthy at once" },
    [4464] = { 1, "mended a songflower twisted by corruption, the Cenarion salve turning it vibrant in moments" },
    [4465] = { 1, "freed a songflower from Felwood's corruption with Cenarion plant salve, so it could bloom healthy again" },
    [4466] = { 1, "cured a corrupted windblossom with a double dose of Cenarion salve, its blossoms coming back vibrant" },
    [4467] = { 1, "reclaimed a windblossom from the corruption with two Cenarion plant salves" },
    [4490] = { 2, "received from Strahad Farsan the power to summon a felsteed, his reward for patience and hard work" },
    [4491] = { 3, "led Ringo, overcome by heat on Fire Plume Ridge, back to his friend Spraggle Frock, with a canteen ready in case he fainted" },
    [4492] = { 1, "looked for Ringo on Fire Plume Ridge, a friend Spraggle Frock feared for after he went exploring the volcano" },
    [4495] = { 1, "looked for Iverron, hours late for his daily visit to Dirania, near the spider-filled cave to the north" },
    [4496] = { 1, "gathered a Gorishi scent gland and Un'Goro soil for Pestlezugg's lure, meant to draw out the silithid hive queen" },
    [4501] = { 1, "thinned the pterrordax that menaced the crater's travellers, so the terrified Spraggle Frock might dare to leave camp" },
    [4502] = { 1, "gathered ash from the volcano's fire elementals for Liv Rizzlefix in Ratchet, who studied the crater's volcanic activity" },
    [4503] = { 1, "collected webbed scales from pterrordaxes and diemetradons for the wings of Shizzle's flying machine, his way home" },
    [4504] = { 1, "collected tar off the beasts of the Un'Goro tar pits for Tran'rek's latest scheme to earn a quick gold" },
    [4505] = { 1, "drew water from the Jadefire satyrs' corrupted moonwell for Winna Hazzard, who meant to turn the corruption against the Alliance" },
    [4506] = { 2, "loosed Winna Hazzard's kitten by the corrupted moonwell and brought it back, her experiment in making corrupted sabers for the Horde" },
    [4507] = { 3, "lured out the Gorishi Hive Queen and slew her, then brought her brain to Pestlezugg to study the silithid" },
    [4508] = { 1, "carried Pestlezugg's Un'Goro report to Gracina Spiritmight, in hope the Alliance's leaders would heed the silithid threat" },
    [4509] = { 1, "carried Pestlezugg's Un'Goro report to Zilzibin Drumlore, in hope the Horde's leaders would heed the silithid threat" },
    [4512] = { 1, "collected samples from the cursed and tainted oozes of Felwood for Laris Geardawdle, who wanted to know where all the ooze comes from" },
    [4513] = { 1, "hunted for pure ooze samples, untouched by any corruption, for Laris Geardawdle, who believed oozes take on the aspects of their land" },
    [4521] = { 1, "cleared the owlbeasts of Winterspring for Trull Failbane, who suspected the wildkin guarded secrets of the night elves" },
    [4542] = { 1, "carried an urgent warning of renewed centaur attacks to Cliffwatcher Longhorn at Freewind Post" },
    [4581] = { 1, "carried Shindrell's report to the druid Kayneth Stillwind, who feared a corruption moving through Ashenvale" },
    [4621] = { 3, "killed Fleet Master Seahorn and Baron Revilgaz of Booty Bay, so the Bloodsail could sail free, and became their admiral" },
    [4642] = { 1, "released a Felwood ooze beside a primal Un'Goro ooze for Chemist Fuely, and brought back what was left of the meeting" },
    [4681] = { 2, "dived to a skeletal sea turtle west of Auberdine, a solid chance at learning why the sea creatures beach themselves" },
    [4701] = { 3, "destroyed Halycon, the corrupt beast at the source of the Blackrock orcs' worgs, whose numbers never dwindled" },
    [4721] = { 2, "culled the berserk owlbeasts by the caves of southern Winterspring, maddened by the very thing Trull Failbane hoped they guarded" },
    [4722] = { 1, "scraped samples from a sea turtle beached long ago, scavenged by the murlocs camped around it, for the Temple of the Moon" },
    [4723] = { 1, "took bones from a giant thresher beached on the Mist's Edge, far too big for the murlocs feasting on it to have killed" },
    [4724] = { 3, "slew Halycon, gigantic den mother of the Bloodaxe worgs, and lived through her mate Gizrul the Slavener" },
    [4725] = { 2, "found a strangely marked box on a beached turtle's carriage, naga work that explained their presence in Darkshore" },
    [4726] = { 1, "caught broodling essence with Tinkee Steamboil's Draco-Incarcinatrix 900, for her study of the dragon whelps" },
    [4727] = { 1, "sampled a turtle carcass on the northern beaches that even the Greymist murlocs seemed to shy away from" },
    [4728] = { 1, "gathered a sample from a beached sea creature the Explorer's League had been studying until murlocs chased them out" },
    [4729] = { 1, "caught a Bloodaxe worg pup in Blackrock Spire for Kibler, who tamed exotic beasts as pets for the rich" },
    [4730] = { 1, "cut bone from a half-devoured sea creature guarded by stronger murlocs, for Gwennyth's study of the beachings" },
    [4731] = { 1, "carried another naga box from a beached turtle's carriage to Gwennyth, who wondered if it had been bound for Ashenvale" },
    [4732] = { 1, "salvaged what the Greymist murlocs had left of a beached sea turtle, for the Temple of the Moon to study" },
    [4733] = { 1, "brought back bones of a thresher several times larger than any in these parts, washed up on the Twilight Shore" },
    [4734] = { 1, "tested Tinkee Steamboil's eggscilloscope on a black dragon egg in the Rookery, high in Blackrock Spire" },
    [4735] = { 1, "froze and collected black dragon eggs from the Rookery for Tinkee Steamboil and her patron" },
    [4740] = { 3, "slew Murkdeep, the murloc blamed for a Sentinel's death and two sunken cargo vessels, so Auberdine could sleep soundly" },
    [4741] = { 1, "hunted the moontouched owlbeasts of northern Winterspring, fiercer still, to push Trull Failbane's search deeper" },
    [4742] = { 2, "took the three gemstones of command from the generals of the lower spire, to adorn Vaelan's Seal of Ascension" },
    [4743] = { 3, "broke the will of the ancient drake Emberstrife in the Wyrmbog and forced his flame upon the Seal of Ascension" },
    [4762] = { 2, "drew a sample of the fouling Cliffspring River for Thundris Windweaver, who feared its taint would reach Auberdine" },
    [4763] = { 3, "lured out the satyr corruptor with a cleansing bowl for its Talisman of Corruption, which might one day free the furbolgs" },
    [4764] = { 1, "found Doomrigger's Clasp, a gem-encrusted dwarven relic, in the ruined Hall of Fortune for Mayara Brightwing's patron" },
    [4765] = { 1, "delivered the crated Doomrigger's Clasp to Count Remington Ridgewell in Stormwind for his family museum" },
    [4767] = { 1, "gathered wyvern eggs at Highperch for Elu, who needed more wyverns for the wind riders and hoped to become one" },
    [4768] = { 1, "recovered the Darkstone Tablet, the mad alchemist Urheld Darkstone's research, from Blackrock Spire for Vivian Lagrave" },
    [4770] = { 3, "escorted Pao'ka Swiftmountain, lost for days after getting too close to the wyvern nests, out of Highperch to Whitereach Post" },
    [4771] = { 3, "planted Dawn's Gambit in the Scholomance's viewing room and defeated the undead mage Vectus and his scourge scholars" },
    [4787] = { 2, "recovered the ancient egg from a cave high in Jintha'Alor for Yeh'kinya, the relic he hoped could hold the essence of Hakkar" },
    [4788] = { 2, "took the last Mosh'aru tablets from the Smolderthorn trolls of the spire for Prospector Ironboot, who feared what was coming" },
    [4808] = { 1, "carried Tinkee's letter to Felnok Steelspring in Everlook, asking for parts to freeze dragon whelp eggs" },
    [4809] = { 1, "collected uncracked chillwind horns, packed with cold, so Felnok Steelspring could complete Tinkee's order" },
    [4810] = { 1, "carried Felnok's package of chillwind horns to Tinkee Steamboil in the Burning Steppes, along with the reminder that she owed Felnok" },
    [4811] = { 2, "searched the eastern mountains for the red crystal said to draw hostile moonkin, for Sentinel Glynda Nal'Shea" },
    [4812] = { 2, "poured moonwell water over the red crystal, which turned clear to show bone fragments and half a jawbone inside" },
    [4821] = { 2, "took the alien egg from a serpent den for Hagar Lightninghoof, who wanted to know what the serpents guarded so closely" },
    [4822] = { 1, "bought a young ward Tigule and Foror's Strawberry Ice Cream, to him the best strawberry ice cream in the world" },
    [4841] = { 2, "attacked the Galak centaur camp north of Freewind Post in revenge for the caravan they had slaughtered" },
    [4842] = { 2, "followed Donova Snowden's directions to the dark, muggy south of Winterspring, where demons in Darkwhisper Gorge seemed to be heating the springs" },
    [4861] = { 1, "braved the wildkin to reach Jaron Stoneshaper's wrecked camp, which he had barely escaped and where he feared a friend had not" },
    [4862] = { 1, "collected spire spider eggs for Kibler, who had sent Bijou after them and not heard from her in weeks" },
    [4864] = { 2, "pulled Jaron Stoneshaper's tools from the snow and took back the amulet he had unearthed from the wildkin who guarded it so fiercely" },
    [4865] = { 1, "brought word to Motega Firemane that the legend of Arikara was true, and that vengeance had come to Thousand Needles" },
    [4866] = { 1, "got deliberately poisoned by Mother Smolderweb, so Ragged John could milk the venom for his ale" },
    [4867] = { 1, "got back Warosh's mojo in Blackrock Spire, to lift the curse Urok had laid on his mind" },
    [4881] = { 2, "warned Kanati Greycloud of the centaur plot to kill him for daring to set up a hunting camp" },
    [4882] = { 1, "showed a glowing Blue-feathered Necklace from a slain wildkin to Trull Failbane, who knew the owlbeasts better than most" },
    [4883] = { 2, "took the wildkin's necklace to Nara Wildmane, who sensed that Elune had made the wildkin to guard her most sacred places" },
    [4901] = { 3, "lit the cave torches with Ranshalla and guarded her while she recited the incantations of Kel'Theril to open the Altar of Elune" },
    [4902] = { 1, "told Arch Druid Fandral Staghelm of the Altar of Elune, only to learn the Circle had long known the wildkin were Elune's guardians" },
    [4903] = { 3, "killed Highlord Omokk, War Master Voone and Overlord Wyrmthalak and seized their documents for Warlord Goretooth" },
    [4904] = { 3, "escorted Lakota Windsong out of Darkcloud Pinnacle, where Arnak had taken her after killing her brother, back to Thalia" },
    [4906] = { 3, "slew Xavaric, who reaped the spoils of the corrupted moonwell, and his Jadefire betrayers to the north, for Eridan Bluewind" },
    [4921] = { 2, "searched the Barrens for some sign of Mankrik's wife, lost when the Bristlebacks overwhelmed their camp" },
    [4941] = { 1, "carried word to Eitrigg and then to Thrall that Rend, thought slain decades ago, still lived" },
    [4961] = { 3, "killed the Demon of the Orb as soon as Tabetha drew it out, before it could slip back inside, so the Infernal Orb could be cleansed" },
    [4962] = { 2, "captured the soul of a Desolace felhound in the Felhas Ruby, for Menara Voidrender to merge with the cleansed orb" },
    [4963] = { 2, "trapped the spirit of a Desolace infernal in the Infus Emerald, for Menara Voidrender to merge with the cleansed orb" },
    [4966] = { 3, "stood with Kanati Greycloud against the centaur assassins sent to kill him" },
    [4970] = { 1, "gathered shardtooth and chillwind meat to feed the frostsabers Rivern Frostwind was training" },
    [4971] = { 2, "rooted out the temporal parasites of Andorhal's silos so Chromie could mend the timeline she believed the Scourge had altered" },
    [4972] = { 1, "searched Andorhal's rubble for lockboxed watches trapped since the plague, which Chromie needed to mend the town's time" },
    [4973] = { 1, "turned up more Andorhal watches for Chromie, to help her hold back whatever was meddling with the town's timeline" },
    [4974] = { 3, "took the head of Warchief Rend Blackhand to Thrall in Orgrimmar, a crippling blow to the Blackrock orcs" },
    [4976] = { 1, "returned the cleansed Infernal Orb to Menara Voidrender, to have a demon of choice imprisoned within it" },
    [4981] = { 1, "tracked down Bijou in Blackrock Spire, a goblin operative who had spent Horde funds while working for Kibler" },
    [4982] = { 1, "recovered the recon gear Bijou had stashed in the spire after she set off an alarm, the price of her return" },
    [4983] = { 1, "carried Bijou's reconnaissance report to Grandmaster Lexlort in Kargath, an advantage over the Blackrock orcs" },
    [4984] = { 1, "put the diseased wolves out of their misery for Mulgris Deepriver, a tauren druid come to heal the plague's harm" },
    [4985] = { 2, "ended the torment of the diseased grizzlies near the eastern border, the last thing Mulgris Deepriver asked before he died" },
    [4986] = { 2, "carried Mulgris Deepriver's glyphed branch to the Cenarion Circle in Darnassus, with all he knew of the plague" },
    [4987] = { 2, "brought Mulgris Deepriver's glyphed branch to the Cenarion Circle in Thunder Bluff, with all he had learned of the plague" },
    [5001] = { 1, "recovered the goblin Bijou's belongings in Blackrock Spire in exchange for what she had learned of the Blackrock threat" },
    [5002] = { 1, "brought Bijou's map to Marshal Maxwell, marking where Nefarian's lieutenants held the lower citadel" },
    [5021] = { 1, "searched the Felstone barn for the package a frightened ghost still begged to have delivered, four years too late" },
    [5022] = { 1, "asked the Stormwind census after Emma Felstone, to whom the ghost's package had been addressed more than four years before" },
    [5023] = { 1, "traced Jeremiah Felstone through the Undercity census, so the ghost's long-overdue package could reach him" },
    [5041] = { 1, "recovered the supply crates the Razormane had taken in their raid, supplies the Crossroads desperately needed" },
    [5047] = { 1, "carried a glowing piece of flesh, snatched by Finkle Einhorn from the beast's innards, to Malyfous Darkhammer in Everlook" },
    [5048] = { 2, "sought out Ol' Emma, the muttering old woman of Stormwind, who was indeed Emma Felstone, with a package from her sister Janice" },
    [5049] = { 1, "found Jeremiah Payson, the Undercity cockroach vendor, to give him a package from his long-dead sister Janice Felstone" },
    [5050] = { 2, "returned half of a good luck charm to the ghost of Janice Felstone, in the hope her sister's things would let her rest" },
    [5051] = { 3, "pieced the Felstone good luck charm together from its lost half, which at last freed the ghost of Janice Felstone" },
    [5052] = { 1, "brought Mangletooth a Bristleback blood shard, to show an understanding of Agamaggan's magic and earn his blessings" },
    [5054] = { 2, "hunted Ursius of the shardtooth bears for Storm Shadowhoof, a clever beast that had turned everyone sent after him into prey" },
    [5055] = { 2, "tracked down Brumeran of the chillwind, a graceful chimaera whose path had cost many their lives, as Storm Shadowhoof's next test" },
    [5056] = { 3, "called Shy-Rotam, matriarch of the frostsabers, to her stone with the sacred meat of her kin and defeated her, Storm Shadowhoof's final test" },
    [5057] = { 1, "carried Storm Shadowhoof's marker to Melor Stonehoof in Thunder Bluff, in remembrance of the great beasts of Winterspring brought down" },
    [5058] = { 1, "read the last entry in Mrs. Dalson's diary, written after her husband Harold had turned and she had locked him away" },
    [5059] = { 2, "unlocked the Dalson outhouse with the key from Mrs. Dalson's skeleton, and faced the ghoul her husband had become" },
    [5060] = { 1, "opened the Dalson cabinet with the key from the farmer's ghoulish remains, where the family's last valuables lay intact" },
    [5062] = { 1, "harvested Incendia agave for Magatha Grimtotem to enchant into a powder that would summon Arikara" },
    [5063] = { 1, "brought Malyfous Darkhammer the pristine hide of the Beast and the rest of the components for a Cap of the Scarlet Savant" },
    [5064] = { 2, "stole three secret notes from Darkcloud Pinnacle, to learn what the Grimtotem were plotting with unknown agents" },
    [5065] = { 2, "pried the third and fourth Tablets of Mosh'aru from the mossflayer trolls for Prospector Ironboot, who feared their secrets" },
    [5067] = { 1, "gathered the pristine hide of the Beast and Frostwhisper's embalming fluid for Malyfous Darkhammer's attempt at the never-made Leggings of Arcana" },
    [5068] = { 1, "sought out the components for a Breastplate of Bloodthirst, a piece said to have been made only once, for the assassin Garona" },
    [5081] = { 3, "destroyed War Master Voone, Highlord Omokk and Overlord Wyrmthalak to throw the Blackrock command into chaos" },
    [5082] = { 2, "fought back the Winterfall furbolg, grown fiercely protective of the hot springs, so Donova Snowden could get back to studying their water" },
    [5083] = { 1, "showed Donova Snowden an empty Winterfall flask that still held a few glowing green drops" },
    [5084] = { 2, "searched the corrupted Deadwood furbolg camp in Felwood for signs of dealings between the Deadwood and the Winterfall" },
    [5085] = { 1, "brought a sample of the Deadwood cauldron's green goo to Donova Snowden, afraid the Winterfall would soon be as corrupted as the Deadwood" },
    [5086] = { 2, "collected droplets from the toxic horrors of the Irontree Woods so Donova could compare them with the cauldron's goo" },
    [5087] = { 2, "stopped the Winterfall Runners on their way from Felwood and took their shipment, to cut off the Winterfall from the Deadwood" },
    [5088] = { 3, "summoned Arikara at the sacred fire of life and slew her, a creature Magatha feared was stalking Cairne Bloodhoof" },
    [5089] = { 1, "brought Marshal Maxwell a letter from General Drakkisath, found on the corpse of a slain serpent" },
    [5092] = { 2, "thinned the undead of Sorrow Hill so Commander Ashlam Valorfist could strike at Andorhal by its weaker eastern road" },
    [5096] = { 2, "burned the Scarlet Crusade's command tent and left a Scourge banner there, so the Crusade would avenge it on the Scourge" },
    [5097] = { 2, "marked Andorhal's four watchtowers with a beacon torch, targets for Commander Ashlam Valorfist's troops to strike" },
    [5098] = { 2, "planted beacons at Andorhal's four watchtowers for High Executor Derrington, readying the Horde's attack on the city" },
    [5102] = { 3, "destroyed General Drakkisath in Blackrock Spire for Marshal Maxwell, who carried the fight to the black dragons' doorstep" },
    [5103] = { 1, "snatched unfired plate gauntlets from beside a dead man's charred bones, then got out of the fire to find who knew their use" },
    [5121] = { 3, "slew High Chief Winterfall, whose orders had likely turned a peaceful tribe aggressive, so the Winterfall would grow no worse" },
    [5122] = { 2, "recovered the Medallion of Faith so Aurius could leave the chapel and go after Baron Rivendare, who had helped corrupt him" },
    [5123] = { 1, "handed the Crudely-written Log from High Chief Winterfall to Donova Snowden, who could make nothing of it" },
    [5124] = { 1, "gathered enchanted thorium, essence of fire and star rubies so Malyfous Darkhammer could work out the recipe for Fiery Plate Gauntlets" },
    [5125] = { 3, "saw Aurius through his reckoning in Stratholme, which left the paladin dying but with his soul saved" },
    [5127] = { 2, "slew Goraluk Anvilcrack and drove Lorax's fel-imbued pike through his heart, to claim the soul he had bartered away" },
    [5128] = { 1, "bore the High Chief's log to Kelek Skykeeper of the Emerald Circle in Felwood, who might translate what drove the furbolg to their firewater" },
    [5141] = { 2, "committed to dragonscale leatherworking for good, with scorpid armour and dragonscales for Peter Galen in Azshara" },
    [5142] = { 2, "searched ruined Darrowshire for little Pamela, the niece a wandering spirit had hidden there when the battle began" },
    [5143] = { 2, "chose tribal leatherworking for good, offering Caryssia Moonhunter in Feralas the finest wild leather armour" },
    [5144] = { 2, "committed to elemental leatherworking, bringing Sarah Tanner in Searing Gorge essences of fire, water, earth and wind" },
    [5145] = { 2, "chose the dragonscale path for good, proving it to Thorkaf Dragoneye in the Badlands with scorpid armour and dragonscales" },
    [5146] = { 2, "swore to elemental leatherworking alone, with essences of the four elements for Brumn Winterhoof in the Arathi Mountains" },
    [5147] = { 3, "brought Arnak Grimtotem, the outcast wanted for murder and kidnapped, to justice for Cliffwatcher Longhorn" },
    [5148] = { 2, "took up tribal leatherworking for good, bringing Se'Jib in Stranglethorn Vale the finest samples of wild leather armour" },
    [5149] = { 1, "found the doll little Pamela had left in town, something to hold while she waited alone for her father to come for her" },
    [5151] = { 2, "slew the caged panther that wore Wizlo Bearingshiner's hypercapacitor, for the lone survivor of a centaur raid on a caravan" },
    [5152] = { 1, "carried word of Pamela to her Auntie Marlene, who had not the heart to tell the child what became of her father" },
    [5153] = { 2, "dug up Joseph Redpath's wedding ring for Chromie, in hope of changing the fate of a man the Scourge had twisted" },
    [5154] = { 2, "recovered the Annals of Darrowshire from Andorhal's city hall, hoping they would show Chromie how to save Joseph Redpath" },
    [5155] = { 2, "cut into the Shadow Council's forces in Jaedenar, where they plot with the Burning Legion, to win Greta Mosshoof's trust" },
    [5156] = { 2, "scouted Shatter Scar Vale for Taronn Redfeather, to see whether its infernal craters still held corrupt water, and found they did" },
    [5157] = { 1, "filled a canteen at Jaedenar's corrupted Moon Well so Greta Mosshoof could break the Shadow Council's protective braziers" },
    [5158] = { 1, "carried the corrupt moonwell water to Islen Waterseer in the Barrens, to ask the spirits of water to purify it" },
    [5159] = { 1, "brought the water Islen Waterseer's spirits had purified back to Greta Mosshoof in Felwood, a sign the task was blessed" },
    [5160] = { 1, "carried Awbee's scale to Haleh in Winterspring, so the matron protectorate could scry what Awbee had felt in the spire" },
    [5163] = { 2, "turned Umi's mechanical yeti loose on her friends Legacki, Sprinkle and Quixxil, who had made fun of her ideas" },
    [5165] = { 2, "doused the four braziers of Shadow Hold with purified water so Greta Mosshoof could scry past the Shadow Council's wards" },
    [5166] = { 2, "gathered a chromatic carapace, scales and heroes' blood for Jeziba the Sculptor's breastplate against the chromatic flight" },
    [5167] = { 2, "supplied Jeziba the Sculptor with chromatic scales, heroes' blood and skins of shadow for legplates against the chromatic flight" },
    [5168] = { 2, "gathered Davil Lightfire's libram and Captain Redpath's cracked shield for Carlin Redpath, relics of Darrowshire's heroes" },
    [5181] = { 2, "retrieved the skull of Horgus the Ravager and the shattered sword of Marduk the Black, villains of Darrowshire's battle" },
    [5201] = { 2, "drove the crazed Winterfall furbolg away from Frostsaber Rock, where Rivern Frostwind had watched them slay countless creatures" },
    [5202] = { 2, "searched Jaedenar for whatever a Shadow Council member's strange red key unlocked, and found a prisoner desperate to escape" },
    [5203] = { 3, "escorted Arko'narin out of Shadow Hold with Trey's sword Lightforge, so she could warn her superiors of what was happening there" },
    [5204] = { 3, "killed the succubus Rakaiah, who had tortured Trey Lightforge, and gathered his remains so Arko'narin might have some peace" },
    [5206] = { 2, "hunted scourge champions for skulls that made Carlin Redpath's crystal resonate, the last reagent of Chromie's spell" },
    [5210] = { 1, "brought Carlin Redpath the Annals of Darrowshire, whose new pages told of the days after the battle" },
    [5211] = { 2, "freed the souls of Darrowshire's fallen defenders by destroying the ghouls and flayers the Scourge had made of them" },
    [5212] = { 2, "gathered plagued flesh in Stratholme for Betina Bigglezink, who feared that the plague was growing stronger" },
    [5213] = { 2, "searched the ziggurats of Stratholme for Scourge data, to learn what had changed in the plague's active agents" },
    [5214] = { 1, "dug through the ruins of Fras Siabi's smoke shop for a surviving box of his famous tobacco, for Smokey LaRue" },
    [5216] = { 2, "killed Cauldron Lord Bilemaw at Felstone Field for his cauldron's key and drew off its poison for a counter agent" },
    [5218] = { 2, "poured reagents into the Felstone Field cauldron until the Scourge near it recoiled from the cloud it spewed" },
    [5219] = { 2, "slew the cauldron lord of Dalson's Tears and bottled its ichors for High Priestess MacDonnell to turn on the Scourge" },
    [5221] = { 2, "tipped the counter agent into the Dalson's Tears cauldron until the Scourge nearby recoiled from their own fumes" },
    [5222] = { 2, "opened the Writhing Haunt cauldron with its lord's key and bottled its brew, a third chance to turn the Scourge's poisons" },
    [5224] = { 2, "fed the Writhing Haunt cauldron the reagents that changed its poison, so the cloud it spewed worked against the Scourge" },
    [5225] = { 2, "faced the wraiths and ghosts of Gahrron's Withering to kill Cauldron Lord Soulwrath and sample the last western cauldron" },
    [5227] = { 2, "added the counter agent to the Gahrron's Withering cauldron, souring the Scourge's plague against its own makers" },
    [5229] = { 2, "defeated Cauldron Lord Bilemaw at Felstone Field and drew off his cauldron's poison for Apothecary Dithers to study" },
    [5231] = { 2, "cut down the cauldron lord at Dalson's Tears and bottled that cauldron's own brew of toxins for Shadow Priestess Vandis" },
    [5233] = { 2, "took the key from the Writhing Haunt's cauldron lord and bottled the plague it brewed, for the Forsaken's counter agent" },
    [5235] = { 2, "braved the wraiths of Gahrron's Withering to slay Cauldron Lord Soulwrath and bottle the last western cauldron's brew" },
    [5241] = { 1, "found Pamela's Uncle Carlin to tell him she was waiting for him and his story about the rabbits and the berry jam" },
    [5242] = { 3, "killed Shadow Lord Fel'dan, head of the Shadow Council in Jaedenar and maker of pacts with the Legion, and his two succubi" },
    [5243] = { 1, "recovered the Argent Dawn's holy water from the supply crates of Stratholme for Leonid Barthalomew the Revered" },
    [5245] = { 2, "picked the four Highborne Relic Fragments out of the ice of Kel'Theril's lake, pieces of the stolen relic that cursed the highborne to that place" },
    [5246] = { 2, "recovered the Sacred Highborne Writings from Azshara, so Aurora Skycaller could mend the Crystal of Zin-Malor" },
    [5247] = { 1, "fetched thorium, crystal restore and dire water from Dire Maul, so Aurora Skycaller could fuse the crystal whole" },
    [5248] = { 2, "took the mended Crystal of Zin-Malor to Lake Kel'Theril, to show a highborne spirit the old wrong made right" },
    [5251] = { 3, "destroyed Archivist Galford and burned the Scarlet Archive in Stratholme, years of the Crusade's intelligence lost" },
    [5253] = { 2, "took the Crystal of Zin-Malor to Fandral Staghelm, so its power would rest with those who would not abuse it" },
    [5262] = { 3, "brought the head of Balnazzar, the dreadlord posing as Grand Crusader, to Duke Nicholas Zverenhoff as proof" },
    [5263] = { 3, "destroyed Baron Rivendare, Kel'Thuzad's errand boy who ruled Stratholme, and brought his head to Duke Nicholas Zverenhoff" },
    [5265] = { 3, "opened the Argent Hold, locked for years with none worthy to reach inside, in reward for service to the Argent Dawn" },
    [5281] = { 1, "sought out Egan, whose work with ghosts might aid the restless spirits of those who died in the fall of Stratholme" },
    [5282] = { 2, "freed the restless souls of Stratholme's ghostly citizens with Egan's blaster, in the hope his mother was among them" },
    [5283] = { 3, "forged ornate mithril helms, boots and a breastplate for Grumnus, the raw talent he demanded before making an armorsmith" },
    [5284] = { 3, "made moonsteel broadswords, iron and mithril axes and black maces for Ironus, the trial before the weaponsmith's path" },
    [5301] = { 3, "forged ornate mithril helms, boots and a breastplate for Okothos, his task before taking a smith onto the armorsmith's path" },
    [5302] = { 3, "made broadswords, axes and maces for Borgosh, who dreams of a Warchief's hammer, the trial to become a weaponsmith" },
    [5305] = { 2, "killed the Crimson Hammersmith in Stratholme for his apron, the price of Lilith's secret of the enchanted battlehammer" },
    [5306] = { 2, "slew the shadow huntress Vosh'gajin in Blackrock Spire, Kilram's vengeance for his scar, for the secret of Dawn's Edge" },
    [5307] = { 2, "destroyed the Black Guard Swordsmith in Stratholme, who guarded the stolen plans for the great blade Corruption" },
    [5321] = { 2, "guided the sleepy Kerlonian Evershade, newly woken from the Emerald Dream, to Liladris Moonriver at Maestra's Post" },
    [5341] = { 2, "recovered the four Barov deeds from the Scholomance for Alexi Barov, before his living brother Weldon could claim them" },
    [5342] = { 3, "assassinated Weldon Barov at Chillwind Camp so that his brother Alexi alone would hold the power and fortune of house Barov" },
    [5343] = { 2, "recovered the Barov deeds from the Scholomance for Weldon Barov, before his undead brother Alexi could lay hands on them" },
    [5344] = { 3, "took the head of Alexi Barov from under the Horde's protection at the Bulwark, so Weldon's fortune would be secure" },
    [5361] = { 1, "carried Cliffwatcher Longhorn's report of unusual centaur activity to his brother Nataka at Ghost Walker Post in Desolace" },
    [5381] = { 2, "seized the Demon Box from the Burning Blade, which held the Hand of Iruxos they used to open portals at Mannoroc Coven" },
    [5382] = { 3, "destroyed Doctor Theolen Krastinov, the Butcher of thousands, and burned the remains of Eva and Lucien Sarkhoff" },
    [5384] = { 3, "lured Kirtonos the Herald with the blood of innocents and destroyed him, the master Krastinov had served" },
    [5385] = { 2, "carried Trey Lightforge's remains to Jessir Moonbow, so the fallen paladin could be given proper respects by his friends" },
    [5386] = { 1, "fetched Bloodbelly fish from Shadowprey Village for Nataka Longhorn, who had long missed the smell of cooked fish" },
    [5441] = { 1, "woke the lazy peons with Foreman Thazz'ril's blackjack to keep them gathering lumber" },
    [5461] = { 2, "searched Stromgarde's ruins for a keepsake of Ras Frostwhisper's life, so Magistrate Marduke could make him mortal again" },
    [5463] = { 2, "laid the Keepsake of Remembrance on Menethil's Gift, the unholy ground in Stratholme where Ras Frostwhisper became a lich" },
    [5464] = { 2, "carried the soulbound keepsake to Leonid Barthalomew, so a soul might cling to Ras Frostwhisper as it had to the keepsake" },
    [5466] = { 3, "made the lich Ras Frostwhisper mortal with the soulbound keepsake and struck him down, a mortal blow to the Scourge" },
    [5481] = { 1, "picked gloom weed for big-handed Gordo, only to learn his master, Junior Apothecary Holland, had no need of it" },
    [5482] = { 1, "gathered doom weed by the mass gravesite for Junior Apothecary Holland, the weed his servant Gordo kept getting wrong" },
    [5501] = { 1, "gathered kodo bones from the Kodo Graveyard for Bibbly F'utzbuckle, whose customers made furniture and blasted powder of them" },
    [5502] = { 2, "brought Grunth back to Orphan Matron Battlewail at the end of Children's Week, an orphan now set on being a hero" },
    [5515] = { 2, "struck down Jandice Barov in the catacombs for Krastinov's Bag of Horrors, the means of summoning his master Kirtonos" },
    [5518] = { 1, "brought cloth, leather and thread to the chained goblin Knot Thimblejack for an ogre suit to slip past Captain Kromcrush" },
    [5522] = { 2, "handed Tinkee's frozen dragon eggs to Leonid Barthalomew, who had tricked her so they would never reach her evil master" },
    [5525] = { 2, "freed Knot Thimblejack, a goblin chained in the Gordok wing who had expected to end up an ogre's appetizer" },
    [5526] = { 3, "ended Alzzin the Wildshaper's corruption in Dire Maul and sealed a shard of the Felvine in the Reliquary of Purity" },
    [5527] = { 2, "scoured the ruins of Southwind Village in Silithus for a Reliquary of Purity, the one vessel that could hold the Felvine" },
    [5529] = { 2, "killed the plagued hatchlings bred in the Scholomance, before the Scourge could raise a dragonflight of its own" },
    [5531] = { 1, "brought the frozen dragon eggs, kept from the Scourge's experiments, to Betina Bigglezink and her weapon against them" },
    [5534] = { 1, "wrested from the naga of Eldarath the rune the blood elves sought, Kim'jael's revenge on the employers who betrayed him" },
    [5535] = { 1, "released the restless Highborne spirits of the Shadowsong Shrine, as Loh'atu had promised the Sentinels" },
    [5536] = { 1, "purged the Haldarr satyrs from the sacred lands once travelled by Cenarius, to keep Loh'atu's oath to the Earthmother" },
    [5537] = { 2, "collected skeletal fragments around Andorhal for Alchemist Arbington, the start of a Skeleton Key to open Scholomance" },
    [5541] = { 1, "recovered a crate of ammunition a courier abandoned near the Grizzled Den and took it to Hegnar Rumbleshot" },
    [5542] = { 1, "thinned the plaguehounds and their runts for Tirion Fordring, to earn a warm meal and some conversation at his stead" },
    [5543] = { 1, "destroyed the plaguebats that struck from the skies over the Plaguelands, at the request of Tirion Fordring" },
    [5544] = { 1, "harvested carrion worm meat, the one beast the Plague had spared, so Tirion Fordring could restock his food for winter" },
    [5545] = { 1, "collected bundles of wood the wolves and bears had driven Raelen's workers away from, so the lumber order would meet its deadline" },
    [5561] = { 1, "jolted old kodos into tame ones with Smeed Scrabblescrew's kombobulator, for the caravan he had a partnership with" },
    [5581] = { 3, "banished the demon portals at Mannoroc Coven with the Hand of Iruxos, to stem the tide of demons into the world" },
    [5582] = { 1, "took a rare healthy scale from a plagued hatchling to Betina Bigglezink, to study the Scourge's machinations" },
    [5601] = { 2, "searched Darrowshire for the family a refugee of Lordaeron had left behind, most of all her little sister Pamela" },
    [5621] = { 2, "healed the wounded Sentinel Shaya near Dolanaar and fortified her, the test that earned a first robe of Elune's order" },
    [5624] = { 2, "healed Guard Roberts, hurt by the lake east of Goldshire, and fortified him, to earn the robes of a priest of the Light" },
    [5625] = { 2, "mended Mountaineer Dolf's wounds outside Kharanos and granted him Fortitude, the test that earned Maxan Anvol's robe" },
    [5648] = { 2, "healed Grunt Kor'ja, hurt fighting Proudmoore's old troops south of Razor Hill, and blessed her, so she could defend the town again" },
    [5650] = { 2, "healed Deathguard Kel, wounded guarding Brill from gnolls, and fortified him for duty, Dark Cleric Beryl's test of the light" },
    [5713] = { 3, "defended the poisoned Sentinel Aynasha from the furbolg Marosh and his trackers until her antidote took hold" },
    [5721] = { 3, "relived the battle of Darrowshire with its risen spirits, to defeat Redpath the Corrupted and save Joseph Redpath's soul" },
    [5722] = { 2, "searched Ragefire Chasm for the body of Maur Grimtotem, Magatha's servant, and whatever he found before he died" },
    [5724] = { 1, "brought Rahauro in Thunder Bluff the satchel Maur Grimtotem clutched as the troggs beat him down" },
    [5725] = { 2, "took two spell books of shadow from the Searing Blade for Varimathras, Legion gifts the Dark Lady wanted in her own hands" },
    [5726] = { 2, "seized a lieutenant's insignia from the Burning Blade in Skull Rock for Thrall, who meant to find the true head of the traitors" },
    [5727] = { 2, "passed as one of the Burning Blade before Neeru Fireblade, the warlock Thrall knew to be their secret leader" },
    [5728] = { 3, "slew Bazzalan and Jergosh the Invoker, leaders of the Searing Blade beneath Orgrimmar, for Thrall without Neeru Fireblade knowing" },
    [5729] = { 1, "returned to Neeru Fireblade in the Cleft of Shadow to win his trust and learn more of the Shadow Council for Thrall" },
    [5730] = { 1, "told Thrall of the Shadow Council's new agenda in the Barrens and Ashenvale, learned while posing as Neeru's lieutenant" },
    [5741] = { 2, "wrested the Sceptre of Light from a Burning Blade seer at Thunder Axe Fortress, a relic said to sink whole cities" },
    [5761] = { 3, "killed Taragaman the Hungerer, the felguard leading the Searing Blade in Ragefire Chasm, for Neeru Fireblade" },
    [5762] = { 1, "delivered Kravel's crate of special-gauge ammunition to Hemet Nesingwary's hunting camp in Stranglethorn" },
    [5763] = { 1, "carried Roon Wildmane's kodo horn to Hemet Nesingwary in Stranglethorn, an invitation to hunt together again" },
    [5781] = { 2, "recovered the toy hammer young Taelan buried at his father's false grave, to help him regain what he had lost" },
    [5801] = { 2, "forged a skeleton key in the lava lake atop Fire Plume Ridge for Alchemist Arbington, a step toward facing Araj the Summoner" },
    [5802] = { 2, "forged a skeleton key in the lava lake atop Fire Plume Ridge for Apothecary Dithers, a step toward facing Araj the Summoner" },
    [5803] = { 3, "destroyed Araj the Summoner, once master of Scholomance, and pried the scarab from his phylactery to crown the Skeleton Key" },
    [5804] = { 3, "broke Araj the Summoner's hold on Andorhal and took his scarab, the last piece of Apothecary Dithers' key to Scholomance" },
    [5821] = { 2, "guarded the Gizelton Caravan past the Kolkar village, whose war drums usually brought its kodos to a halt" },
    [5845] = { 2, "brought back the Symbol of Lost Honor, the standard Taelan threw down at Northdale when he renounced all he had known" },
    [5846] = { 2, "searched Caer Darrow for Renfray's portrait of Tirion Fordring with his wife and son, his fondest memory" },
    [5848] = { 2, "uncovered the painting Of Love and Family beneath a picture of the twin moons in the Scarlet Bastion, for Tirion Fordring" },
    [5862] = { 2, "slipped into Hearthglen under Myranda's illusion to put Tirion's Gift into the hands of his son, Highlord Taelan Fordring" },
    [5863] = { 3, "broke the Dunemaul Compound and killed Gor'marok the Ravager before the ogres could build up a force in Tanaris" },
    [5881] = { 1, "brought Grish Longrunner at the Great Lift word of his relief, so he could at last visit his family" },
    [5882] = { 1, "traded the spoils of the hunt to Arathandris Silversky for Cenarion plant salve, to purify the corrupted plants of Felwood" },
    [5883] = { 1, "brought Arathandris Silversky vitriol mined in Felwood, the makings of the plant salve that purifies its corrupted plants" },
    [5884] = { 1, "gathered what Arathandris Silversky could purify into Cenarion plant salve, every bit of it a help in taking back Felwood" },
    [5885] = { 1, "handed over a skinner's haul to Arathandris Silversky for plant salves, to reclaim Felwood from the corruption" },
    [5886] = { 1, "gave up a lesser nether essence, the most potent stuff for turning swords into plowshares, for Arathandris Silversky's plant salve" },
    [5887] = { 1, "traded what the hunt had yielded to Maybess Riverbreeze for Cenarion plant salve, to scour Felwood for corrupted plants" },
    [5888] = { 1, "handed Maybess Riverbreeze vitriol from the mines of Felwood, the more of it the more salve for the corrupted plants" },
    [5889] = { 1, "brought gathered goods to Maybess Riverbreeze to be purified into salve, every bit a help in taking back Felwood" },
    [5890] = { 1, "supplied Maybess Riverbreeze with a skinner's haul for plant salves, to reclaim Felwood from the corruption" },
    [5891] = { 1, "spent a lesser nether essence with Maybess Riverbreeze, the most potent thing for her salves, to heal Felwood's plants" },
    [5892] = { 1, "hauled Dun Baldar's stored supplies out of the Irondeep mine, which the Alliance no longer had the troops to guard against the troggs" },
    [5893] = { 1, "brought the Frostwolf supplies cached in the Coldtooth mine back to the keep, now that the clan could spare no warriors to hold it" },
    [5901] = { 1, "filled a jar with Plaguewood termites for Mickey Levine, who meant to take a lumber mill from the Scarlet Crusade" },
    [5902] = { 2, "set a barrel of termites loose in the Northridge Lumber Mill, to rob the Scarlet Crusade of its precious lumber" },
    [5903] = { 1, "filled a jar with Plagueland termites near Stratholme for Nathaniel Dumah to loose on the Scarlet Crusade's lumber mill" },
    [5904] = { 1, "set a barrel of termites in the heart of the Northridge Lumber Mill, to leave it useless to the Scarlet Crusade" },
    [5929] = { 2, "sought out the Great Bear Spirit in Moonglade, as every druid must, to learn from it the true nature of the bear" },
    [5930] = { 2, "sat at the feet of the Great Bear Spirit in Moonglade, every druid's first tutor in the nature of the bear" },
    [5941] = { 1, "took the Bundle of Relics to Chromie in Andorhal, who said that with them Darrowshire could yet be saved" },
    [5942] = { 1, "opened the chest behind Pamela's house with the key her father sent along with his thanks" },
    [5943] = { 2, "protected the Gizelton Caravan through Mannoroc Coven, where something had the kodos spooked" },
    [5944] = { 3, "escorted Highlord Taelan Fordring out of Hearthglen to his father Tirion, a flight that cost Taelan his life" },
    [5981] = { 1, "felled the Frostmaul giants of the southern valley in the name of the frostsaber queen, Shy-Rotam, to prove loyalty to the frostsabers" },
    [6001] = { 3, "called forth Lunaclaw at the Moonkin Stone near Auberdine and faced it, for the strength of body and heart a druid needs" },
    [6002] = { 3, "faced Lunaclaw at the Moonkin Stone west of Taurajo, for the strength of body and heart one of the Claw must have" },
    [6004] = { 1, "thinned the Scarlet Crusade's camp below Hearthglen for Kirsta Deepshadow, a scout too worn down to keep fighting alone" },
    [6021] = { 3, "killed Zaeldarr the Outcast, the dead troll whose gang stole bodies from the pit at Light's Hope Chapel" },
    [6022] = { 1, "slaughtered the Scourge of Corin's Crossing for living rot, ground fast enough to feed Nathanos Blightcaller's hounds" },
    [6023] = { 2, "killed Huntsman Radley and Cavalier Durgen, the backbone of the Scarlet Crusade outside Hearthglen, for Kirsta Deepshadow" },
    [6024] = { 2, "granted Infiltrator Hameya's plea for death before the lich's whispers drove him to infect more of his people" },
    [6025] = { 2, "climbed to a high point in Hearthglen to gauge the Scarlet Crusade's numbers for Kirsta Deepshadow, too worn to go herself" },
    [6026] = { 1, "gathered thorium, a golden rod, bombs and triggers for Smokey LaRue, hired by the Argent Dawn for some demolition work" },
    [6027] = { 2, "summoned the guardian of the Book of the Ancients on Ranazjar Isle, and brought the naga's secrets to Azore Aldamort" },
    [6030] = { 1, "carried Umbranse's Studies in Spirit Speaking to Duke Nicholas Zverenhoff, a linguist who might make sense of its jibber-jabber" },
    [6031] = { 1, "brought runecloth to Meilosh, so the Timbermaw could have clothing as fine as a night elf friend's runecloth cloak" },
    [6032] = { 1, "supplied Meilosh with mooncloth, sacred to the Timbermaw, for their holy garments, in return for a secret fashioning technique" },
    [6041] = { 2, "blew up the Scourge ziggurats and slaughterhouses of Plaguewood that Smokey LaRue had marked for the Argent Dawn" },
    [6042] = { 1, "swatted plaguebats off the farm so Nathanos Blightcaller could take his hounds after the Scourge without being accosted" },
    [6061] = { 1, "tamed an adult plainstrider with Yaw Sharpmane's rod, a first step toward oneness with nature in the tauren way" },
    [6062] = { 1, "subdued a dire mottled boar near Razor Hill with Thotar's taming rod, a first test of command over a beast" },
    [6063] = { 1, "tamed a webwood lurker with Dazalar's rod, to prove a hunter understood that nature is to be respected rather than bent" },
    [6064] = { 1, "tried a large crag boar as a companion with Grif Wildheart's taming rod, to see what kind of beast suited" },
    [6082] = { 3, "mastered an armored scorpid, the last of Thotar's trials, to earn the power to tame and command a beast of any choosing" },
    [6083] = { 1, "tamed a surf crawler off the Echo Isles for Thotar, learning that a pet must become an extension of its hunter" },
    [6084] = { 1, "won over a snow leopard for Grif Wildheart, a swifter, more agile companion than the burly crag boar" },
    [6085] = { 3, "tamed an ice claw bear, Grif Wildheart's last trial before granting the power to tame a loyal pet of any kind" },
    [6087] = { 1, "tamed a prairie stalker for Yaw Sharpmane, to take on its swift, fearless nature and fight as one with a beast" },
    [6088] = { 3, "brought a swoop down from the sky with the taming rod, Yaw Sharpmane's last trial before choosing a companion" },
    [6101] = { 1, "tamed a nightsaber stalker for Dazalar, to learn how the creatures of a changing nature differ from one another" },
    [6102] = { 3, "won a strigid screecher from the skies, Dazalar's last trial before choosing a companion of land, water or sky" },
    [6122] = { 2, "drew water from the cave by Cliffspring Falls, past the naga, to find the poison sickening the deer of Darkshore" },
    [6123] = { 1, "gathered earthroot and lunar fungus for the salve Alanndarian Nightsong would make for Darkshore's poisoned deer" },
    [6124] = { 2, "cured sickly deer across Darkshore with Alanndarian Nightsong's salve, victims of a taint spreading through the land" },
    [6127] = { 2, "drew water atop Dreadmist Peak, likely tainted by the Burning Blade, to trace the poison sickening the gazelles" },
    [6128] = { 1, "brought down kodos for their horns and found earthroot, for Tonga Runetotem's salve for the poisoned gazelles" },
    [6129] = { 2, "tended the sickly gazelles of the northern Barrens with Tonga Runetotem's salve, to give the cure a head start" },
    [6132] = { 3, "got Melizza Brimbuzzle out of the Valley of Spears before the Maraudine centaurs could put her in their cookpot" },
    [6133] = { 2, "raided the high elves' Quel'Lithien lodge for the Quel'Thalas Registry at the ranger lord's behest, leaving grief behind" },
    [6134] = { 1, "lured Magram ghosts in the Valley of Bones to ghost magnets for their ghost-o-plasm, to be sold to the centaurs" },
    [6135] = { 2, "tracked down Duskwing, the albino demon bat, for the white fur Nathanos Blightcaller would fashion into a reward" },
    [6136] = { 3, "destroyed Borelgore, the corpulent maggot beast that had cost Nathanos Blightcaller entire regiments" },
    [6142] = { 1, "dug soft-shelled clam meat near a coastal wreck for Mai'Lahii, bait for the fishing that cured his headache" },
    [6143] = { 2, "avenged Drulzegar's fishing crew, slaughtered by the Slitherblade naga near Ranazjar Isle while he alone survived" },
    [6145] = { 2, "intercepted the Crimson Courier for the Grand Crusader's Command, the daily report that was the key to striking the Crusade" },
    [6146] = { 2, "ate a rotten apple to pass as a crusader in Tyr's Hand and deliver an altered command, a ruse to expose the Scarlet Oracle" },
    [6148] = { 3, "hunted down Demetria, the Scarlet Oracle and the Grand Crusader's chief advisor, on the road from Tyr's Hand" },
    [6161] = { 1, "found Rackmore's silver and golden keys and opened the treasure chest he had hidden on Ranazjar Isle" },
    [6162] = { 3, "killed Overlord Ror, the befouled furbolg that Dreka'Sur's husband went after and never came back from, so his widow could rest" },
    [6163] = { 3, "slew Ramstein the Gorger, the abomination that had overwhelmed Nathanos Blightcaller on his stead, for his vengeance" },
    [6164] = { 1, "fetched Augustus the Touched's receipt book from his room at the inn, so he could open up shop in Terrordale again" },
    [6185] = { 2, "scoured the Plaguelands for word of the Blightcaller and the missing SI:7 agents, whom Flint Shadowmore feared dead" },
    [6186] = { 2, "broke the news to Highlord Bolvar Fordragon that Nathanos Marris, once a noble ranger lord, had become the Forsaken's Blightcaller" },
    [6187] = { 3, "assembled an army to destroy Nathanos Blightcaller, the human ranger lord turned champion of the Forsaken" },
    [6281] = { 1, "flew Quartermaster Lewis's note to Osric Strang in Stormwind, a request for armour as Sentinel Hill's supply dwindled" },
    [6282] = { 2, "culled the Bloodfury harpies of Stonetalon for Maggran Earthbinder, the source of the harpies spreading across Kalimdor" },
    [6283] = { 3, "slew Bloodfury Ripper, all but a queen to the harpies, so their numbers would at last diminish" },
    [6284] = { 3, "killed Besseleth, the old spider of Sishir Canyon, so travellers could come to Sun Rock Retreat without fear" },
    [6285] = { 1, "brought Osric's crate of armour back to Quartermaster Lewis for the fighting men and women of Sentinel Hill" },
    [6301] = { 1, "gathered Gaea seeds at Mirkfallon Lake for Tammra Windfield to bless, to begin healing the wrecked land" },
    [6323] = { 1, "flew Podrig's order to Gordon Wendham in the Undercity, for weapons to replace those the Deathguards had lost" },
    [6324] = { 1, "brought Gordon's crate of weapons back to Deathguard Podrig, so the Sepulcher's guards would not be caught unprepared" },
    [6342] = { 1, "flew to Auberdine with Nessa's fish bones and scales for Laird, to compare Teldrassil's catch with the mainland's" },
    [6343] = { 1, "carried Laird's reply back to Nessa Shadowsong, with his suspicion that the world tree made the fish there grow so large" },
    [6362] = { 1, "flew a bundle of Barrens hides to Ahanu in Thunder Bluff, who would work them into leather goods" },
    [6364] = { 1, "flew Ahanu's leather goods back to Jahan Hawkwing to sell to the hunters crowding the Crossroads" },
    [6381] = { 2, "planted enchanted Gaea seeds at the heart of the Charred Vale, to help the cycle of life return to the burnt land" },
    [6384] = { 1, "flew Zargh's choice cuts of meat to his friend Gryshka, the innkeeper in Orgrimmar" },
    [6386] = { 1, "carried Gryshka's letter of thanks back to Zargh, who took it as proof she liked his steaks" },
    [6389] = { 2, "pried open the termite barrel in the Northridge Lumber Mill and escaped the swarm, which let Nathaniel Dumah's father rest" },
    [6390] = { 2, "unleashed the termites in the Northridge Lumber Mill for Mickey Levine, to ruin the Scarlet Crusade's work there" },
    [6391] = { 1, "flew Brock Stoneseeker's list of his best mining students to Ironforge, where their honorary picks were waiting" },
    [6392] = { 1, "flew the honorary picks back to Brock Stoneseeker for his mining students, eager to try them on Loch Modan's ore" },
    [6393] = { 1, "destroyed fire elementals in the Charred Vale for Tsunaman, whose Tribunal of the Tides waged war on their fiery cousins" },
    [6394] = { 1, "retrieved Foreman Thazz'ril's favourite pick from the Burning Blade Coven, left behind among the beasts that filled the cave" },
    [6395] = { 2, "put down Samuel Fipps, who killed his wife Marla after the plague took him, and buried him at her grave as she had wished" },
    [6401] = { 1, "brought Tammra Windfield the news that her niece Kaya had survived the attack on her village" },
    [6403] = { 3, "stood with Marshal Reginald Windsor as he unmasked Lady Prestor as Onyxia and gave his life to free Stormwind from her spell" },
    [6421] = { 2, "explored the kobold cave at Boulderslide Ravine for Resonite crystals, so Mor'rogal could learn what evil lurked below" },
    [6441] = { 1, "collected satyr horns for Pixel, a trader bound for Ratchet, where they were in high demand" },
    [6442] = { 2, "threw the Wrathtail naga back into the sea from the Zoram Strand, land the Horde had worked hard to claim" },
    [6461] = { 1, "killed the Deepmoss spiders that raided Malaka'Jin's camps at night to steal the trolls' hunt" },
    [6462] = { 2, "recovered the sacred charms of Mitsuwa's kin from Thistlefur Hold, taken by the furbolgs who killed them on the road" },
    [6481] = { 3, "smashed open the Resonite cask and slew Goggeroc, an Earthen the kobolds had dug up, before it could threaten Kalimdor" },
    [6482] = { 3, "escorted Ruul, Yama Snowhoof's brother, out of the Thistlefur camp, where the furbolgs had taken him for a bear and starved him" },
    [6501] = { 2, "searched the world for one of dragon blood who could restore the Fragment of the Dragon's Eye, the key to Onyxia's lair" },
    [6502] = { 3, "took the Blood of the Black Dragon Champion from General Drakkisath, to remake the amulet that opens Onyxia's lair" },
    [6503] = { 2, "hunted the Ashenvale Outrunners spying on the Horde's defenses, to blind the Alliance before it could attack" },
    [6504] = { 1, "found the scattered pages of a shredder manual for Gurda Ragescar, who could not work the new shredder without them" },
    [6521] = { 3, "hunted down Ambassador Malcin outside Razorfen Downs, the Scourge envoy courting the quilboar, and brought his head to Varimathras" },
    [6522] = { 2, "delivered to Varimathras a scroll found on the crone of Razorfen Kraul, Ambassador Malcin's offer of a pact with the Scourge" },
    [6523] = { 3, "escorted Kaya Flathoof to Camp Aparaje after her rescue, so her father Makaba would know she was safe" },
    [6543] = { 1, "carried Kadrak's orders to the Warsong scouts in Ashenvale and brought their reports back for the Horde's campaign" },
    [6544] = { 3, "fought beside Torek's raiders in their attack on Silverwing Outpost and its leader, Duriel Moonfire" },
    [6548] = { 2, "killed Grimtotem raiders for Makaba Flathoof, who had barely escaped when they massacred his village" },
    [6561] = { 3, "killed Twilight Lord Kelris, who fed innocents to Aku'Mai in a fallen temple of Elune, and took his head to Bashana Runetotem" },
    [6563] = { 1, "pried sapphires of Aku'Mai from the walls of Blackfathom before the naga could make use of their elemental power" },
    [6569] = { 2, "gathered black dragonspawn eyes in the upper spire for Myranda the Hag, for an illusion to fool the black flight's gatekeeper" },
    [6570] = { 2, "slipped into Emberstrife's Den in the Wyrmbog in the guise of a dragonspawn, to face the old drake's tests for Onyxia's elite guard" },
    [6571] = { 1, "gathered saw blades, rope, oil and axes for the Warsong Lumber Camp, wresting the rope and oil back from furbolgs and satyrs" },
    [6601] = { 1, "showed the Dull Drakefire Amulet to Rexxar, since Myranda's disguise would not hold inside Blackrock Spire" },
    [6602] = { 3, "killed General Drakkisath and brought his blood to Rexxar, to waken the key to Onyxia's lair" },
    [6607] = { 2, "caught rare fish from four far-off waters for Nat Pagle, who promised to teach a thing or two about fishing in return" },
    [6610] = { 1, "gathered giant eggs, clam meat and Alterac Swiss for Dirge Quikcleave's clamlette, the price of lessons in exotic cuisine" },
    [6621] = { 3, "raised Karang's banner on the Foulweald totem mound and held it until Chief Murgut came out to face me, and fell" },
    [6622] = { 2, "saved wounded soldiers in order of triage at Hammerfall, the examination to join the ranks of Horde Trauma" },
    [6624] = { 2, "tended wounded soldiers in order of triage, the critical first, the examination to join the ranks of Alliance Trauma" },
    [6626] = { 2, "thinned the battleguards, thornweavers and Death's Head cultists flocking to the Scourge diplomat at Razorfen Downs, for Myriam Moonsinger" },
    [6629] = { 3, "killed Grundig Darkcloud, who had led the Grimtotem attack on Makaba Flathoof's village" },
    [6641] = { 3, "guarded Muglash while he lured out Vorsha the Lasher, the hydra that kept attacking Zoram'gar, and saw her slain" },
    [6661] = { 1, "lured Deeprun rats with Monty's flute and brought them back alive, the only way his brother's rat kabobs would not go sour" },
    [6662] = { 1, "rode the tram with a crate of live rats for Nipsy's rat kabob stand before they went bad" },
    [6681] = { 2, "sought out the hidden Ravenholdt Manor in the hills of Hillsbrad with its seal, the first test of cunning for the Assassin's League" },
    [6801] = { 1, "offered up the blood of slain Stormpike soldiers so the Frostwolf could call Lokholar the Ice Lord down on their enemies" },
    [6804] = { 2, "cured the plagued water elementals of the Eastern Plaguelands with the Aspect of Neptulon, and defeated the maddened surges" },
    [6805] = { 1, "defeated the dust stormers and desert rumblers of Silithus, servants of air and earth, to prove conviction to Duke Hydraxis" },
    [6821] = { 3, "slew the Pyroguard Emberseer, a fire servant held in Blackrock Spire, for the eye Duke Hydraxis wanted as proof of strength" },
    [6822] = { 2, "faced a fire lord, a molten giant, a core hound and a lava surger in the Molten Core, Duke Hydraxis's real test of strength" },
    [6824] = { 3, "took the hands of Lucifron, Sulfuron, Gehennas and Shazzrah in the Molten Core, a terrible blow to the Firelords" },
    [6844] = { 1, "took the encrusted find to Umber, the Cenarion Circle's archivist in Nighthaven, in hope of a window into the past" },
    [6846] = { 1, "carried the orders that left the assault to a commander's will, and that will was to strike at once" },
    [6847] = { 2, "recovered Master Ryson's All Seeing Eye from the Winterax trolls' caves, a cursed thing the Syndicate would sell its services for" },
    [6848] = { 2, "reclaimed Master Ryson's All Seeing Eye from the Winterax trolls, the price of the Syndicate's help in the war, curse and all" },
    [6881] = { 1, "gathered storm crystals from the Frostwolf so the Circle could amass the power to call Ivus the Forest Lord to the Alliance's aid" },
    [6901] = { 1, "delivered the overdue orders that let the Horde attack and show the Alliance their folly in coming to Alterac Valley" },
    [6921] = { 2, "retrieved the fathom core from the Moonshrine Ruins, so the Earthen Ring could learn what the Twilight's Hammer was doing" },
    [6922] = { 2, "brought Je'neu Sancrea the strange globe that had fed Baron Aquanis in Blackfathom, proof of what had corrupted him" },
    [6962] = { 1, "fetched gingerbread cookies and ice cold milk for Great-father Winter, worn out after greeting folk all day" },
    [6963] = { 2, "searched the snows of the Alterac Mountains for the Smokywood Pastures agent who went after a missing shipment of Winter Veil treats" },
    [6981] = { 1, "took a disturbing glowing shard, smoke swirling inside it, to Ratchet to learn what it was" },
    [6982] = { 1, "raided the Horde's depot in the Coldtooth mine, deep in their territory, to keep the Alliance supplied and strip the Horde of gear" },
    [6983] = { 3, "recovered the stolen Winter Veil treats from the Abominable Greench, the creature that had frozen Sacks into a snowman" },
    [6985] = { 1, "plundered the Stormpike stores in the Irondeep mine, deep in Alliance territory, to curtail their efforts and equip the Frostwolf" },
    [7001] = { 1, "tamed a frostwolf from the valley's forest with a muzzle so the stables could fill and the Wolf Riders return to the front" },
    [7002] = { 1, "slew the rams the Stormpike cavalry rode for their hides, so harnesses could be made and the Frostwolf Wolf Riders ride once more" },
    [7003] = { 1, "tried Zorbin Fandazzle's goblin Ultra-Shrinker on the giants of Feralas, a test he preferred not to risk himself" },
    [7025] = { 1, "brought Greatfather Winter gingerbread cookies and ice cold milk, a treat he had earned after a long day of greetings" },
    [7026] = { 1, "struck at the Frostwolf base for the hides of the wolves they ride, so the Stormpike cavalry would not charge into battle bareback" },
    [7027] = { 1, "snared an Alterac ram with a training collar for the empty Stormpike stables, so the cavalry could be reborn" },
    [7028] = { 1, "collected Theradric crystal carvings in Maraudon for Willow, who wanted to study the relics of the old gods hidden there" },
    [7029] = { 2, "purged Vyletongue's corruption from the Vylestem vines of Maraudon and slew the Noxxious Scions driven out of them, for Vark Battlescar" },
    [7041] = { 2, "purged Vyletongue's corruption from the Vylestem vines of Maraudon and slew the Noxxious Scions driven out of them, for Talendria" },
    [7042] = { 2, "looked for the missing Smokywood Pastures investigator in the Alterac Mountains, sent after a lost shipment of holiday treats" },
    [7043] = { 3, "tracked down the Abominable Greench, who had stolen Smokywood Pastures' Winter Veil treats and turned poor Sacks into a snowman" },
    [7044] = { 2, "won back the two parts of Celebras's scepter from Noxxion and Lord Vyletongue, to reach Celebras, wandering blind and cursed in Maraudon" },
    [7046] = { 2, "helped Celebras the Redeemed reunite rod and diamond into his scepter, and took up his hope of bringing peace to his uncle's spirit" },
    [7061] = { 1, "carried a book of the old Winter Veil legends to Cairne Bloodhoof, who wanted the lore of his people kept alive" },
    [7063] = { 1, "took a book on the Feast of Winter Veil to King Magni Bronzebeard, who was glad to see the older legends remembered" },
    [7064] = { 3, "slew Princess Theradras deep in Maraudon, so the remains of Zaetar, first son of Cenarius, might be recovered" },
    [7065] = { 3, "slew Princess Theradras deep in Maraudon, so the remains of Zaetar, first son of Cenarius, might be recovered" },
    [7066] = { 2, "carried the Seed of Life from Zaetar's spirit to Remulos in Moonglade, word that his brother lived on and had found peace" },
    [7067] = { 2, "fetched the Amulet of Union from the holy halls of Maraudon for the exiled Centaur Pariah, who hoped to unite the centaur tribes" },
    [7068] = { 1, "pried shadowshard fragments from the crystal creatures of Maraudon for Uthel'nay's magics" },
    [7070] = { 1, "collected shadowshards from Maraudon's elementals for Archmage Tervosh, who was testing the arcane properties of crystals" },
    [7081] = { 2, "tore the Horde banner from one of Alterac Valley's graveyards, the sacred ground both sides fought over most savagely" },
    [7082] = { 2, "pulled the Alliance banner from a graveyard in Alterac Valley, where the battles raged fiercest and the lines kept shifting" },
    [7101] = { 2, "seized an Alliance bunker for the Horde by pulling down its banner, so the Frostwolf troops could charge forward" },
    [7102] = { 2, "stormed a Horde tower and tore down its banner, driving their ranged troops out of position so the Alliance line could advance" },
    [7122] = { 2, "captured a mine for the Stormpike by killing its leader, so troops could hold it and gather its minerals and cached supplies" },
    [7124] = { 2, "secured one of Alterac's mines for the Horde by slaying its leader, for its ore and the supplies cached in its depths" },
    [7141] = { 3, "killed Drek'Thar, the Frostwolf general, so the Explorers' League could search Alterac Valley for its artifacts" },
    [7142] = { 3, "slew Vanndar Stormpike, the dwarven general, to drive the Stormpike invaders out of Alterac Valley" },
    [7161] = { 3, "recovered the Frostwolf Banner from the Wildpaw gnoll cave, the rite of battle every newcomer to the valley had to pass" },
    [7162] = { 3, "won the Stormpike Banner from the Icewing Caverns to earn a place among the Stormpike and an initiate's insignia" },
    [7163] = { 1, "presented the initiate's insignia to Warmaster Laggrond to be named a soldier and a friend of the Frostwolf Clan" },
    [7164] = { 1, "rose again in rank among the Frostwolf, a brave and honourable soldier in Warmaster Laggrond's eyes" },
    [7165] = { 2, "earned reverence among the Frostwolf, with tales of the fighting already told and the Stormpike said to shake in fear" },
    [7166] = { 2, "being raised to Hero of Frostwolf, exalted by the clan and told that command of the valley would soon follow" },
    [7167] = { 3, "received the Eye of Command from Warmaster Laggrond, praised by Drek'Thar and the Warchief for a stalwart defence of the clan" },
    [7168] = { 1, "presented the initiate's insignia to Lieutenant Haggerdin, raised above mediocrity to a soldier of rank among the Stormpike" },
    [7169] = { 1, "being honoured among the Stormpike Guard for blows struck in the Field of Strife, with word of them sent to the king" },
    [7170] = { 2, "earned reverence among the Stormpike Guard, a hero in the making that Lieutenant Haggerdin never guessed at on first meeting" },
    [7171] = { 2, "rose to legend among the Stormpike, marked as the one likely to carry the Eye of Command" },
    [7172] = { 3, "took up the Eye of Command for the Stormpike, a commander whose orders the troops would follow against the Frostwolf" },
    [7181] = { 3, "hunted down Korrak the Bloodrager, the cruel and cunning leader of the cannibal Winterax trolls, when he showed himself" },
    [7201] = { 1, "pried Essence of the Elements from the golems of Blackrock Depths for Vivian Lagrave, who imagined what it could do for the Forsaken" },
    [7202] = { 3, "slew Korrak the Bloodrager, who led the Winterax trolls that wanted Stormpike bones for their stew" },
    [7223] = { 1, "gathered Armor Scraps from the battlefield for Murgot Deepforge, who could not outfit the Stormpike veterans on Ironforge's supplies" },
    [7224] = { 1, "stripped Armor Scraps from fallen enemies so Smith Regzar could melt them down into armour for the Frostwolf troops" },
    [7281] = { 3, "killed Commander Karl Philips of the Stormpike, Louis Philips's own brother, in the hope the Banshee Queen could turn him as she had Louis" },
    [7282] = { 3, "destroyed Commander Louis Philips, Karl Philips's brother made a mindless servant of the Banshee Queen, to end his torment" },
    [7301] = { 2, "searched Tower Point West and Frostwolf Keep for the Stormpike's best pilots, Wing Commanders Slidore, Vipore and Ichman" },
    [7302] = { 2, "found out what became of Wing Commanders Guse, Jeztor and Mulverick, shot down over enemy ground, so a rescue could be attempted" },
    [7321] = { 1, "hunted snapjaws on Lake Lordamere for turtle meat, so Christoph Jeffcoat would share his secret soothing turtle bisque" },
    [7361] = { 1, "took the head of a slain night elf to Najak Hexxen, who would not let Staghelm's people wipe out the Darkspear" },
    [7362] = { 1, "brought a tuft of gnome hair to Ravak Grimtotem, who was studying the gnomes' resilience for Magatha, the Elder Crone" },
    [7363] = { 1, "collected a slain human's bone chip for Commander Louis Philips and the Dark Apothecaries' cure for the human condition" },
    [7364] = { 1, "repaid the tauren for the gnome hair they cut from fallen gnomes by bringing Dirk Swindle a tauren's hoof" },
    [7365] = { 1, "stole a slain troll's mojo for Athramanis, by Staghelm's order to exterminate the trolls on the field" },
    [7366] = { 1, "claimed a Forsaken heart for Commander Karl Philips, to be burned at the Cathedral of Light as the Archbishop's mercy" },
    [7367] = { 2, "killed the Frostwolf Explosives Expert near the Iceblood Garrison, so the Horde's mines could be disarmed and stay down" },
    [7368] = { 2, "hunted down the Stormpike Explosives Expert in the first tower on the Field of Strife, so their landmines would stay disarmed" },
    [7381] = { 3, "cut down Korrak the Bloodrager again on his return to the Field of Strife, and brought his skull to Warmaster Laggrond this time" },
    [7382] = { 3, "ended Korrak the Bloodrager once more on his return, and took his skull to Lieutenant Haggerdin, who wanted the corpse burned this time" },
    [7383] = { 1, "filled a phial at the Oracle Tree's moonwell, the first and most powerful on Teldrassil, as Corithras told of the dragons' refusal" },
    [7401] = { 1, "ripped the spine from a slain dwarf for Sergeant Yazra Bloodsnarl, a warning to all who opposed the Frostwolf" },
    [7402] = { 1, "pulled a tooth from a slain orc as proof for Corporal Noreg Stormpike, by his standing order to the Stormpike soldiers" },
    [7429] = { 1, "unlocked Knot Thimblejack's chains in the Gordok wing, to the goblin's loud delight" },
    [7441] = { 2, "chased the imp Pusillin through the Warpwood Quarter to recover Azj'Tordin's stolen book of incantations" },
    [7461] = { 3, "destroyed Immol'thar in his prison and ended Prince Tortheldrin, to lay the spirits of Eldre'Thalas to rest" },
    [7463] = { 2, "extracted Hydrospawn's essence, an anomaly in the east wing that Lorekeeper Lydros wanted catalogued, for a useful cantrip" },
    [7481] = { 2, "searched Dire Maul for Kariel Winthalus, an elven master who fled with ancient artifacts, and found only that they were lost" },
    [7482] = { 2, "looked through Dire Maul for the lost elven master Kariel Winthalus and the knowledge he carried, and found no trace of him" },
    [7483] = { 1, "brought Lorekeeper Lydros the Libram of Rapidity and costly reagents, for an arcanum that lends armour a little haste" },
    [7484] = { 1, "found the Libram of Focus, lost somewhere in that wing, so Lorekeeper Lydros could conjure its arcanum" },
    [7485] = { 1, "returned the Libram of Protection, whose loss had made its owner weep like an infant, to Lorekeeper Lydros for an arcanum" },
    [7488] = { 3, "stopped the blood elf mage Lethtendris and took her web, which ensnared Dire Maul's magic, before it could do lasting harm" },
    [7489] = { 3, "defeated Lethtendris, who meant to turn Dire Maul's tainted magic on her enemies, and brought her web to Talo Thornhoof" },
    [7490] = { 3, "presented the Head of Onyxia, brood mother of the Black Dragonflight, to Thrall in Orgrimmar" },
    [7493] = { 1, "learned to make a cloak of the brood mother's scales, a shield against the incendiary breath of Nefarian, Lord of Blackrock" },
    [7495] = { 3, "presented the Head of Onyxia to Highlord Bolvar Fordragon, long held under her gaze, and saw Stormwind's honour restored" },
    [7507] = { 2, "returned Foror's Compendium of Dragon Slaying, its seal broken, to the Athenaeum rather than selling it on the black market" },
    [7508] = { 1, "presented Lorekeeper Lydros with a dull elven blade, to be heated in a dragon's breath and tempered in her blood" },
    [7509] = { 3, "let Onyxia's breath heat the ancient blade, then slew her and drove it into her corpse to forge Quel'Serrar" },
    [7563] = { 2, "collected the blood of Winterspring's owl beasts, maddened by Darkwhisper Gorge, as ink for the glyphs that would bind a dreadsteed" },
    [7564] = { 1, "delivered the case of owl beast blood to Gorzeeki Wildeyes, Mor'zul's alchemist, to be made into ink for the dreadsteed parchment" },
    [7581] = { 2, "spilled the blood of the Wildspawn satyrs in Dire Maul's Warpwood Quarter, to bond and power Daio's crystal prison for a Doomguard" },
    [7582] = { 2, "gathered the Tears of the Hederine from the demons of Darkwhisper Gorge, crystals hard enough to hold even a Doomguard" },
    [7583] = { 3, "imprisoned a Doomguard Commander in the Tainted Scar with Daio's crystal prison while it fought wildly to escape" },
    [7602] = { 2, "harvested flawless fel essences in Azshara, Jaedenar and the Blasted Lands, so Impsy could make the fel fire to raise Kroshius" },
    [7603] = { 3, "reignited the infernal Kroshius in Shatter Scar Vale and slew him for his core, Niby's price for teaching an infernal's summoning" },
    [7622] = { 3, "saved the peasants fleeing Stratholme, as Eris Havenfire never could, so her cursed existence would not go on" },
    [7623] = { 1, "crossed Jaedenar cloaked by Gorzeeki's shadowy potions to ask Lord Banehollow of the Shadow Council for Xorothian stardust" },
    [7624] = { 2, "confronted Ulathek, Lord Banehollow's servant and Hel'nurath's spy, and brought back the traitor's heart to win the dreadlord's favour" },
    [7625] = { 1, "bought Xorothian stardust from Ur'dan, Lord Banehollow's servant, for the parchment that would open a portal to Xoroth" },
    [7626] = { 1, "procured elixirs of shadow power for Gorzeeki's Bell of Dethmoora, one of three tools for the Circle of Greater Summoning" },
    [7627] = { 1, "found large brilliant shards and dark iron ore for the Wheel of the Black March, which would direct the ritual's violent energies" },
    [7628] = { 1, "acquired black dragonscales for Gorzeeki's Doomsday Candle, whose flames would burn any wayward demon that disrupted the ritual" },
    [7629] = { 2, "carried Gorzeeki's imp in a jar into the Scholomance's alchemy lab, where it infused the dreadsteed parchment with Xorothian stardust" },
    [7630] = { 1, "obtained arcanite bars for Gorzeeki's black lodestone, which would keep the dreadsteed ritual from fizzling out" },
    [7631] = { 3, "performed the ritual of the Circle of Greater Summoning to open a portal to Xoroth, then defeated a dreadsteed and bound its spirit" },
    [7632] = { 2, "sought the owner of an ancient petrified leaf that glowed green with something old and powerful" },
    [7634] = { 2, "slew an adult blue dragon for sinew, so Hastat the Ancient could bind his leaf into a quiver unseen in 10,000 years" },
    [7635] = { 2, "slew a mature black dragon for its sinew, so Stoma the Ancient could enchant an almost indestructible bowstring" },
    [7636] = { 3, "faced alone the four demonic corrupters of the Burning Legion, for their heads and Vartrus the Ancient's stave" },
    [7637] = { 1, "bought High Priest Rohan's exorcism censer with a generous donation, a first sacrifice on the road to a charger" },
    [7640] = { 2, "drove the tormented spirits out of Terrordale with the exorcism censer, passing the Light's judgment on them" },
    [7642] = { 1, "assembled runecloth, arcanite, Arthas' Tears, holy water and a hefty fee so Grimand Elmore could make a charger's barding" },
    [7643] = { 2, "slew Tendris Warpwood in Dire Maul to free the Ancient Equine Spirit, and soothed it so it would bless the barding" },
    [7645] = { 1, "paid Merideth Carlson, once called mad by the Silver Hand, in gold and manna biscuits for her spirit horse feed" },
    [7646] = { 1, "found an Azerothian and a Pristine Black diamond for Lord Grayson Shadowbreaker, the last pieces of a divination scryer" },
    [7647] = { 3, "defeated Death Knight Darkreaver in the Great Ossuary of Scholomance to redeem the soul of the fallen charger he rode" },
    [7649] = { 1, "returned a tome of the Athenaeum to Lorekeeper Lydros, who tore out its platemail recipe in thanks" },
    [7650] = { 1, "brought a second Athenaeum tome on enchanted thorium platemail home to Lorekeeper Lydros, for the page he tore out of it" },
    [7651] = { 1, "handed the third volume on enchanted thorium platemail back to Lorekeeper Lydros, its rightful keeper, for the recipe inside" },
    [7667] = { 1, "brought Sagorne Creststrider two diamonds to finish a divination scryer that could pierce the shadows of the Great Ossuary" },
    [7701] = { 3, "killed Overseer Maltorius, the Thorium Brotherhood traitor commanding the Dark Iron crew of the Slag Pit, for the bounty" },
    [7703] = { 3, "won back the Gauntlet of Gordok Might from Prince Tortheldrin, proof of being the true ruler of the Gordok" },
    [7704] = { 1, "brought Chambermaid Pillaclencher's gigantic ornate pillow to Evonice Sootsmoker, who was overjoyed to have it" },
    [7721] = { 1, "collected water elemental cores along the Forgotten Coast to fuel Zorbin Fandazzle's Ultra-Shrinker and thin the elementals" },
    [7722] = { 2, "recovered the Thorium Brotherhood's secret plans for fiery flux, stolen by the traitor Maltorius into the Slag Pit" },
    [7723] = { 1, "pounded Heavy War Golems around the Cauldron for Hansel Heavyhands, whose fingers had swollen too fat to fight" },
    [7724] = { 1, "killed the fire-spitting Greater Lava Spiders that upset the children, a job Hansel Heavyhands passed along" },
    [7725] = { 1, "zapped more of Feralas' giants down to size for Zorbin Fandazzle, who promised to spread the word among his goblin friends" },
    [7726] = { 1, "prised more cores from the sea elementals for Zorbin Fandazzle, still struggling to set up shop on the Forgotten Coast" },
    [7727] = { 1, "cleared incendosaurs from the Slag Pit's lava pools so the Thorium Brotherhood could send its teams down to explore" },
    [7728] = { 1, "got back a smithing tuyere and a lookout's spyglass the Dark Irons had stolen from the Thorium Brotherhood" },
    [7729] = { 1, "culled the Dark Iron taskmasters and slavers of the Searing Gorge for Taskmaster Scrange, to be rid of the competition" },
    [7730] = { 2, "drove into the Writhing Deep to thin the Zukk'ash insects that were sending the gnolls into a frenzy against Camp Mojache" },
    [7731] = { 3, "killed Stinglasher, a giant insect of the Writhing Deep, and cut out its glands for Hadoken Swiftstrider to study" },
    [7732] = { 1, "delivered Camp Mojache's report on the Zukk'ash to Zilzibin Drumlore in Orgrimmar, an expert on such alien creatures" },
    [7733] = { 1, "took hides from the tougher yetis of Rage Scar Hold for Pratt McGrubben, an even better source for his leatherwork" },
    [7734] = { 1, "braved the yetis of Rage Scar Hold for hides Jangdor Swiftstrider expected to be harder still once cured" },
    [7735] = { 1, "brought Pratt McGrubben a pristine yeti hide, perhaps the finest he had seen, from which he meant to make something special" },
    [7738] = { 1, "offered Jangdor Swiftstrider a perfect yeti hide, the finest specimen he had ever seen, to make into something special" },
    [7761] = { 2, "found the brand General Drakkisath guarded, to bear the Mark of Drakkisath that opens the way into Blackwing" },
    [7781] = { 3, "laid the head of Nefarian, Lord of Blackrock, before Highlord Bolvar Fordragon, a victory the Alliance had not known in years" },
    [7783] = { 3, "brought the head of Nefarian, son of Deathwing, back to Thrall in Orgrimmar" },
    [7786] = { 3, "brought the Bindings of the Windseeker, elementium and the Essence of the Firelord so Highlord Demitrian could free Thunderaan" },
    [7787] = { 3, "forced the lying Highlord Demitrian, after the Windseeker's defeat, to wake the dormant blade Thunderfury" },
    [7788] = { 1, "defended Silverwing Hold in Warsong Gulch against the Horde, who were felling the sacred forest for their war machines" },
    [7789] = { 1, "fought the Silverwing Sentinels in Warsong Gulch, for a Horde that held the wilds of Ashenvale its own to harvest" },
    [7815] = { 1, "killed the saltwater snapjaws that kept stealing Katoom the Angler's bait, a service to the fishermen of Revantusk Village" },
    [7816] = { 2, "hunted down Gammerita, the thieving leader of the saltwater snapjaws, to cut Katoom the Angler's best lure from her stomach" },
    [7828] = { 1, "stalked the Silvermane wolves that lie in wait for Revantusk's hunters, who had lost many brave trolls to them" },
    [7829] = { 1, "slew the savage owlbeasts whose claws and beaks had cost Revantusk many a good warrior" },
    [7830] = { 2, "brought down a Razorbeak Skylord for Huntsman Markhor, who wondered how many of his hunters the elder gryphon had devoured" },
    [7838] = { 2, "won a dozen Arena Master trinkets on the floor of the Gurubashi Arena, enough to be named its Grandmaster" },
    [7839] = { 1, "recovered Smith Slagtree's stolen tools from the Vilebranch, a gift from the gnome who saved his life when he was young" },
    [7840] = { 1, "fetched Lard's lunch back from his secret picnic spot on the island to the north, where the Vilebranch had chased him off" },
    [7841] = { 2, "slaughtered the Highvale high elves at the Quel'Danil Lodge, a message in blood to the Wildhammer for their new alliance" },
    [7842] = { 1, "killed the gryphons of the Hinterlands for their long feathers, the next part of Otho Moji'ko's message to the Wildhammer" },
    [7843] = { 3, "planted Otho Moji'ko's blood-drenched spear by the well in the heart of Aerie Peak, the final message to the Wildhammer" },
    [7844] = { 2, "destroyed Vilebranch scalpers and soothsayers for Mystic Yayo'jin, a depraved tribe that feeds on other trolls" },
    [7845] = { 2, "climbed Jintha'alor to find Elder Torntusk, Primal Torntusk's mate, taken in a raid to be sacrificed to Hakkar" },
    [7846] = { 3, "killed Hitah'ya the Keeper for the key to Elder Torntusk's shackles, freeing him to go home to Revantusk Village" },
    [7848] = { 2, "recovered a core fragment in Blackrock Depths, so Lothos Riftwaker could open the rift into the maw of the Firelord" },
    [7849] = { 2, "recovered the bones of Huntsman Markhor's twin brother from the Vilebranch oozes and wolves, to save at least his soul" },
    [7850] = { 2, "stole the vessels of tainted blood from Jintha'alor, the blood god's magic driving the Vilebranch to ferocity and madness" },
    [7861] = { 3, "slew Vile Priestess Hexx and her Aman'zasi guard atop Jintha'alor, a crippling blow to the Vilebranch" },
    [7862] = { 2, "cut down Vilebranch berserkers, shadow hunters, blood drinkers and soul eaters to apply for Revantusk's Guard Captain" },
    [7871] = { 1, "pushed the invading Horde back from Silverwing Hold in Warsong Gulch, to spare the evergreens of the sacred forest" },
    [7872] = { 1, "battled the Horde in Warsong Gulch for the Silverwing Sentinels, whose sacred forest was being felled for war machines" },
    [7873] = { 1, "defended Silverwing Hold in Warsong Gulch against the Horde, who were felling the sacred forest for their war machines" },
    [7874] = { 1, "cut down the Silverwing Sentinels in Warsong Gulch, who would stop the Horde harvesting Ashenvale's woods" },
    [7875] = { 1, "battled the Alliance in Warsong Gulch for the Warsong Outriders, so the Horde could keep logging Ashenvale" },
    [7876] = { 1, "fought the Silverwing Sentinels in Warsong Gulch, for a Horde that held the wilds of Ashenvale its own to harvest" },
    [7881] = { 1, "made carnival boots for the Darkmoon Faire, whose folk praised the craftsmanship and paid in tickets" },
    [7882] = { 1, "stitched rugged leather jerkins for the Darkmoon Faire in trade for its tickets" },
    [7883] = { 1, "brought the Darkmoon Faire costume pieces for the world's largest gnome, should one big enough ever be found" },
    [7884] = { 1, "crafted what the Darkmoon Faire needed for its Crocolisk Boy and Bearded Murloc act" },
    [7885] = { 1, "supplied the Darkmoon Faire with armour kits, one of them just right to patch a rip in a tent" },
    [7889] = { 1, "made coarse weightstones for the Darkmoon Faire, neither too heavy nor too light for building muscle" },
    [7890] = { 1, "hauled heavy grinding stones to a Faire hand who meant to build muscle lifting them" },
    [7894] = { 1, "built copper modulators for a secret Darkmoon Faire construction" },
    [7895] = { 1, "tinkered whirring bronze gizmos for a Faire booth meant to be the wonder of the world" },
    [7896] = { 1, "made green fireworks to announce that a Darkmoon Faire booth was ready, whenever it would be" },
    [7897] = { 1, "provided mechanical repair kits so the Faire's tinker could get everything working again" },
    [7898] = { 1, "made thorium widgets for Yebb, a clever and maybe devious gnome of the Darkmoon Faire" },
    [7899] = { 1, "gathered small furry paws for toys and baubles that would draw more visitors to the Faire" },
    [7900] = { 1, "collected torn bear pelts to be sewn into plush toys for the Faire, the envy of children across Azeroth" },
    [7901] = { 1, "brought in soft bushy tails, prizes to make the Faire's visitors happy and bring their friends" },
    [7902] = { 1, "gathered vibrant plumes to spark imaginations at the Darkmoon Faire's show" },
    [7903] = { 1, "hunted bats for evil eyes to frighten visitors at the Darkmoon Faire" },
    [7907] = { 1, "returned a full deck of Beast cards to the Darkmoon Faire, as a mysterious ninth card had bidden" },
    [7927] = { 1, "presented the completed Portals Deck at the Faire for one of its greater cards, as the deck's ninth card asked" },
    [7928] = { 1, "took the finished Warlords Deck back to the Darkmoon Faire, a gesture the Darkmoon would not soon forget" },
    [7929] = { 1, "handed in a whole deck of Elemental cards at the Darkmoon Faire, where its ninth card promised a reward" },
    [7937] = { 1, "followed Sayge's warm fortune to a haystack by the stable of the Eastvale Logging Camp, where a lockbox lay hidden" },
    [7938] = { 1, "followed a fortune into the Deadmines, through a shimmering portal to a strange chest with a lockbox inside" },
    [7944] = { 1, "sought a fortune in the heart of Wailing Caverns, where a strange chest appeared beyond a shimmering portal" },
    [7945] = { 1, "traced a fortune to a tree stump outside Palemane Rock in Mulgore, a lockbox hidden within" },
    [8053] = { 1, "brought Primal Hakkari Bindings out of Zul'Gurub to Jin'rokh the Breaker, a heathen's first proof among the Zandalar freethinkers" },
    [8054] = { 1, "wrested a Primal Hakkari Shawl from Hakkar's minions for Jin'rokh, honouring the freethinkers who never wavered against the Blood God" },
    [8055] = { 1, "took a Primal Hakkari Tabard most painfully from the fools of Zul'Gurub, to prove worth as a freethinker to Jin'rokh once and for all" },
    [8056] = { 1, "offered Maywiki of Zuldazar a Primal Hakkari Armsplint from Zul'Gurub, to earn the bracers the Zandalar augurs prize above all others" },
    [8057] = { 1, "proved worth to Maywiki of Zuldazar with a Primal Hakkari Stanchion, for bracers fit for a Zandalar haruspex" },
    [8058] = { 1, "claimed vengeance on Hakkar's minions in the tribe's name, a Primal Hakkari Armsplint for Jin'rokh and the way of the vindicator" },
    [8059] = { 1, "carried a Primal Hakkari Stanchion out of Zul'Gurub so Al'tabim the All-Seeing would teach the power of the demoniac" },
    [8060] = { 1, "pried Primal Hakkari Bindings from Zul'Gurub for Al'tabim the All-Seeing, mojo the Zandalar meant to turn on the risen Blood God" },
    [8061] = { 1, "fought Hakkar's minions for a Primal Hakkari Stanchion, so Al'tabim would show what it means to be a Zandalar confessor" },
    [8062] = { 1, "hunted Hakkar's minions for Primal Hakkari Bindings, to show Falthir the Sightless how a hunter rates among Zandalar predators" },
    [8063] = { 1, "sowed madness in Zul'Gurub for a Primal Hakkari Armsplint, the price Falthir the Sightless set on the first of the madcap's armours" },
    [8064] = { 1, "delivered a Primal Hakkari Sash to Maywiki of Zuldazar, its latent power a treasure to the tribe, for a haruspex's belt" },
    [8065] = { 1, "took a Primal Hakkari Tabard from Zul'Gurub to Maywiki of Zuldazar, the offering that made a haruspex revered among the tribe" },
    [8066] = { 1, "stalked Hakkar's minions for a Primal Hakkari Shawl, mojo Falthir the Sightless meant to turn against the Blood God's schemes" },
    [8067] = { 1, "won a Primal Hakkari Aegis in Zul'Gurub for Falthir the Sightless, and with it the right to wear the Zandalar predator's mantle" },
    [8068] = { 1, "gathered a Primal Hakkari Shawl in Zul'Gurub for Al'tabim the All-Seeing, to earn the honoured mantle of the Zandalar illusionists" },
    [8069] = { 1, "wrested a Primal Hakkari Kossack from Zul'Gurub for Al'tabim, the price of an illusionist's robe said never to look the same twice" },
    [8070] = { 1, "faced the depravity of Hakkar's Gurubashi for a Primal Hakkari Sash, Al'tabim the All-Seeing's next step against the Blood God" },
    [8071] = { 1, "carried a Primal Hakkari Aegis to Al'tabim the All-Seeing, retribution on Hakkar's minions repaid with a confessor's mantle" },
    [8072] = { 1, "weaved madness on the Zandalar's enemies in Zul'Gurub until a Primal Hakkari Girdle earned Falthir's madcap mantle" },
    [8073] = { 1, "seized a Primal Hakkari Aegis from Zul'Gurub for Falthir the Sightless, a feat few thought possible, for the madcap's prized tunic" },
    [8074] = { 1, "offered Maywiki of Zuldazar a Primal Hakkari Girdle, proof of evil vanquished in Zul'Gurub, for the belt the Zandalar augurs wear" },
    [8075] = { 1, "defeated the evil that seeps out of Zul'Gurub for a Primal Hakkari Tabard, which Maywiki repaid with an augur's hauberk" },
    [8076] = { 1, "gained a Primal Hakkari Sash in Zul'Gurub for Al'tabim the All-Seeing, power the Zandalar needed to survive their enemies" },
    [8077] = { 1, "tore a Primal Hakkari Kossack from Zul'Gurub for Al'tabim the All-Seeing, a victory that assured the tribe Hakkar would not prevail" },
    [8078] = { 1, "wreaked havoc on Hakkar's minions for a Primal Hakkari Girdle, Jin'rokh's proof that Zul'Gurub had tasted Zandalar vengeance" },
    [8079] = { 1, "made Hakkar's minions pay for the mojo stolen from the Zandalar, a Primal Hakkari Kossack for Jin'rokh and a vindicator's breastplate" },
    [8080] = { 2, "won the battle for Arathi Basin and brought a crate of its resources to Sergeant Maclear, to arm and feed the Alliance's troops" },
