    [8183] = { 3, "carried the Heart of Hakkar to Molthor on Yojamba Isle, proof that the Soulflayer had been slain" },
    [8184] = { 1, "took a Primal Hakkari Idol from Hakkar's mightiest lieutenants so Zanza could work the Presence of Might, an old troll enchantment" },
    [8185] = { 1, "searched the jinxed hoodoo for a punctured voodoo doll, half of what Zanza needed to make the Syncretist's Sigil" },
    [8186] = { 1, "stripped a Primal Hakkari Idol from the Hakkari lieutenants for Zanza, whose old troll mojo would become Death's Embrace" },
