    [8201] = { 3, "strung the heads of the high priests who channelled the troll gods' power into Hakkar, to weaken him, for Exzhal on Yojamba Isle" },
    [8222] = { 1, "collected glowing scorpid blood for paint to turn cheap junk into glowing treasure at the Faire" },
    [8227] = { 1, "returned the measuring tape Nat Pagle lost in Zul'Gurub, the one he had measured his biggest fish with" },
    [8231] = { 1, "tracked wavethrashers along the coast of Azshara for scales that mirror a hunter's strength, for Ogtinc's charm" },
    [8232] = { 3, "slew the green drake Morphaz in the Temple of Atal'Hakkar with others, for the last trophy of Ogtinc's charm" },
    [8234] = { 2, "recovered Lord Jorach Ravenholdt's Sealed Azure Bag from a Timbermaw shaman in Azshara, who had bought it from the thieves as a holy relic" },
    [8235] = { 1, "gathered the encoded fragments of Archmage Xylem's ruined books from the beasts of Azshara, so he could break the azure bag's enchantment" },
    [8236] = { 3, "hunted the green drake Morphaz deep in the Temple of Atal'Hakkar for the Azure Key Lord Ravenholdt thought lost forever" },
    [8240] = { 1, "destroyed a Hakkari Bijou at the Altar of Zanza, one more wrested from the Blood God's minions" },
