    [8252] = { 1, "pried enchanted coral from the spitelash sirens, who had stripped the bay of it, for Archmage Xylem's research" },
    [8253] = { 3, "slew the green drake Morphaz in the Sunken Temple for the arcane shard in his stomach, swallowed with Xylem's apprentice" },
    [8255] = { 1, "hunted the mosshoof coursers of Azshara for their glands, first part of Ogtinc's restorative salve to heal Felwood" },
    [8256] = { 1, "took an ichor of undeath from the lingering highborne of Eldarath, the one part poison the Felwood salve called for" },
    [8257] = { 3, "slew the green drake Morphaz in the sunken temple of Atal'Hakkar for the blood Greta Mosshoof needed to begin healing Felwood" },
    [8258] = { 3, "killed Death Knight Darkreaver in the Scholomance's Great Ossuary, who threatened to twist the spirit realm to his bidding" },
    [8277] = { 2, "gathered stingers and fangs so Beetix Ficklespragg could try to brew an antidote for her poisoned cousin Noggle" },
    [8278] = { 3, "fetched poison samples from the deadlier creatures of the far south for Noggle's antidote, which at last brought him round" },
    [8279] = { 2, "wrested the three chapters of the Twilight Lexicon from the Twilight Keepers, so Hermit Ortell could decode the tablet" },
    [8280] = { 2, "culled the dredge strikers that had ravaged a shipment of morrowgrain, to keep Cenarion Hold's supply lines open" },
    [8281] = { 1, "killed dredge crushers before the bigger southern worms could take the strikers' place along the Hold's supply lines" },
    [8282] = { 1, "recovered the satchel of rare reagents Noggle lost fleeing Deathclasp, without which no potions could be made for the Hold" },
    [8283] = { 3, "hunted down Deathclasp, terror of the sands, to open the southern mountains as a path around the silithid hives" },
    [8284] = { 2, "searched the ruins of a Twilight's Hammer camp for pieces of a clay tablet, to learn why the cult was in Silithus" },
