    [8287] = { 3, "delivered the decoded tablet to Commander Mar'alith, shedding some light on what the Twilight's Hammer did in Silithus" },
    [8288] = { 3, "slew Broodlord Lashlayer, who guards the way to Nefarian's inner sanctum, and brought his head to Baristolth" },
