    [8301] = { 2, "proved the makings of a hero to the Brood of Nozdormu with carapace torn from the silithid of all three hives" },
    [8302] = { 1, "tore two hundred more carapace fragments from the hives, each load earning Baristolth's leave to name another deputy" },
    [8304] = { 2, "questioned the dwarves of Bronzebeard's Encampment for Commander Mar'alith, whose beloved Natalia had gone missing" },
    [8305] = { 2, "gazed into the Crystalline Tear by the sacred barrier, a token of all that was lost in the War of the Shifting Sands" },
    [8306] = { 3, "ventured into Hive'Regal after Commander Mar'alith's lost Natalia, and found the monster that C'Thun had made of her" },
    [8307] = { 1, "searched the Twilight's Hammer camp west of Cenarion Hold for how they made bitter sandworm meat palatable" },
    [8308] = { 1, "carried Brann Bronzebeard's lost letter to his old camp, word of a tunnel into Ahn'Qiraj and a plea for his monkey" },
    [8309] = { 2, "took rubbings from the glyphed crystals of all three hives, hoping they would explain why the hives were spewing out bugs" },
    [8310] = { 1, "collected a brain from each kind of hive silithid for Frankal Stonebridge's elixir, meant to help read the glyphs" },
    [8311] = { 1, "trick-or-treating at the city inns for Jesper, a child at the Stormwind Orphanage too sick to go" },
    [8312] = { 1, "went trick-or-treating for Spoops, a sick child at the Orgrimmar Orphanage, and did every trick the innkeepers asked" },
    [8313] = { 1, "brought the torn recipe page to Calandrath, who could make sense of the Twilight's Hammer's names for desert herbs" },
    [8314] = { 1, "took the glyphed crystal prism to Geologist Larksbane, hoping she could unlock the messages hidden in it" },
    [8315] = { 3, "drew the Glyphs of Calling at the Bones of Grakkarond and slew the Qiraji Emissary who came, for the crystals' key" },
    [8317] = { 1, "cooked smoked desert dumplings for Calandrath from the Twilight's Hammer recipe, which turned out surprisingly good" },
    [8318] = { 1, "took encrypted texts off Twilight's Hammer cultists for Bor Wildmane, so fewer of their secret orders went around" },
    [8320] = { 2, "struck at the heads of the serpent, the Twilight geolords who led the cult's rituals in the camps of Silithus" },
    [8321] = { 3, "killed Vyral the Vile, leader of the Twilight's Hammer in the cave of Twilight's Run, his signet ring the proof" },
    [8322] = { 1, "fought into the Southshore Inn to drop rotten eggs in its main brew keg, ruining the humans' prized ale for weeks to come" },
    [8323] = { 1, "collected the cult's coded bulletins for Hermit Ortell, who wanted to know whether his old order still hunted him" },
    [8332] = { 2, "won crests from Abyssal Templars so Aurel Goldleaf could forge a cult medallion to fool the Abyssal Council" },
    [8341] = { 2, "found shards and signets for Aurel Goldleaf's ring of lordship, a disguise to lure an Abyssal Lord into ambush" },
    [8348] = { 2, "summoned one of the Abyssal Dukes and destroyed it, its signet brought to Bor Wildmane to shake the cult's underlings" },
    [8352] = { 3, "brought down a Lord of the Abyssal Council with a battle-ready force, its scepter carried back to Bor Wildmane as proof" },
    [8353] = { 1, "clucked like a chicken at Innkeeper Firebrew for an Ironforge Mint, a treat for a sick child's Hallow's End" },
    [8354] = { 1, "clucked like a chicken for Innkeeper Norman, the price of an Undercity Mint for a sick child" },
    [8355] = { 1, "made train noises at Talvash del Kissel for a Gnomeregan Gumdrop meant for a sick child" },
    [8356] = { 1, "flexed for Innkeeper Allison to earn Stormwind Nougat for a sick child's Hallow's End" },
    [8357] = { 1, "danced for Innkeeper Saelienne in exchange for Darnassus Marzipan for a sick child" },
    [8358] = { 1, "chugged like a train for Kali Remik in Sen'jin Village to win a Darkspear Gumdrop for a sick child" },
    [8359] = { 1, "flexed for Innkeeper Gryshka, who wanted a show of strength before handing over Orgrimmar Nougat for a sick child" },
    [8360] = { 1, "danced for Innkeeper Pala in Thunder Bluff, the price of Thunder Bluff Marzipan for a sick child" },
    [8361] = { 2, "beat an Abyssal Templar, one of the elementals giving the cult orders, to throw its chain of command into disarray" },
    [8365] = { 1, "took hats off the Southsea pirates of Lost Rigger Cove for the Haughty Modiste, who dressed kings and warchiefs" },
    [8366] = { 2, "taught the Southsea pirates of Lost Rigger Cove a lesson for Bilgewhizzle, since they had begun ignoring the Cartel's protection money" },
    [8373] = { 1, "scrubbed Forsaken stink bombs off Southshore with a pine cleaner for Sergeant Hartman during Hallow's End" },
    [8410] = { 1, "gathered samples of air, fire, earth and water for Bath'rah the Windwatcher, to show readiness for his summons" },
    [8411] = { 1, "presented Bath'rah the Windwatcher with the four elements, the proof he wanted before trusting a shaman" },
    [8412] = { 1, "gathered bear claws and spider eyes in the Western Plaguelands for a spirit totem to protect Bath'rah from the spirits that turned on him" },
    [8413] = { 2, "killed six trolls of the Sunken Temple for their voodoo feathers, so Bath'rah's spirit totem would let him sleep at last" },
    [8414] = { 1, "collected minion's scourgestones for High Priest Thel'danis at Uther's Tomb, so their evil could be dispelled" },
    [8416] = { 1, "carried a purged scourgestone to Commander Ashlam Valorfist, who meant to bathe the Scourge in righteous fire" },
    [8418] = { 2, "took voodoo feathers from the troll priests of the Sunken Temple, magic to forge a Holy Mightstone against the undead" },
    [8419] = { 1, "brought felcloth from the satyrs of Felwood to the imp Impsy, the sign of good faith he asked for" },
    [8420] = { 1, "looted felcloth from the Felwood satyrs for Impsy, who wanted a pet of his own just as Niby had him" },
    [8421] = { 1, "tore rotting wood from the irontree folk and essence from the tainted oozes, for the eyes and demon smell of Impsy's homemade pet" },
    [8422] = { 2, "killed Gasher, Mijan, Zolo, Hukku, Zul'lor and Loro in the Sunken Temple for the voodoo feathers to stuff Impsy's pet" },
    [8423] = { 1, "killed helboars in the Blasted Lands, the test of strength the Fallen Hero of the Horde set before asking an honorable task" },
    [8424] = { 2, "slaughtered the Shadowsworn, whose dark rituals tormented the spirit of the Fallen Hero of the Horde" },
    [8425] = { 3, "destroyed the troll guardians of the Sunken Temple for voodoo feathers to lend the Fallen Hero of the Horde a body for a moment" },
    [8446] = { 2, "found a druid to decipher a Nightmare Engulfed Object, whose corruption seemed tied to the dragons out of the Dream" },
    [8447] = { 2, "waited as Keeper Remulos cleansed the nightmare-engulfed object in Lake Elune'ara, revealing a ring of Malfurion's" },
    [8460] = { 1, "drove back the corrupted Deadwood furbolgs near the Emerald Sanctuary, to earn the trust of Grazle and the wary Timbermaw" },
    [8461] = { 2, "cleared the corrupted Deadwood camp near Timbermaw Hold for Nafien, who grieved that his tribe must fight its own brethren" },
    [8464] = { 2, "thinned the enraged Winterfall furbolgs of Winterfall Village, grown hostile to the Timbermaw, for Salfa" },
    [8470] = { 1, "took a Deadwood ritual totem into Timbermaw Hold, where the furbolgs hoped to learn from it what poisoned their brethren's minds" },
    [8471] = { 1, "brought a Winterfall Ritual Totem, heavy with dread, to the Timbermaw, who found in it the taint that set the Winterfall against them" },
    [8481] = { 3, "summoned and destroyed the demon Xandivious at High Chief Winterfall's cave, the corruption at the root of the Winterfall tribe" },
    [8484] = { 2, "bore the Timbermaw Offering of Peace to King Magni Bronzebeard in Ironforge, a first step toward peace with the furbolgs" },
    [8485] = { 2, "carried the Timbermaw Offering of Peace to Thrall in Orgrimmar, a first step toward peace with the furbolgs" },
    [8492] = { 1, "smelted copper bars for Sergeant Stonebrow in Ironforge, metal for the Alliance's war materiel against Ahn'Qiraj" },
    [8494] = { 1, "brought iron bars to a grudging Corporal Carnes as the Alliance geared up for war in Ahn'Qiraj" },
    [8496] = { 1, "provided heavy bandages for Cenarion Hold, its field supply run dangerously low after recent casualties" },
    [8497] = { 1, "put together survival kits of water, anti-venom and dumplings, to keep the Hold's fresh recruits alive in the desert" },
    [8498] = { 2, "intercepted battle orders carried by guarded Twilight Prophets, so Commander Mar'alith could anticipate the cult's attacks" },
    [8499] = { 1, "supplied thorium bars to Dame Twinbraid for the battalion of steam tanks the Alliance meant to airlift into Silithus" },
    [8501] = { 1, "shot down airborne Hive'Ashi stingers in Cenarion Hold's assault on Hive'Ashi" },
    [8502] = { 1, "killed Hive'Ashi workers so the silithid would struggle to repair their hive once the assault had damaged it" },
    [8503] = { 1, "pulled stranglekelp for Private Draxlegauge, who needed a great deal of it for the Ahn'Qiraj war effort" },
    [8505] = { 1, "picked purple lotus for Master Nightsong, herbs for the Alliance's stand against the ruthless silithid advance" },
    [8507] = { 1, "served field duty with Captain Blackanvil's Ironforge Brigade outside Hive'Zora, before greater tasks at Cenarion Hold" },
    [8509] = { 1, "collected Arthas' Tears for Sergeant Major Germaine, under orders for the Ahn'Qiraj war effort that nobody explained" },
    [8511] = { 1, "skinned light leather for Bonnie Stoneflayer, whose family of skinners tanned it for the Alliance's war materiel" },
    [8513] = { 1, "brought medium leather to Private Porter, who tracked every piece gathered for the war at Ahn'Qiraj" },
    [8515] = { 1, "hauled thick leather to an excited Marta Finespindle, who needed a ton of it for the Ahn'Qiraj war effort" },
    [8517] = { 1, "made linen bandages for Sentinel Silversky, for a war at Ahn'Qiraj expected to be long and bloody" },
    [8519] = { 2, "watched a forgotten memory of the War of the Shifting Sands in the crystal, down to Staghelm's betrayal" },
    [8520] = { 1, "rolled silk bandages for Nurse Stonefield so the soldiers bound for Ahn'Qiraj would have everything they needed" },
    [8522] = { 1, "donated runecloth bandages to Keeper Moonshade, to give those sent to Ahn'Qiraj every advantage to survive" },
    [8524] = { 1, "fished and cooked rainbow fin albacore for Slicky Gastronome, food for the soldiers of the Ahn'Qiraj War" },
    [8526] = { 1, "roasted raptor for Sarah Sadwhistle, a reluctant volunteer stocking food for the soldiers bound for Ahn'Qiraj" },
    [8528] = { 1, "caught and cooked spotted yellowtail for Huntress Swiftriver's stockpile, food that would keep until the war began" },
    [8532] = { 1, "smelted copper ore into bars for Miner Cromwell in Orgrimmar, raw metal for the Horde's war materiel" },
    [8534] = { 1, "reached Cenarion Scout Azenel deep in Hive'Zora for her written report on the silithid's movements" },
    [8535] = { 1, "summoned and destroyed a Hoary Templar, one of the elemental nobles the Twilight's Hammer worships" },
    [8536] = { 1, "called up an Earthen Templar and put an end to it, so the cult outside Ahn'Qiraj would not catch the Hold off guard" },
    [8537] = { 1, "found a way to summon a Crimson Templar and slew it, the cult's elemental nobles too great a threat to ignore" },
    [8538] = { 3, "lured the Dukes of Cynders, Fathoms, Zephyrs and Shards into this world and destroyed them, the cult's chief organizers" },
    [8539] = { 1, "cut down Hive'Zora hive sisters with the reinforcements called to the assault on Hive'Zora" },
    [8540] = { 1, "procured ornate mithril boots for the mounted division of the Cenarion Hold guard, who were short of them" },
    [8541] = { 1, "supplied the Cenarion Hold guard with grinding stones, dense, solid and heavy, of which they had run short" },
    [8542] = { 1, "made tin bars for Grunt Maug, who would rather have been sharpening weapons for the war on the insects of Ahn'Qiraj" },
    [8544] = { 1, "handed the Qiraji Bindings of Command to Andorgos, to be shaped into pauldrons more dreadful than the wings of Nefarian" },
    [8545] = { 1, "mined and smelted mithril for Senior Sergeant T'kelah, bars to build what the Horde would need for the coming war" },
    [8549] = { 1, "gathered peacebloom for Herbalist Proudfeather, to be brewed into potions for the Horde's coming trial at Ahn'Qiraj" },
    [8551] = { 2, "won back Captain Smotts' chest from Gorlash, one of the sea giants who had wrecked his ship and killed his crew" },
    [8552] = { 2, "returned a sash embroidered HS to Captain Smotts, proof that Mok'rash, one of the giants who had wrecked his ships, was dead" },
    [8554] = { 3, "baited the giant Negolash with buzzard wings and wine, then killed him to recover Captain Smotts' cutlass" },
    [8559] = { 1, "gave Kandrostrasz the Qiraji Bindings of Command, magic to give a dragon pause, to be made into boots" },
