    [8578] = { 1, "searched the Molten Core for Narain Soothfancy's scrying goggles, lost there a month before by someone nosing around" },
    [8580] = { 1, "collected firebloom for Batrider Pele'keiki, who guessed the Horde wanted it for things that go boom" },
