    [8587] = { 1, "hauled Dirge's 500 pound chicken back to Narain Soothfancy, who dug into it with both fists" },
    [8588] = { 1, "skinned heavy leather for Skinner Jamani, for the armour, reinforcement and plain tarps of the Horde's war materiel" },
