    [8593] = { 1, "brought Ouro's Intact Hide to Kandrostrasz to prove worthy of the dragons, for leggings of the worm's unnatural skin" },
    [8594] = { 1, "carried the bindings of the highest Qiraji leaders to Andorgos, who made pauldrons of them and fallen Qiraji scales" },
