    [8603] = { 2, "carried the Husk of the Old God, a piece of the slain C'Thun, to Vethsera, who had not expected anyone to come back" },
    [8604] = { 1, "stockpiled wool bandages for Healer Longrunner's first aid kits, since soldiers in the field cannot rely on a healer" },
