    [8729] = { 3, "casted the Arcanite Buoy into the Bay of Storms' Swirling Maelstrom to face Maws, for a shard Anachronos needed" },
    [8730] = { 3, "slew Nefarian for the Red Scepter Shard before he could destroy it, as the dying Vaelastrasz begged" },
    [8731] = { 1, "served field duty with Krug Skullsplit's Orgrimmar Legion outside Hive'Regal, who signed the papers in silithid blood" },
    [8733] = { 1, "sought Malfurion's agent outside Darnassus, the first step toward cleansing Eranikus of the Old Gods' taint" },
    [8735] = { 2, "drew fragments of the Nightmare's corruption from the dragonkin of the four dream portals, for Keeper Remulos' ritual" },
    [8736] = { 3, "held Nighthaven against Eranikus without slaying him, keeping Keeper Remulos alive until Tyrande came to redeem the dragon" },
    [8737] = { 1, "drew out an Azure Templar and destroyed it, the elemental nobles of the Twilight's Hammer being a danger to the Hold" },
    [8738] = { 1, "searched Hive'Regal for Cenarion Scout Landion, watching the silithid there for days, and brought back his report" },
    [8739] = { 1, "found Cenarion Scout Jalia inside Hive'Ashi and carried her report back so the Hold could act on it quickly" },
    [8740] = { 2, "defeated the twilight marauders and their leader Morna, mounted cultists picking off Cenarion Hold's patrols and caravans" },
    [8741] = { 2, "carried the green scepter shard to Anachronos at the Caverns of Time, a piece of the Scepter of the Shifting Sands" },
    [8742] = { 3, "took up the Scepter of the Shifting Sands, made whole at last, to shatter the prophecy of C'Thun" },
    [8743] = { 3, "banged the gong, and watched a special crystal spring from the ground beside it, perhaps a sign of the Brood's favour" },
    [8746] = { 3, "freed Metzen, one of Great-father Winter's eight reindeer, from the kidnappers who sent Smokywood Pastures ransom letters" },
    [8762] = { 3, "rescued Metzen the Reindeer with a pouch of reindeer dust, following the clues in the two ransom letters sent to Smokywood Pastures" },
    [8763] = { 1, "fed deeprock salt and five gold to a Holly Preserver, a secret shared with the hero of the day, for holly that never goes bad" },
    [8770] = { 1, "slew Hive'Ashi defenders in the attack on Hive'Ashi, the silithid an ever growing threat to Cenarion Hold's war" },
    [8771] = { 1, "stalked Hive'Ashi sandstalkers in Cenarion Hold's assault on their hive" },
    [8772] = { 1, "killed Hive'Zora waywatchers for Commander Mar'alith as fresh reinforcements pressed the attack on Hive'Zora" },
    [8773] = { 1, "felled Hive'Zora reavers in the attack on their hive, for a victory Commander Mar'alith thought near" },
    [8774] = { 1, "killed Hive'Regal ambushers in the assault on Hive'Regal, the silithid having menaced every operation of the war" },
    [8775] = { 1, "brought down airborne Hive'Regal spitfires as the war effort turned on their hive" },
    [8776] = { 1, "slew Hive'Regal slavemakers during Cenarion Hold's assault on Hive'Regal" },
    [8777] = { 1, "rooted out Hive'Regal burrowers as Cenarion Hold carried the war to Hive'Regal" },
    [8778] = { 1, "gathered volatile oils, rocket fuel and blasted powder for Arcanist Nozzlespring of the Ironforge Brigade" },
    [8779] = { 1, "procured scrying materials for Geologist Larksbane, whose studies had served Cenarion Hold well" },
    [8780] = { 1, "restocked the Ironforge Brigade's armour kits, run dangerously low on the battlefield outside Hive'Zora" },
    [8781] = { 1, "armed the Ironforge Brigade with moonsteel broadswords, many of its supplies lost on the way to Silithus" },
    [8782] = { 1, "gathered mooncloth, runecloth and spider silk for uniforms, the newest volunteers having left Cenarion Hold short" },
    [8783] = { 1, "provided enchanted thorium and leather for Vargus, Cenarion Hold's blacksmith, so the troops could stay well equipped" },
    [8785] = { 1, "collected mojo and oils of immolation for Shadow Priestess Shai, for a concoction the silithid would not like" },
    [8786] = { 1, "delivered massive iron axes to Merok Longstride, weapons the Orgrimmar Legion had asked for and the Hold could not spare" },
    [8787] = { 1, "replaced the armour kits the Orgrimmar Legion had lost on its way to Silithus" },
    [8789] = { 1, "brought Imperial Qiraji Armaments and elementium to Arygos for weapons that would cut through the Qiraji and their god" },
    [8790] = { 1, "fetched Imperial Qiraji Regalia and elementium for Merithra of the Dream, for weapons deadly to the Old God's servants" },
    [8791] = { 3, "presented the head of Ossirian the Unscarred at Cenarion Hold, the cruel menace of the Ruins finally laid to rest" },
    [8798] = { 1, "learned to build a mechanical yeti from Umi, her thanks to a fellow engineer for helping teach her friends a lesson" },
    [8799] = { 1, "used the Holly Preserver on deeprock salt and five gold, a reward for the hero of the day, for holly that would never wilt" },
    [8801] = { 3, "pried an eye stalk from the remains of C'Thun, an evil older than the world, for the dragons in the next chamber" },
    [8802] = { 3, "took the Eye of C'Thun to Anachronos at the Caverns of Time, the last step of a journey of legend" },
    [8804] = { 1, "assembled survival kits for the recruits of Cenarion Hold, prey to thirst and poison in the desert" },
    [8805] = { 1, "found a batch of ornate mithril boots for Captain Vish Kozus and his mounted guard" },
    [8806] = { 1, "kept the guard of Cenarion Hold in grinding stones, a supply they had run short of" },
    [8807] = { 1, "found shards and a huge emerald for Geologist Larksbane's scrying, her research of great value to the war" },
    [8808] = { 1, "supplied uniform cloth to Windcaller Proudhorn for the latest influx of volunteers" },
    [8809] = { 1, "fetched enchanted bars and leather so Vargus could forge powerful weapons for the Hold's forces" },
    [8810] = { 1, "restocked Windcaller Proudhorn's heavy bandages after recent casualties left the battlefield short of them" },
    [8829] = { 2, "gathered what Aurel Goldleaf needed to copy a twilight emissary's robe and try the cult's stones as a way through" },
    [8856] = { 1, "packed desert survival kits of water, anti-venom and baked salmon for the inexperienced volunteers at Cenarion Hold" },
    [8857] = { 1, "rushed a fresh husk sample from the fallen Colossus of Ashi to Oglethorpe Obnoticus in Booty Bay before it could rot" },
    [8858] = { 1, "carried a husk of the Colossus of Regal to Overseer Oilfist in Searing Gorge, who meant to make armour of its chitin" },
    [8859] = { 1, "hurried a husk of the Colossus of Zora to Lord Maxwell Tyrosus, who hoped its secrets would help against the Scourge" },
    [8860] = { 1, "delivered Smokywood Pastures fare to Innkeeper Allison in Stormwind to feed the crowds at the new year celebration" },
    [8861] = { 1, "brought Smokywood Supplies to Innkeeper Pala in Thunder Bluff to feed the people come to celebrate the new year" },
    [8867] = { 1, "launched fireworks for the Lunar Festival, the yearly celebration of Moonglade's triumph over an ancient evil" },
    [8868] = { 3, "summoned and defeated Omen, a fallen hero of the War of the Ancients, to quiet his rage for another year and earn Elune's blessing" },
    [8869] = { 3, "killed the Crimson Hammersmith so Lilith would train a hammersmith, a path that closes those of sword and axe" },
    [8897] = { 1, "carried Lieutenant Heldric's carefully penned note to his sweetheart Colara Dean, though he feared she would forget him for richer men" },
    [8898] = { 1, "delivered a letter rewritten twelve times by a smitten admirer to Colara Dean, who still remembered his beard and smile" },
    [8899] = { 1, "took an immaculate letter to Colara Dean from an admirer left at a loss for words after thousands of years of them" },
    [8900] = { 1, "delivered a note to Elenia Haydon in the Undercity from an orc laughed at for the connection he had felt with her" },
    [8901] = { 1, "carried a tauren's letter asking Elenia Haydon to come to Mulgore, a love she knew she could not return" },
    [8902] = { 1, "brought Elenia Haydon a letter from the sweetheart she had been betrothed to a lifetime ago, too nervous to give it himself" },
    [8903] = { 2, "got a Stormwind guard's love card for Aristan Mottar, who feared an unnatural epidemic of love had reached the city guards" },
    [8904] = { 2, "got a guardian's moldy love card for Fenstad Argyle, who feared an unnatural epidemic of love was weakening the Undercity" },
    [8905] = { 1, "drew blood from the frostsabers and bears of Winterspring for Deliana, who offered finer bracers in trade for it" },
