    [8913] = { 1, "gathered venom from the spiders and scorpions of Silithus for Mokvar, who would trade far finer armour for plain Wildheart Bracers" },
    [8914] = { 1, "collected Silithus venom from its spiders and scorpions for Mokvar, who offered a far finer piece for plain Beaststalker's Bindings" },
    [8915] = { 1, "drew venom from the spiders and scorpions of Silithus for Mokvar, the favour he asked before trading up the Magister's Bindings" },
    [8916] = { 1, "fetched venom samples from the spiders and scorpions of Silithus for Mokvar, who would trade far better bracers for Devout Bracers" },
