    [8923] = { 1, "carried venom samples to Mux Manascrambler as payment, in hope his device could reach the ghost of Anthion Harmon" },
    [8924] = { 2, "harvested ectoplasm from the restless dead of Silithus, Winterspring and the Eastern Plaguelands for Mux's ghost revealer" },
    [8925] = { 2, "slew Magma Lord Bokk in the Burning Steppes for the magma core that would power Mux's ghost revealer" },
    [8928] = { 1, "bought a Fel Elemental Rod from a shifty imp in Darkwhisper Gorge, the last part of Mux's ghost revealer" },
    [8929] = { 1, "tried a goblin's ghost revealer at the gates of Stratholme to speak with Anthion Harmon, slain there by the undead" },
    [8930] = { 1, "tested a goblin's invention at Stratholme's gates to learn what the ghost of Anthion Harmon knew" },
    [8945] = { 3, "rescued Ysida Harmon from Baron Rivendare, finishing what her husband Anthion had attempted" },
    [8946] = { 2, "carried Ysida's Locket to the ghost of Anthion Harmon as proof she lived, so he could rest in peace at last" },
    [8947] = { 1, "gathered dark iron, leather, mooncloth and hides for Anthion Harmon, to take a piece of Valthalak's medallion by force" },
    [8949] = { 1, "killed ogres for their warbeads to feed Falrin Treeshaper's hatred, his brother having died at their hands" },
    [8950] = { 1, "gathered a spectre's essence, dark runes and brilliant shards for Falrin Treeshaper's enchantment on a challenge banner" },
    [8951] = { 2, "relayed Anthion's parting words to Deliana: Valthalak's curse would end only when his split medallion was mended, with Bodley's help" },
    [8952] = { 2, "relayed Anthion's parting words to Deliana: Valthalak's curse would end only when his split medallion was mended, with Bodley's help" },
