    [8957] = { 1, "carried Anthion's parting words to Mokvar, that only Bodley could find the pieces of Valthalak's amulet and so end the curse" },
    [8958] = { 2, "relayed Anthion's parting words to Deliana: Valthalak's curse would end only when his split medallion was mended, with Bodley's help" },
    [8959] = { 2, "relayed Anthion's parting words to Deliana: Valthalak's curse would end only when his split medallion was mended, with Bodley's help" },
    [8960] = { 1, "took a goblin's ghost revealer to Blackrock Mountain to find Bodley, who never came back from Blackrock Spire" },
    [8961] = { 2, "gathered the remains of three nobles of fire and a Hallowed Brazier, to recover the rest of Lord Valthalak's amulet" },
    [8962] = { 1, "took Druidical Remains from the silithid of Hive'Regal, to call the druid Mor Grayhoof's spirit to Bodley's brazier" },
    [8963] = { 1, "wrested a Starbreeze Village Relic from the Frostmaul giants, to draw the priestess Isalien's spirit to Bodley's brazier" },
    [8964] = { 1, "took a Brilliant Sword of Zealotry from Tyr's Hand, to call up Jarien and Sothos, who had aspired to Scarlet knighthood" },
    [8965] = { 1, "gathered Soul Ashes of the Banished on Purgation Isle, to summon the ogre necromancer Kormok with Bodley's brazier" },
    [8966] = { 2, "summoned and slew the spirit of Mor Grayhoof, possessed by a piece of Lord Valthalak's amulet, so it could rest in peace" },
    [8967] = { 2, "summoned and slew the spirit of Isalien, a priestess ambushed in Dire Maul by Alzzin the Wildshaper, to put her to rest" },
    [8968] = { 2, "summoned Jarien and Sothos with the Brazier of Beckoning and slew them for the left piece of Lord Valthalak's amulet" },
    [8969] = { 2, "summoned Kormok's spirit in Ras Frostwhisper's chamber and slew him for the left piece of Lord Valthalak's amulet" },
    [8970] = { 2, "gathered bloodkelp from the Strashaz naga of Alcaz Island so Bodley could divine where the last piece of the amulet lay" },
    [8977] = { 1, "handed Deliana the Extra-Dimensional Ghost Revealer built by Mux, a goblin device she distrusted but had no choice but to rely on" },
    [8979] = { 2, "brought the fashionable cologne and perfume to Apothecary Zinge, to test Fenstad Argyle's hunch that foul alchemy was clouding minds" },
    [8980] = { 1, "brought Fenstad Argyle word from Apothecary Zinge that the new perfumes held traces of mind control potions" },
    [8982] = { 1, "asked Innkeeper Norman where his popular perfume had come from, tracing the tainted fragrances for Fenstad Argyle" },
    [8983] = { 1, "tracked down Mara Rennick, the new merchant who had sold the tainted perfume to Innkeeper Norman" },
    [8984] = { 3, "found the maker of the tainted perfume, Apothecary Staffron Lerent, who meant it to weaken Alliance and Horde for the Shadow Council" },
    [8985] = { 1, "recovered a Starbreeze Village Relic from the Frostmaul giants, to entice the spirit of Isalien, who grew up there" },
    [8986] = { 1, "gathered Druidical Remains around Hive'Regal, to call up Mor Grayhoof, whose Cenarion Circle friends fell there" },
    [8987] = { 1, "won a Brilliant Sword of Zealotry in Tyr's Hand, so Bodley could call up the Scarlet-minded siblings Jarien and Sothos" },
    [8988] = { 1, "took Soul Ashes from Purgation Isle, where the ogre Kormok loved summoning the banished dead, to lure his spirit" },
    [8989] = { 2, "laid the possessed spirit of Mor Grayhoof to rest and brought Bodley the reassembled amulet of Lord Valthalak" },
    [8990] = { 2, "laid Isalien's possessed spirit to rest and brought Bodley the reassembled amulet of Lord Valthalak" },
    [8991] = { 2, "called Jarien and Sothos back with the Brazier of Beckoning for the right piece of Lord Valthalak's amulet" },
    [8992] = { 2, "called up Kormok's spirit in the Scholomance and slew him for his piece, making Lord Valthalak's amulet whole" },
    [8994] = { 1, "stripped bracers from the orcs of Blackrock Spire and found a Flask of Supreme Power, to attune Bodley's brazier" },
    [8995] = { 3, "summoned Lord Valthalak in the Beast's old chamber and killed him again, so his spirit could take back his amulet" },
    [8996] = { 2, "brought Bodley the Brazier of Beckoning and word that Lord Valthalak would call off his spectral assassins" },
    [9007] = { 2, "saw Mokvar and the others delivered at last from the mistakes of their past, the long business of Valthalak's curse behind them" },
    [9008] = { 2, "closed the long business of Valthalak's curse with Mokvar, who said those efforts had delivered them all from the mistakes of their past" },
    [9009] = { 2, "finished the matter of Valthalak's curse for Mokvar, who said it had delivered them from the mistakes of their past" },
    [9010] = { 2, "ended the long business of Valthalak's curse with Mokvar, who spoke of a debt that might never be repaid" },
    [9011] = { 2, "closed the tale of Valthalak's cursed amulet with Mokvar, who said those efforts had delivered them from the mistakes of the past" },
    [9012] = { 2, "finished the long business of Valthalak's curse for Mokvar, delivered at last with the others from the mistakes of their past" },
    [9013] = { 2, "saw the business of Valthalak's curse through for Mokvar, who said those efforts had delivered them from the mistakes of the past" },
    [9014] = { 2, "ended the matter of Valthalak's curse with Mokvar, who called it a truly amazing story and was delivered from the mistakes of the past" },
    [9015] = { 2, "defied High Justice Grimstone in the Ring of the Law to draw out Theldren and his gladiators, for a piece of Lord Valthalak's amulet" },
    [9016] = { 1, "returned with Anthion's last words to Mokvar, that Bodley alone could find the pieces of Valthalak's amulet and lift its curse" },
    [9017] = { 1, "carried Anthion's parting words to Mokvar, that the curse would end only with Valthalak's amulet made whole, and only Bodley could find its pieces" },
    [9018] = { 1, "reported Anthion's parting words to Mokvar, that Bodley was the only hope of finding the rest of Valthalak's amulet and ended the curse" },
    [9019] = { 1, "took Anthion's last words to Mokvar, that only Bodley could find the remaining pieces of Valthalak's amulet and stop its spell" },
    [9020] = { 1, "relayed Anthion's parting words to Mokvar, that Bodley was the one hope of making Valthalak's amulet whole and ended the curse" },
    [9021] = { 1, "delivered Anthion's last words to Mokvar, that Bodley alone could find the rest of Valthalak's amulet and end the curse on them" },
    [9022] = { 1, "bore Anthion's parting words back to Mokvar, that only Bodley could find the remaining pieces of Valthalak's amulet and lift the curse" },
    [9023] = { 2, "took venom sacs from Kurinnaxx and Venoxis for Dirk Thunderwood, who sought a new poison for Lord Ravenholdt" },
    [9024] = { 2, "carried cologne and perfume to Morgan Pestle to test Aristan Mottar's suspicion that foul alchemy had clouded the guards' thinking" },
    [9025] = { 1, "told Aristan Mottar that Morgan Pestle had found traces of love potions and mind-altering draughts in the new perfumes" },
    [9026] = { 1, "asked Innkeeper Allison at The Gilded Rose where the cologne everyone wanted had come from" },
    [9027] = { 1, "questioned Evert Sorisam at The Finest Thread, the new merchant behind the cologne sold at The Gilded Rose" },
    [9028] = { 3, "traced the cologne to Apothecary Staffron Lerent behind Ravenholdt Manor, who brewed it to leave Alliance and Horde lovesick and weak" },
    [9032] = { 1, "searched Blackrock Mountain with a goblin's ghost revealer for Bodley, never heard of since he set out for Blackrock Spire" },
    [9033] = { 2, "entered Naxxramas to destroy the Scourge Kel'Thuzad was amassing for another attack, proof of dedication to the Dawn" },
    [9034] = { 1, "brought Korfax a Desecrated Breastplate and plate scraps from Naxxramas for a Dreadnaught Breastplate, armour worn by heroes" },
    [9036] = { 1, "carried Desecrated Legplates back from Naxxramas for Korfax to remake as Dreadnaught Legplates, armour of heroes" },
