    [9052] = { 1, "collected bloodcap and Gorishi stings for Torwa Pathfinder's toxin, to pacify a great creature of Un'Goro unharmed" },
    [9053] = { 2, "recovered a putrid vine from the bottom of the Temple of Atal'Hakkar, to make Torwa Pathfinder's toxin strong enough" },
