    [9058] = { 1, "handed Huntsman Leopold Desecrated Boots and Nexus Crystals for Cryptstalker Boots, armour never before seen in the world" },
    [9059] = { 1, "took Desecrated Handguards to Huntsman Leopold, who could join them with crypt fiend carapace into Cryptstalker Handguards" },
    [9060] = { 1, "delivered a Desecrated Girdle and wartorn chain scraps to Huntsman Leopold for a Cryptstalker Girdle" },
    [9061] = { 1, "returned Desecrated Wristguards from Naxxramas to Huntsman Leopold to be fashioned into Cryptstalker Wristguards" },
    [9068] = { 1, "returned a Desecrated Tunic, armour of those who fell defending these lands, to Rimblat Earthshatter for an Earthshatter Tunic" },
    [9069] = { 1, "recovered Desecrated Legguards, armour of the fallen put to evil in Naxxramas, for Rimblat Earthshatter's Earthshatter Legguards" },
    [9070] = { 1, "brought Rimblat Earthshatter a Desecrated Headpiece and wartorn chain scraps to renew as an Earthshatter Headpiece" },
    [9071] = { 1, "gathered mooncloth and arcanite so Rimblat Earthshatter could purify Desecrated Spaulders into Earthshatter Spaulders" },
    [9072] = { 1, "carried Desecrated Boots to Rimblat Earthshatter, so the armour of the fallen could be worn for battle once more as Earthshatter Boots" },
    [9073] = { 1, "handed Rimblat Earthshatter Desecrated Handguards and purification materials for a pair of Earthshatter Handguards" },
    [9074] = { 1, "took a Desecrated Girdle back from the Scourge to Rimblat Earthshatter, to be remade as an Earthshatter Girdle" },
    [9075] = { 1, "honored the fallen by bringing their Desecrated Wristguards to Rimblat Earthshatter for Earthshatter Wristguards" },
    [9077] = { 1, "supplied Rohan the Assassin with a Desecrated Breastplate and leather scraps for a Bonescythe Breastplate, the bones his part" },
    [9078] = { 1, "brought Rohan the Assassin Desecrated Legplates from the floating city of death, and his price, for Bonescythe Legplates" },
    [9079] = { 1, "paid Rohan the Assassin for his troubles and handed him a Desecrated Helmet to make a Bonescythe Helmet" },
    [9080] = { 1, "gathered hides and a Nexus Crystal so Rohan the Assassin could build Bonescythe Pauldrons from desecrated ones" },
    [9081] = { 1, "traded Desecrated Sabatons and coin to Rohan the Assassin for a pair of Bonescythe Sabatons" },
    [9082] = { 1, "carried Desecrated Gauntlets down from Naxxramas for Rohan the Assassin to make into Bonescythe Gauntlets" },
    [9083] = { 1, "took a Desecrated Waistguard to Rohan the Assassin, who would supply the bones for a Bonescythe Waistguard" },
    [9084] = { 1, "delivered Desecrated Bracers, leather scraps and his fee to Rohan the Assassin for Bonescythe Bracers" },
    [9085] = { 3, "unmasked and destroyed a Shadow of Doom, one of the Lich King's most frightening creatures, at a Scourge summoning circle" },
    [9086] = { 1, "recovered a Desecrated Tunic, stripped from a fallen hero and taken to Naxxramas, for Rayne to craft into a Dreamwalker Tunic" },
    [9087] = { 1, "brought Rayne Desecrated Legguards and wartorn scraps so the armour of the fallen could become Dreamwalker Legguards" },
    [9088] = { 1, "took a Desecrated Headpiece back from the Scourge for Rayne to make into a Dreamwalker Headpiece" },
    [9089] = { 1, "gathered the hides and Nexus Crystal Rayne needed to make Dreamwalker Spaulders from desecrated ones" },
    [9090] = { 1, "carried Desecrated Boots and mooncloth to Rayne, who would craft Dreamwalker Boots from them" },
    [9091] = { 1, "handed Rayne Desecrated Handguards, armour the Scourge had stripped from the dead, for Dreamwalker Handguards" },
    [9092] = { 1, "reclaimed a Desecrated Girdle from Naxxramas so Rayne could make a Dreamwalker Girdle" },
    [9093] = { 1, "delivered Desecrated Wristguards and an Arcane Crystal to Rayne for a pair of Dreamwalker Wristguards" },
    [9095] = { 1, "brought Archmage Angela Dosantos a Desecrated Robe for a Frostfire Robe, archmage's armour described in one of Medivh's tomes" },
    [9096] = { 1, "gathered mooncloth and Nexus Crystals so Angela Dosantos could make Frostfire Leggings from a design in Medivh's books" },
    [9097] = { 1, "carried a Desecrated Circlet to Archmage Angela Dosantos, who knew the Frostfire Circlet from Medivh's own tomes" },
    [9098] = { 1, "supplied Angela Dosantos with what she needed for Frostfire Shoulderpads, a design found among Medivh's personal effects" },
    [9099] = { 1, "handed Archmage Angela Dosantos Desecrated Sandals from Naxxramas for a pair of Frostfire Sandals" },
    [9100] = { 1, "took Desecrated Gloves and mooncloth to Angela Dosantos at Light's Hope for Frostfire Gloves" },
    [9101] = { 1, "traded a Desecrated Belt and wartorn scraps to Archmage Angela Dosantos for a Frostfire Belt" },
    [9102] = { 1, "delivered Desecrated Bindings to Angela Dosantos, the Watcher who learned of Frostfire from Medivh's tomes, for Frostfire Bindings" },
    [9103] = { 1, "met Mataus the Wrathcaster's high price for a Plagueheart Robe, its darkness enough to destroy them both" },
    [9104] = { 1, "brought Mataus the Wrathcaster Desecrated Leggings for Plagueheart Leggings, dark work he priced high" },
    [9105] = { 1, "carried a Desecrated Circlet to Mataus the Wrathcaster, who would risk the darkness of Plagueheart only for riches" },
    [9106] = { 1, "handed Mataus the Wrathcaster Desecrated Shoulderpads and hides for Plagueheart Shoulderpads, whatever the darkness in them" },
    [9107] = { 1, "took Desecrated Sandals to Mataus the Wrathcaster, who meant to die a rich man, for Plagueheart Sandals" },
    [9108] = { 1, "gathered what Mataus the Wrathcaster demanded for a pair of Plagueheart Gloves" },
    [9109] = { 1, "traded a Desecrated Belt and Arcane Crystals to Mataus the Wrathcaster for a Plagueheart Belt" },
    [9110] = { 1, "delivered Desecrated Bindings and wartorn scraps to Mataus the Wrathcaster for Plagueheart Bindings" },
    [9111] = { 1, "brought Father Inigo Montoy the vestments of the fallen and reagents of purification for a Robe of Faith" },
    [9112] = { 1, "returned Desecrated Leggings, stripped from those who died in battle, to Father Inigo Montoy for Leggings of Faith" },
    [9113] = { 1, "carried a Desecrated Circlet to Father Inigo Montoy, to be purified into a Circlet of Faith" },
    [9114] = { 1, "restored a little dignity to the fallen by taking their Desecrated Shoulderpads to Father Inigo Montoy for Shoulderpads of Faith" },
    [9115] = { 1, "handed Father Inigo Montoy Desecrated Sandals and purified reagents for Sandals of Faith" },
    [9116] = { 1, "took the Desecrated Gloves of the departed to Father Inigo Montoy for Gloves of Faith" },
    [9117] = { 1, "gathered reagents of purification for Father Inigo Montoy to make a Belt of Faith from desecrated remnants" },
    [9118] = { 1, "delivered Desecrated Bindings to Father Inigo Montoy at Light's Hope for Bindings of Faith" },
    [9120] = { 3, "carried the Phylactery of Kel'Thuzad, all that remained of the master of Naxxramas, to Light's Hope Chapel instead of destroying it" },
    [9121] = { 1, "paid Archmage Angela Dosantos in crystals and gold for the Kirin Tor cloaking that slips past the wards of Naxxramas" },
    [9122] = { 1, "brought arcane and nexus crystals to Archmage Angela Dosantos for the cloaking that opens the rune portal into Naxxramas" },
    [9123] = { 1, "received at no cost, for unwavering service to the Argent Dawn, the arcane cloaking that opens the way into Naxxramas" },
    [9124] = { 1, "collected crypt fiend parts for Huntsman Leopold, who made Cryptstalker armour for those who venture into Naxxramas" },
    [9126] = { 1, "smashed Scourge for the bone fragments Rohan the Assassin always needed more of for his Bonescythe armour" },
    [9128] = { 1, "gathered cores of elements from elementals across the world for Archmage Angela Dosantos, who paid in insignias" },
    [9131] = { 1, "scrounged Dark Iron scraps for Korfax to put together sets of Dreadnaught armour for the Dawn's champions" },
    [9136] = { 1, "picked savage fronds for Rayne's Dreamwalker armour, made for the heroes who enter Naxxramas" },
    [9153] = { 2, "battled the Scourge around a necropolis's magic circles to break the defenses of the floating fortresses, for the Argent Dawn" },
    [9165] = { 1, "carried a writ of safe passage, signed once a caravan had made it through the Scourge, back to Dispatch Commander Metz" },
    [9229] = { 2, "searched Naxxramas for Ramaladni, a pupil of Highlord Mograine who went in seeking vengeance and never returned" },
    [9230] = { 2, "found a Frozen Rune so Korfax could restore Ramaladni's ring, broken and all that was found of him" },
    [9232] = { 1, "brought Craftsman Wilhelm frozen runes and sapphires for a pair of pants, the one recipe Omarion had left him" },
    [9233] = { 1, "carried the dead craftsman Omarion's handbook of recipes to his old friend Craftsman Wilhelm at Light's Hope" },
    [9234] = { 1, "paid Craftsman Wilhelm to make Icebane Gauntlets from frozen runes, with the recipes the late Omarion left him" },
    [9235] = { 1, "brought Wilhelm frozen runes, thorium and his crafting fee for Icebane Bracers from Omarion's recipes" },
    [9236] = { 1, "commissioned an Icebane Breastplate from Craftsman Wilhelm, frozen runes from Naxxramas and thorium for a recipe of Omarion's" },
    [9237] = { 1, "supplied Craftsman Wilhelm with frozen runes and runecloth for a Glacial Cloak, a pattern from Omarion's handbook" },
    [9238] = { 1, "had Craftsman Wilhelm make Glacial Wrists from frozen runes and spider silk, thanks to Omarion's recipes" },
    [9239] = { 1, "gathered frozen runes and essences of water so Wilhelm could make Glacial Gloves from a recipe of Omarion's" },
    [9240] = { 1, "ordered a Glacial Vest from Craftsman Wilhelm, frozen runes, runecloth and silk for a pattern the late Omarion left" },
    [9241] = { 1, "traded frozen runes and enchanted leather to Craftsman Wilhelm for Polar Bracers, made from Omarion's recipes" },
    [9242] = { 1, "paid Craftsman Wilhelm's fee and brought frozen runes for Polar Gloves, one of Omarion's patterns" },
    [9243] = { 1, "commissioned a Polar Tunic from Craftsman Wilhelm with frozen runes and enchanted leather, by a recipe of the late Omarion" },
    [9244] = { 1, "collected frozen runes and heavy scorpid scales for Icy Scale Bracers that Wilhelm could make from Omarion's handbook" },
    [9245] = { 1, "brought Craftsman Wilhelm frozen runes and scorpid scales for Icy Scale Gauntlets, a recipe Omarion had left him" },
    [9246] = { 1, "ordered an Icy Scale Breastplate from Craftsman Wilhelm, frozen runes and scorpid scale for one of Omarion's recipes" },
    [9248] = { 1, "showed Aurel Goldleaf the scepter of a fallen Lord of the Abyssal Council, for a band to wear against the Qiraji" },
    [9251] = { 3, "recovered the head of Atiesh from Kel'Thuzad in Naxxramas and its base from Ahn'Qiraj, for Anachronos to make the staff whole" },
    [9257] = { 3, "defeated the hand of Sargeras, cast out of Atiesh on the consecrated earth of Stratholme, to cleanse the Greatstaff of the Guardian" },
    [9260] = { 2, "thinned the Scourge camped outside Stormwind and investigated their glowing runic circles, to learn what they were for" },
    [9261] = { 2, "thinned the Scourge camped outside Ironforge and investigated their glowing runic circles, to learn what they were for" },
    [9262] = { 2, "thinned the Scourge camped outside Darnassus and investigated their glowing runic circles, to learn what they were for" },
    [9263] = { 2, "thinned the Scourge camped outside Orgrimmar and investigated their glowing runic circles, to learn what they were for" },
    [9264] = { 2, "thinned the Scourge camped outside Thunder Bluff and investigated their glowing runic circles, to learn what they were for" },
    [9265] = { 2, "thinned the Scourge camped outside the Undercity and investigated their glowing runic circles, to learn what they were for" },
    [9269] = { 3, "faced the hand of Sargeras, driven out of Atiesh on Stratholme's consecrated earth, to cleanse the Greatstaff of the Guardian" },
    [9270] = { 3, "destroyed the demon cast out of Atiesh on the consecrated earth of Stratholme, the hand of Sargeras that befouled the staff" },
    [9271] = { 3, "overcame the hand of Sargeras, loosed from Atiesh where Lordaeron's knights were murdered, to cleanse the Greatstaff" },
    [9292] = { 1, "showed Lieutenant Orrin a cracked necrotic crystal from an abomination, a sign the Scourge had tried to make a camp inside Stormwind" },
    [9295] = { 1, "gave the Keeper of the Rolls a torn letter found on the Scourge, a soldier's words to a loved one, in hope of finding the family" },
    [9299] = { 1, "gave the Keeper of the Rolls a careworn note found on the Scourge, a soldier's words to a loved one, in hope of finding the family" },
    [9300] = { 1, "gave the Keeper of the Rolls a ragged page found on the Scourge, a soldier's words to a loved one, in hope of finding the family" },
    [9301] = { 1, "gave the Keeper of the Rolls a bloodstained envelope from the Scourge, a soldier's words to a loved one, in hope of finding the family" },
    [9302] = { 1, "gave the Keeper of the Rolls a crumpled missive from the Scourge, a soldier's words to a loved one, in hope of finding the family" },
    [9304] = { 1, "gave the Keeper of the Rolls a smudged document from the Scourge, a soldier's words to a loved one, in hope of finding the family" },
    [9310] = { 1, "showed Lieutenant Rukag a faint necrotic crystal from a fallen wight, a sign the Scourge had tried to make a camp in the Undercity" },
    [9319] = { 1, "touched the bonfires burning deep in Blackrock Spire, Dire Maul, Scholomance and Stratholme for the Midsummer Fire Festival" },
    [9322] = { 1, "visited the blue Midsummer fires of Winterspring, Azshara, Silithus and Un'Goro for the Festival Flamekeeper" },
    [9323] = { 1, "sought out the blue Midsummer fires of the Blasted Lands, the Plaguelands, the Hinterlands and Searing Gorge" },
    [9324] = { 2, "stole the flame from the heart of Orgrimmar itself for the Festival Loremaster's collection" },
    [9325] = { 2, "stole the flame of the shaman of Thunder Bluff for the Festival Loremaster's collection" },
    [9326] = { 2, "stole the smoldering flame from the ruins above the Undercity for the Festival Loremaster's collection" },
    [9330] = { 2, "stole the flame from the heart of Stormwind itself for the Festival Talespinner's collection" },
    [9331] = { 2, "stole the flame from the halls of Ironforge for the Festival Talespinner's collection" },
    [9332] = { 2, "stole the flame from the shores of Teldrassil for the Festival Talespinner's collection" },
    [9362] = { 2, "killed Warlord Krellian in the Temple of Zin-Malor for the prismatic shell Archmage Xylem's scrying had found" },
    [9364] = { 2, "polymorphed the Spitelash so the prismatic shell could gather their split essence, from which Archmage Xylem formed a new spell" },
    [9367] = { 1, "made sure the bonfires of Stormwind, Ironforge and Darnassus burned hot and bright for the Midsummer Fire Festival" },
    [9368] = { 1, "made sure the bonfires of Orgrimmar, Thunder Bluff and the Undercity burned hot and bright for the Midsummer Fire Festival" },
    [9388] = { 1, "checked that the green Midsummer fires of the Barrens, Darkshore, Ashenvale and Stonetalon still burned" },
    [9389] = { 1, "saw that the green Midsummer fires of the Wetlands, Silverpine, Westfall and Hillsbrad had not gone out" },
    [9419] = { 1, "carried silithyst across the desert to the Alliance extractor near Hive'Zora, to keep its bounty from the Horde" },
    [9422] = { 1, "hauled silithyst to the Horde's extractor near Hive'Regal, in a race with the Alliance for the desert's resources" },
    [9664] = { 2, "captured the four old towers of the Eastern Plaguelands, to tighten the Alliance's noose around the Forsaken" },
    [9665] = { 2, "seized the four towers of the Eastern Plaguelands to stave off an Alliance incursion on the Forsaken's eastern border" },
    [65593] = { 2, "procured the hearts of Avelina Lilly and Isaac Pearson, lovers at opposite ends of the world, as a lure for Carendin Halgar's incubus" },
    [65597] = { 3, "summoned an incubus over the lovers' hearts and beat it down, the trial Carendin Halgar set before he would teach the binding" },
    [65602] = { 2, "recovered a lovers' keepsake thousands of years old from a house in Ashenvale, the lure Gakin the Darkbinder needed to tempt an incubus" },
    [65603] = { 3, "called up an incubus with the old figurine in the crypts below the Slaughtered Lamb and defeated it, the trial before Gakin would bind it" },
    [65610] = { 2, "searched Fallen Sky Lake in Ashenvale for a sign of Krilge, the missing soldier Magar refused to believe a deserter" },
    [76156] = { 1, "slipped into the Venture Company mine in a flimsy disguise to steal seaforium charges, Boarton Shadetotem's test for a talent in the subtle arts" },
    [76160] = { 1, "crushed Windfury cones from beneath the harpy nests into a blade poison for Boarton Shadetotem, though it came out as pine nut butter" },
    [76240] = { 2, "filleted a smallfish with two knives before Boarton Shadetotem, his last try at finding a hidden talent, which proved to be ambidexterity" },
    [78261] = { 2, "stole the Horn of Xelthos out of Shadowfang Keep alone, a job left in a note by someone signing as C, with Veenix's help past the gate" },
    [78823] = { 1, "handed Hemet Nesingwary a primitive drawing of a great bird of prey, which he found interesting indeed" },
    [79007] = { 1, "followed a charred note from a burned-out camp, whose riddle pointed to the twin land and a stranger's next hiding place" },
    [79008] = { 1, "followed the riddle of a blistered note found in a burned-out camp, toward the twin land and a stranger's next hiding place" },
    [79192] = { 2, "tracked the note-writer toward a cosy spot between the Barrens and Desolace, after a note tied the charred dead to New Plague deliveries" },
    [79229] = { 1, "sought someone in Desolace who knew of a pillaged campsite where two humans and a dwarf lay dead, killed by no beast or centaur" },
    [79358] = { 2, "gathered twisted totems of all four elements for Veyric Thunderhame, to learn how the quilboar turned the elements and prepare a counter-ritual" },
    [79360] = { 3, "defeated Charlga Razorflank in Razorfen Kraul for word of the quilboar's plans, a cause of the elemental unrest Bath'rah the Windwatcher had sensed" },
    [79361] = { 2, "gathered twisted totems of all four elements for Prate Cloudseer, to turn back the storm the quilboar meant to flood Thousand Needles with" },
    [79362] = { 2, "found Grant Valor's mace in the skeleton at Raven Hill Cemetery that wounded him, perhaps the unfinished business keeping his spirit there" },
    [79363] = { 2, "drove the Defias out of Addle's Stead, perhaps the unfinished business of Silvia Valor's spirit, who guarded Raven Hill's homes in life" },
    [79366] = { 3, "set the twisted totems at the steam pools to call up the corrupted elementals and end the quilboar ritual, until the rumbling ground fell silent" },
    [79974] = { 1, "read the riddle of the waterfalls to find the eagle's nest, the next of the hidden note-writer's hideouts" },
    [79975] = { 1, "trailed the note-writer, loyal to the Eagle and Fist, toward an old barricade of the Old Kingdoms" },
    [79976] = { 2, "reached the last hideout at Thoradin's Wall just after the note-writer had gone back underground to keep the work from the wrong hands" },
    [79980] = { 1, "dug up the stash the note-writer had left a hundred paces north, down a steep cliffside, with enough to keep going" },
    [86574] = { 1, "recovered a dead courier's supplies from the Pridewing wyverns' nests, a shipment meant for Innkeeper Faralia at Stonetalon Peak" },
    [86576] = { 1, "collected the golden sunstones the Bloodfury harpies hoard in the Charred Vale, for Mor'rogal, who had a use for them" },
    [86585] = { 3, "raised a fallen mountaineer's trampled banner of Ironforge to call out Headsplitter, the trogg that had killed her" },
    [86613] = { 1, "returned the tools the excavators abandoned when the troggs overran their camp, for Magmar Fellhew's stalled dig" },
    [86614] = { 1, "returned a silver hair clip found in the debris to its owner, who had given it up for lost" },
    [86667] = { 1, "scooped a jar of snow at South Gate Pass for Norric Lochthane's shamanic workings, and got it to him before it could melt" },
    [86757] = { 2, "stripped swords and daggers from the orc grunts and scouts in eastern Ashenvale for Shandrina, to push the orcs back out of the forest" },
    [86758] = { 2, "hunted Daggerfang, the crocolisk that nearly took Marek Ironheart's hand, for the safety of the lake's other hunters" },
    [86776] = { 1, "smelted bronze bars for Morhan Coppertongue, whose forge in Thelsamar kept running short for tools, kettles and pots" },
    [86784] = { 1, "gathered firewood for Eleanor Shackleton's camp in the hills, a wanderer who knew the wilds of the Glades" },
    [87288] = { 1, "skinned Teldrassil's aggressive nightsabers for Aldia, a trader in Dolanaar who would make the pelts into blankets and shawls" },
    [87318] = { 2, "searched Thandol Span for Essene Villard, lost when the Dark Irons fell on her and her partner Corma" },
    [87491] = { 2, "escorted a fire elemental the Dark Irons kept caged in Dun Modr out to its freedom, eager as it was to burn them all" },
    [87760] = { 3, "slew the Stormscale beastmistress in the Ruins of Mathystra for her rod, so the naga could no longer enslave the threshers and sea turtles" },
    [88756] = { 2, "stole back the explosives the Dark Irons hauled off to Direforge Hill, before they could make mischief with the powder" },
    [88757] = { 1, "found the necklace, spellbook and waterskin Essene Villard dropped while fleeing the Dark Irons" },
    [88758] = { 1, "carried Essene's note back to Corma Villard, word that she was alive and on her way" },
    [90902] = { 2, "healed injured Deathguard with the Light through the pain it now caused, to reawaken what death had dulled" },
    [91208] = { 2, "sought out a newly risen paladin who had fled into the hills, to lead her back to the Light if she could be reached" },
    [91285] = { 1, "drove the Vile Fin murlocs back from Bandarion Keep, whose spawning grounds the new paladin order had taken" },
    [91316] = { 1, "scavenged lumber from a root cellar in ruined Shadowvale to rebuild Bandarion Keep, far from the Undercity's supplies" },
    [91317] = { 3, "ended the Tarnished at Shadowvale and took their commander Rudolph Gelhardt's head, risen paladins who still killed Forsaken" },
    [91723] = { 1, "thinned the kobold geomancers of Jasperlode Mine, whose crude magic kept throwing off Hamish Bergwort's instruments" },
    [91724] = { 1, "stopped the Defias wizards at Stone Cairn Lake, whose spells still disrupted Hamish Bergwort's instruments in the Tower of Azora" },
    [91725] = { 1, "found the enchanting supplies gnolls took from Blixie Fitzwink, sparing her weeks cleaning up after Theocritus's polymorph experiments" },
    [91732] = { 1, "fetched finely made picks from the depths of Jasperlode Mine for Hagar Lowe, whose logging tools had suffered for want of good steel" },
    [91733] = { 1, "fished Ormin Pelford's axe, saw and toolbox out of the river below Eastvale, washed away when his wagon tipped, among murlocs and wolves" },
    [91738] = { 1, "treated Sergeant De Vries to a bottle of Thunder Applejack, the first his troops had seen in months" },
    [91740] = { 2, "carried the head of Croaky to Ridgepoint Tower, the murloc leader whose kind had cost the watch two of its own" },
    [91741] = { 1, "returned a book a kobold had tried to eat to the little library Brother Paxton kept in the abbey" },
    [91743] = { 1, "rescued Brother Paxton's books from the kobolds of Northshire Valley before, as he feared, they devoured his whole library" },
    [91746] = { 1, "traded the head of Elmpaw to Helene Peltskinner near Goldshire, a trophy she would prepare for some collector's mantle" },
    [91751] = { 1, "skinned Elwynn's wolves for Helene Peltskinner, who needed pelts to finish her orders while her husband was busy by the abbey" },
    [91752] = { 2, "wrested the sack of picture books from Shinyfinder Narf deep in Echo Ridge Mine, who had his kobolds steal them for him" },
    [91753] = { 1, "disenchanted the kobolds' wax effigies for Kitta Firewind, a lesson in the crude magic they practise without any schooling" },
    [91772] = { 1, "followed the tracks of a kobold carrying off a sack of stolen books, which led toward the Fargodeep mine" },
    [91775] = { 2, "searched Fargodeep Mine for Brother Paxton's stolen books, above all Fun with Elementals, which even a kobold might use to summon a servant" },
    [91777] = { 3, "recovered the last two of Brother Paxton's books from Jasperlode Mine, where the kobolds' master might be summoning elementals" },
    [91860] = { 2, "searched Fenris Isle for the missing Earthen Ring envoys, a tauren and a cloaked elf, and found the tauren's body on the gnolls' pyre" },
    [91861] = { 2, "searched Fenris Keep for the elf of the Earthen Ring party, in hope she was still alive somewhere inside" },
    [91862] = { 3, "freed Lumina Windsinger, a shen'dorei Windshaper come to study the elements with the Earthen Ring, from the gnolls' cage in Fenris Keep" },
    [91920] = { 1, "took murloc eyes to Apothecary Renferrel for a better cure, since his potion of hearts had done nothing for Quinn Yorick" },
    [91921] = { 2, "rushed Renferrel's new potion to Quinn Yorick at the Ivar Patch, who had begun to resign himself to becoming a ghoul" },
    [92109] = { 1, "gathered vials, silverleaf and peacebloom for an odd little girl hiding in a Moonbrook barn, eager to learn alchemy like her daddy" },
    [92110] = { 1, "fetched murloc eyes for the odd child in the Moonbrook barn, so she could mix her first real potion" },
    [92401] = { 2, "learned the fate of Edward Heartweaver for his wife Tabitha, gone missing in the Ruins of Lordaeron while searching for their lost son" },
    [92415] = { 2, "showed a blood-stained letter from the graveyard of Lordaeron to Orphan Matron Nightingale, about a missing child of the Heartweaver family" },
    [92421] = { 2, "gathered intact limbs from the Scourge in the Ruins of Lordaeron for Morbin Lightbane, to mend Forsaken whose decaying flesh could not be reknit" },
    [92422] = { 3, "destroyed Rath'mael, the necromancer whose unholy fog hid the Scourge in the streets of the Ruins of Lordaeron" },
    [92434] = { 2, "found a way into Dalaran through the sewers by Lordamere Lake while its barrier was down, to learn the Kirin Tor's secrets for Wordeen Voidglare" },
    [92456] = { 1, "plucked a fel-infused blossom from the central garden of Dalaran for Shylamiir, curious about the Kirin Tor's mana-touched plants" },
    [92460] = { 3, "came of age in Thendal Village, where Rorian the Dayseeker gave me a relic carried by many before me and one day to pass to another" },
    [92461] = { 1, "culled the vuldren of Thendal Grove, grown too many, to restore the harmony Rorian the Dayseeker said all its creatures shared" },
    [92462] = { 1, "exterminated the cirrusflies infesting the east of Thendal Grove for Elatrell Featherlight, before the swarm grew too large" },
    [92463] = { 2, "tracked the Cirrusfly Queen to her hive deep in the grove, since killing the workers alone would never end the infestation" },
    [92464] = { 1, "sought out Yala Windwatcher by the standing stones, where the simple wind sprites had turned agitated" },
    [92465] = { 2, "dispersed roiling winds and Al'Aketh converts in Thendal Grove for Yala Windwatcher, who blamed the cult for the sprites' violence" },
    [92466] = { 2, "drove Al'Aketh converts from the eastern standing stones for a Signet of Akir, proof of resolve before Windshaper Boro's trials" },
    [92467] = { 3, "drank the Earth Sapta at the Rise of Spirits, where the earth taught its strength but could not say why the winds had left" },
    [92468] = { 2, "brought the Rough Quartz from the manifestation of earth back to Windshaper Boro, to be the heart of a first earth totem" },
    [92469] = { 1, "warned Rorian the Dayseeker of the Al'Aketh in the grove, a clear escalation from a cult the village had long watched from afar" },
    [92470] = { 2, "proved resolve to Aetheen of the Gales by slaying the ursera scavengers and their den mother, Urs'anah" },
    [92472] = { 1, "headed south to Shen'dar Village at the word of Aetheen of the Gales, to offer Constable Aonda aid against the Al'Aketh threatening it" },
    [92473] = { 2, "put down the scrawny ursera of the den southwest of the village for Valreaa Valewind, after a hungry one went for a boy at play" },
    [92474] = { 1, "leapt from the watchtower in Thendal Grove for Myriaal Mistwake's game and floated on the air, then being told not to waste the gift" },
    [92489] = { 3, "destroyed the Arcanic Enigma in Dalaran for High Sorcerer Andromath, to help the Kirin Tor contain the wayward arcane energies in their city" },
    [92515] = { 2, "thinned the prideclaws pressing on Shen'dar Village before they took someone's pet or child, their pelts for Indari Sunseam's goods" },
    [92516] = { 1, "broke up the hippogryph nesting grounds southeast of Shen'dar Village, matriarch and all, after the flock began harrying travellers" },
    [92517] = { 2, "cleared the bandit cave behind the waterfall north of Shen'dar Village and killed its leader, Badwind Bennic, for Constable Aonda" },
    [92528] = { 2, "posed as a recruit in Falaath Village and learned that Lorthuna, the cult's own leader, had her eyes on Shen'dar Village" },
    [92529] = { 1, "bore Sania Silverstream's mark as a new recruit into Falaath Village, to be welcomed by Missionary Jasaan of the Al'Aketh" },
    [92544] = { 2, "killed Malduko Cloudcrush, the monster leading the Al'Aketh ruffians at the temple ruins, for the Rangers of Thendal Grove" },
    [92550] = { 3, "struck Falaath Village before the cult could strike Shen'dar, and took Commander Cyclas's head back to Constable Aonda" },
    [92551] = { 1, "recovered the Shen'dar supplies the Al'Aketh had raided from the caravans and hoarded in Falaath Village, for townsfolk in dire need" },
    [92553] = { 1, "gathered eggs and strider meat for Zerril Softbreeze, to keep Shen'dar Village fed while no one had time to hunt or forage" },
    [92579] = { 1, "carried Constable Aonda's report to Valennia Stormfist in Valanaar, word that the pylon and Shen'dar Village were safe for now" },
    [92595] = { 1, "listened to Illaya Amberwind on why the Windshapers needed every soul with the skysight, if the winds were ever to answer again" },
    [92596] = { 1, "sat with Rathiril Sunlance to hear why the High Order, heirs of Eldre'Thalas, meant to help the islanders stand on their own" },
    [92597] = { 1, "drew on a ley line at the standing stones for Falorne Fallwind, one of the lines newly broken through to the island's surface" },
    [92598] = { 1, "used the skysight at the elemental convergence by the standing stones, a gift Ventaari Brightwish thought might be the key to survival" },
    [92640] = { 2, "rallied the Windshapers and the High Order behind a strike on the Shrine of Akir, to stop Lorthuna before her scheme was done" },
    [92642] = { 2, "cut down the cult's healers and brawlers below the eastern watchtower, where Yorana Windyreed's people could not hold much longer" },
    [92643] = { 2, "sought out a cult turncoat hiding northwest of Valanaar who claimed to know the Al'Aketh's true plans, and found him already dead" },
    [92644] = { 2, "handed High Elder Talaanis Shadowsong the damaged crystal found beneath the dead turncoat, in case it still held his secrets" },
    [92645] = { 3, "killed Commander Belguilos the Breaker, a former peacekeeper turned terror of the cult, to end the assault on the eastern watchtower" },
    [92646] = { 3, "followed High Priestess Lorthuna through her portal to the Rohashi Spires, to face her with Ayessa Dawnsinger and Elaadrin Evengale" },
    [92679] = { 1, "answered Alvarion Windfield's plea for fighters to save his farm, though his wife Aamelia feared he had sent help to die for nothing" },
    [92682] = { 1, "picked stormapples and killed the bandits among the trees of the Windfield Orchard, working for meals until Ferauu's gang came" },
    [92683] = { 1, "swatted flutterflies for their wing dust, a chore Aamelia Windfield had put off for weeks with bandits lurking too near the house" },
    [92684] = { 1, "culled the ornery galestriders that stole stormapples from a light harvest, their tenderloins for Aamelia Windfield's pot" },
    [92685] = { 2, "raided the bandit camp in the hills above the orchard for bloodied masks, to even the odds before Ferauu came for the Windfields" },
    [92693] = { 3, "stood with Aamelia Windfield against Ferauu and his thugs in a final stand at the orchard, and lived to see it over" },
    [92698] = { 1, "puzzled over the broken words of a cyclone construct that had wandered the orchard's fields for decades, perhaps since the wind elementals left" },
    [92701] = { 1, "took Constable Aonda's written report to Valennia Stormfist, who led the island's peacekeepers and needed to know what happened" },
    [92703] = { 1, "carried the news from the orchard to Alvarion Windfield, with Aamelia's word to bring a Windshaper to look at the construct" },
    [92706] = { 3, "killed Bruuz, the giant shark circling Ratchet's docks and attacked sailors, for the bounty Gazlowe put on its fin" },
    [92708] = { 1, "heard Ayessa Dawnsinger's belief that the means to save Zephras Isle lay below, on Azeroth" },
    [92709] = { 1, "learned from Elaadrin Evengale that the forebears' lost magic was the key to saving Zephras Isle, and the Kirin Tor the way to it" },
    [92727] = { 2, "searched the road west of Valanaar for Fillion Flamebreeze, a High Order scholar overdue from the highlands, and found his satchel" },
    [92741] = { 1, "hunted shrieklings in Shadowgale Forest, their numbers spilling out of the woods, for talons Iaadaria Bitterwind wanted to study" },
    [92742] = { 2, "drew water from the wells of the Jansen Stead and the Molsen Farm for Alba Fairmoon, to trace the poison corrupting Westfall's land" },
    [92744] = { 1, "cut gills from the shoreline murlocs for Alba Fairmoon, to learn whether the poison had reached the sea and Stormwind's fish" },
    [92745] = { 2, "killed the kobolds and gnolls the Defias had digging in Jangolode Mine and the Gold Coast Quarry, once the wells turned up toxic metals" },
    [92747] = { 2, "searched Moonbrook for signs of mining under the town, Alba Fairmoon's last lead on the poison in Westfall's soil" },
    [92749] = { 1, "got coarse dynamite for Sprite Jumpsprocket, who took gladly to the idea of industrial sabotage in the Deadmines" },
    [92751] = { 1, "fetched an SI:7 prototype detonator for Sprite Jumpsprocket, so the blast under Westfall could be set off from safely outside" },
    [92753] = { 2, "planted explosives by the hidden forge in the Deadmines, the source of the poison seeping into Westfall's farmland" },
    [92819] = { 3, "set off the detonator under Moonbrook to destroy the Deadmines forge, in hope that Westfall's land could begin to heal" },
    [92834] = { 2, "took prayer charms from Al'Aketh cultists for Elaadrin Evengale, after the cult sent back his envoy Belathaan Brightwish's tongue" },
    [92840] = { 2, "read the elemental currents at the Overlook Standing Stones for the High Order, against Windshapers who called it a massacre" },
    [92849] = { 3, "found Fillion Flamebreeze in the cave north of the road and carried him to safety, before the beast that struck him could eat him" },
    [92850] = { 2, "returned to the Shriekling Den for the head of its matriarch, the beast that struck Fillion down, nested far too close to Valanaar" },
    [92860] = { 1, "pledged the High Order's full support to Valennia Stormfist against the Al'Aketh, who swore to avenge her cousin Belathaan" },
    [92871] = { 1, "carried the Windshapers' pledge of full support to Valennia Stormfist, with rumours of the cult gearing up for something larger" },
    [92880] = { 1, "reported to Valennia Stormfist that the eastern watchtower was stable again, to her plain relief" },
    [92881] = { 1, "went to High Elder Talaanis Shadowsong for a promising lead, since the attacks on both watchtowers were no coincidence" },
    [92909] = { 1, "gathered isosprings and gyrostabilizers from the harvest golems for Ozwin Ironsprocket, chased into a stable at Saldean's Farm" },
    [92910] = { 1, "handed a harvester's salvaged assembly to Ozwin Ironsprocket, who wanted to learn what made the golems tick" },
    [92911] = { 1, "scrounged parts for Ozwin Ironsprocket's device to override the harvest golems' systems, built from the salvaged assembly" },
    [92947] = { 2, "stormed the Shrine of Akir behind a distraction, cutting through its guardians while Valennia Stormfist led the flank" },
    [93036] = { 2, "got close to Sania Silverstream, the Al'Aketh's missionary in Shen'dar Village, to learn for Constable Aonda what the cult planned" },
    [93089] = { 1, "carried High Elder Talaanis Shadowsong's blessing to Elaadrin Evengale for the High Order's expedition from Zephras Isle to Azeroth" },
    [93090] = { 1, "brought Ayessa Dawnsinger the High Elder's blessing for the Windshapers' expedition to Azeroth, the time to leave come at last" },
    [93159] = { 1, "kept the Strange Hermit of Shadowgale Forest company, after so long without anyone to talk to, and heard what little he would tell" },
    [93160] = { 1, "gathered Shadowgale acorns for the Strange Hermit to roast, since he feared becoming a giant bird's lunch out on the forest floor" },
    [93165] = { 1, "collected ears from Al'Aketh cultists for Vayn Moongaze of the Nightclaw, repaying blood with blood for the tragedy at the enclave" },
    [93172] = { 2, "destroyed the wind hollows that sang at the old ruins, in the Strange Hermit's hope that the trapped spirits would find peace" },
    [93176] = { 1, "caught a tarantula, a hay weevil and a flesh picker with Amaryllis Webb's starter kit, to take up her study of insects" },
    [93317] = { 1, "caught Windsong Crawlers for Nyalah Brightfire in their short season, once a delicacy begged for on the other islands" },
    [93318] = { 2, "hunted down Vulgara the Insatiable, the winged vuldren terror of the highlands, for the bounty Constable Aonda posted on her head" },
    [93319] = { 1, "took back the windstones bandits had pilfered from Shen'dar Village's emergency reserve, to tide Teeri Wellwind over" },
    [93320] = { 1, "hurried to the eastern pylon watchtower under cult attack, where Yorana Windyreed's relief force was holding against greater numbers" },
    [93552] = { 1, "harvested raw windstones in Thendal Grove for Dalia the Collector, the winds' own energy grown precious as the island's magic faded" },
    [93585] = { 2, "escorted Father Tuttle past the draenei's savage kin to the Harborage, where the Church of the Holy Light hoped to win a foothold" },
    [93663] = { 1, "found a lost goblin courier's shipment along the swamp road, likely a crocolisk's doing, and saw it to the Harborage for its trader" },
    [93680] = { 2, "searched the Kirin Tor's camps for a way into rebuilt Dalaran, on the Dark Lady's doorstep, for Magus Wordeen Voidglare" },
    [93735] = { 1, "lent a hand to Riaani Nightwind, a Windshaper artisan mending one of the last working constructs in Valanaar" },
    [93736] = { 2, "gathered essences from the wind hollows of Shadowgale Forest for Endaria Mistgaze, sprites first seen once the spirits had left" },
    [93737] = { 2, "scavenged lightning, a gyrozephyr and a core for Riaani Nightwind's construct, so its memory might tell who had stolen its parts" },
    [93738] = { 2, "told Ayessa Dawnsinger what the mended construct revealed, that Belathaan Brightwish of the High Order had taken its parts" },
    [93739] = { 1, "called on Vol'jin, Cairne Bloodhoof and Lady Sylvanas Windrunner in their capitals, as Thrall advised a guest of the Horde" },
    [93740] = { 2, "traded blood for blood with the Al'Aketh for Ayessa Dawnsinger, after Windshaper novices were found dead in the highlands" },
    [93746] = { 2, "confronted Belathaan Brightwish on the road to the Shrine of Akir to frighten him, and brought Ayessa Dawnsinger word of his death" },
    [93797] = { 2, "fetched a Wind-Infused Bough from the wind shrine near Falaath Village for Belann Windwood, to craft a spell focus as young mages do" },
    [93835] = { 3, "took the portal to the Rohashi Spires after the fleeing Lorthuna, to help Elaadrin Evengale and Ayessa Dawnsinger stop her" },
    [93836] = { 2, "warned High Elder Talaanis Shadowsong that the wards hiding Zephras were down and the island lay defenceless before Al'Akir" },
    [93926] = { 2, "raced to the western watchtower to call its peacekeepers home for Constable Aonda, and found Peacekeeper Vaaniel already dead" },
    [93927] = { 3, "slew Skypriest Aanders to stop the cult at the western watchtower, and gathered the keepsakes of the peacekeepers who died there" },
    [93948] = { 2, "carried the Shadowsong Family Signet from the western watchtower to High Elder Talaanis Shadowsong, whose nephew had died there" },
    [93949] = { 1, "stamped out the skyhoppers of Valanaar for Valennia Stormfist, since the cult seemed to be using enchanted ones as spies" },
    [93951] = { 1, "gathered fallen hippogryph down for Taleen Shimmerthread, feathers for the islanders' hair, a small joy kept even in hard times" },
    [93958] = { 2, "pressed into the inner sanctum of the Shrine of Akir, gone unsettlingly quiet, and found Valennia Stormfist gravely wounded" },
    [93963] = { 1, "called on Magni Bronzebeard, High Tinker Mekkatorque and Tyrande Whisperwind in their capitals, as Bolvar Fordragon advised a guest" },
    [94003] = { 2, "reclaimed the Skybreaker Bulwark from the cultist Zaal Stormshield for Seena Skybreaker, the last of a line the Al'Aketh murdered" },
    [94006] = { 2, "sought out Urs'endris, the spirit who taught druids the ursera shape, by the falls northeast of Valanaar, his domain falling into the sky" },
    [94013] = { 3, "tamed a Vuldren Alpha in the Gustberry Lowlands, Quel'ana Quickgale's last trial before learning to bond with a companion for good" },
    [94215] = { 1, "took a free action potion to the spot a crafting writ marked, where a Mudsnout gnoll lay thrashing in spider silk" },
    [94220] = { 1, "handed a pearl-handled dagger ordered by writ to Alan Sneeks, on watch in Alterac against the Syndicate" },
    [94221] = { 1, "brought a golden rod ordered by writ to Muggol Breezebeard, who hoped it might help him commune with the Binding Stones" },
    [94228] = { 1, "supplied green iron boots on a writ to Kixxle, who had stomped around the Wetlands with soggy feet for days" },
    [94231] = { 1, "delivered a moonsight rifle on a writ to Grembly, lying low in Ashenvale and eager to try it on a satyr" },
    [94236] = { 1, "supplied a big bronze bomb on a writ to Razzeric, who had wanted a whole variety of them to test" },
    [94244] = { 1, "fitted Narkk with dark leather shoulders on a writ, a pirate tired of a squawking bird's claws in his shoulder" },
    [94247] = { 1, "passed a lesser wizard's robe to Alan Sneeks, a man in dark leathers watching Dalaran on behalf of the Kirin Tor" },
    [94254] = { 1, "delivered a greater adept's robe on a writ to Magus Tirth, so he could at last wear robe and wizard hat together" },
    [94369] = { 2, "warned High Elder Talaanis Shadowsong of Al'Akir now the wards were down, and told him of the High Order's mission to Azeroth" },
    [94373] = { 2, "won two bear pendants from the Frostmane trolls' cave for Teo Hammerstorm, the first test on the shaman's path of earth" },
    [94374] = { 3, "drank the earth sapta at the Spirit Stone at the end of a hidden mountain path, to see what the earth had to show" },
    [94375] = { 2, "brought the spirit's rough quartz to Teo Hammerstorm as proof of the meeting, to be the heart of an earth totem" },
    [94411] = { 2, "drove High Order apprentices from the standing stones north of Shen'dar Village for Illaya Amberwind, who feared their meddling" },
    [94413] = { 2, "chased Windshaper novices from the southwest forest's ley line for Rathiril Sunlance, who wanted it studied, not healed over as a scar" },
    [94414] = { 1, "looked upon the anchor pylon through Halaan Hawk-Eye's gift, one of the spirits' gifts that bind the island, its magic grown unstable" },
    [94434] = { 1, "gave linen to Tanis Alderwood, an Undercity beggar, to wrap his wife, who was falling apart while the apothecaries were busy" },
    [94438] = { 3, "raised Deathguard Falgan with the Symbol of Life at Venomweb Vale, where he had stayed behind so his friend Billmuth could flee the Scarlets" },
    [94440] = { 2, "seized the Scarlet Crusade's attack plans at Venomweb Vale, so the Deathguard could prepare an ambush before Brill was struck" },
    [94465] = { 1, "carried the Torch of the Dormant Flame to Braldir Ashmantle, keeper of a hidden shrine high in the crags of Loch Modan" },
    [94466] = { 2, "wrested fire tar from the Tunnel Rat geomancers and a pouch from a Stonesplinter seer, so Braldir Ashmantle could brew the fire sapta" },
    [94467] = { 3, "defeated a manifestation of fire atop the Shrine of Eternal Flame and lit the brazier with its ember, to earn the fire's favour" },
    [94468] = { 2, "brought the Torch of Eternal Flame down to Bruegs Kindleborn, who saw the spirit burning in it and granted a fire totem" },
    [94484] = { 1, "checked on the druids of Shadowgale Forest, whose word to Lotheluum Starbreeze was overdue, and found them in dire straits" },
    [94485] = { 1, "searched the roots of Shadowgale's trees for Lady's Tear moss, so Elegael Thornpaw could bind the wounds of the druids left in the den" },
    [94486] = { 1, "plucked feathers from the shrieklings of Shadowgale for the second half of Elegael Thornpaw's poultice" },
    [94487] = { 2, "pried bloodied heirlooms from the Al'Aketh in Shadowgale Forest, for Elegael Thornpaw to keep for a future generation" },
    [94488] = { 3, "killed Commander Haalien, Elegael Thornpaw's own cousin, a druid turned cultist who had spilled his kin's blood" },
    [94489] = { 2, "carried Elegael Thornpaw's poultices into the den to heal the wounded druids, and searched for her mate, Jorel Windsinger" },
    [94490] = { 2, "found a torn missive on Haalien showing the cult had struck the druids for the pylon, on orders that may have come from Valanaar" },
    [94491] = { 2, "took the missive and the fate of the fallen druids to Lotheluum Starbreeze in Valanaar, who feared a traitor in the city" },
    [94493] = { 1, "answered Elegael Thornpaw's plea in Shadowgale Forest, her den ambushed by the cult and many inside wounded or died" },
    [94497] = { 1, "filled a waterskin where the falls below Hervdana Saegrund's cave meet the brackish marsh, her first sample for the water sapta" },
    [94499] = { 1, "drew water from Stonewatch Falls, by the twisted Nightcrawler murlocs, for Hervdana Saegrund to learn what tainted it" },
    [94500] = { 1, "travelled to Astranaar in Ashenvale for a sample of its pure, ancient lake water, the last Hervdana Saegrund needed" },
    [94501] = { 1, "carried Hervdana's vial of purest water to Norric Lochthane, who had one last task before the water rites" },
    [94502] = { 3, "cleansed the corruption that had silenced the spirits of Stendel's Pond near Moonbrook, the last trial of the water rite" },
    [94505] = { 2, "brought the Shard of Water from the cleansed spirit of Stendel's Pond to Norric Lochthane, the proof he asked for before the water totem" },
    [94568] = { 2, "learned what the dead turncoat's crystal held of the cult's plans, and that the peacekeepers would fare badly against the cult in the open" },
    [94638] = { 3, "ended the suffering of Ur'endra, mate of Urs'endris, lost to madness and turned on her kin, to earn his blessing and the ursera shape" },
    [94792] = { 2, "tamed a Rockhide boar with Josephine Carson's taming rod, a hunter's first lesson in earning a beast's trust" },
    [94863] = { 1, "tamed a gray forest wolf with the rod, Josephine Carson's next lesson in winning the trust of fiercer companions" },
    [94864] = { 2, "tamed a young forest bear, the final challenge Josephine Carson set to prove a hunter could earn even the mightiest companion" },
    [94896] = { 2, "recovered what the refugees of Ban'aethal left behind when it began drifting into the sky one night, for Ealaane Nimbuswalker" },
    [94897] = { 2, "searched the ruins of Ban'aethal for Resaan, who went back for supplies, and brought only his heirloom home to Ealaane Nimbuswalker" },
    [94946] = { 3, "boarded the skycutter from Zephras Isle to Dalaran with the High Order's vanguard, to seek on Azeroth the means to save the island" },
    [94947] = { 1, "stepped through the Kirin Tor's portal to Stormwind as an emissary of the High Order, to meet the regent Bolvar Fordragon" },
    [94978] = { 1, "tamed a Windsong Crawler with Quel'ana Quickgale's rod, the first challenge in learning the bond between beast and master" },
    [94979] = { 1, "earned the trust of an Ornery Galestrider in the Gustberry Lowlands, the second of Quel'ana Quickgale's taming trials" },
    [95036] = { 2, "gathered lumber, silver and a gem for the blade Trevan Rol needed against Old Fire-Eye, the worgen that would not stay dead" },
    [95041] = { 1, "recovered the punch cards Jemma Quikswitch lost in the snow outside Gnomeregan, without which her family's archives could not be read" },
    [95065] = { 1, "fetched a shiny bauble and nightcrawlers for old Gilbert Gray at the Stormwind harbor, down to his last bait while the fish were biting" },
    [95111] = { 1, "offered Ott, a humble weaponsmith in Tarren Mill, the commission for the blade, a chance to make something truly special" },
    [95125] = { 1, "watched Ott forge the blade at Tarren Mill, the finest work of a smith who had only ever made humble, honest weapons" },
    [95126] = { 1, "brought Ott's masterwork to Trevan Rol at the Sepulcher, the moonsilver blade meant to end Old Fire-Eye" },
    [95140] = { 3, "killed Old Fire-Eye near the gates of Gilneas with the moonsilver blade, the worgen that doomed Lumina Windsinger's companion Banon" },
    [95161] = { 2, "delivered the blood-stained letter to Avette Fellwood in Duskwood, the new mother of Jeremy Heartweaver, who had not spoken since Lordaeron fell" },
    [95189] = { 1, "returned a weathered Crest of Lordaeron from the ruins to Lady Dena Kennedy in Stormwind, one of the few relics left of the fallen kingdom" },
    [95195] = { 1, "gathered the insignias of Lordaeron's fallen soldiers for General Marcus Jonathan, to be given to whatever kin were left in Stormwind" },
    [95204] = { 1, "brought a weathered Crest of Lordaeron to Oran Snakewrithe in the Undercity, a rare relic of the kingdom that fell to the Scourge" },
    [95212] = { 1, "hunted the fiercest leopards for pristine pelts for Amberstill Ranch, saddles for the rams bound to reinforce the Alterac expedition" },
    [95213] = { 1, "brought an empty keg of blasting powder found among the troggs to Quarrymaster Thesten at Gol'Bolar Quarry" },
    [95214] = { 2, "recovered the blasting powder the troggs stole from Gol'Bolar Quarry, enough to open Magni's throne room to the sky, before they lit it" },
    [95216] = { 2, "drew a sample of Witherfang's venom, said to eat through undead flesh, for Theodore Griffs of the Royal Apothecary Society" },
    [95217] = { 1, "traded copper bars and boar hides to Frast Dokner for lessons in smithing, materials for repairs at the quarry camp" },
    [95250] = { 2, "searched the Ruins of Lordaeron for the Grand Marshal whose return Captain Truman still awaited, and brought back the head of the Baron" },
    [95314] = { 1, "recovered bottles of Whispering Elixir from ruined Shadowvale for Carolai Anise, a banned brew her buyers were eager to get" },
    [95328] = { 1, "sold the squirming residue of a whispering horror to Father Lankester in the Undercity, who studied the void's touch on that forest" },
    [95349] = { 3, "crossed on the skycutter from Zephras Isle to Mulgore, home of the Earthen Ring, with the vanguard of the Windshapers sent to Azeroth" },
    [95350] = { 1, "flew to Orgrimmar as an emissary of the Windshapers, to meet Thrall, Warchief of the Horde" },
    [95494] = { 1, "gathered savannah lion hides for Vrang Wildgore, laid up with an injured leg but unwilling to fall short on his trade" },
    [95495] = { 1, "carried Vrang Wildgore's hides up the ridge to a hermit tanner who, Vrang swore, was no threat whatever his looks" },
    [95507] = { 1, "checked Vrang Wildgore's traps across the valley, so the injured hunter would not go to bed hungry" },
    [95508] = { 2, "stood with Walton, a Kul Tiras deserter who had objected to executing civilians, when Terry Longdrink and the marines came for him" },
    [95621] = { 2, "killed the Kul Tiras soldiers camped by the wrecked caravan to learn why they had come, and found they hunted a deserter" },
    [95646] = { 2, "killed a Highland Horror in the excavation sites for its root core, the corruption Rethiel the Greenwarden felt seeping down the gully" },
    [95647] = { 2, "searched the excavation sites for Ardin Grassman, gone too long after grasses taller than any seen, for his wife Caitlin" },
    [95664] = { 1, "showed a strange titan relic from the excavation to the elders on the Elder Rise in Thunder Bluff, to learn what it might be" },
    [95682] = { 2, "cleared the Dragonmaw from the excavation sites so the Deathstalkers could move in unseen, and took what orders they carried" },
    [95697] = { 1, "butchered thicket raptors in the excavation sites for Borstan, who wanted a grand take on homestyle cooking at his firepit" },
    [95772] = { 2, "looked for Daewyn Songblade in Whelgar's excavation site, for his brother Dorin, who had heard nothing from him since he left" },
    [95774] = { 2, "reclaimed the bone jewels of Olgra, Mankrik's fallen wife, from the Razormane raiders for the memorial he was building her" },
    [95795] = { 2, "brought Dorin Songblade in Lakeshire the news that his brother Daewyn had died in the excavation sites" },
    [95803] = { 2, "presented the head of Rudolph Gelhardt to Sylvanas Windrunner, to show the Dark Lady the paladins tended their own house" },
    [95805] = { 1, "carried burning incense to the shrine of An'she and Mu'sha in the hills before it turned to ash, to honour the sun and the moon" },
    [95809] = { 2, "brought Caitlin Grassman the reed heart Ardin wove in the excavation site, word that he had survived and was coming home" },
    [95810] = { 1, "presented a fractured titan relic from the rock automaton to Prospector Whelgar, to learn what kind of device it had been" },
    [95883] = { 1, "claimed a tortured soul from the undead of Beren's Peril, one of the pieces still missing from the ritual at the offering stone" },
    [95884] = { 1, "followed a scrap of note to the offering stone in Beren's Peril, where someone had laid out the makings of a ritual" },
    [95885] = { 2, "offered blood willingly at the stone in Beren's Peril and faced the tortured soul it freed, to finish a ritual of unknown purpose" },
    [95981] = { 1, "culled Dalaran's wizards and watchers on the roads around Ambermill, to stop the Kirin Tor's pendants crossing into Silverpine" },
    [95999] = { 3, "killed Incinerator Gar'im, leader of an orc incursion in Render's Valley, whose fall gave Lakeshire hope of reclaiming Stonewatch Keep" },
    [96016] = { 1, "brought the Eye of the Tempest to Bath'rah the Windwatcher, a troll shaman versed in storm elementals, to be made into a weapon" },
    [96101] = { 1, "sat by Raan Wildwind's campfire to learn the basics of surviving outdoors, since a well-rested adventurer lives longer" },
    [96130] = { 2, "hunted Chakuyak, a prairie wolf so aggressive she had become a threat to travellers near Stonebull Lake" },
    [96135] = { 3, "set twisted totems by the steam pools of Thousand Needles to summon the quilboar's elementals and put an end to the Razormane ritual" },
    [96137] = { 1, "cleared the worgs that still claimed travellers in Duskwood, perhaps the unfinished business of Ira, the ranger whose spirit wandered there" },
    [96138] = { 2, "drove off the Splinter Fist ogres near Raven Hill, perhaps the unfinished business of Merrick Valor's spirit, who had kept its roads safe" },
    [96139] = { 1, "searched Raven Hill for any trace of its lost history for Sirra Von'Indi, who wanted its fallen folk remembered" },
    [96204] = { 2, "escorted Lumina Windsinger out of Fenris Keep as she made the gnolls regret ever caging a Windshaper" },
    [96241] = { 1, "drew venom from the gnawed corpses at Gloomrise for Mazu'kon, curious about the new creatures skittering there" },
    [96259] = { 2, "killed the spiders infesting Gloomrise, an ancient tauren burial ground they were defiling, for Muln Earthfury" },
    [96260] = { 1, "gathered crystalline silk from the Gloomrise spinners for Yorn Grimtotem, after a scout came back half dead and wrapped in it" },
    [96261] = { 3, "destroyed Broodmother Valraxx, the matriarch behind the spiders spreading through Gloomrise, to drive the brood off for good" },
    [96264] = { 3, "defeated Charlga Razorflank in Razorfen Kraul for word of the ritual the quilboar were massing for, while the earth rumbled" },
    [96294] = { 2, "brought Muln Earthfury the bloody letter found on Broodmother Valraxx, who had proved to be a night elf druid in a twisted form" },
    [96390] = { 2, "killed the Dark Iron spies at Ironband's Compound for Earthseer Farsen, to nip their incursion into Dun Morogh in the bud" },
    [96391] = { 2, "brought Earthseer Farsen a Dark Iron map of tunnels and highways that all converged beneath Ironforge itself" },
    [96392] = { 1, "looked through Earthseer Farsen's farsight to see how thick the Dark Irons lay across Dun Morogh" },
    [96393] = { 3, "claimed the head of Durgen Dirgehammer, commander of a Dark Iron incursion in the Hall of Thanes beneath Old Ironforge, for King Magni" },
    [96394] = { 1, "put the startled dead of the Hall of Thanes back to rest, so the keepers would go down to their duties again" },
    [96395] = { 3, "laid to rest the spirit of Faldrim Anvilmar, a thane consumed by an ancient grudge, at his ghostly attendant's plea" },
    [96403] = { 1, "gathered dwarven heirlooms in the Hall of Thanes for Thom Filch, a gnome suspiciously eager to appraise them" },
    [96646] = { 1, "learned cooking from Zerril Softbreeze, the first step toward a campfire and a camp of one's own anywhere in the wilds" },
    [96774] = { 2, "pried an ancient Gurubashi idol from a priest of the Drowned City off Stranglethorn for Mazu'kon, a truesilver channel for old blood magic" },
    [96779] = { 3, "killed Lord Tomas inside Durnholde Keep for Ravenholdt, a single cut in the right place to wound the Syndicate" },
    [96781] = { 2, "picked Barton's scouting report from his pocket at Strahnbrad, to learn what the Syndicate sought in Alterac's ruins without alerting them" },
    [96783] = { 1, "stole a Syndicate uniform at Northfold Manor, a disguise to slip into Stromgarde Keep and learn of a trade being arranged there" },
    [96821] = { 1, "cleared the spiders nesting along the road in southern Durotar, so the peons of Razor Hill would dare travel it again" },
    [96822] = { 2, "recovered the weapons of the Horde's fallen from the outskirts of Tiragarde Keep, for Turroc to display in a place of honour" },
    [96825] = { 1, "gathered prickly pears from the Razormane grounds for Cook Torka, a sweet treat for the troops and seeds to plant around Orgrimmar" },
    [96873] = { 1, "stripped Zalazane's binding spells from the hexed pendants of his enthralled trolls for Pa'zula, so their spirits could rest" },
    [96874] = { 1, "hacked spines from the beasts of Thunder Ridge for Ug'thok, with stones to grind them, for the mighty axe head he was sure they would make" },
    [96875] = { 1, "supplied Kamari with lizard hides from Thunder Ridge, to line the walls and roofs of Orgrimmar's new buildings" },
    [96876] = { 1, "returned the pack Ukor dropped in southern Durotar as he ran from a huge spider" },
    [96877] = { 1, "carried the hoof of Halikor, a mighty lizard, to Orgrimmar as proof of the fight" },
    [96897] = { 2, "killed the Cult of the Damned's neophytes and enforcers snooping outside the Undercity, for Hadric Harlson of the Argent Dawn" },
    [96898] = { 2, "gathered the necrotic crystal shards scattered when Naxxramas bore down on the Undercity, before the cultists could claim them" },
    [96984] = { 3, "reached the Violet Citadel, where Dalaran's disruption began, to help stop a catastrophe and take its arcane mote for Wordeen Voidglare" },
    [96986] = { 3, "defeated Atrexis the Grave Knight, a necromancer who betrayed the Forsaken and raised undead beneath Dalaran, for Melisara in Tarren Mill" },
    [96988] = { 1, "prised cracked cores from Dalaran's rampaging constructs for Doctor Martin Felben, who dreamed of an army of arcane abominations" },
    [97003] = { 3, "slew Chol'aruk the Ravener, a monstrous quilboar in a cave on Thorn Hill, for Gur'ak, who had fought its like before" },
    [97005] = { 3, "slew Chol'aruk the Ravener in its lair on Thorn Hill for Bainham, for the honour of the comrades he had lost to its kind" },
    [97220] = { 1, "hauled a shipment for the short-handed docks to the Gatehouse's stockroom, reached through Trias' Cheese shop in the Trade District" },
    [97223] = { 3, "killed the Bloodtalon Matriarch, a savage raptor that had killed many of Sen'jin's people, and saved her eggs for Xar'Ti to raise" },
    [97225] = { 2, "gathered the loa idols the Darkspear left on the Echo Isles, scattered by Zalazane's followers, lest the tribe offend its loa" },
    [97234] = { 1, "carried Roy Lewells's wrapped books to the Stormwind library for his book club, to trade them for newer writing" },
    [97236] = { 1, "offered the fang of Githyiss, a great spider, to a student of spiders in Aldrassil" },
    [97237] = { 1, "found the book club's chosen tomes on the library shelves for Roy Lewells, for lively talk in the cellar after hours" },
    [97242] = { 1, "cut cattails and speargrass in the Valley of Honor for Yelmak, who meant to teach his proud apprentice Whuut a lesson" },
    [97243] = { 1, "carried the Torch of Dormant Flame to Olariaan Swiftburn at the Shrine of Flames, to begin learning to heed the call of fire" },
    [97244] = { 2, "slew Skypriest Faladiel, a Windshaper turned cultist with his former kin's blood on his hands, for the heart the fire ritual needed" },
    [97245] = { 2, "summoned the ancient forest sprite Kuramaa from its stump near the highlands Anchor Pylon, where only fire could harm it, for its mask" },
    [97249] = { 1, "delivered young Migi a lunch from Borstan's Firepit behind Grommash Hold, for Thatog, who knew the boy skipped meals to play" },
    [97250] = { 2, "killed the Alliance soldiers on the Dustwallow border who toppled the tauren pathfinders' landmarks and blamed the Horde for a burned tavern" },
    [97253] = { 1, "gathered the scattered parts of Wrenix the Wretched's machine from a pirate camp south of Ratchet, after the pirates took it apart" },
    [97257] = { 3, "carried the Eternal Flame from Olariaan Swiftburn's ritual to Valanaar before it faded, lighting the brazier to end the trial of fire" },
    [97263] = { 1, "delivered a misplaced urgent package from Aerie Peak to Eldrun Stormbreaker, who had checked the mailbox every day for it" },
    [97265] = { 2, "raided the Hatefury satyrs at Sargeron for Aka'rai, who had bargained with them for power and been cast aside" },
    [97275] = { 1, "gave Whuut a potion Yelmak brewed from common speargrass and cattail, to teach the young prodigy respect for the basics" },
    [97277] = { 2, "recovered Gozwin's mechanic's log from his camp and killed the snow leopard that had mauled him, for his friend Grund" },
    [97279] = { 1, "salvaged the training weapons failed recruits had left lying about, for Kzan Thornslash to mend for the next wave" },
    [97281] = { 1, "showed Rezlak near Drygulch Ravine a strange storm orb a harpy had been using" },
    [97282] = { 1, "harvested charged thunder lizard organs so Rezlak could recharge the orb, in hope it would keep harpies off his caravan" },
    [97288] = { 1, "brought the much-reattached head of a strange abomination to Master Apothecary Faranell in the Undercity, who knew it at once" },
    [97289] = { 2, "set the Baron's head, once a Grand Marshal of the Alliance, beside the body of Othmar for Faranell, so its secrets could be made to talk" },
    [97291] = { 1, "fetched a toxic skullcap, blisterweed and essence of agony around the Undercity for Faranell's serum, to bend the Baron to the Dark Lady's will" },
    [97292] = { 2, "fed Faranell's hissing serum into the workings above Othmar, to show him why he should serve the Dark Lady loyally" },
    [97326] = { 1, "hauled smooth boulders behind Grommash Hold for Thra and friends, so they had something to sit on during their game" },
    [97485] = { 1, "made incense from herbs, cedar, sinew and flint bought on the rises and scattered it to the winds off Hunter's Rise, a tauren tradition" },
    [97538] = { 1, "gathered mirkweed pods from Mirkfallon Lake for Tah Winterhoof, whose red pigment for painting had run out" },
    [97539] = { 1, "harvested spider silk for Doctor Gregory Victor's field sutures, to keep the neglected infirmary at Hammerfall working" },
    [97558] = { 1, "gathered bat membranes, darkhound hides and murloc skin for Shelene Rhobart, to patch Forsaken skin that never heals on its own" },
    [97891] = { 1, "ran an unstable potion across the canal to Doctor Martin Felben in time, after the last six had gone bad on the way" },
    [97914] = { 1, "carried Thundris Windweaver's letter to Baros Alexston in Stormwind, his plea to have Auberdine and its work recognised" },
    [97926] = { 1, "brought Baros Alexston's reply back to Thundris Windweaver, word that Stormwind's thin coffers had no help to spare for Auberdine" },
    [97963] = { 1, "earned Nyassa Swiftdraught's lesson in crafting a Mana Well for camp, a draw for every healer and spellcaster nearby" },
    [97964] = { 1, "proved skill at the forge until Aedi Thriceforged would teach the Sharpening Wheel, for warriors and rogues to hone blades at camp" },
    [97965] = { 1, "practised first aid until Naleeia Tattermend would teach the First Aid Kit, healing at camp that might even save lives" },
    [97967] = { 1, "fished until Fenn Fairweather would teach the Fish Bowl, a bit of joy for a camp in the wilds and the fighters around it" },
    [97968] = { 1, "picked herbs until Syriel Nightrain would teach the Incense Candle, to keep a camp's healers and spellcasters in high spirits" },
    [97969] = { 1, "worked leather until Indari Sunseam would teach the making of a camp tent, cool on hot days and dry on rainy ones" },
    [97970] = { 1, "mined until Messana Crestwind would teach the Lodestone, whose extra oomph lifts the fighting of all gathered round a camp" },
    [97971] = { 1, "skinned until Mendalass Tattermend would teach the Camp Chair, a comfy seat to rest in before the next fight" },
    [97972] = { 1, "sewed until Taleen Shimmerthread would teach the Rallying Banner, an inspiring banner to keep a camp energised" },
    [97973] = { 1, "stitched cloth until Taleen Shimmerthread would teach the Rallying Banner, a banner to keep spirits up around a camp" },
    [97977] = { 2, "searched the Gnarlpine's abandoned camps for totems whose engravings might tell Tarindrella why the furbolg turned on the elves" },
    [97985] = { 2, "slew Stormheart, a huge thunder lizard of Thousand Needles, for the still-beating heart Calder Gray needed for an abomination" },
    [98013] = { 2, "cut down the Stormscale naga in the ruins for Arbal, cursed Highborne who might aid the Twilight's Hammer against the forests" },
    [98025] = { 3, "slew Jai'vhanel, a black owl long a guardian of Darkshore's roads, gone mad and attacked travellers on the road to Auberdine" },
    [98027] = { 1, "returned a silver crescent necklace inscribed to Maliynn to its owner in Astranaar" },
    [98028] = { 2, "carried the clouded water globe of Baron Marinous, the elemental guardian of a ruin, to Onu at the Grove of the Ancients" },
    [98042] = { 2, "seized a peerless eye from the Twilight's cultists at the Master's Glaive for Thundris Windweaver, who saw in it the mark of an ancient evil" },
    [98046] = { 1, "carried Fandral Staghelm's drained phial to Lariia in the Temple of the Moon, who found a few drops still in it" },
    [98059] = { 1, "slipped Captain McManus's sealed request onto the Hillsbrad council's table, after they ignored every letter asking for soldiers" },
    [98065] = { 1, "presented the moonwell remnants from Fandral's failed incantation to Tyrande Whisperwind, water blessed by Elune" },
    [98067] = { 1, "placed sentinel owls about Darnassus for Sentinel Dalia Sunblade, to keep watch while something was amiss on Teldrassil" },
    [98069] = { 1, "recovered the supplies harpies took from the last caravan bound for Freewind Post, before the post ran short" },
    [98070] = { 2, "killed the Screeching harpies who ambushed every caravan through their canyon, lest none dare the trek to Freewind Post" },
    [98071] = { 1, "traded Brewmeister Bilger's Fallrook wine to Dun Garok for a sack of their homebrew hops" },
    [98072] = { 1, "collected crimson whelp scales along the Green Belt for James Halloran, worth far more to him than crocolisk hides" },
    [98093] = { 2, "cleared the hyenas and lizards around the tree Sulhasa had fled up in the southern Barrens, so she could get home to Camp Taurajo" },
    [98095] = { 1, "uncorked apothecary vials on three peaks around Hillsbrad to draw the bat riders back to their drop-off points" },
    [98155] = { 1, "gathered Pesterhide hyena pelts for Kristy Grant, to send to her sisters in Stormwind" },
    [98189] = { 1, "finished the Blind Princess's last delivery, carrying the Menethil statuette to Captain Stoutfist in Menethil Keep" },
    [98190] = { 1, "rushed the Menethil statuette, a rare memorial of King Terenas, to Bolvar Fordragon, out of the Dragonmaw's reach" },
    [98191] = { 2, "brought the statuette of King Terenas to Lord Grayson Shadowbreaker, to be kept in the Cathedral of Light, for the Light had gathered in it" },
    [98197] = { 1, "salvaged Khaz Modan timber and iron from the harbor, once stolen for the Old Horde's fleet, to bolster Menethil against the Dragonmaw" },
    [98208] = { 2, "recovered Nord'el, a bloom from the peak of Mount Hyjal, from the murloc-held wreck of the Flying Osprey for Sylessa Duskwhisper" },
    [98209] = { 1, "carried Nord'el, the Bloom of the Heavens, to Thundris Windweaver in Auberdine for the weary Sylessa" },
    [98216] = { 2, "woke the Goaz Warder with its own stone and took its titanic keystone for Prospector Whelgar, alarmed by talk of Old Gods" },
    [98221] = { 2, "destroyed the Dragonmaw's attack plans in the Angerfang Encampment for Captain Stoutfist, to learn where they meant to strike next" },
    [98223] = { 2, "brought Captain Stoutfist a burned Dragonmaw spellbook on the Demon Soul, patched by Nek'rosh, its fresh ink naming a Shadow Council" },
    [98240] = { 1, "hauled a crate of whelp scales out to Howin Kindfeather, who had sent his gryphon into town with the order" },
    [98245] = { 1, "collected Razormaw incisors for Howin Kindfeather, sharp enough to work the whelp scales that ward off dragonfire" },
    [98246] = { 1, "gathered perfect Razormaw eggs for Howin Kindfeather, to fill the belly of his gryphon Bassbeak before his plan could go ahead" },
    [98251] = { 1, "thinned the beasts around a ravine in Ashenvale for Va'xug Firefure, lost there and seethed at the forest" },
    [98252] = { 1, "guided Va'xug Firefure's Eye of Kilrogg out of the ravine to the Ashenvale road, so the lost warlock could follow it out" },
    [98282] = { 1, "extracted an unruptured venom gland from the spiders of Thelgen Rock for Caitlin Grassman, who needed antivenom before she could go out again" },
    [98283] = { 3, "lured Carnage, the maddened alpha of the Razormaw raptors, with diseased bear flesh and took its head for Rethiel the Greenwarden" },
    [98284] = { 1, "took up enchanting until Nasalanna Windsinger would teach the Enchanted Lute, music for a camp's idle hours on the road" },
    [98285] = { 1, "tinkered until the Strange Hermit would teach the making of a Reagent Bot, one of the helpful constructs a camp needs" },
    [98286] = { 1, "enchanted until Nasalanna Windsinger would teach the Enchanted Lute, to entertain a camp through hard days on the trail" },
    [98291] = { 2, "thinned the Dragonmaw along their old retreat so Howin Kindfeather could get near Grim Batol and reclaim it for the Wildhammers" },
    [98293] = { 2, "seized the weapons the Dragonmaw were stockpiling in their retreat for Captain Stoutfist, before more of their soldiers could be armed" },
    [98297] = { 3, "slew the warlocks binding a red dragonspawn at the Dragonmaw Gates and put the creature out of its misery, as Howin Kindfeather asked" },
    [98298] = { 2, "tore apart worgen by the Greymane Wall for Dalar Dawnweaver, to learn how their curse spread, since Arugal could only bind them" },
    [98299] = { 2, "put down the human refugees by the Greymane Wall for Dalar Dawnweaver, before the worgen curse could make them Arugal's servants" },
    [98310] = { 2, "woke the golems Ados, Modr, Golm and Neru across the Wetlands with the Goaz Stone and took their hearts for Prospector Whelgar" },
    [98313] = { 1, "carried Prospector Whelgar's bundle of relics to Historian Karnik in Ironforge, a mystery it would take an army of scholars to crack" },
    [98319] = { 2, "searched the wendigo-filled Grizzled Den for Mountaineer Cornelius, who had charged in alone, for his partner Gretchen" },
    [98321] = { 1, "recovered the ore shipments miners dropped when wendigos overran the Grizzled Den, to get Tognus Flintfire's forge running again" },
    [98323] = { 1, "carried Mountaineer Gretchen's report to Senir Whitebeard in Kharanos, that the Grizzled Den was a lost cause" },
    [98326] = { 2, "slew Frosthowl, the wendigo that stole Gretta Ganter's fish, so her husband Paxton would not spend more nights on the frozen lake" },
    [98341] = { 1, "met the Avatar of Saeyleenan in Moonglade, a windborne cat spirit of Zephras come to oversee the trial of its own shape" },
    [98342] = { 3, "took the relics of the fang, the claw and the silent shadow from the Stormrage Barrow Dens, the Great Cat Spirit's trial of cunning and stealth" },
    [98372] = { 1, "took the unlit torch from a Night Watchman mauled by some large beast, a light to reveal what the darkness of Duskwood hid" },
    [98386] = { 1, "cleared the tarantulas and their eggs from Alther's Mill for Foreman Oslow, so his workers could fetch lumber for the bridge safely" },
    [98387] = { 2, "robbed the Blackrock camps south of Stonewatch Keep of food and weapons for Marshal Marris, to starve the orcs out of Redridge" },
    [98389] = { 1, "freed the newly risen from the webs of Night's Web Hollow for Aramis Hammerhand, to show the Forsaken their paladins meant them no harm" },
    [98392] = { 2, "pried the amulets from three harpy leaders for Sentinel Arynia Cloudsbreak, to prove where the taint in their belts came from" },
    [98396] = { 3, "proved the cunning, stealth and ferocity of the cat by taking three relics from the spirits guarding the Stormrage Barrow Dens" },
    [98403] = { 3, "brought down Xethorr the Wicked in the Cleft for Tallonkai Swiftroot, the satyr twisting Teldrassil's spiders with fel moss" },
    [98404] = { 3, "bore three relics past the enraged spirits of the Stormrage Barrow Dens, the Avatar of Saeyleenan's trial for its windborne shape" },
    [98407] = { 1, "stripped the spiked collars from the gnoll thrashers for Deputy Feldon, to frighten gnolls camped too close to Lakeshire back into the hills" },
    [98417] = { 2, "searched among the Satyrnaar demons west of Forest Song for Kurothel, the husband Maseara Autumnmoon could still feel in the woods" },
    [98423] = { 2, "brought King Magni an old tablet from the vault, the peace the Bronzebeards and Wildhammers signed after the War of the Three Hammers" },
    [98424] = { 2, "gathered Supervisor Fizsprocket's papers in the Venture Co. mine for Morin Cloudstalker, plans that could be turned against them" },
    [98427] = { 3, "stopped the Venture Co. shredder in the mine near Bloodhoof Village and took its key, so that it would fell no more trees" },
    [98430] = { 3, "freed Perith Stormhoof, Cairne Bloodhoof's trusted Longwalker scout, from the gnolls of Palemane Rock before he became their feast" },
    [98435] = { 1, "delivered Thunderhorn's report on the cleansed wells of Mulgore to Arch Druid Hamuul Runetotem" },
    [98459] = { 1, "delivered a mocking gift from old Half-fish to Bart Tidewater, the so-called captain of the Maiden's Virtue" },
    [98461] = { 1, "carried Hollee's note over the sea to Tarrel Rockweaver, an old classmate she still pined for, now happily married" },
    [98512] = { 1, "cleared Al'Aketh assassins from a house on the hill north of Fendaal Windstone's patrol, stone cold killers about business no one knew" },
    [98815] = { 1, "hunted thicket raptors in the Highlands excavation for their hides, for a trade with James Halloran, the tanner in Menethil Harbor" },
    [98823] = { 1, "carried the titan relic to Muln Earthfury of the Earthen Ring at the Skywatcher Plateau, who would know most about buried ruins" },
    [98824] = { 1, "donated the titan relic to High Explorer Magellas in Ironforge's Hall of Explorers, to be catalogued for the museum" },
    [99046] = { 2, "searched the road to the Oracle Glade for Sentinel Eralya Leafshadow, a runner still in training, long overdue with the Oracle Tree's message" },
    [99047] = { 1, "ran to Byancie in Dolanaar for help, while Sentinel Eralya Leafshadow lay dying of wounds from the tainted harpies" },
    [99048] = { 1, "searched north of Tiragarde Keep for Heglan Shadeeye, a Shattered Hand watcher whose reports had suddenly stopped" },
    [99049] = { 2, "searched the wreck of Heglan Shadeeye's hut for signs of her killers, which proved to be naga come down the coast" },
    [99050] = { 2, "gathered lasher fronds, a vial and spring water for Byancie's salve, to hold back the rot long enough to bring Eralya home" },
    [99051] = { 2, "killed the naga scouts camped on Durotar's coast for Orgnil Soulscar, before they could gain a foothold so near Razor Hill" },
    [99052] = { 3, "killed the young sea giant that followed the naga down Durotar's north coast, strong enough to rip an orc in half" },
    [99053] = { 3, "led Sentinel Lynessa Duskblossom out of Ban'ethil Barrow Den, where the Gnarlpine had dragged her before she could deliver her message" },
    [99073] = { 2, "took Byancie's salve to Sentinel Eralya Leafshadow on the road, to ease her suffering if it could not cure her" },
    [99079] = { 1, "searched the eastern edge of Mulgore for Longwalker Malah Longwind, three days overdue, and found her shot down with arrows" },
    [99080] = { 3, "drove the Galak raiders out of Mulgore for Baine Bloodhoof and brought back the head of Herak the Pillager as a warning" },
    [99081] = { 1, "brought Longwalker Malah's report to Brave Wildrunner, with word of her death and the new centaur camp her killers came from" },
    [99101] = { 1, "carried Malah's report to Baine Bloodhoof, word of a centaur raiding party loose in Mulgore" },
    [99108] = { 1, "sparred in Krang Stonehoof's arena against novices and willing challengers, to learn the warriors' ways first hand" },
    [99123] = { 2, "led Pal'juh, a young hunter who went scouting alone, out of Kolkar Crag after her magic ran out at the wrong time" },
    [99127] = { 1, "checked Jason Mathers's fishing traps in Crystal Lake, which held nothing but half-eaten fish" },
    [99128] = { 1, "thinned the murlocs at Crystal Lake for Jason Mathers, before there were no fish left anywhere in it" },
    [99130] = { 1, "gathered duskweed petals and animal blood for Remy Two Times, to make a poisoned bait that would teach the murlocs to keep away" },
    [99134] = { 1, "punished the Deathguards who had disappointed Executor Zygand, pain being one of the few delights left in death" },
    [99141] = { 1, "collected the overdue reports of Executor Zygand's Deathguards, and one from the abomination Gordo" },
    [99142] = { 1, "gathered tomb weed from the Balnir Farmstead for Junior Apothecary Holland, an altered doom weed that drew the Scourge to it" },
    [99143] = { 1, "rummaged through the murloc camp for shiny junk Lee Brown hoped would make good bait for fish" },
    [99144] = { 3, "helped Bareth Dawnstone, a Forsaken paladin of Bandarion Keep, escape the Scarlet Crusade at Crusader's Outpost" },
    [99152] = { 1, "gathered faintly glowing bones beneath Shadowvale for Hilda the Breaker, to learn how a Scourge threat had festered there unnoticed" },
    [99153] = { 2, "found the glowing shard of the focusing crystal a cultist had hidden beneath Shadowvale, before it raised more dead" },
    [99156] = { 3, "killed Riptear, a rogue abomination that had slipped past the Bulwark into eastern Tirisfal, and brought back its heart" },
    [99158] = { 1, "delivered a crate of holy candles to Father Gavin of the Argent Dawn at Misty Pine Refuge, his resting place for travellers" },
    [99159] = { 1, "gathered firewood for Father Gavin's hearth at Misty Pine Refuge, open to warm any soul" },
    [99160] = { 1, "destroyed the ice elementals a rockslide had riled up, to make the mountain road around Misty Pine Refuge safer" },
    [99161] = { 2, "killed Avala, the great ice elemental behind the slides and sudden weather around Misty Pine Refuge, for Father Gavin" },
    [99162] = { 2, "searched the slopes for the rifles of mountaineers lost to the slides, so Father Gavin could send them home to any family" },
    [99260] = { 1, "brought Elaadrin Evengale word from Fillion Flamebreeze that the readings to steer skycutters through the elemental plane were lost" },
    [99411] = { 1, "fed tender strider meat to Kyle, Ahab Wheathoof's runaway puppy, so he would settle down and come home" },
  },
}
